{"command":"cd /workspace/gdalgo && cat > go.mod <<'EOF'
module gdalgo

go 1.21
EOF
cat > json.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

// JKind is the type of a JSON value.
type JKind int

const (
	JNull JKind = iota
	JBool
	JNumber
	JString
	JArray
	JObject
)

// JValue is an ordered JSON value.
type JValue struct {
	Kind  JKind
	B     bool
	Raw   string // raw number text (if from parser) or preformatted
	F     float64
	IsInt bool
	I     int64
	S     string
	Arr   []*JValue
	Keys  []string
	Vals  map[string]*JValue
	// formatting hint for doubles
	Prec int // -1 => default
}

func JNewObject() *JValue { return &JValue{Kind: JObject, Vals: map[string]*JValue{}} }
func JNewArray() *JValue  { return &JValue{Kind: JArray, Arr: []*JValue{}} }
func JStr(s string) *JValue {
	return &JValue{Kind: JString, S: s}
}
func JInt(i int64) *JValue { return &JValue{Kind: JNumber, IsInt: true, I: i, F: float64(i)} }
func JBoolV(b bool) *JValue {
	return &JValue{Kind: JBool, B: b}
}
func JNullV() *JValue { return &JValue{Kind: JNull} }

// JDouble creates a double value formatted json-c style.
func JDouble(f float64) *JValue { return &JValue{Kind: JNumber, F: f, Prec: -1} }

// JRawNum creates a number with given text representation.
func JRawNum(s string) *JValue { return &JValue{Kind: JNumber, Raw: s} }

func (o *JValue) Set(k string, v *JValue) *JValue {
	if o.Vals == nil {
		o.Vals = map[string]*JValue{}
	}
	if _, ok := o.Vals[k]; !ok {
		o.Keys = append(o.Keys, k)
	}
	o.Vals[k] = v
	return o
}

func (o *JValue) Delete(k string) {
	if _, ok := o.Vals[k]; !ok {
		return
	}
	delete(o.Vals, k)
	for i, kk := range o.Keys {
		if kk == k {
			o.Keys = append(o.Keys[:i], o.Keys[i+1:]...)
			break
		}
	}
}

func (o *JValue) Get(k string) *JValue {
	if o == nil || o.Kind != JObject {
		return nil
	}
	return o.Vals[k]
}

func (o *JValue) Add(v *JValue) *JValue {
	o.Arr = append(o.Arr, v)
	return o
}

func (o *JValue) Str() string {
	if o == nil {
		return ""
	}
	switch o.Kind {
	case JString:
		return o.S
	case JNumber:
		return o.NumText()
	case JBool:
		if o.B {
			return "true"
		}
		return "false"
	}
	return ""
}

func (o *JValue) Num() float64 {
	if o == nil {
		return 0
	}
	if o.Kind == JNumber {
		if o.Raw != "" {
			f, _ := strconv.ParseFloat(o.Raw, 64)
			return f
		}
		if o.IsInt {
			return float64(o.I)
		}
		return o.F
	}
	if o.Kind == JString {
		f, _ := strconv.ParseFloat(strings.TrimSpace(o.S), 64)
		return f
	}
	if o.Kind == JBool && o.B {
		return 1
	}
	return 0
}

func (o *JValue) IsIntegral() bool {
	if o.Kind != JNumber {
		return false
	}
	if o.Raw != "" {
		return !strings.ContainsAny(o.Raw, ".eE")
	}
	return o.IsInt
}

func (o *JValue) IntVal() int64 {
	if o.Kind == JNumber {
		if o.Raw != "" {
			if i, err := strconv.ParseInt(o.Raw, 10, 64); err == nil {
				return i
			}
			f, _ := strconv.ParseFloat(o.Raw, 64)
			return int64(f)
		}
		if o.IsInt {
			return o.I
		}
		return int64(o.F)
	}
	return int64(o.Num())
}

// jsoncDouble formats a double like json-c does (%.17g, with ".0" appended
// when the result looks like an integer).
func jsoncDouble(f float64) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	// Go's shortest repr uses e notation for large exponents: convert to C style
	s = goGToC(s)
	if !strings.ContainsAny(s, ".eEn") {
		s += ".0"
	}
	return s
}

// goGToC converts Go's exponent format (e+06 / e-07) into C style (e+06 kept).
func goGToC(s string) string {
	// Go 'g' with -1 precision produces e.g. "1e+21", "1e-07". C %g gives "1e+21", "1e-07".
	return s
}

func (o *JValue) NumText() string {
	if o.Raw != "" {
		return o.Raw
	}
	if o.IsInt {
		return strconv.FormatInt(o.I, 10)
	}
	if o.Prec >= 0 {
		return formatSignificant(o.F, o.Prec)
	}
	return jsoncDouble(o.F)
}

// formatSignificant mimics json_object_new_double_with_significant_figures.
func formatSignificant(f float64, prec int) string {
	if math.IsNaN(f) {
		return "NaN"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	s := cfmt("%.*g", prec, f)
	if !strings.ContainsAny(s, ".e") {
		s += ".0"
	}
	return s
}

func jsonEscape(buf *bytes.Buffer, s string, escapeSlash bool) {
	buf.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			buf.WriteString("\\\"")
		case '\\':
			buf.WriteString("\\\\")
		case '\n':
			buf.WriteString("\\n")
		case '\r':
			buf.WriteString("\\r")
		case '\t':
			buf.WriteString("\\t")
		case '\b':
			buf.WriteString("\\b")
		case '\f':
			buf.WriteString("\\f")
		case '/':
			if escapeSlash {
				buf.WriteString("\\/")
			} else {
				buf.WriteByte('/')
			}
		default:
			if c < 0x20 {
				fmt.Fprintf(buf, "\\u%04x", c)
			} else {
				buf.WriteByte(c)
			}
		}
	}
	buf.WriteByte('"')
}

// SerializePretty renders like json-c JSON_C_TO_STRING_PRETTY (2 spaces) as used by CPLJSONDocument.
func (o *JValue) SerializePretty() string {
	var buf bytes.Buffer
	o.writePretty(&buf, 0, true)
	return buf.String()
}

func (o *JValue) SerializePrettyNoSlash() string {
	var buf bytes.Buffer
	o.writePretty(&buf, 0, false)
	return buf.String()
}

func indent(buf *bytes.Buffer, n int) {
	for i := 0; i < n; i++ {
		buf.WriteString("  ")
	}
}

func (o *JValue) writePretty(buf *bytes.Buffer, level int, esc bool) {
	if o == nil {
		buf.WriteString("null")
		return
	}
	switch o.Kind {
	case JNull:
		buf.WriteString("null")
	case JBool:
		if o.B {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case JNumber:
		buf.WriteString(o.NumText())
	case JString:
		jsonEscape(buf, o.S, esc)
	case JArray:
		buf.WriteString("[\n")
		for i, v := range o.Arr {
			indent(buf, level+1)
			v.writePretty(buf, level+1, esc)
			if i+1 < len(o.Arr) {
				buf.WriteByte(',')
			}
			buf.WriteByte('\n')
		}
		indent(buf, level)
		buf.WriteByte(']')
	case JObject:
		buf.WriteString("{\n")
		for i, k := range o.Keys {
			indent(buf, level+1)
			jsonEscape(buf, k, esc)
			buf.WriteByte(':')
			o.Vals[k].writePretty(buf, level+1, esc)
			if i+1 < len(o.Keys) {
				buf.WriteByte(',')
			}
			buf.WriteByte('\n')
		}
		indent(buf, level)
		buf.WriteByte('}')
	}
}

// SerializeSpaced renders like json-c JSON_C_TO_STRING_SPACED (single line, spaces).
func (o *JValue) SerializeSpaced(esc bool) string {
	var buf bytes.Buffer
	o.writeSpaced(&buf, esc)
	return buf.String()
}

func (o *JValue) writeSpaced(buf *bytes.Buffer, esc bool) {
	if o == nil {
		buf.WriteString("null")
		return
	}
	switch o.Kind {
	case JNull:
		buf.WriteString("null")
	case JBool:
		if o.B {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case JNumber:
		buf.WriteString(o.NumText())
	case JString:
		jsonEscape(buf, o.S, esc)
	case JArray:
		buf.WriteString("[ ")
		for i, v := range o.Arr {
			if i > 0 {
				buf.WriteString(", ")
			}
			v.writeSpaced(buf, esc)
		}
		buf.WriteString(" ]")
	case JObject:
		buf.WriteString("{ ")
		for i, k := range o.Keys {
			if i > 0 {
				buf.WriteString(", ")
			}
			jsonEscape(buf, k, esc)
			buf.WriteString(": ")
			o.Vals[k].writeSpaced(buf, esc)
		}
		buf.WriteString(" }")
	}
}

// SerializePlain renders compactly: {"a":1,"b":[1,2]}
func (o *JValue) SerializePlain(esc bool) string {
	var buf bytes.Buffer
	o.writePlain(&buf, esc)
	return buf.String()
}

func (o *JValue) writePlain(buf *bytes.Buffer, esc bool) {
	if o == nil {
		buf.WriteString("null")
		return
	}
	switch o.Kind {
	case JArray:
		buf.WriteString("[")
		for i, v := range o.Arr {
			if i > 0 {
				buf.WriteString(",")
			}
			v.writePlain(buf, esc)
		}
		buf.WriteString("]")
	case JObject:
		buf.WriteString("{")
		for i, k := range o.Keys {
			if i > 0 {
				buf.WriteString(",")
			}
			jsonEscape(buf, k, esc)
			buf.WriteString(":")
			o.Vals[k].writePlain(buf, esc)
		}
		buf.WriteString("}")
	default:
		o.writeSpaced(buf, esc)
	}
}

// ---------------- Parser ----------------

type jsonParser struct {
	s   string
	pos int
	err string
}

func ParseJSON(s string) (*JValue, error) {
	p := &jsonParser{s: s}
	p.skipWS()
	v := p.parseValue()
	if p.err != "" {
		return nil, fmt.Errorf("%s", p.err)
	}
	p.skipWS()
	if p.pos < len(p.s) {
		return nil, fmt.Errorf("trailing data")
	}
	return v, nil
}

// ParseJSONPrefix parses one value and returns the rest position.
func ParseJSONPrefix(s string) (*JValue, int, error) {
	p := &jsonParser{s: s}
	p.skipWS()
	v := p.parseValue()
	if p.err != "" {
		return nil, p.pos, fmt.Errorf("%s", p.err)
	}
	return v, p.pos, nil
}

func (p *jsonParser) skipWS() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
		} else {
			break
		}
	}
}

func (p *jsonParser) fail(msg string) *JValue {
	if p.err == "" {
		p.err = msg
	}
	return nil
}

func (p *jsonParser) parseValue() *JValue {
	if p.err != "" {
		return nil
	}
	if p.pos >= len(p.s) {
		return p.fail("unexpected end")
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		p.pos++
		o := JNewObject()
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == '}' {
			p.pos++
			return o
		}
		for {
			p.skipWS()
			if p.pos >= len(p.s) || p.s[p.pos] != '"' {
				return p.fail("expected key")
			}
			k := p.parseString()
			if p.err != "" {
				return nil
			}
			p.skipWS()
			if p.pos >= len(p.s) || p.s[p.pos] != ':' {
				return p.fail("expected colon")
			}
			p.pos++
			p.skipWS()
			v := p.parseValue()
			if p.err != "" {
				return nil
			}
			o.Set(k, v)
			p.skipWS()
			if p.pos >= len(p.s) {
				return p.fail("unexpected end")
			}
			if p.s[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.s[p.pos] == '}' {
				p.pos++
				return o
			}
			return p.fail("expected , or }")
		}
	case c == '[':
		p.pos++
		a := JNewArray()
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == ']' {
			p.pos++
			return a
		}
		for {
			p.skipWS()
			v := p.parseValue()
			if p.err != "" {
				return nil
			}
			a.Arr = append(a.Arr, v)
			p.skipWS()
			if p.pos >= len(p.s) {
				return p.fail("unexpected end")
			}
			if p.s[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.s[p.pos] == ']' {
				p.pos++
				return a
			}
			return p.fail("expected , or ]")
		}
	case c == '"':
		s := p.parseString()
		if p.err != "" {
			return nil
		}
		return JStr(s)
	case c == 't':
		if strings.HasPrefix(p.s[p.pos:], "true") {
			p.pos += 4
			return JBoolV(true)
		}
	case c == 'f':
		if strings.HasPrefix(p.s[p.pos:], "false") {
			p.pos += 5
			return JBoolV(false)
		}
	case c == 'n':
		if strings.HasPrefix(p.s[p.pos:], "null") {
			p.pos += 4
			return JNullV()
		}
	case c == 'N':
		if strings.HasPrefix(p.s[p.pos:], "NaN") {
			p.pos += 3
			return &JValue{Kind: JNumber, F: math.NaN(), Prec: -1}
		}
	case c == 'I':
		if strings.HasPrefix(p.s[p.pos:], "Infinity") {
			p.pos += 8
			return &JValue{Kind: JNumber, F: math.Inf(1), Prec: -1}
		}
	case c == '-' || (c >= '0' && c <= '9'):
		if strings.HasPrefix(p.s[p.pos:], "-Infinity") {
			p.pos += 9
			return &JValue{Kind: JNumber, F: math.Inf(-1), Prec: -1}
		}
		st := p.pos
		if p.s[p.pos] == '-' {
			p.pos++
		}
		for p.pos < len(p.s) && strings.IndexByte("0123456789.eE+-", p.s[p.pos]) >= 0 {
			p.pos++
		}
		raw := p.s[st:p.pos]
		v := &JValue{Kind: JNumber, Raw: raw, Prec: -1}
		if !strings.ContainsAny(raw, ".eE") {
			if i, err := strconv.ParseInt(raw, 10, 64); err == nil {
				v.IsInt = true
				v.I = i
				v.F = float64(i)
				return v
			}
		}
		f, err := strconv.ParseFloat(raw, 64)
		if err != nil && !strings.Contains(err.Error(), "range") {
			return p.fail("bad number")
		}
		v.F = f
		return v
	}
	return p.fail("unexpected character")
}

func (p *jsonParser) parseString() string {
	p.pos++ // opening quote
	var sb strings.Builder
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return sb.String()
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.s) {
				break
			}
			e := p.s[p.pos]
			p.pos++
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'u':
				if p.pos+4 > len(p.s) {
					p.fail("bad escape")
					return ""
				}
				n, err := strconv.ParseUint(p.s[p.pos:p.pos+4], 16, 32)
				if err != nil {
					p.fail("bad escape")
					return ""
				}
				p.pos += 4
				r := rune(n)
				if r >= 0xD800 && r < 0xDC00 && p.pos+6 <= len(p.s) && p.s[p.pos] == '\\' && p.s[p.pos+1] == 'u' {
					n2, err2 := strconv.ParseUint(p.s[p.pos+2:p.pos+6], 16, 32)
					if err2 == nil && n2 >= 0xDC00 && n2 < 0xE000 {
						r = (r-0xD800)<<10 + (rune(n2) - 0xDC00) + 0x10000
						p.pos += 6
					}
				}
				var b [4]byte
				l := utf8.EncodeRune(b[:], r)
				sb.Write(b[:l])
			default:
				sb.WriteByte(e)
			}
			continue
		}
		sb.WriteByte(c)
		p.pos++
	}
	p.fail("unterminated string")
	return ""
}
