package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

const (
	CE_None    = 0
	CE_Debug   = 1
	CE_Warning = 2
	CE_Failure = 3
	CE_Fatal   = 4
)

const (
	CPLE_None           = 0
	CPLE_AppDefined     = 1
	CPLE_OutOfMemory    = 2
	CPLE_FileIO         = 3
	CPLE_OpenFailed     = 4
	CPLE_IllegalArg     = 5
	CPLE_NotSupported   = 6
	CPLE_AssertionFailed = 7
	CPLE_NoWriteAccess  = 8
	CPLE_UserInterrupt  = 9
	CPLE_ObjectNull     = 10
)

var lastErrorMsg string
var lastErrorType int
var lastErrorNo int
var quietErrors int // when >0, errors are not printed (CPLPushErrorHandler(CPLQuietErrorHandler))
var collectedErrors []string

var configOptions = map[string]string{}
var configOrder []string

func CPLError(class int, code int, format string, args ...interface{}) {
	msg := format
	if len(args) > 0 {
		msg = cfmt(format, args...)
	}
	emitError(class, code, msg)
}

func emitError(class int, code int, msg string) {
	lastErrorMsg = msg
	lastErrorType = class
	lastErrorNo = code
	if quietErrors > 0 {
		return
	}
	if class == CE_Warning {
		fmt.Fprintf(os.Stderr, "Warning %d: %s\n", code, msg)
	} else if class == CE_Failure || class == CE_Fatal {
		fmt.Fprintf(os.Stderr, "ERROR %d: %s\n", code, msg)
	}
}

func CPLErrorReset() {
	lastErrorMsg = ""
	lastErrorType = 0
	lastErrorNo = 0
}

func CPLDebug(cat string, format string, args ...interface{}) {
	v := CPLGetConfigOption("CPL_DEBUG", "")
	if v == "" || strings.EqualFold(v, "OFF") || strings.EqualFold(v, "NO") || strings.EqualFold(v, "FALSE") || v == "0" {
		return
	}
	if !strings.EqualFold(v, "ON") && !strings.EqualFold(v, "YES") && !strings.EqualFold(v, "TRUE") && v != "1" && !strings.EqualFold(v, cat) {
		return
	}
	fmt.Fprintf(os.Stderr, "%s: %s\n", cat, cfmt(format, args...))
}

func CPLSetConfigOption(k, v string) {
	if _, ok := configOptions[k]; !ok {
		configOrder = append(configOrder, k)
	}
	configOptions[k] = v
}

func CPLGetConfigOption(k, def string) string {
	if v, ok := configOptions[k]; ok {
