cd /workspace/gdalgo && cat > cli.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"sort"
	"strconv"
	"strings"
)

type ArgDef struct {
	Name        string
	Short       string
	Aliases     []string
	Type        string
	Description string
	Metavar     string
	Required    bool
	Category    string
	Packed      bool
	Repeated    bool
	MinCount    int
	MaxCount    int
	Default     *JValue
	Choices     []string
	MutexGroup  string
	HasMin      bool
	MinValue    float64
	MinIncl     bool
	HasMax      bool
	MaxValue    float64
	MaxIncl     bool
	DatasetType []string
	InputFlags  []string
	OutputFlags []string
	Positional  bool
	Section     string
	JSON        *JValue
	HiddenCLI   bool
}

func (a *ArgDef) IsList() bool {
	return strings.HasSuffix(a.Type, "_list")
}

func (a *ArgDef) MetaVarDisplay() string {
	if a.Metavar != "" {
		return a.Metavar
	}
	return "<" + strings.ToUpper(a.Name) + ">"
}

type AlgDef struct {
	Path        []string
	Name        string
	Node        *JValue
	Args        []*ArgDef
	ByLong      map[string]*ArgDef
	ByShort     map[string]*ArgDef
	Positionals []*ArgDef
	SubNames    []string
	Help        string
	PathStr     string
}

func (d *AlgDef) Arg(name string) *ArgDef {
	for _, a := range d.Args {
		if a.Name == name {
			return a
		}
	}
	return nil
}

func findUsageNode(path []string) *JValue {
	n := getUsageRoot()
	for _, p := range path {
		var found *JValue
		subs := n.Get("sub_algorithms")
		if subs == nil {
			return nil
		}
		for _, s := range subs.Arr {
			if s.Get("name").Str() == p {
				found = s
				break
			}
		}
		if found == nil {
			return nil
		}
		n = found
	}
	return n
}

type helpOpt struct {
	names   []string // as displayed, with dashes
	metavar string
	section string
}

func parseHelpOptions(help string) []helpOpt {
	lines := strings.Split(help, "\n")
	col := -1
	for _, l := range lines {
		if strings.HasPrefix(l, "  -h, --help") {
			idx := strings.Index(l, "Display help message")
			if idx > 0 {
				col = idx
			}
			break
		}
	}
	var res []helpOpt
	if col < 0 {
		return res
	}
	section := ""
	for _, l := range lines {
		if strings.HasSuffix(l, ":") && !strings.HasPrefix(l, " ") {
			section = l
			continue
		}
		if !strings.HasPrefix(l, "  -") || len(l) < 3 {
			continue
		}
		var optstr string
		if len(l) >= col {
			optstr = strings.TrimRight(l[2:col], " ")
		} else {
			optstr = strings.TrimRight(l[2:], " ")
		}
		if strings.HasPrefix(l[col-2:], "  ") == false && len(l) > col {
			// not aligned; skip
		}
		parts := strings.Split(optstr, ", ")
		var ho helpOpt
		ho.section = section
		for i, p := range parts {
			if i == len(parts)-1 {
				sp := strings.IndexByte(p, ' ')
				if sp >= 0 {
					ho.metavar = p[sp+1:]
					p = p[:sp]
				}
			}
			ho.names = append(ho.names, p)
		}
		res = append(res, ho)
	}
	return res
}

var algDefCache = map[string]*AlgDef{}

func strListOf(v *JValue) []string {
	var r []string
	if v == nil {
		return r
	}
	for _, x := range v.Arr {
		r = append(r, x.Str())
	}
	return r
}

func argDefFromJSON(a *JValue, section string) *ArgDef {
	d := &ArgDef{
		Name:        a.Get("name").Str(),
		Type:        a.Get("type").Str(),
		Description: a.Get("description").Str(),
		Metavar:     a.Get("metavar").Str(),
		Required:    a.Get("required") != nil && a.Get("required").B,
		Category:    a.Get("category").Str(),
		Default:     a.Get("default"),
		Choices:     strListOf(a.Get("choices")),
		MutexGroup:  a.Get("mutual_exclusion_group").Str(),
		DatasetType: strListOf(a.Get("dataset_type")),
		InputFlags:  strListOf(a.Get("input_flags")),
		OutputFlags: strListOf(a.Get("output_flags")),
		Section:     section,
		JSON:        a,
	}
	if v := a.Get("packed_values_allowed"); v != nil {
		d.Packed = v.B
	}
	if v := a.Get("repeated_arg_allowed"); v != nil {
		d.Repeated = v.B
	}
	if v := a.Get("min_count"); v != nil {
		d.MinCount = int(v.IntVal())
	}
	d.MaxCount = 1
	if v := a.Get("max_count"); v != nil {
		d.MaxCount = int(v.IntVal())
	}
	if v := a.Get("min_value"); v != nil {
		d.HasMin = true
		d.MinValue = v.Num()
		d.MinIncl = a.Get("min_value_is_included") != nil && a.Get("min_value_is_included").B
	}
	if v := a.Get("max_value"); v != nil {
		d.HasMax = true
		d.MaxValue = v.Num()
		d.MaxIncl = a.Get("max_value_is_included") != nil && a.Get("max_value_is_included").B
	}
	return d
}

func commonHiddenArgs() []*ArgDef {
	return []*ArgDef{
		{Name: "help", Short: "h", Type: "boolean", Category: "Common", Description: "Display help message and exit"},
		{Name: "json-usage", Type: "boolean", Category: "Common", Description: "Display usage as JSON document and exit"},
		{Name: "config", Type: "string_list", Category: "Common", Metavar: "<KEY>=<VALUE>", Repeated: true, MaxCount: math.MaxInt32, Description: "Configuration option"},
	}
}

func getAlgDef(path []string) *AlgDef {
	key := strings.Join(path, " ")
	if d, ok := algDefCache[key]; ok {
		return d
	}
	node := findUsageNode(path)
	if node == nil {
		return nil
	}
	helpKey := strings.Join(append([]string{"gdal"}, path...), " ")
	d := &AlgDef{Path: path, Node: node, ByLong: map[string]*ArgDef{}, ByShort: map[string]*ArgDef{}}
	if len(path) > 0 {
		d.Name = path[len(path)-1]
	} else {
		d.Name = "gdal"
	}
	d.PathStr = helpKey
	d.Help = getHelpText(helpKey)
	for _, s := range node.Get("sub_algorithms").Arr {
		d.SubNames = append(d.SubNames, s.Get("name").Str())
	}
	for _, sec := range []string{"input_arguments", "output_arguments", "input_output_arguments"} {
		for _, a := range node.Get(sec).Arr {
			ad := argDefFromJSON(a, sec)
			d.Args = append(d.Args, ad)
		}
	}
	d.Args = append(d.Args, commonHiddenArgs()...)
	setupArgNames(d, d.Help)
	algDefCache[key] = d
	return d
}

func setupArgNames(d *AlgDef, help string) {
	hopts := parseHelpOptions(help)
	byName := map[string]*ArgDef{}
	for _, a := range d.Args {
		byName[a.Name] = a
	}
	for _, ho := range hopts {
		var target *ArgDef
		for _, n := range ho.names {
			if strings.HasPrefix(n, "--") {
				if a, ok := byName[n[2:]]; ok {
					target = a
					break
				}
			}
		}
		if target == nil {
			// e.g. user provided option
			continue
		}
		for _, n := range ho.names {
			if strings.HasPrefix(n, "--") {
				if n[2:] != target.Name {
					target.Aliases = append(target.Aliases, n[2:])
				}
			} else if strings.HasPrefix(n, "-") {
				target.Short = n[1:]
			}
		}
		if ho.metavar != "" && target.Metavar == "" {
			target.Metavar = ho.metavar
		}
		if ho.section == "Positional arguments:" {
			target.Positional = true
			d.Positionals = append(d.Positionals, target)
		}
	}
	// hidden "progress" option for algorithms supporting quiet
	if _, ok := byName["quiet"]; ok {
		if _, ok2 := byName["progress"]; !ok2 {
			p := &ArgDef{Name: "progress", Type: "boolean", Category: "Common", HiddenCLI: true}
			d.Args = append(d.Args, p)
		}
	}
	for _, a := range d.Args {
		if a.Section == "output_arguments" && (a.Name == "output-string" || a.Name == "return-code") {
			a.HiddenCLI = true
			continue
		}
		if a.Name == "pipeline" {
			continue
		}
		d.ByLong[a.Name] = a
		for _, al := range a.Aliases {
			d.ByLong[al] = a
		}
		if a.Short != "" {
			d.ByShort[a.Short] = a
		}
	}
}

// ---------------- Argument values -----------------

type ArgVal struct {
	Def      *ArgDef
	Set      bool
	Bool     bool
	Str      string
	Int      int
	Real     float64
	StrList  []string
	IntList  []int
	RealList []float64
	DSNames  []string
	DSs      []*Dataset
	// whether a list arg has been fed through the in-construction mechanism
	building bool
}

type Alg struct {
	Def        *AlgDef
	Vals       map[string]*ArgVal
	order      []string
	Positional []string
	Usage      func() string
	// for pipelines/steps
	callPath string
	// set when user-provided ordering matters
	SetOrder []string
}

func newAlg(def *AlgDef) *Alg {
	a := &Alg{Def: def, Vals: map[string]*ArgVal{}}
	for _, ad := range def.Args {
		v := &ArgVal{Def: ad}
		applyDefault(v)
		a.Vals[ad.Name] = v
	}
	return a
}

func applyDefault(v *ArgVal) {
	d := v.Def.Default
	if d == nil {
		return
	}
	switch v.Def.Type {
	case "boolean":
		v.Bool = d.B
	case "string":
		v.Str = d.Str()
	case "integer":
		v.Int = int(d.IntVal())
	case "real":
		v.Real = d.Num()
	case "string_list":
		if d.Kind == JArray {
			v.StrList = strListOf(d)
		} else {
			v.StrList = []string{d.Str()}
		}
	case "integer_list":
		if d.Kind == JArray {
			for _, x := range d.Arr {
				v.IntList = append(v.IntList, int(x.IntVal()))
			}
		}
	case "real_list":
		if d.Kind == JArray {
			for _, x := range d.Arr {
				v.RealList = append(v.RealList, x.Num())
			}
		}
	}
}

func (a *Alg) V(name string) *ArgVal {
	v := a.Vals[name]
	if v == nil {
		return &ArgVal{Def: &ArgDef{Name: name}}
	}
	return v
}

func (a *Alg) IsSet(name string) bool { return a.V(name).Set }
func (a *Alg) Bool(name string) bool  { return a.V(name).Bool }
func (a *Alg) Str(name string) string { return a.V(name).Str }
func (a *Alg) Int(name string) int    { return a.V(name).Int }
func (a *Alg) Real(name string) float64 {
	return a.V(name).Real
}
func (a *Alg) StrList(name string) []string {
	v := a.V(name)
	if v.Def.Type == "dataset_list" || v.Def.Type == "dataset" {
		return v.DSNames
	}
	return v.StrList
}
func (a *Alg) IntList(name string) []int       { return a.V(name).IntList }
func (a *Alg) RealList(name string) []float64  { return a.V(name).RealList }
func (a *Alg) DSName(name string) string {
	v := a.V(name)
	if len(v.DSNames) > 0 {
		return v.DSNames[0]
	}
	return ""
}

// errors

type parseError struct{}

func (a *Alg) errPrefix() string { return a.Def.Name + ": " }

func (a *Alg) ReportError(code int, format string, args ...interface{}) {
	CPLError(CE_Failure, code, a.errPrefix()+format, args...)
}

func (a *Alg) ReportWarning(code int, format string, args ...interface{}) {
	CPLError(CE_Warning, code, a.errPrefix()+format, args...)
}

func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	prev := make([]int, lb+1)
	cur := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		cur[0] = i
		for j := 1; j <= lb; j++ {
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			m := prev[j] + 1
			if cur[j-1]+1 < m {
				m = cur[j-1] + 1
			}
			if prev[j-1]+cost < m {
				m = prev[j-1] + cost
			}
			cur[j] = m
		}
		prev, cur = cur, prev
	}
	return prev[lb]
}

func (a *Alg) suggest(name string) string {
	best := ""
	bestD := 1000
	var names []string
	for _, ad := range a.Def.Args {
		if ad.HiddenCLI || ad.Name == "pipeline" {
			continue
		}
		names = append(names, ad.Name)
		names = append(names, ad.Aliases...)
	}
	for _, n := range names {
		d := levenshtein(name, n)
		m := len(name)
		if len(n) < m {
			m = len(n)
		}
		if d <= 2 && d < m && d < bestD {
			bestD = d
			best = n
		}
	}
	return best
}

func parseIntStrict(s string) (int, bool) {
	t := strings.TrimLeft(s, " \t\n\r\f\v")
	if t == "" {
		return 0, false
	}
	i := 0
	if t[0] == '+' || t[0] == '-' {
		i = 1
	}
	if i >= len(t) {
		return 0, false
	}
	for j := i; j < len(t); j++ {
		if t[j] < '0' || t[j] > '9' {
			return 0, false
		}
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil || v > math.MaxInt32 || v < math.MinInt32 {
		return 0, false
	}
	return int(v), true
}

func parseRealStrict(s string) (float64, bool) {
	f, n := strtod(s)
	if n == 0 {
		return 0, false
	}
	rest := s[n:]
	if strings.TrimLeft(rest, " \t\n\r") != "" {
		return 0, false
	}
	return f, true
}

func typeLabel(t string) string {
	switch t {
	case "integer", "integer_list":
		return "integer"
	case "real", "real_list":
		return "real"
	}
	return t
}

// Validate a string against choices. Returns canonical value or error.
func (a *Alg) checkChoices(ad *ArgDef, val string) (string, bool) {
	if len(ad.Choices) == 0 {
		return val, true
	}
	for _, c := range ad.Choices {
		if strings.EqualFold(c, val) {
			return c, true
		}
	}
	// hidden choices
	if hc, ok := hiddenChoices(ad, val); ok {
		return hc, true
	}
	var q []string
	for _, c := range ad.Choices {
		q = append(q, "'"+c+"'")
	}
	CPLError(CE_Failure, CPLE_IllegalArg, "Invalid value '%s' for string argument '%s'. Should be one among %s.", val, ad.Name, strings.Join(q, ", "))
	return "", false
}

func hiddenChoices(ad *ArgDef, val string) (string, bool) {
	isType := false
	for _, c := range ad.Choices {
		if c == "UInt8" {
			isType = true
		}
	}
	if isType && strings.EqualFold(val, "Byte") {
		return "Byte", true
	}
	return "", false
}

func (a *Alg) checkMinMax(ad *ArgDef, v float64, isInt bool) bool {
	fmtv := func(x float64) string {
		if isInt {
			return strconv.Itoa(int(x))
		}
		return cfmt("%g", x)
	}
	if ad.HasMin {
		if (ad.MinIncl && v < ad.MinValue) || (!ad.MinIncl && v <= ad.MinValue) || math.IsNaN(v) {
			op := ">="
			if !ad.MinIncl {
				op = ">"
			}
			CPLError(CE_Failure, CPLE_IllegalArg, "Value of argument '%s' is %s, but should be %s %s", ad.Name, fmtv(v), op, fmtv(ad.MinValue))
			return false
		}
	}
	if ad.HasMax {
		if (ad.MaxIncl && v > ad.MaxValue) || (!ad.MaxIncl && v >= ad.MaxValue) {
			op := "<="
			if !ad.MaxIncl {
				op = "<"
			}
			CPLError(CE_Failure, CPLE_IllegalArg, "Value of argument '%s' is %s, but should be %s %s", ad.Name, fmtv(v), op, fmtv(ad.MaxValue))
			return false
		}
	}
	return true
}

// setScalar sets a scalar value from string. dispName is as typed by user (e.g. "--format" or "f").
func (a *Alg) setScalar(ad *ArgDef, dispName string, val string) bool {
	v := a.Vals[ad.Name]
	switch ad.Type {
	case "boolean":
		if val == "" || val == "true" {
			v.Bool = true
		} else if val == "false" {
			v.Bool = false
		} else {
			a.ReportError(CPLE_IllegalArg, "Invalid value '%s' for boolean argument '%s'. Should be 'true' or 'false'.", val, dispName)
			return false
		}
	case "string":
		c, ok := a.checkChoices(ad, val)
		if !ok {
			return false
		}
		if !a.customValidate(ad, c) {
			return false
		}
		v.Str = c
	case "integer":
		i, ok := parseIntStrict(val)
		if !ok {
			a.ReportError(CPLE_IllegalArg, "Expected integer value for argument '%s', but got '%s'.", dispName, val)
			return false
		}
		if !a.checkMinMax(ad, float64(i), true) {
			return false
		}
		v.Int = i
	case "real":
		f, ok := parseRealStrict(val)
		if !ok {
			a.ReportError(CPLE_IllegalArg, "Expected real value for argument '%s', but got '%s'.", dispName, val)
			return false
		}
		if !a.checkMinMax(ad, f, false) {
			return false
		}
		v.Real = f
	case "dataset":
		v.DSNames = []string{val}
	}
	v.Set = true
	a.SetOrder = append(a.SetOrder, ad.Name)
	return true
}

// customValidate allows per-algorithm validation hooks at set time.
func (a *Alg) customValidate(ad *ArgDef, val string) bool {
	if ad.Name == "nodata" || ad.Name == "dst-nodata" || ad.Name == "src-nodata" {
		_ = val
	}
	return true
}

type pendingList struct {
	def    *ArgDef
	values []string
	disp   string
}

// appendList parses a token into a list arg's pending values.
func (a *Alg) appendList(pend map[string]*pendingList, order *[]string, ad *ArgDef, dispName, val string) bool {
	p := pend[ad.Name]
	if p == nil {
		p = &pendingList{def: ad, disp: dispName}
		pend[ad.Name] = p
		*order = append(*order, ad.Name)
	}
	var parts []string
	if ad.Packed && ad.Type != "dataset_list" {
		if val == "" {
			parts = []string{}
		} else {
			parts = splitPacked(val)
		}
	} else {
		parts = []string{val}
	}
	switch ad.Type {
	case "integer_list":
		for _, s := range parts {
			if _, ok := parseIntStrict(s); !ok {
				a.ReportError(CPLE_IllegalArg, "Expected list of integer value for argument '%s', but got '%s'.", dispName, val)
				return false
			}
		}
	case "real_list":
		for _, s := range parts {
			if _, ok := parseRealStrict(s); !ok {
				a.ReportError(CPLE_IllegalArg, "Expected list of real value for argument '%s', but got '%s'.", dispName, val)
				return false
			}
		}
	case "string_list":
		for i, s := range parts {
			if len(ad.Choices) > 0 {
				c, ok := a.checkChoices(ad, s)
				if !ok {
					return false
				}
				parts[i] = c
			}
		}
	}
	p.values = append(p.values, parts...)
	return true
}

func splitPacked(s string) []string {
	// split on commas, honouring double quotes
	var res []string
	var cur strings.Builder
	inq := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' {
			inq = !inq
			continue
		}
		if c == ',' && !inq {
			res = append(res, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	res = append(res, cur.String())
	return res
}

func (a *Alg) applyList(p *pendingList) bool {
	ad := p.def
	v := a.Vals[ad.Name]
	n := len(p.values)
	if ad.MinCount == ad.MaxCount && ad.MinCount > 0 {
		if n != ad.MinCount {
			if ad.MinCount == 1 {
				a.ReportError(CPLE_AppDefined, "%d %s been specified for argument '%s', whereas exactly %d was expected.", n, valuesHave(n), ad.Name, ad.MinCount)
			} else {
				a.ReportError(CPLE_AppDefined, "%d %s been specified for argument '%s', whereas exactly %d were expected.", n, valuesHave(n), ad.Name, ad.MinCount)
			}
			return false
		}
	}
	if n < ad.MinCount {
		a.ReportError(CPLE_AppDefined, "Only %d %s been specified for argument '%s', whereas at least %d expected.", n, valuesHave(n), ad.Name, ad.MinCount)
		return false
	}
	if n > ad.MaxCount {
		a.ReportError(CPLE_AppDefined, "%d %s been specified for argument '%s', whereas at most %d expected.", n, valuesHave(n), ad.Name, ad.MaxCount)
		return false
	}
	switch ad.Type {
	case "integer_list":
		v.IntList = nil
		for _, s := range p.values {
			i, _ := parseIntStrict(s)
			if !a.checkMinMax(ad, float64(i), true) {
				return false
			}
			v.IntList = append(v.IntList, i)
		}
	case "real_list":
		v.RealList = nil
		for _, s := range p.values {
			f, _ := parseRealStrict(s)
			if !a.checkMinMax(ad, f, false) {
				return false
			}
			v.RealList = append(v.RealList, f)
		}
	case "string_list":
		v.StrList = append([]string{}, p.values...)
	case "dataset_list":
		v.DSNames = append([]string{}, p.values...)
	}
	v.Set = true
	a.SetOrder = append(a.SetOrder, ad.Name)
	return true
}

func valuesHave(n int) string {
	if n == 1 {
		return "value has"
	}
	if n == 0 {
		return "value has"
	}
	return "values have"
}

// ParseCommandLine parses CLI args for a leaf algorithm. Returns false on error.
func (a *Alg) ParseCommandLine(args []string) bool {
	pend := map[string]*pendingList{}
	var pendOrder []string
	var positional []string
	seen := map[string]bool{}
	for i := 0; i < len(args); i++ {
		tok := args[i]
		if strings.HasPrefix(tok, "--") {
			name := tok[2:]
			val := ""
			hasVal := false
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
				hasVal = true
			}
			disp := "--" + name
			ad := a.Def.ByLong[name]
			if ad == nil || name == "" {
				if s := a.suggest(name); s != "" && name != "" {
					a.ReportError(CPLE_IllegalArg, "Option '%s' is unknown. Do you mean '--%s'?", disp, s)
				} else {
					a.ReportError(CPLE_IllegalArg, "Option '%s' is unknown.", disp)
				}
				return false
			}
			if ad.Type == "boolean" {
				if seen[ad.Name] {
					a.ReportError(CPLE_IllegalArg, "Argument '%s' has already been specified.", disp)
					return false
				}
				seen[ad.Name] = true
				if !a.setScalar(ad, disp, val) {
					return false
				}
				if ad.Name == "help" || ad.Name == "json-usage" {
					a.Vals[ad.Name].Bool = true
				}
				continue
			}
			if !hasVal {
				if i+1 >= len(args) {
					a.ReportError(CPLE_IllegalArg, "Expected value for argument '%s', but ran short of tokens", disp)
					return false
				}
				i++
				val = args[i]
			}
			if !a.handleValue(ad, disp, val, seen, pend, &pendOrder) {
				return false
			}
		} else if strings.HasPrefix(tok, "-") && len(tok) >= 2 && !isNumericStr(tok) {
			sn := tok[1:2]
			ad := a.Def.ByShort[sn]
			if ad == nil {
				a.ReportError(CPLE_IllegalArg, "Short name option '%s' is unknown.", sn)
				return false
			}
			if len(tok) > 2 {
				if ad.Type != "boolean" {
					a.ReportError(CPLE_IllegalArg, "Invalid argument '%s'. Option '%s' is not a boolean option.", tok, sn)
					return false
				}
				// combined short boolean flags
				for k := 1; k < len(tok); k++ {
					s := tok[k : k+1]
					ad2 := a.Def.ByShort[s]
					if ad2 == nil {
						a.ReportError(CPLE_IllegalArg, "Short name option '%s' is unknown.", s)
						return false
					}
					if ad2.Type != "boolean" {
						a.ReportError(CPLE_IllegalArg, "Invalid argument '%s'. Option '%s' is not a boolean option.", tok, s)
						return false
					}
					if seen[ad2.Name] {
						a.ReportError(CPLE_IllegalArg, "Argument '%s' has already been specified.", s)
						return false
					}
					seen[ad2.Name] = true
					a.setScalar(ad2, s, "")
				}
				continue
			}
			if ad.Type == "boolean" {
				if seen[ad.Name] {
					a.ReportError(CPLE_IllegalArg, "Argument '%s' has already been specified.", sn)
					return false
				}
				seen[ad.Name] = true
				a.setScalar(ad, sn, "")
				continue
			}
			if i+1 >= len(args) {
				a.ReportError(CPLE_IllegalArg, "Expected value for argument '%s', but ran short of tokens", sn)
				return false
			}
			i++
			if !a.handleValue(ad, sn, args[i], seen, pend, &pendOrder) {
				return false
			}
		} else {
			positional = append(positional, tok)
		}
	}
	if a.Vals["help"] != nil && a.Vals["help"].Bool {
		return true
	}
	if a.Vals["json-usage"] != nil && a.Vals["json-usage"].Bool {
		return true
	}
	// positional processing
	pi := 0
	cur := 0
	pos := a.Def.Positionals
	for pi < len(positional) && cur < len(pos) {
		ad := pos[cur]
		for a.Vals[ad.Name].Set {
			cur++
			if cur == len(pos) {
				break
			}
			ad = pos[cur]
		}
		if cur == len(pos) {
			break
		}
		if ad.IsList() && ad.MinCount != ad.MaxCount {
			if cur == 0 {
				nAtEnd := 0
				for j := 1; j < len(pos); j++ {
					o := pos[j]
					if o.IsList() {
						nAtEnd += o.MinCount
					} else {
						nAtEnd++
					}
				}
				if len(positional) < nAtEnd {
					a.ReportError(CPLE_AppDefined, "Not enough positional values.")
					return false
				}
				for ; pi < len(positional)-nAtEnd; pi++ {
					if !a.appendList(pend, &pendOrder, ad, ad.Name, positional[pi]) {
						return false
					}
				}
			} else {
				for ; pi < len(positional); pi++ {
					if !a.appendList(pend, &pendOrder, ad, ad.Name, positional[pi]) {
						return false
					}
				}
			}
		} else if ad.IsList() {
			n := ad.MinCount
			if len(positional)-pi < n {
				a.ReportError(CPLE_AppDefined, "Not enough positional values.")
				return false
			}
			for j := 0; j < n; j++ {
				if !a.appendList(pend, &pendOrder, ad, ad.Name, positional[pi]) {
					return false
				}
				pi++
			}
		} else {
			if !a.setScalar(ad, ad.Name, positional[pi]) {
				return false
			}
			pi++
		}
		cur++
	}
	for _, n := range pendOrder {
		if !a.applyList(pend[n]) {
			return false
		}
	}
	if pi < len(positional) {
		a.ReportError(CPLE_AppDefined, "Positional values starting at '%s' are not expected.", positional[pi])
		return false
	}
	if cur < len(pos) {
		ad := pos[cur]
		need := ad.Required
		if ad.IsList() {
			need = ad.MinCount > 0
		}
		if need {
			for cur < len(pos) && a.Vals[pos[cur].Name].Set {
				cur++
			}
			if cur < len(pos) {
				a.ReportError(CPLE_AppDefined, "Positional arguments starting at '%s' have not been specified.", stripAngle(pos[cur].MetaVarDisplay()))
				return false
			}
		}
	}
	return true
}

func stripAngle(s string) string {
	if strings.HasPrefix(s, "<") && strings.HasSuffix(s, ">") {
		return s[1 : len(s)-1]
	}
	return s
}

func (a *Alg) handleValue(ad *ArgDef, disp, val string, seen map[string]bool, pend map[string]*pendingList, pendOrder *[]string) bool {
	if ad.IsList() {
		if seen[ad.Name] && !ad.Repeated {
			a.ReportError(CPLE_IllegalArg, "Argument '%s' has already been specified.", disp)
			return false
		}
		seen[ad.Name] = true
		if ad.Name == "config" {
			if !strings.Contains(val, "=") {
				a.ReportError(CPLE_IllegalArg, "Configuration option should be specified as KEY=VALUE.")
			}
		}
		return a.appendList(pend, pendOrder, ad, disp, val)
	}
	if seen[ad.Name] {
		a.ReportError(CPLE_IllegalArg, "Argument '%s' has already been specified.", disp)
		return false
	}
	seen[ad.Name] = true
	return a.setScalar(ad, disp, val)
}

// ---------------- Help ----------------

func (a *Alg) fullHelp() string {
	return a.Def.Help
}

// shortUsage returns usage printed after a parse error.
func (d *AlgDef) shortUsage() string {
	h := d.Help
	if len(d.SubNames) > 0 {
		// non-leaf: replace option sections by "Try" line
		idx := strings.Index(h, "\nCommon Options:\n")
		if idx < 0 {
			return h
		}
		rest := h[idx+1:]
		// find epilog: first paragraph after option sections that is not an option section
		paras := strings.Split(rest, "\n\n")
		var tail []string
		for i, p := range paras {
			if strings.HasSuffix(strings.SplitN(p, "\n", 2)[0], "Options:") {
				continue
			}
			tail = paras[i:]
			break
		}
		return h[:idx+1] + "Try '" + d.PathStr + " --help' for help.\n\n" + strings.Join(tail, "\n\n")
	}
	first := strings.SplitN(h, "\n", 2)[0]
	return first + "\nTry '" + d.PathStr + " --help' for help.\n"
