				CPLError(CE_Failure, CPLE_AppDefined, "--debug option given without debug level.")
				return nil, 1
			}
			CPLSetConfigOption("CPL_DEBUG", args[i+1])
			i++
		case la == "--optfile":
			if i+1 >= len(args) {
				CPLError(CE_Failure, CPLE_AppDefined, "--optfile option given without filename.")
				return nil, 1
