func runNode(def *AlgDef, path []string, args []string) int {
	isRoot := len(path) == 0
	name := def.Name
	if len(def.SubNames) > 0 {
		// non leaf: process leading options
		i := 0
		for i < len(args) {
			a := args[i]
			if !strings.HasPrefix(a, "-") || a == "-" {
