				}
				out(def.Help)
				return 0
			case a == "--json-usage":
				n := map[string]int{"": 3, "raster": 2, "pipeline": 1, "raster pipeline": 1}[strings.Join(path, " ")]
				for k := 0; k < n; k++ {
					nztmWarning()
				}
				out(def.jsonUsage())
				return 0
			case a == "--drivers" && (isRoot || strings.Join(path, " ") == "raster" || strings.Join(path, " ") == "vector" || strings.Join(path, " ") == "mdim"):
