		np := append(append([]string{}, path...), subName)
		sd := getAlgDef(np)
		return runNode(sd, np, args[i+1:])
	}
	return runLeaf(def, path, args)
}

func printNodeErrorUsage(def *AlgDef, path []string) {
	for k := 0; k < nodeHasTileWarning(path); k++ {
		if strings.Join(path, " ") == "raster" {
			nztmWarning()
		}
	}
	printErrStr(def.shortUsage())
}

var subAliases = map[string]map[string]string{
	"dataset": {"cp": "copy", "rm": "delete", "remove": "delete", "ren": "rename", "mv": "rename"},
	"raster":  {"neighbours": "neighbors"},
	"vsi":     {"cp": "copy", "rm": "delete", "rmdir": "delete", "del": "delete", "ls": "list", "mv": "move", "ren": "move", "rename": "move"},
}

func resolveSubAlias(path []string, sub string) string {
	def := getAlgDef(path)
	for _, s := range def.SubNames {
		if s == sub {
			return s
		}
	}
	if m, ok := subAliases[strings.Join(path, " ")]; ok {
		if r, ok := m[sub]; ok {
			return r
		}
	}
	return ""
}

// rootShortcut handles 'gdal <FILENAME>' and 'gdal read ...'
func rootShortcut(args []string) (int, bool) {
	if args[0] == "read" {
		np := []string{"pipeline"}
		return runLeaf(getAlgDef(np), np, args), true
	}
	for _, a := range args {
		if a == "!" {
			np := []string{"pipeline"}
			return runLeaf(getAlgDef(np), np, args), true
		}
	}
	if fileExistsForOpen(args[0]) {
		np := []string{"info"}
		return runLeaf(getAlgDef(np), np, args), true
	}
	return 0, false
}

func fileExistsForOpen(name string) bool {
	if strings.HasPrefix(name, "/vsi") {
		return true
	}
	_, err := os.Stat(name)
	return err == nil
}

func runLeaf(def *AlgDef, path []string, args []string) int {
	key := strings.Join(path, " ")
	if key == "raster tile" {
		nztmWarning()
	}
	if f, ok := specialLeaf[key]; ok {
		return f(def, path, args)
	}
	alg := newAlg(def)
	if !alg.ParseCommandLine(args) {
		if shouldPrintUsageAfterError() {
			printErrStr(def.shortUsage())
		}
		return 1
	}
	if alg.Bool("help") {
		if key == "raster tile" {
			// warning already printed
		}
		out(def.Help)
		return 0
	}
	if alg.Bool("json-usage") {
		if key == "raster tile" {
		}
		out(def.jsonUsage())
		return 0
	}
	if alg.Bool("quiet") {
		progressEnabled = false
	}
	if !alg.Validate() {
		printErrStr(def.shortUsage())
		return 1
	}
	f := commands[key]
	if f == nil {
		CPLError(CE_Failure, CPLE_NotSupported, "%s: not implemented", def.Name)
		return 1
	}
	if !f(alg) {
		return 1
	}
	return 0
}

var specialLeaf = map[string]func(def *AlgDef, path []string, args []string) int{}
