func clampRound(t DataType, v float64) float64 {
	switch t.baseType() {
	case GDT_Float64:
		return v
	case GDT_Float32:
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return v
		}
		if v > math.MaxFloat32 {
			return math.Inf(1)
		}
		if v < -math.MaxFloat32 {
			return math.Inf(-1)
		}
		return float64(float32(v))
	case GDT_Float16:
		return float16Round(v)
	}
	if math.IsNaN(v) {
		return 0
	}
	mn, mx := t.Range()
	if t.baseType() == GDT_UInt64 || t.baseType() == GDT_Int64 {
		if v >= mx {
			return mx
		}
		if v <= mn {
			return mn
		}
		return math.Round(v)
	}
	r := math.Floor(v + 0.5)
	if v < 0 {
		r = math.Ceil(v - 0.5)
	}
	if r < mn {
		return mn
	}
	if r > mx {
		return mx
	}
	return r
