	GDT_CFloat64 DataType = 11
	GDT_UInt64   DataType = 12
	GDT_Int64    DataType = 13
	GDT_Int8     DataType = 14
	GDT_Float16  DataType = 15
	GDT_CFloat16 DataType = 16
)

var dataTypeNames = map[DataType]string{
	GDT_Unknown: "Unknown", GDT_Byte: "Byte", GDT_UInt16: "UInt16", GDT_Int16: "Int16",
	GDT_UInt32: "UInt32", GDT_Int32: "Int32", GDT_Float32: "Float32", GDT_Float64: "Float64",
	GDT_CInt16: "CInt16", GDT_CInt32: "CInt32", GDT_CFloat32: "CFloat32", GDT_CFloat64: "CFloat64",
	GDT_UInt64: "UInt64", GDT_Int64: "Int64", GDT_Int8: "Int8", GDT_Float16: "Float16", GDT_CFloat16: "CFloat16",
}

func (t DataType) String() string { return dataTypeNames[t] }

func dataTypeFromName(s string) DataType {
	if strings.EqualFold(s, "UInt8") {
		return GDT_Byte
	}
	for k, v := range dataTypeNames {
		if strings.EqualFold(v, s) {
			return k
		}
	}
	return GDT_Unknown
}

func (t DataType) Size() int {
	switch t {
	case GDT_Byte, GDT_Int8:
		return 1
	case GDT_UInt16, GDT_Int16, GDT_Float16:
		return 2
	case GDT_UInt32, GDT_Int32, GDT_Float32, GDT_CInt16, GDT_CFloat16:
		return 4
	case GDT_Float64, GDT_CInt32, GDT_CFloat32, GDT_UInt64, GDT_Int64:
		return 8
	case GDT_CFloat64:
		return 16
	}
	return 0
}

func (t DataType) IsComplex() bool {
	return t == GDT_CInt16 || t == GDT_CInt32 || t == GDT_CFloat32 || t == GDT_CFloat64 || t == GDT_CFloat16
}

func (t DataType) IsFloat() bool {
	return t == GDT_Float32 || t == GDT_Float64 || t == GDT_Float16 || t == GDT_CFloat32 || t == GDT_CFloat64 || t == GDT_CFloat16
}

func (t DataType) IsSigned() bool {
	return t == GDT_Int8 || t == GDT_Int16 || t == GDT_Int32 || t == GDT_Int64 || t.IsFloat() || t == GDT_CInt16 || t == GDT_CInt32
}

// baseType returns the real component type of a complex type.
func (t DataType) baseType() DataType {
	switch t {
	case GDT_CInt16:
		return GDT_Int16
	case GDT_CInt32:
		return GDT_Int32
	case GDT_CFloat32:
		return GDT_Float32
	case GDT_CFloat64:
		return GDT_Float64
	case GDT_CFloat16:
		return GDT_Float16
	}
	return t
}

func (t DataType) Bits() int { return t.Size() * 8 }

// typeRange returns min/max representable values
func (t DataType) Range() (float64, float64) {
	switch t.baseType() {
	case GDT_Byte:
		return 0, 255
	case GDT_Int8:
		return -128, 127
	case GDT_UInt16:
		return 0, 65535
	case GDT_Int16:
		return -32768, 32767
	case GDT_UInt32:
		return 0, 4294967295
	case GDT_Int32:
		return -2147483648, 2147483647
	case GDT_UInt64:
		return 0, 18446744073709551615
	case GDT_Int64:
		return -9223372036854775808, 9223372036854775807
	case GDT_Float16:
		return -65504, 65504
	case GDT_Float32:
		return -math.MaxFloat32, math.MaxFloat32
	}
	return -math.MaxFloat64, math.MaxFloat64
}

// clampRound converts a double to the representable value in type t (GDALCopyWords semantics).
func clampRound(t DataType, v float64) float64 {
	switch t.baseType() {
	case GDT_Float64:
		return v
	case GDT_Float32:
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return v
		}
		if v > math.MaxFloat32 {
			return math.Inf(1)
		}
		if v < -math.MaxFloat32 {
			return math.Inf(-1)
		}
		return float64(float32(v))
	case GDT_Float16:
		return float16Round(v)
	}
	if math.IsNaN(v) {
		return 0
	}
	mn, mx := t.Range()
	if t.baseType() == GDT_UInt64 || t.baseType() == GDT_Int64 {
		if v >= mx {
			return mx
		}
		if v <= mn {
			return mn
		}
		return math.Round(v)
	}
	r := math.Floor(v + 0.5)
	if v < 0 {
		r = math.Ceil(v - 0.5)
	}
	if r < mn {
		return mn
	}
	if r > mx {
		return mx
	}
	return r
}

func float16Round(v float64) float64 {
	return halfToFloat(floatToHalf(float32(v)))
}

