// Metadata store with domains
type MDDomain struct {
	Keys []string
	Vals map[string]string
	// raw list for domains with non KEY=VALUE items (xml:)
	Raw []string
}

type Metadata struct {
	Domains []string
	M       map[string]*MDDomain
}

func NewMetadata() *Metadata { return &Metadata{M: map[string]*MDDomain{}} }

func (m *Metadata) dom(d string, create bool) *MDDomain {
	x := m.M[d]
	if x == nil && create {
		x = &MDDomain{Vals: map[string]string{}}
		m.M[d] = x
		m.Domains = append(m.Domains, d)
	}
	return x
}

func (m *Metadata) Set(domain, key, val string) {
	d := m.dom(domain, true)
	if _, ok := d.Vals[key]; !ok {
		d.Keys = append(d.Keys, key)
	}
	d.Vals[key] = val
}

func (m *Metadata) Unset(domain, key string) {
	d := m.dom(domain, false)
	if d == nil {
		return
	}
	if _, ok := d.Vals[key]; !ok {
		return
	}
	delete(d.Vals, key)
	for i, k := range d.Keys {
		if k == key {
			d.Keys = append(d.Keys[:i], d.Keys[i+1:]...)
			break
		}
	}
}

func (m *Metadata) Get(domain, key string) (string, bool) {
	d := m.dom(domain, false)
	if d == nil {
		return "", false
	}
	v, ok := d.Vals[key]
	return v, ok
}

func (m *Metadata) GetDef(domain, key, def string) string {
	if v, ok := m.Get(domain, key); ok {
		return v
	}
	return def
}

// List returns KEY=VALUE pairs for a domain in insertion order.
func (m *Metadata) List(domain string) []string {
	d := m.dom(domain, false)
	if d == nil {
		return nil
	}
	if d.Raw != nil {
		return d.Raw
	}
	var r []string
	for _, k := range d.Keys {
		r = append(r, k+"="+d.Vals[k])
	}
	return r
}

func (m *Metadata) SetRaw(domain string, items []string) {
	d := m.dom(domain, true)
	d.Raw = items
}

func (m *Metadata) SetList(domain string, items []string) {
	d := m.dom(domain, true)
	d.Keys = nil
	d.Vals = map[string]string{}
	d.Raw = nil
	for _, it := range items {
		if i := strings.IndexByte(it, '='); i >= 0 {
			k := it[:i]
			if _, ok := d.Vals[k]; !ok {
				d.Keys = append(d.Keys, k)
			}
			d.Vals[k] = it[i+1:]
		}
	}
}

func (m *Metadata) HasDomain(d string) bool {
	x := m.M[d]
	if x == nil {
		return false
	}
	return len(x.Keys) > 0 || len(x.Raw) > 0
}

func (m *Metadata) DomainList() []string {
	var r []string
	for _, d := range m.Domains {
		if m.HasDomain(d) {
			r = append(r, d)
		}
	}
	return r
}

func (m *Metadata) Clone() *Metadata {
	n := NewMetadata()
	for _, d := range m.Domains {
		src := m.M[d]
		dst := n.dom(d, true)
		dst.Keys = append([]string{}, src.Keys...)
		for k, v := range src.Vals {
			dst.Vals[k] = v
		}
		if src.Raw != nil {
			dst.Raw = append([]string{}, src.Raw...)
		}
	}
	return n
}

