// Band is an in-memory raster band with lazy loading.
type Band struct {
	DS          *Dataset
	Index       int
	DataType    DataType
	BlockX      int
	BlockY      int
	data        []float64
	imag        []float64
	loader      func(b *Band) error
	loaded      bool
	HasNoData   bool
	NoData      float64
	NoDataI64   int64
	NoDataU64   uint64
	ColorInterp int
	ColorTable  *ColorTable
	Description string
	MD          *Metadata
	HasOffset   bool
	Offset      float64
	HasScale    bool
	Scale       float64
	Unit        string
	Categories  []string
	Overviews   []*Band
	MaskBand    *Band // per-dataset or per-band mask (for GTiff internal masks)
	MaskFlags   int
	IsAlphaMask bool
	XSize       int
	YSize       int
	NBits       int
	Histograms  []*Histogram
	PixelType   string
	// for statistics computed
	statsComputed bool
}

type Histogram struct {
	Min, Max          float64
	Buckets           int
	IncludeOutOfRange bool
	Approx            bool
