}

func (b *Band) Width() int {
	if b.XSize > 0 {
		return b.XSize
	}
	return b.DS.XSize
}
func (b *Band) Height() int {
	if b.YSize > 0 {
		return b.YSize
	}
	return b.DS.YSize
}

func (b *Band) Load() error {
	if b.loaded {
		return nil
	}
	b.loaded = true
	if b.loader != nil {
		if err := b.loader(b); err != nil {
			return err
		}
	}
	n := b.Width() * b.Height()
	if b.data == nil {
		b.data = make([]float64, n)
	}
	if b.DataType.IsComplex() && b.imag == nil {
		b.imag = make([]float64, n)
	}
	return nil
}

func (b *Band) Data() []float64 {
	b.Load()
	return b.data
}

func (b *Band) Imag() []float64 {
	b.Load()
	if b.imag == nil {
		b.imag = make([]float64, b.Width()*b.Height())
	}
	return b.imag
}

func (b *Band) SetData(d []float64) {
	b.data = d
	b.loaded = true
}

func NewBand(ds *Dataset, idx int, dt DataType) *Band {
	return &Band{DS: ds, Index: idx, DataType: dt, MD: NewMetadata(), Scale: 1, BlockX: ds.XSize, BlockY: 1, MaskFlags: GMF_ALL_VALID}
}

const (
	GMF_ALL_VALID   = 0x01
	GMF_PER_DATASET = 0x02
	GMF_ALPHA       = 0x04
	GMF_NODATA      = 0x08
)

// Dataset generic container for raster and vector.
type Dataset struct {
	Name        string
	Driver      *Driver
	XSize       int
	YSize       int
	Bands       []*Band
	GT          [6]float64
	HasGT       bool
	SRS         *SRS
	GCPs        []GCP
	GCPSRS      *SRS
	MD          *Metadata
	Layers      []*Layer
	FileList    []string
	Update      bool
	OnClose     func(ds *Dataset) error
	PAMDirty    bool
	PAMFile     string
	PAMLoaded   bool
	Subdatasets []string
	MaskBand    *Band // dataset-level mask (per dataset)
	Interleave  string
	Extra       map[string]interface{}
	closed      bool
	// vector specific
	Description string
	StyleTable  string
}

func NewDataset(name string, x, y int) *Dataset {
	return &Dataset{Name: name, XSize: x, YSize: y, MD: NewMetadata(), GT: [6]float64{0, 1, 0, 0, 0, 1}, Extra: map[string]interface{}{}}
}

func (ds *Dataset) AddBand(dt DataType) *Band {
	b := NewBand(ds, len(ds.Bands)+1, dt)
	ds.Bands = append(ds.Bands, b)
	return b
}

func (ds *Dataset) Close() error {
	if ds == nil || ds.closed {
		return nil
	}
	ds.closed = true
	var err error
	if ds.OnClose != nil {
		err = ds.OnClose(ds)
	}
	if ds.PAMDirty {
		writePAM(ds)
	}
	return err
}

func (ds *Dataset) IsRaster() bool { return ds.XSize > 0 || len(ds.Bands) > 0 || ds.Driver != nil && ds.Driver.Raster && !ds.Driver.Vector }
func (ds *Dataset) IsVector() bool { return len(ds.Layers) > 0 || (ds.Driver != nil && ds.Driver.Vector && !ds.Driver.Raster) }

func (ds *Dataset) GetLayerByName(name string) *Layer {
	for _, l := range ds.Layers {
		if l.Name == name {
			return l
		}
	}
	for _, l := range ds.Layers {
		if strings.EqualFold(l.Name, name) {
			return l
		}
	}
	return nil
}

