		return d.CanCopy
	case "DCAP_OPEN":
		return d.CanOpen
	case "DCAP_UPDATE":
		return d.CanUpdate
	}
	return false
}

var drivers []*Driver

func registerDriver(d *Driver) { drivers = append(drivers, d) }

func getDriverByName(name string) *Driver {
	for _, d := range drivers {
		if strings.EqualFold(d.ShortName, name) {
			return d
		}
	}
	return nil
}

type OpenInfo struct {
	Filename   string
	Header     []byte
	Exists     bool
	IsDir      bool
	Update     bool
	Raster     bool
	Vector     bool
	OpenOpts   []string
	AllowedDrv []string
}

const (
	OF_RASTER = 1
	OF_VECTOR = 2
	OF_MDIM   = 4
	OF_UPDATE = 8
)

// OpenDataset opens a dataset. flags: OF_RASTER|OF_VECTOR. Reports errors like GDALOpenEx.
func OpenDataset(name string, flags int, allowed []string, openOpts []string, report bool) *Dataset {
	oi := &OpenInfo{Filename: name, Raster: flags&OF_RASTER != 0, Vector: flags&OF_VECTOR != 0, Update: flags&OF_UPDATE != 0, OpenOpts: openOpts, AllowedDrv: allowed}
	st, err := os.Stat(name)
	if err == nil {
		oi.Exists = true
		oi.IsDir = st.IsDir()
		if !oi.IsDir {
			f, e2 := os.Open(name)
			if e2 == nil {
				buf := make([]byte, 1024)
				n, _ := f.Read(buf)
				oi.Header = buf[:n]
				f.Close()
			}
		}
	}
	for _, d := range drivers {
		if !d.CanOpen || d.Open == nil {
			continue
		}
		if len(allowed) > 0 {
			ok := false
			for _, a := range allowed {
				if strings.EqualFold(a, d.ShortName) {
					ok = true
				}
			}
			if !ok {
				continue
			}
		}
		if (oi.Raster && d.Raster) || (oi.Vector && d.Vector) {
		} else {
			continue
		}
		if d.Identify != nil && !d.Identify(oi) {
			continue
		}
		ds, err := d.Open(oi)
		if err != nil {
			if report {
				if oe, ok := err.(*openErr); ok {
					CPLError(CE_Failure, oe.code, "%s", oe.msg)
				}
			}
			return nil
		}
		if ds != nil {
			if ds.Driver == nil {
				ds.Driver = d
			}
			if ds.Name == "" {
				ds.Name = name
			}
			return ds
		}
	}
	if report {
		if !oi.Exists && !strings.HasPrefix(name, "/vsi") {
			CPLError(CE_Failure, CPLE_OpenFailed, "%s: No such file or directory", name)
		} else {
			CPLError(CE_Failure, CPLE_OpenFailed, "`%s' not recognized as being in a supported file format.", name)
		}
	}
	return nil
}

type openErr struct {
	code int
	msg  string
}

func (e *openErr) Error() string { return e.msg }

func newOpenErr(code int, format string, args ...interface{}) error {
	return &openErr{code: code, msg: cfmt(format, args...)}
}

func fileExt(name string) string {
	e := filepath.Ext(name)
	if e == "" {
		return ""
	}
	return strings.ToLower(e[1:])
}

func sortStrings(s []string) []string {
	r := append([]string{}, s...)
	sort.Strings(r)
	return r
}
