import "C"

import (
	"unsafe"
)

var projAvailable bool

func initProj() {
	if projAvailable {
		return
	}
	projAvailable = C.proj_load() != 0
}

type pjPtr = unsafe.Pointer

func cstr(s string) *C.char { return C.CString(s) }

func gostr(p *C.char) string {
	if p == nil {
		return ""
	}
	return C.GoString(p)
}

func pjCreate(s string) pjPtr {
	if !projAvailable {
		return nil
	}
	cs := cstr(s)
	defer C.free(unsafe.Pointer(cs))
	return pjPtr(C.c_create(cs))
}

func pjCreateFromWKT(s string) pjPtr {
	if !projAvailable {
		return nil
	}
	cs := cstr(s)
	defer C.free(unsafe.Pointer(cs))
	return pjPtr(C.c_create_from_wkt(cs))
}

// category: 0 ellipsoid,1 prime meridian,2 datum,3 crs,4 coordop
func pjCreateFromDB(auth, code string, cat int) pjPtr {
	if !projAvailable {
		return nil
	}
	a := cstr(auth)
	c := cstr(code)
	defer C.free(unsafe.Pointer(a))
	defer C.free(unsafe.Pointer(c))
	return pjPtr(C.c_create_from_db(a, c, C.int(cat)))
}

func pjDestroy(p pjPtr) {
	if p != nil {
		C.c_destroy(p)
	}
}

