	}
	m := 0
	if multiline {
		m = 1
	}
	return gostr(C.c_as_wkt(p, C.int(typ), C.int(m), 1))
}

func pjAsWKTOpts(p pjPtr, typ int, opts ...string) string {
	if p == nil {
		return ""
	}
	var cs [3]*C.char
	for i := 0; i < 3 && i < len(opts); i++ {
		cs[i] = cstr(opts[i])
		defer C.free(unsafe.Pointer(cs[i]))
	}
	return gostr(C.c_as_wkt_opts(p, C.int(typ), cs[0], cs[1], cs[2]))
}

