type axisInfo struct {
	Name, Abbrev, Dir string
	Conv              float64
	UnitName          string
	UnitAuth          string
	UnitCode          string
}

func pjAxes(crs pjPtr) ([]axisInfo, int) {
	if crs == nil {
		return nil, -1
	}
	cs := C.c_crs_cs(crs)
	if cs == nil {
		return nil, -1
	}
	defer C.c_destroy(cs)
	n := int(C.c_cs_axis_count(cs))
	typ := int(C.c_cs_type(cs))
	var res []axisInfo
	for i := 0; i < n; i++ {
		var name, abbr, dir, uname, uauth, ucode *C.char
		var conv C.double
		C.c_cs_axis_info(cs, C.int(i), &name, &abbr, &dir, &conv, &uname, &uauth, &ucode)
		res = append(res, axisInfo{gostr(name), gostr(abbr), gostr(dir), float64(conv), gostr(uname), gostr(uauth), gostr(ucode)})
	}
	return res, typ
}

