func pjParams(op pjPtr) []projParam {
	if op == nil {
		return nil
	}
	n := int(C.c_param_count(op))
	var res []projParam
	for i := 0; i < n; i++ {
		var name, auth, code, vs, un, ua, uc, ucat *C.char
		var val, conv C.double
		C.c_param(op, C.int(i), &name, &auth, &code, &val, &vs, &conv, &un, &ua, &uc, &ucat)
		res = append(res, projParam{gostr(name), gostr(auth), gostr(code), float64(val), gostr(vs), float64(conv), gostr(un), gostr(ua), gostr(uc), gostr(ucat)})
	}
	return res
}

