func pjTrans(op pjPtr, dir int, x, y, z float64) (float64, float64, float64, bool) {
	cx, cy, cz, ct := C.double(x), C.double(y), C.double(z), C.double(0)
	e := C.c_trans(op, C.int(dir), &cx, &cy, &cz, &ct)
	return float64(cx), float64(cy), float64(cz), e == 0
}

