type identifyResult struct {
	Obj  pjPtr
	Conf int
}

func pjIdentify(p pjPtr, auth string) []identifyResult {
	if p == nil {
		return nil
	}
	var ca *C.char
	if auth != "" {
		ca = cstr(auth)
		defer C.free(unsafe.Pointer(ca))
	}
	var conf *C.int
	l := C.c_identify(p, ca, &conf)
	if l == nil {
		return nil
	}
	n := int(C.c_list_count(l))
	var res []identifyResult
	for i := 0; i < n; i++ {
		o := C.c_list_get(l, C.int(i))
		c := 0
		if conf != nil {
			c = int(C.c_int_at(conf, C.int(i)))
		}
		res = append(res, identifyResult{pjPtr(o), c})
	}
	C.c_list_destroy(l)
	if conf != nil {
		C.c_int_list_destroy(conf)
	}
	return res
}

