import "C"

import (
	"unsafe"
)

var projAvailable bool

func initProj() {
	if projAvailable {
		return
	}
	projAvailable = C.proj_load() != 0
}

type pjPtr = unsafe.Pointer

func cstr(s string) *C.char { return C.CString(s) }

func gostr(p *C.char) string {
	if p == nil {
		return ""
	}
	return C.GoString(p)
}

func pjCreate(s string) pjPtr {
	if !projAvailable {
		return nil
	}
	cs := cstr(s)
	defer C.free(unsafe.Pointer(cs))
	return pjPtr(C.c_create(cs))
}

func pjCreateFromWKT(s string) pjPtr {
	if !projAvailable {
		return nil
	}
	cs := cstr(s)
	defer C.free(unsafe.Pointer(cs))
	return pjPtr(C.c_create_from_wkt(cs))
}

// category: 0 ellipsoid,1 prime meridian,2 datum,3 crs,4 coordop
func pjCreateFromDB(auth, code string, cat int) pjPtr {
	if !projAvailable {
		return nil
	}
	a := cstr(auth)
	c := cstr(code)
	defer C.free(unsafe.Pointer(a))
	defer C.free(unsafe.Pointer(c))
	return pjPtr(C.c_create_from_db(a, c, C.int(cat)))
}

func pjDestroy(p pjPtr) {
	if p != nil {
		C.c_destroy(p)
	}
}

const (
	PJ_WKT2_2015            = 0
	PJ_WKT2_2015_SIMPLIFIED = 1
	PJ_WKT2_2019            = 2
	PJ_WKT2_2019_SIMPLIFIED = 3
	PJ_WKT1_GDAL            = 4
	PJ_WKT1_ESRI            = 5
)

func pjAsWKT(p pjPtr, typ int, multiline bool) string {
	if p == nil {
		return ""
	}
	m := 0
	if multiline {
		m = 1
	}
	return gostr(C.c_as_wkt(p, C.int(typ), C.int(m), 1))
}

func pjAsWKTOpts(p pjPtr, typ int, opts ...string) string {
	if p == nil {
		return ""
	}
	var cs [3]*C.char
	for i := 0; i < 3 && i < len(opts); i++ {
		cs[i] = cstr(opts[i])
		defer C.free(unsafe.Pointer(cs[i]))
	}
	return gostr(C.c_as_wkt_opts(p, C.int(typ), cs[0], cs[1], cs[2]))
}

func pjAsPROJJSON(p pjPtr, multiline bool) string {
	if p == nil {
		return ""
	}
	m := 0
	if multiline {
		m = 1
	}
	return gostr(C.c_as_projjson(p, C.int(m)))
}

func pjAsPROJJSONOpts(p pjPtr, opts ...string) string {
	if p == nil {
		return ""
	}
	var cs [2]*C.char
	for i := 0; i < 2 && i < len(opts); i++ {
		cs[i] = cstr(opts[i])
		defer C.free(unsafe.Pointer(cs[i]))
	}
	return gostr(C.c_as_projjson_opts(p, cs[0], cs[1]))
}

func pjAsPROJString(p pjPtr) string {
	if p == nil {
		return ""
	}
	return gostr(C.c_as_proj_string(p))
}

func pjName(p pjPtr) string {
	if p == nil {
		return ""
	}
	return gostr(C.c_get_name(p))
}

func pjIDAuth(p pjPtr, i int) string {
	if p == nil {
		return ""
	}
