)

type SRS struct {
	pj      pjPtr
	mapping []int
	epoch   float64
	// set when mapping was explicitly set
	mappingSet bool
}

func newSRSFromPJ(p pjPtr) *SRS {
	if p == nil {
		return nil
	}
	s := &SRS{pj: p}
	s.setTraditionalMapping()
	return s
}

func (s *SRS) Clone() *SRS {
	if s == nil {
		return nil
	}
	n := &SRS{pj: pjCreateFromWKT(s.WKTForClone()), mapping: append([]int{}, s.mapping...), epoch: s.epoch, mappingSet: s.mappingSet}
	if n.pj == nil {
		n.pj = s.pj
	}
	return n
}

func (s *SRS) WKTForClone() string {
	return pjAsPROJJSON(s.pj, false)
}

func srsFromEPSG(code int) *SRS {
	p := pjCreateFromDB("EPSG", strconv.Itoa(code), 3)
	if p == nil {
		return nil
	}
	return newSRSFromPJ(p)
}

func srsFromWKT(wkt string) *SRS {
	p := pjCreateFromWKT(wkt)
	if p == nil {
		return nil
	}
	return newSRSFromPJ(p)
}

var wellKnownGeog = map[string]string{
	"WGS84": "EPSG:4326", "WGS72": "EPSG:4322", "NAD27": "EPSG:4267", "NAD83": "EPSG:4269",
	"CRS84": "OGC:CRS84", "CRS27": "OGC:CRS27", "CRS83": "OGC:CRS83",
}

// srsFromUserInput mimics OGRSpatialReference::SetFromUserInput.
func srsFromUserInput(def string) (*SRS, bool) {
	d := strings.TrimSpace(def)
	if d == "" {
		return nil, false
	}
	if v, ok := wellKnownGeog[strings.ToUpper(d)]; ok {
		d = v
	}
	if strings.HasPrefix(strings.ToUpper(d), "EPSGA:") {
		d = "EPSG:" + d[6:]
	}
	if isIntegerStr(d) {
		return nil, false
	}
	// file containing a definition
	if !strings.ContainsAny(d, "[{:+ ") {
		if data, err := os.ReadFile(d); err == nil {
			return srsFromUserInput(string(data))
		}
	}
	lower := strings.ToLower(d)
	if strings.HasPrefix(lower, "+") || strings.Contains(lower, "+proj=") || strings.HasPrefix(lower, "proj=") {
		if !strings.Contains(lower, "+type=crs") && !strings.Contains(lower, "type=crs") {
			d = d + " +type=crs"
		}
		if strings.Contains(lower, "+init=") {
			// handled by PROJ
		}
	}
	p := pjCreate(d)
	if p == nil {
		return nil, false
	}
	if !pjIsCRS(p) {
		pjDestroy(p)
		return nil, false
	}
	// bound CRS from +towgs84 etc. are kept as is
	s := newSRSFromPJ(p)
	return s, true
}

func (s *SRS) setTraditionalMapping() {
	axes, _ := s.horizontalAxes()
	n := s.AxisCount()
	m := make([]int, n)
	for i := range m {
		m[i] = i + 1
	}
	if len(axes) >= 2 {
		d0 := strings.ToLower(axes[0].Dir)
		d1 := strings.ToLower(axes[1].Dir)
		if (d0 == "north" || d0 == "south") && (d1 == "east" || d1 == "west") {
			m[0], m[1] = 2, 1
		}
	}
	s.mapping = m
}

func (s *SRS) SetAuthorityCompliantMapping() {
	n := s.AxisCount()
	m := make([]int, n)
	for i := range m {
		m[i] = i + 1
	}
	s.mapping = m
}

func (s *SRS) AxisCount() int {
	if s == nil || s.pj == nil {
		return 0
	}
	t := pjType(s.pj)
	if t == PJ_TYPE_COMPOUND_CRS {
		n := 0
		for i := 0; i < 2; i++ {
			sub := pjSubCRS(s.pj, i)
			if sub != nil {
				n += (&SRS{pj: sub}).AxisCount()
				pjDestroy(sub)
			}
		}
		return n
	}
	if t == PJ_TYPE_BOUND_CRS {
		src := pjSourceCRS(s.pj)
		defer pjDestroy(src)
		return (&SRS{pj: src}).AxisCount()
	}
	axes, _ := pjAxes(s.pj)
	return len(axes)
}

// horizontalCRS returns the horizontal component (not to be destroyed if same as s.pj)
func (s *SRS) horizontalPJ() (pjPtr, bool) {
	t := pjType(s.pj)
	if t == PJ_TYPE_COMPOUND_CRS {
		return pjSubCRS(s.pj, 0), true
	}
	if t == PJ_TYPE_BOUND_CRS {
		src := pjSourceCRS(s.pj)
		if pjType(src) == PJ_TYPE_COMPOUND_CRS {
			h := pjSubCRS(src, 0)
			pjDestroy(src)
			return h, true
		}
		return src, true
	}
	return s.pj, false
}

func (s *SRS) horizontalAxes() ([]axisInfo, int) {
	if s == nil || s.pj == nil {
		return nil, -1
	}
	h, own := s.horizontalPJ()
	if own {
		defer pjDestroy(h)
	}
	return pjAxes(h)
}

func (s *SRS) Name() string { return pjName(s.pj) }

func (s *SRS) IsGeographic() bool {
	if s == nil {
		return false
	}
	h, own := s.horizontalPJ()
	if own {
		defer pjDestroy(h)
	}
	t := pjType(h)
	return t == PJ_TYPE_GEOGRAPHIC_2D_CRS || t == PJ_TYPE_GEOGRAPHIC_3D_CRS || t == PJ_TYPE_GEOGRAPHIC_CRS
}

func (s *SRS) IsProjected() bool {
	if s == nil {
		return false
	}
	h, own := s.horizontalPJ()
	if own {
		defer pjDestroy(h)
