func (s *SRS) EPSGCode() int {
	a, c := s.AuthID()
	if strings.EqualFold(a, "EPSG") {
		v, _ := strconv.Atoi(c)
		return v
	}
	return 0
}

func (s *SRS) TypeString() string {
	t := pjType(s.pj)
	base := func(p pjPtr) string {
		switch pjType(p) {
		case PJ_TYPE_GEOGRAPHIC_2D_CRS:
			return "Geographic 2D"
		case PJ_TYPE_GEOGRAPHIC_3D_CRS:
			return "Geographic 3D"
		case PJ_TYPE_PROJECTED_CRS:
			return "Projected"
		case PJ_TYPE_GEOCENTRIC_CRS:
			return "Geocentric"
		case PJ_TYPE_VERTICAL_CRS:
			return "Vertical"
		case PJ_TYPE_ENGINEERING_CRS:
			return "Engineering"
		case PJ_TYPE_TEMPORAL_CRS:
			return "Temporal"
		}
		return "Unknown"
	}
	if t == PJ_TYPE_COMPOUND_CRS {
		h := pjSubCRS(s.pj, 0)
		defer pjDestroy(h)
		b := base(h)
		if strings.HasPrefix(b, "Geographic") {
			b = "Geographic"
		}
		return "Compound of " + b
	}
	if t == PJ_TYPE_BOUND_CRS {
		src := pjSourceCRS(s.pj)
		defer pjDestroy(src)
		return (&SRS{pj: src}).TypeString()
	}
	return base(s.pj)
}

func normAlnum(s string) string {
	var b strings.Builder
	for _, c := range strings.ToLower(s) {
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
			b.WriteRune(c)
		}
	}
	return b.String()
}

// Summary returns the GDAL "summary" lines (without trailing newline) or "" if no ID.
func (s *SRS) Summary() []string {
	auth, code := s.AuthID()
	if auth == "" || code == "" {
		return nil
	}
	var lines []string
	lines = append(lines, "  - name: "+s.Name())
	id := auth + ":" + code
	if i := strings.IndexByte(auth, '_'); i >= 0 {
