func needsSwap(s *SRS) bool {
	return len(s.mapping) >= 2 && s.mapping[0] == 2 && s.mapping[1] == 1
}

func NewCoordTransform(src, dst *SRS) *CoordTransform {
	if src == nil || dst == nil {
		return nil
	}
	op := pjCRSToCRS(src.pj, dst.pj)
	if op == nil {
		return nil
	}
	return &CoordTransform{op: op, src: src, dst: dst, srcSwap: needsSwap(src), dstSwap: needsSwap(dst)}
}

// Transform transforms in place, returns per-point success.
func (ct *CoordTransform) Transform(x, y, z []float64) []bool {
	ok := make([]bool, len(x))
	for i := range x {
		ax, ay := x[i], y[i]
		if ct.srcSwap {
			ax, ay = ay, ax
		}
		zz := 0.0
		if z != nil {
			zz = z[i]
		}
		rx, ry, rz, good := pjTrans(ct.op, 1, ax, ay, zz)
		if math.IsInf(rx, 0) || math.IsInf(ry, 0) || math.IsNaN(rx) || math.IsNaN(ry) || rx == math.MaxFloat64 {
			good = false
		}
		if ct.dstSwap {
			rx, ry = ry, rx
		}
		if good {
			x[i], y[i] = rx, ry
			if z != nil {
				z[i] = rz
			}
		} else {
			x[i], y[i] = math.Inf(1), math.Inf(1)
		}
		ok[i] = good
	}
	return ok
}

