package main

import (
	"os"
	"strings"
)

// noAutoOpen lists "path argname" for which input datasets are not opened during validation.
var noAutoOpen = map[string]bool{
	"raster calc input":       true,
	"raster mosaic input":     true,
	"raster stack input":      true,
	"vector concat input":     true,
	"raster index input":      true,
	"vector index input":      true,
	"dataset identify filename": true,
	"raster pansharpen spectral": true,
}

// declOrder returns args in (approximate) declaration order.
func (a *Alg) declOrder() []*ArgDef {
	var inputs, outs, inouts []*ArgDef
	for _, ad := range a.Def.Args {
		switch ad.Section {
		case "input_arguments":
			inputs = append(inputs, ad)
		case "output_arguments":
			outs = append(outs, ad)
		case "input_output_arguments":
			inouts = append(inouts, ad)
		}
	}
	if len(inouts) == 0 {
		return append(inputs, outs...)
	}
	pos := len(inputs)
	for i, ad := range inputs {
		if ad.Name == "output-format" || ad.Name == "creation-option" || ad.Name == "overwrite" {
			pos = i
			break
		}
	}
	var res []*ArgDef
	res = append(res, inputs[:pos]...)
	res = append(res, inouts...)
	res = append(res, inputs[pos:]...)
	res = append(res, outs...)
	return res
}

func (a *Alg) datasetFlags(ad *ArgDef) int {
	f := 0
	for _, t := range ad.DatasetType {
		switch t {
		case "raster":
			f |= OF_RASTER
		case "vector":
			f |= OF_VECTOR
		case "multidim_raster":
			f |= OF_MDIM
		}
	}
	return f
}

func (a *Alg) existsMessage() string {
	var opts []string
	for _, n := range []string{"overwrite", "overwrite-layer", "append", "update"} {
		if _, ok := a.Vals[n]; ok {
			opts = append(opts, "--"+n)
		}
	}
	return strings.Join(opts, "/")
}

func datasetExists(name string) bool {
	if strings.HasPrefix(name, "/vsimem/") {
		return vsimemExists(name)
	}
	_, err := os.Stat(name)
	return err == nil
}

// Validate implements the post-parse validation phase.
func (a *Alg) Validate() bool {
	ok := true
	key := strings.Join(a.Def.Path, " ")
	for _, ad := range a.declOrder() {
		v := a.Vals[ad.Name]
		if v == nil {
			continue
		}
		if (ad.Type == "dataset" || ad.Type == "dataset_list") && v.Set {
			if ad.Section == "input_arguments" {
				if !noAutoOpen[key+" "+ad.Name] && hasFlag(ad.InputFlags, "dataset") && preOpenHook(a, ad) {
					v.DSs = make([]*Dataset, len(v.DSNames))
					for i, n := range v.DSNames {
						ds := a.openInputDataset(ad, n)
						if ds == nil {
							ok = false
						}
						v.DSs[i] = ds
					}
				}
			} else if ad.Section == "input_output_arguments" {
				if !a.outputExistsOK(ad, v) {
					ok = false
				}
			}
		}
		if ad.Required && !v.Set && !(ad.Type == "dataset" && len(v.DSs) > 0) {
			a.ReportError(CPLE_AppDefined, "Required argument '%s' has not been specified.", ad.Name)
			ok = false
		}
	}
	// mutual exclusion
	groups := map[string]string{}
	for _, ad := range a.declOrder() {
		v := a.Vals[ad.Name]
		if ad.MutexGroup == "" || v == nil || !v.Set {
			continue
		}
		if prev, ok2 := groups[ad.MutexGroup]; ok2 {
			a.ReportError(CPLE_AppDefined, "Argument '%s' is mutually exclusive with '%s'.", ad.Name, prev)
			ok = false
		} else {
			groups[ad.MutexGroup] = ad.Name
		}
	}
	if ok {
		if f, has := extraValidators[key]; has {
			if !f(a) {
				ok = false
			}
		}
	}
	return ok
}

var extraValidators = map[string]func(a *Alg) bool{}

func preOpenHook(a *Alg, ad *ArgDef) bool {
	return true
}

func hasFlag(l []string, f string) bool {
	for _, x := range l {
		if x == f {
			return true
		}
	}
	return false
}

func (a *Alg) openInputDataset(ad *ArgDef, name string) *Dataset {
	flags := a.datasetFlags(ad)
	var allowed []string
	if v := a.Vals["input-format"]; v != nil && ad.Name == "input" {
		allowed = v.StrList
	}
	var oo []string
	if v := a.Vals["open-option"]; v != nil && ad.Name == "input" {
		oo = v.StrList
	}
	if a.Vals["update"] != nil && a.Vals["update"].Bool && ad.Name == "input" {
		flags |= OF_UPDATE
	}
	return OpenDataset(name, flags, allowed, oo, true)
}

func (a *Alg) outputExistsOK(ad *ArgDef, v *ArgVal) bool {
	if len(v.DSNames) == 0 {
		return true
	}
	name := v.DSNames[0]
	if a.Bool("overwrite") || a.Bool("append") || a.Bool("update") || a.Bool("overwrite-layer") || a.Bool("upsert") {
		return true
	}
	if _, has := a.Vals["overwrite"]; !has {
		return true
	}
	if a.Str("output-format") != "" && strings.EqualFold(a.Str("output-format"), "MEM") {
		return true
	}
	if datasetExists(name) {
		a.ReportError(CPLE_AppDefined, "Dataset '%s' already exists. You may specify the %s option.", name, a.existsMessage())
		return false
	}
	return true
}
