// setTimeValidate performs validation actions attached to scalar args at set time.
func (a *Alg) setTimeValidate(ad *ArgDef, val string) bool {
	switch {
	case ad.Name == "output-format" && ad.Type == "string":
		return a.validateDriverName(ad, val)
	case strings.Contains(ad.Description, "('none', numeric value, 'nan', 'inf', '-inf')"):
		if !validNodataString(val) {
			a.ReportError(CPLE_IllegalArg, "Value of '%s' should be 'none', a numeric value, 'nan', 'inf' or '-inf'", ad.Name)
			return false
		}
	}
	return true
}

func validNodataString(v string) bool {
	l := strings.ToLower(v)
	if l == "none" || l == "nan" || l == "inf" || l == "-inf" || l == "+inf" {
		return true
	}
	_, ok := parseRealStrict(v)
	return ok
}

func requiredCaps(ad *ArgDef) []string {
	if ad.JSON == nil {
		return nil
	}
	md := ad.JSON.Get("metadata")
	if md == nil {
		return nil
	}
	return strListOf(md.Get("required_capabilities"))
}

func (a *Alg) validateDriverName(ad *ArgDef, val string) bool {
	if strings.Contains(ad.Description, "\"GDALG\" allowed") && strings.EqualFold(val, "GDALG") {
		return true
	}
	if strings.EqualFold(val, "stream") && strings.Contains(ad.Description, "stream") {
		return true
	}
	d := getDriverByName(val)
	if d == nil {
		a.ReportError(CPLE_AppDefined, "Invalid value for argument '%s'. Driver '%s' does not exist.", ad.Name, val)
		return false
	}
	for _, c := range requiredCaps(ad) {
		if !d.HasCap(c) {
			a.ReportError(CPLE_AppDefined, "Invalid value for argument '%s'. Driver '%s' does not expose the required '%s' capability.", ad.Name, val, c)
			return false
		}
	}
	return true
}

func (a *Alg) listApplyValidate(ad *ArgDef, values []string) bool {
	switch {
	case ad.Name == "input-format":
		for _, v := range values {
			if !a.validateDriverName(ad, v) {
				return false
			}
		}
	case ad.Metavar == "<KEY>=<VALUE>" && ad.Name != "config":
		for _, v := range values {
			if !strings.Contains(v, "=") {
				a.ReportError(CPLE_AppDefined, "Invalid value for argument '%s'. <KEY>=<VALUE> expected", ad.Name)
				return false
			}
		}
	}
	return true
}
