package main

import (
	"encoding/binary"
	"math"
	"strconv"
	"strings"
)

const (
	wkbUnknown            = 0
	wkbPoint              = 1
	wkbLineString         = 2
	wkbPolygon            = 3
	wkbMultiPoint         = 4
	wkbMultiLineString    = 5
	wkbMultiPolygon       = 6
	wkbGeometryCollection = 7
	wkbCircularString     = 8
	wkbCompoundCurve      = 9
	wkbCurvePolygon       = 10
	wkbMultiCurve         = 11
	wkbMultiSurface       = 12
	wkbCurve              = 13
	wkbSurface            = 14
	wkbPolyhedralSurface  = 15
	wkbTIN                = 16
	wkbTriangle           = 17
	wkbNone               = 100
	wkbLinearRing         = 101
)

// Geometry type encoding: flat + 1000 (Z) + 2000 (M), like ISO codes.
func geomTypeFlat(t int) int {
	if t == wkbNone || t == wkbLinearRing {
		return t
	}
	t &^= 0x80000000
	return t % 1000
}
func geomTypeHasZ(t int) bool {
	if t == wkbNone || t == wkbLinearRing {
		return false
	}
	return (t%10000)/1000 == 1 || (t%10000)/1000 == 3 || t&0x80000000 != 0
}
func geomTypeHasM(t int) bool {
	if t == wkbNone || t == wkbLinearRing {
		return false
	}
	return (t%10000)/1000 == 2 || (t%10000)/1000 == 3
}
func makeGeomType(flat int, z, m bool) int {
	if flat == wkbNone || flat == wkbLinearRing {
		return flat
	}
	t := flat
	if z {
		t += 1000
	}
	if m {
		t += 2000
	}
	return t
}

var flatTypeNames = map[int]string{
	wkbUnknown: "Unknown (any)", wkbPoint: "Point", wkbLineString: "Line String", wkbPolygon: "Polygon",
	wkbMultiPoint: "Multi Point", wkbMultiLineString: "Multi Line String", wkbMultiPolygon: "Multi Polygon",
	wkbGeometryCollection: "Geometry Collection", wkbCircularString: "Circular String", wkbCompoundCurve: "Compound Curve",
	wkbCurvePolygon: "Curve Polygon", wkbMultiCurve: "Multi Curve", wkbMultiSurface: "Multi Surface",
	wkbCurve: "Curve", wkbSurface: "Surface", wkbPolyhedralSurface: "Polyhedral Surface", wkbTIN: "TIN", wkbTriangle: "Triangle",
	wkbNone: "None", wkbLinearRing: "Linear Ring",
}

// OGRGeometryTypeToName
func geomTypeName(t int) string {
	flat := geomTypeFlat(t)
	z := geomTypeHasZ(t)
	m := geomTypeHasM(t)
	n, ok := flatTypeNames[flat]
	if !ok {
		return "Unrecognized: " + strconv.Itoa(t)
	}
	if flat == wkbUnknown {
		if z && m {
			return "3D Measured Unknown (any)"
		} else if z {
			return "3D Unknown (any)"
		} else if m {
			return "Measured Unknown (any)"
		}
		return n
	}
	if z && m {
		return "3D Measured " + n
	}
	if z {
		return "3D " + n
	}
	if m {
		return "Measured " + n
	}
	return n
}

var wktNames = map[int]string{
	wkbPoint: "POINT", wkbLineString: "LINESTRING", wkbPolygon: "POLYGON", wkbMultiPoint: "MULTIPOINT",
	wkbMultiLineString: "MULTILINESTRING", wkbMultiPolygon: "MULTIPOLYGON", wkbGeometryCollection: "GEOMETRYCOLLECTION",
	wkbCircularString: "CIRCULARSTRING", wkbCompoundCurve: "COMPOUNDCURVE", wkbCurvePolygon: "CURVEPOLYGON",
	wkbMultiCurve: "MULTICURVE", wkbMultiSurface: "MULTISURFACE", wkbPolyhedralSurface: "POLYHEDRALSURFACE",
	wkbTIN: "TIN", wkbTriangle: "TRIANGLE", wkbCurve: "CURVE", wkbSurface: "SURFACE", wkbUnknown: "GEOMETRY",
	wkbLinearRing: "LINEARRING",
}

// Type name as used in JSON outputs ("LineString", "MultiPolygon25D"?).
var jsonTypeNames = map[int]string{
	wkbUnknown: "Unknown", wkbPoint: "Point", wkbLineString: "LineString", wkbPolygon: "Polygon",
	wkbMultiPoint: "MultiPoint", wkbMultiLineString: "MultiLineString", wkbMultiPolygon: "MultiPolygon",
	wkbGeometryCollection: "GeometryCollection", wkbCircularString: "CircularString", wkbCompoundCurve: "CompoundCurve",
	wkbCurvePolygon: "CurvePolygon", wkbMultiCurve: "MultiCurve", wkbMultiSurface: "MultiSurface", wkbCurve: "Curve",
	wkbSurface: "Surface", wkbPolyhedralSurface: "PolyhedralSurface", wkbTIN: "Tin", wkbTriangle: "Triangle",
	wkbNone: "None",
}

func geomTypeJSONName(t int) string {
	flat := geomTypeFlat(t)
	n := jsonTypeNames[flat]
	if flat == wkbNone {
		return "None"
	}
	if geomTypeHasZ(t) && geomTypeHasM(t) {
		return n + "ZM"
	}
	if geomTypeHasZ(t) {
		return n + "Z"
	}
	if geomTypeHasM(t) {
		return n + "M"
	}
	return n
}

type Pt struct{ X, Y, Z, M float64 }

type Geom struct {
	T     int // flat type
	Z, M  bool
	Pts   []Pt
	Parts []*Geom
}

func (g *Geom) Type() int { return makeGeomType(g.T, g.Z, g.M) }

func (g *Geom) Clone() *Geom {
	if g == nil {
		return nil
	}
	n := &Geom{T: g.T, Z: g.Z, M: g.M}
	if g.Pts != nil {
		n.Pts = append([]Pt{}, g.Pts...)
	}
	for _, p := range g.Parts {
		n.Parts = append(n.Parts, p.Clone())
	}
	return n
}

func (g *Geom) IsEmpty() bool {
	if g == nil {
		return true
	}
	switch g.T {
	case wkbPoint, wkbLineString, wkbLinearRing, wkbCircularString:
		return len(g.Pts) == 0
	}
	for _, p := range g.Parts {
		if !p.IsEmpty() {
			return false
		}
	}
	return true
}

func (g *Geom) SetZ(z bool) {
	g.Z = z
	for _, p := range g.Parts {
		p.SetZ(z)
	}
	if !z {
		for i := range g.Pts {
			g.Pts[i].Z = 0
		}
	}
}

func (g *Geom) SetM(m bool) {
	g.M = m
	for _, p := range g.Parts {
		p.SetM(m)
	}
	if !m {
		for i := range g.Pts {
			g.Pts[i].M = 0
		}
	}
}

func (g *Geom) forEachPt(f func(p *Pt)) {
	for i := range g.Pts {
		f(&g.Pts[i])
	}
	for _, p := range g.Parts {
		p.forEachPt(f)
	}
}

func (g *Geom) Envelope() Envelope {
	e := EmptyEnvelope()
	g.forEachPt(func(p *Pt) { e.MergePt(p.X, p.Y) })
	return e
}

func (g *Geom) Envelope3D() Envelope3D {
	e := Envelope3D{Envelope: EmptyEnvelope(), MinZ: math.Inf(1), MaxZ: math.Inf(-1)}
	g.forEachPt(func(p *Pt) {
		e.MergePt(p.X, p.Y)
		z := p.Z
		if !g.Z {
			z = 0
		}
		if z < e.MinZ {
			e.MinZ = z
		}
		if z > e.MaxZ {
			e.MaxZ = z
		}
	})
	return e
}

func (g *Geom) Dim() int {
	switch g.T {
	case wkbPoint, wkbMultiPoint:
		return 0
	case wkbLineString, wkbMultiLineString, wkbLinearRing, wkbCircularString, wkbCompoundCurve, wkbMultiCurve:
		return 1
	case wkbPolygon, wkbMultiPolygon, wkbCurvePolygon, wkbMultiSurface, wkbPolyhedralSurface, wkbTIN, wkbTriangle:
		return 2
	case wkbGeometryCollection:
		d := 0
		for _, p := range g.Parts {
			if pd := p.Dim(); pd > d {
				d = pd
			}
		}
		return d
	}
	return 0
}

func NewPoint(x, y float64) *Geom { return &Geom{T: wkbPoint, Pts: []Pt{{X: x, Y: y}}} }
func NewPointZ(x, y, z float64) *Geom {
	return &Geom{T: wkbPoint, Z: true, Pts: []Pt{{X: x, Y: y, Z: z}}}
}

// ---------- WKT output ----------

// OGR formatting of a coordinate value (OGRFormatDouble with precision 15, 'g').
func ogrFormatDouble(v float64) string {
	if math.IsNaN(v) {
		return "nan"
	}
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	if v == math.Trunc(v) && math.Abs(v) < 1e15 {
		return strconv.FormatInt(int64(v), 10)
	}
	s := cfmt("%.15g", v)
	if strings.ContainsAny(s, "e") {
		return s
	}
	return s
}

func (g *Geom) wktCoords(p Pt) string {
	s := ogrFormatDouble(p.X) + " " + ogrFormatDouble(p.Y)
	if g.Z {
		s += " " + ogrFormatDouble(p.Z)
	}
	if g.M {
		s += " " + ogrFormatDouble(p.M)
	}
	return s
}

func (g *Geom) wktDimSuffix() string {
	if g.Z && g.M {
		return " ZM"
	}
	if g.Z {
		return " Z"
	}
	if g.M {
		return " M"
	}
	return ""
}

func (g *Geom) WKT() string {
	if g == nil {
		return ""
	}
	name := wktNames[g.T] + g.wktDimSuffix()
	if g.IsEmpty() {
		return name + " EMPTY"
	}
	return name + " " + g.wktBody()
}

func (g *Geom) wktBody() string {
	switch g.T {
	case wkbPoint:
		return "(" + g.wktCoords(g.Pts[0]) + ")"
	case wkbLineString, wkbLinearRing, wkbCircularString:
		var sb strings.Builder
		sb.WriteString("(")
		for i, p := range g.Pts {
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(g.wktCoords(p))
		}
		sb.WriteString(")")
		return sb.String()
	case wkbPolygon, wkbTriangle:
		var parts []string
		for _, r := range g.Parts {
			r.Z, r.M = g.Z, g.M
			parts = append(parts, r.wktBody())
		}
		return "(" + strings.Join(parts, ",") + ")"
	case wkbMultiPoint:
		var parts []string
		for _, p := range g.Parts {
			p.Z, p.M = g.Z, g.M
			if p.IsEmpty() {
				parts = append(parts, "EMPTY")
			} else {
				parts = append(parts, "("+g.wktCoords(p.Pts[0])+")")
			}
		}
		return "(" + strings.Join(parts, ",") + ")"
	case wkbMultiLineString, wkbMultiPolygon, wkbPolyhedralSurface, wkbTIN:
		var parts []string
		for _, p := range g.Parts {
			p.Z, p.M = g.Z, g.M
			if p.IsEmpty() {
				parts = append(parts, "EMPTY")
			} else {
				parts = append(parts, p.wktBody())
			}
		}
		return "(" + strings.Join(parts, ",") + ")"
	case wkbGeometryCollection, wkbCompoundCurve, wkbCurvePolygon, wkbMultiCurve, wkbMultiSurface:
		var parts []string
		for _, p := range g.Parts {
			p.Z, p.M = g.Z, g.M
			if (g.T == wkbCompoundCurve || g.T == wkbCurvePolygon || g.T == wkbMultiCurve || g.T == wkbMultiSurface) && (p.T == wkbLineString || p.T == wkbPolygon) {
				parts = append(parts, p.wktBody())
			} else {
				w := p.WKT()
				// strip dimension suffix for sub geometries? OGR keeps "POINT Z (...)" in collections
				parts = append(parts, w)
			}
		}
		return "(" + strings.Join(parts, ",") + ")"
	}
	return ""
}

// ---------- WKT parsing ----------

type wktParser struct {
	s   string
	pos int
}

func ParseWKT(s string) (*Geom, bool) {
	p := &wktParser{s: s}
	g, ok := p.parseGeom()
	if !ok {
		return nil, false
	}
	p.ws()
	return g, true
}

func (p *wktParser) ws() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t' || p.s[p.pos] == '\n' || p.s[p.pos] == '\r') {
		p.pos++
	}
}

func (p *wktParser) word() string {
	p.ws()
	st := p.pos
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') {
			p.pos++
		} else {
			break
		}
	}
	return strings.ToUpper(p.s[st:p.pos])
}

func (p *wktParser) peek() byte {
	p.ws()
	if p.pos < len(p.s) {
		return p.s[p.pos]
	}
	return 0
}

func (p *wktParser) expect(c byte) bool {
	if p.peek() == c {
		p.pos++
		return true
	}
	return false
}

func (p *wktParser) number() (float64, bool) {
	p.ws()
	f, n := strtod(p.s[p.pos:])
	if n == 0 {
		return 0, false
	}
	p.pos += n
	return f, true
}

func (p *wktParser) parseGeom() (*Geom, bool) {
	name := p.word()
	t := -1
	for k, v := range wktNames {
		if v == name {
			t = k
		}
	}
	if t < 0 {
		return nil, false
	}
	g := &Geom{T: t}
	// dimension
	save := p.pos
	d := p.word()
	switch d {
	case "Z":
		g.Z = true
	case "M":
		g.M = true
	case "ZM":
		g.Z, g.M = true, true
	case "EMPTY":
		return g, true
	case "":
	default:
		p.pos = save
	}
	save = p.pos
	if p.word() == "EMPTY" {
		return g, true
	}
	p.pos = save
	ok := p.parseBody(g)
	return g, ok
}

func (p *wktParser) parsePointList(g *Geom) bool {
	if !p.expect('(') {
		return false
	}
	for {
		pt, ok := p.parseCoord(g)
		if !ok {
			return false
		}
		g.Pts = append(g.Pts, pt)
		if p.expect(',') {
			continue
		}
		break
	}
	return p.expect(')')
}

func (p *wktParser) parseCoord(g *Geom) (Pt, bool) {
	var vals []float64
	for {
		c := p.peek()
		if c == ',' || c == ')' || c == 0 {
			break
		}
		v, ok := p.number()
		if !ok {
			return Pt{}, false
		}
		vals = append(vals, v)
	}
	if len(vals) < 2 {
		return Pt{}, false
	}
	pt := Pt{X: vals[0], Y: vals[1]}
	if len(vals) == 3 {
		if g.M && !g.Z {
			pt.M = vals[2]
		} else {
			pt.Z = vals[2]
			g.Z = true
		}
	}
	if len(vals) >= 4 {
		pt.Z = vals[2]
		pt.M = vals[3]
		g.Z, g.M = true, true
	}
	return pt, true
}

func (p *wktParser) parseBody(g *Geom) bool {
	switch g.T {
	case wkbPoint:
		if !p.expect('(') {
			return false
		}
		pt, ok := p.parseCoord(g)
		if !ok {
			return false
		}
		g.Pts = []Pt{pt}
		return p.expect(')')
	case wkbLineString, wkbLinearRing, wkbCircularString:
		return p.parsePointList(g)
	case wkbPolygon, wkbTriangle:
		if !p.expect('(') {
			return false
		}
		for {
			r := &Geom{T: wkbLinearRing, Z: g.Z, M: g.M}
			if !p.parsePointList(r) {
				return false
			}
			if r.Z {
				g.Z = true
			}
			g.Parts = append(g.Parts, r)
			if !p.expect(',') {
				break
			}
		}
		return p.expect(')')
	case wkbMultiPoint:
		if !p.expect('(') {
			return false
		}
		for {
			pg := &Geom{T: wkbPoint, Z: g.Z, M: g.M}
			if p.peek() == '(' {
				p.pos++
				pt, ok := p.parseCoord(pg)
				if !ok {
					return false
				}
				pg.Pts = []Pt{pt}
				if !p.expect(')') {
					return false
				}
			} else {
				save := p.pos
				if p.word() == "EMPTY" {
				} else {
					p.pos = save
					pt, ok := p.parseCoord(pg)
					if !ok {
						return false
					}
					pg.Pts = []Pt{pt}
				}
			}
			if pg.Z {
				g.Z = true
			}
			g.Parts = append(g.Parts, pg)
			if !p.expect(',') {
				break
			}
		}
		return p.expect(')')
	case wkbMultiLineString, wkbMultiPolygon, wkbPolyhedralSurface, wkbTIN:
		sub := wkbLineString
		if g.T == wkbMultiPolygon || g.T == wkbPolyhedralSurface {
			sub = wkbPolygon
		}
		if g.T == wkbTIN {
			sub = wkbTriangle
		}
		if !p.expect('(') {
			return false
		}
		for {
			pg := &Geom{T: sub, Z: g.Z, M: g.M}
			save := p.pos
			if p.word() == "EMPTY" {
			} else {
				p.pos = save
				if !p.parseBody(pg) {
					return false
				}
			}
			if pg.Z {
				g.Z = true
			}
			g.Parts = append(g.Parts, pg)
			if !p.expect(',') {
				break
			}
		}
		return p.expect(')')
	default:
		if !p.expect('(') {
			return false
		}
		for {
			var pg *Geom
			if p.peek() == '(' {
				st := wkbLineString
				if g.T == wkbCurvePolygon || g.T == wkbMultiSurface {
					st = wkbLineString
					if g.T == wkbMultiSurface {
						st = wkbPolygon
					}
				}
				pg = &Geom{T: st, Z: g.Z, M: g.M}
				if g.T == wkbCurvePolygon {
					pg.T = wkbLineString
				}
				if !p.parseBody(pg) {
					return false
				}
			} else {
				var ok bool
				pg, ok = p.parseGeom()
				if !ok {
					return false
				}
			}
			if pg.Z {
				g.Z = true
			}
			if pg.M {
				g.M = true
			}
			g.Parts = append(g.Parts, pg)
			if !p.expect(',') {
				break
			}
		}
		return p.expect(')')
	}
}

// ---------- WKB ----------

func (g *Geom) WKB() []byte {
	var b []byte
	return g.appendWKB(b, true)
}

func (g *Geom) appendWKB(b []byte, iso bool) []byte {
	b = append(b, 1)
	t := uint32(g.T)
	if iso {
		if g.Z {
			t += 1000
		}
		if g.M {
			t += 2000
		}
	} else if g.Z {
		t |= 0x80000000
	}
	b = binary.LittleEndian.AppendUint32(b, t)
	putPt := func(p Pt) {
		b = binary.LittleEndian.AppendUint64(b, math.Float64bits(p.X))
		b = binary.LittleEndian.AppendUint64(b, math.Float64bits(p.Y))
		if g.Z {
			b = binary.LittleEndian.AppendUint64(b, math.Float64bits(p.Z))
		}
		if g.M {
			b = binary.LittleEndian.AppendUint64(b, math.Float64bits(p.M))
		}
	}
	switch g.T {
	case wkbPoint:
		if len(g.Pts) == 0 {
			putPt(Pt{math.NaN(), math.NaN(), math.NaN(), math.NaN()})
		} else {
			putPt(g.Pts[0])
		}
	case wkbLineString, wkbCircularString:
		b = binary.LittleEndian.AppendUint32(b, uint32(len(g.Pts)))
		for _, p := range g.Pts {
			putPt(p)
		}
	case wkbPolygon, wkbTriangle:
		b = binary.LittleEndian.AppendUint32(b, uint32(len(g.Parts)))
		for _, r := range g.Parts {
			b = binary.LittleEndian.AppendUint32(b, uint32(len(r.Pts)))
			for _, p := range r.Pts {
				putPt(p)
			}
		}
	default:
		b = binary.LittleEndian.AppendUint32(b, uint32(len(g.Parts)))
		for _, p := range g.Parts {
			p.Z, p.M = g.Z || p.Z, g.M || p.M
			b = p.appendWKB(b, iso)
		}
	}
	return b
}

func ParseWKB(b []byte) (*Geom, int, bool) {
	if len(b) < 5 {
		return nil, 0, false
	}
	var bo binary.ByteOrder = binary.LittleEndian
	if b[0] == 0 {
		bo = binary.BigEndian
	}
	t := bo.Uint32(b[1:])
	pos := 5
	z, m := false, false
	if t&0x80000000 != 0 {
		z = true
	}
	if t&0x40000000 != 0 {
		m = true
	}
	t &= 0x0fffffff
	switch t / 1000 {
	case 1:
		z = true
	case 2:
		m = true
	case 3:
		z, m = true, true
	}
	flat := int(t % 1000)
	g := &Geom{T: flat, Z: z, M: m}
	readPt := func() (Pt, bool) {
		n := 2
		if z {
			n++
		}
		if m {
			n++
		}
		if pos+8*n > len(b) {
			return Pt{}, false
		}
		var v [4]float64
		for i := 0; i < n; i++ {
			v[i] = math.Float64frombits(bo.Uint64(b[pos:]))
			pos += 8
		}
		p := Pt{X: v[0], Y: v[1]}
		if z {
			p.Z = v[2]
			if m {
				p.M = v[3]
			}
		} else if m {
			p.M = v[2]
		}
		return p, true
	}
	readU32 := func() (int, bool) {
		if pos+4 > len(b) {
			return 0, false
		}
		v := bo.Uint32(b[pos:])
		pos += 4
		return int(v), true
	}
	switch flat {
	case wkbPoint:
		p, ok := readPt()
		if !ok {
			return nil, 0, false
		}
		if !(math.IsNaN(p.X) && math.IsNaN(p.Y)) {
			g.Pts = []Pt{p}
		}
	case wkbLineString, wkbCircularString:
		n, ok := readU32()
		if !ok {
			return nil, 0, false
		}
		for i := 0; i < n; i++ {
			p, ok := readPt()
			if !ok {
				return nil, 0, false
			}
			g.Pts = append(g.Pts, p)
		}
	case wkbPolygon, wkbTriangle:
		n, ok := readU32()
		if !ok {
			return nil, 0, false
		}
		for i := 0; i < n; i++ {
			r := &Geom{T: wkbLinearRing, Z: z, M: m}
			np, ok := readU32()
			if !ok {
				return nil, 0, false
			}
			for j := 0; j < np; j++ {
				p, ok := readPt()
				if !ok {
					return nil, 0, false
				}
				r.Pts = append(r.Pts, p)
			}
			g.Parts = append(g.Parts, r)
		}
	default:
		n, ok := readU32()
		if !ok {
			return nil, 0, false
		}
		for i := 0; i < n; i++ {
			sub, used, ok := ParseWKB(b[pos:])
			if !ok {
				return nil, 0, false
			}
			pos += used
			g.Parts = append(g.Parts, sub)
		}
	}
	return g, pos, true
}

// ---------- measures ----------

func ringArea(pts []Pt) float64 {
	n := len(pts)
	if n < 3 {
		return 0
	}
	s := 0.0
	for i := 0; i < n-1; i++ {
		s += pts[i].X*pts[i+1].Y - pts[i+1].X*pts[i].Y
	}
	return s / 2
}

func (g *Geom) Area() float64 {
	switch g.T {
	case wkbPolygon, wkbTriangle, wkbCurvePolygon:
		a := 0.0
		for i, r := range g.Parts {
			ra := math.Abs(ringArea(r.Pts))
			if i == 0 {
				a += ra
			} else {
				a -= ra
			}
		}
		return a
	case wkbMultiPolygon, wkbGeometryCollection, wkbMultiSurface, wkbPolyhedralSurface, wkbTIN:
		a := 0.0
		for _, p := range g.Parts {
			a += p.Area()
		}
		return a
	}
	return 0
}

func (g *Geom) Length() float64 {
	switch g.T {
	case wkbLineString, wkbLinearRing:
		l := 0.0
		for i := 1; i < len(g.Pts); i++ {
			l += math.Hypot(g.Pts[i].X-g.Pts[i-1].X, g.Pts[i].Y-g.Pts[i-1].Y)
		}
		return l
	case wkbMultiLineString, wkbGeometryCollection, wkbCompoundCurve, wkbMultiCurve:
		l := 0.0
		for _, p := range g.Parts {
			l += p.Length()
		}
		return l
	}
	return 0
}

func (g *Geom) NumPoints() int {
	n := len(g.Pts)
	for _, p := range g.Parts {
		n += p.NumPoints()
	}
	return n
}
