				for p.pos < len(p.s) && strings.ContainsRune(" \t\r\n", rune(p.s[p.pos])) {
					p.pos++
				}
				if p.pos >= len(p.s) {
					break
				}
				if p.s[p.pos] == '/' {
					p.pos += 2
					parent.Children = append(parent.Children, el)
					el = nil
					break
				}
				if p.s[p.pos] == '>' {
					p.pos++
					break
				}
				ks := p.pos
				for p.pos < len(p.s) && p.s[p.pos] != '=' && !strings.ContainsRune(" \t\r\n/>", rune(p.s[p.pos])) {
					p.pos++
				}
				k := p.s[ks:p.pos]
				for p.pos < len(p.s) && strings.ContainsRune(" \t\r\n", rune(p.s[p.pos])) {
					p.pos++
				}
				if p.pos < len(p.s) && p.s[p.pos] == '=' {
					p.pos++
					for p.pos < len(p.s) && strings.ContainsRune(" \t\r\n", rune(p.s[p.pos])) {
						p.pos++
					}
					if p.pos < len(p.s) && (p.s[p.pos] == '"' || p.s[p.pos] == '\'') {
						q := p.s[p.pos]
						p.pos++
						vs := p.pos
						for p.pos < len(p.s) && p.s[p.pos] != q {
							p.pos++
						}
						el.Attrs = append(el.Attrs, XAttr{k, xmlUnescape(p.s[vs:p.pos])})
						p.pos++
					}
				} else {
					el.Attrs = append(el.Attrs, XAttr{k, ""})
				}
			}
			if el != nil {
				p.parseChildren(el)
				parent.Children = append(parent.Children, el)
			}
			continue
		}
		// text
		st := p.pos
		for p.pos < len(p.s) && p.s[p.pos] != '<' {
			p.pos++
		}
		t := p.s[st:p.pos]
		if strings.TrimSpace(t) != "" {
			parent.Children = append(parent.Children, &XNode{IsText: true, Text: xmlUnescape(t)})
		}
	}
}
