package main

import (
	"archive/zip"
	"bytes"
	"compress/gzip"
	"io"
	"os"
	"path"
	"sort"
	"strings"
	"time"
)

var vsimem = map[string][]byte{}
var vsimemDirs = map[string]bool{}

func vsimemNorm(name string) string {
	return path.Clean(name)
}

func vsimemExists(name string) bool {
	n := vsimemNorm(name)
	if _, ok := vsimem[n]; ok {
		return true
	}
	return vsimemDirs[n]
}

func isVSI(name string) bool { return strings.HasPrefix(name, "/vsi") }

// vfsReadFile reads a file through the virtual file system.
func vfsReadFile(name string) ([]byte, error) {
	switch {
	case strings.HasPrefix(name, "/vsimem/"):
		if b, ok := vsimem[vsimemNorm(name)]; ok {
			return b, nil
		}
		return nil, os.ErrNotExist
	case name == "/vsistdin/" || name == "/vsistdin":
		return io.ReadAll(os.Stdin)
	case strings.HasPrefix(name, "/vsigzip/"):
		raw, err := vfsReadFile(name[len("/vsigzip/"):])
		if err != nil {
			return nil, err
		}
		r, err := gzip.NewReader(bytes.NewReader(raw))
		if err != nil {
			return nil, err
		}
		return io.ReadAll(r)
	case strings.HasPrefix(name, "/vsizip/"):
		zipPath, inner := splitZipPath(name[len("/vsizip/"):])
		raw, err := vfsReadFile(zipPath)
		if err != nil {
			return nil, err
		}
		zr, err := zip.NewReader(bytes.NewReader(raw), int64(len(raw)))
		if err != nil {
			return nil, err
		}
		if inner == "" {
			// single file
			var files []*zip.File
			for _, f := range zr.File {
				if !strings.HasSuffix(f.Name, "/") {
					files = append(files, f)
				}
			}
			if len(files) == 1 {
				rc, err := files[0].Open()
				if err != nil {
					return nil, err
				}
				defer rc.Close()
				return io.ReadAll(rc)
			}
			return nil, os.ErrNotExist
		}
		for _, f := range zr.File {
			if f.Name == inner {
				rc, err := f.Open()
				if err != nil {
					return nil, err
				}
				defer rc.Close()
				return io.ReadAll(rc)
			}
		}
		return nil, os.ErrNotExist
	}
	return os.ReadFile(name)
}

func splitZipPath(p string) (string, string) {
	low := strings.ToLower(p)
	for _, ext := range []string{".zip", ".shz", ".kmz"} {
		if i := strings.Index(low, ext); i >= 0 {
			zp := p[:i+len(ext)]
			rest := strings.TrimPrefix(p[i+len(ext):], "/")
			return zp, rest
		}
	}
	return p, ""
}

func vfsWriteFile(name string, data []byte) error {
	if strings.HasPrefix(name, "/vsimem/") {
		vsimem[vsimemNorm(name)] = append([]byte{}, data...)
		return nil
	}
	if name == "/vsistdout/" || name == "/vsistdout" {
		out(string(data))
		return nil
	}
	return os.WriteFile(name, data, 0644)
}

type vfsStatInfo struct {
