	tagGDALNodata       = 42113
	tagLERCParams       = 50674
)

type tiffEntry struct {
	Tag   uint16
	Type  uint16
	Count uint64
	data  []byte // raw value bytes
}

type tiffIFD struct {
	Offset  uint64
	Entries map[uint16]*tiffEntry
	Order   []uint16
}

type tiffFile struct {
	data   []byte
	bo     binary.ByteOrder
	big    bool
	IFDs   []*tiffIFD
}

func tiffTypeSize(t uint16) int {
	switch t {
	case 1, 2, 6, 7:
		return 1
	case 3, 8:
		return 2
	case 4, 9, 11, 13:
		return 4
	case 5, 10, 12, 16, 17, 18:
		return 8
	}
	return 1
}

func parseTIFF(data []byte) (*tiffFile, error) {
	if len(data) < 8 {
		return nil, errors.New("short")
	}
	tf := &tiffFile{data: data}
	switch {
	case data[0] == 'I' && data[1] == 'I':
		tf.bo = binary.LittleEndian
	case data[0] == 'M' && data[1] == 'M':
		tf.bo = binary.BigEndian
	default:
		return nil, errors.New("not tiff")
	}
	magic := tf.bo.Uint16(data[2:])
	var off uint64
	if magic == 42 {
		off = uint64(tf.bo.Uint32(data[4:]))
	} else if magic == 43 {
		tf.big = true
		if len(data) < 16 {
			return nil, errors.New("short")
		}
		off = tf.bo.Uint64(data[8:])
	} else {
		return nil, errors.New("not tiff")
	}
	seen := map[uint64]bool{}
	for off != 0 && !seen[off] && off < uint64(len(data)) {
		seen[off] = true
		ifd, next, err := tf.readIFD(off)
		if err != nil {
			break
		}
		tf.IFDs = append(tf.IFDs, ifd)
		off = next
	}
	if len(tf.IFDs) == 0 {
		return nil, errors.New("no ifd")
	}
	return tf, nil
}

func (tf *tiffFile) readIFD(off uint64) (*tiffIFD, uint64, error) {
	d := tf.data
	ifd := &tiffIFD{Offset: off, Entries: map[uint16]*tiffEntry{}}
	var n uint64
	pos := off
	if tf.big {
		if pos+8 > uint64(len(d)) {
			return nil, 0, errors.New("short")
		}
		n = tf.bo.Uint64(d[pos:])
		pos += 8
	} else {
		if pos+2 > uint64(len(d)) {
			return nil, 0, errors.New("short")
		}
		n = uint64(tf.bo.Uint16(d[pos:]))
		pos += 2
	}
	esz := uint64(12)
	if tf.big {
		esz = 20
	}
	for i := uint64(0); i < n; i++ {
		p := pos + i*esz
		if p+esz > uint64(len(d)) {
			return nil, 0, errors.New("short")
		}
		e := &tiffEntry{Tag: tf.bo.Uint16(d[p:]), Type: tf.bo.Uint16(d[p+2:])}
		var valOff uint64
		inline := 4
		if tf.big {
			e.Count = tf.bo.Uint64(d[p+4:])
			valOff = p + 12
			inline = 8
		} else {
			e.Count = uint64(tf.bo.Uint32(d[p+4:]))
			valOff = p + 8
		}
		sz := uint64(tiffTypeSize(e.Type)) * e.Count
		if sz > uint64(inline) {
			if tf.big {
				valOff = tf.bo.Uint64(d[valOff:])
			} else {
				valOff = uint64(tf.bo.Uint32(d[valOff:]))
			}
		}
		if valOff+sz <= uint64(len(d)) {
			e.data = d[valOff : valOff+sz]
		}
		ifd.Entries[e.Tag] = e
		ifd.Order = append(ifd.Order, e.Tag)
	}
	pos += n * esz
	var next uint64
	if tf.big {
		if pos+8 <= uint64(len(d)) {
			next = tf.bo.Uint64(d[pos:])
		}
	} else {
		if pos+4 <= uint64(len(d)) {
			next = uint64(tf.bo.Uint32(d[pos:]))
		}
	}
	return ifd, next, nil
}

func (tf *tiffFile) uints(e *tiffEntry) []uint64 {
	if e == nil {
		return nil
	}
	sz := tiffTypeSize(e.Type)
	var r []uint64
	for i := 0; i+sz <= len(e.data); i += sz {
		switch e.Type {
		case 1, 7, 6:
			r = append(r, uint64(e.data[i]))
		case 3, 8:
			r = append(r, uint64(tf.bo.Uint16(e.data[i:])))
		case 4, 9, 13:
			r = append(r, uint64(tf.bo.Uint32(e.data[i:])))
		case 16, 17, 18:
			r = append(r, tf.bo.Uint64(e.data[i:]))
		default:
			r = append(r, uint64(e.data[i]))
		}
	}
	return r
}

func (tf *tiffFile) doubles(e *tiffEntry) []float64 {
	if e == nil {
		return nil
	}
	var r []float64
	switch e.Type {
	case 12:
		for i := 0; i+8 <= len(e.data); i += 8 {
			r = append(r, math.Float64frombits(tf.bo.Uint64(e.data[i:])))
		}
	case 11:
		for i := 0; i+4 <= len(e.data); i += 4 {
			r = append(r, float64(math.Float32frombits(tf.bo.Uint32(e.data[i:]))))
		}
	case 5:
		for i := 0; i+8 <= len(e.data); i += 8 {
			a := tf.bo.Uint32(e.data[i:])
			b := tf.bo.Uint32(e.data[i+4:])
			if b == 0 {
				r = append(r, 0)
			} else {
				r = append(r, float64(a)/float64(b))
			}
		}
	default:
		for _, u := range tf.uints(e) {
			r = append(r, float64(u))
		}
	}
	return r
}

func (tf *tiffFile) ascii(e *tiffEntry) string {
	if e == nil {
		return ""
	}
	s := e.data
	if n := bytes.IndexByte(s, 0); n >= 0 && n == len(s)-1 {
		s = s[:n]
	} else if len(s) > 0 && s[len(s)-1] == 0 {
		s = s[:len(s)-1]
	}
	return string(s)
}

func (ifd *tiffIFD) get(tag uint16) *tiffEntry { return ifd.Entries[tag] }

func (tf *tiffFile) getUint(ifd *tiffIFD, tag uint16, def uint64) uint64 {
	v := tf.uints(ifd.get(tag))
	if len(v) == 0 {
		return def
	}
	return v[0]
}

// ---------- decompression ----------

func lzwDecode(src []byte, expected int) ([]byte, error) {
	out := make([]byte, 0, expected)
	// TIFF LZW (MSB first, early change)
	var dict [][]byte
	reset := func() {
		dict = dict[:0]
		for i := 0; i < 256; i++ {
			dict = append(dict, []byte{byte(i)})
		}
		dict = append(dict, nil, nil) // 256 clear, 257 eoi
	}
	dict = make([][]byte, 0, 4096)
	reset()
	bitPos := 0
	codeLen := 9
	readCode := func() int {
		if (bitPos+codeLen+7)/8 > len(src) && bitPos+codeLen > len(src)*8 {
			return 257
		}
		v := 0
		for i := 0; i < codeLen; i++ {
			byteI := (bitPos + i) / 8
			bit := 7 - (bitPos+i)%8
			b := 0
			if byteI < len(src) {
				b = int(src[byteI]>>uint(bit)) & 1
			}
			v = v<<1 | b
		}
		bitPos += codeLen
		return v
	}
	var prev []byte
	for {
		code := readCode()
		if code == 257 {
			break
		}
		if code == 256 {
			reset()
			codeLen = 9
			code = readCode()
			if code == 257 {
				break
			}
			if code >= len(dict) {
				return out, errors.New("lzw")
			}
			out = append(out, dict[code]...)
			prev = dict[code]
			continue
		}
		var entry []byte
		if code < len(dict) && dict[code] != nil {
			entry = dict[code]
			if prev != nil {
				ne := make([]byte, len(prev)+1)
				copy(ne, prev)
				ne[len(prev)] = entry[0]
				dict = append(dict, ne)
			}
		} else if code == len(dict) && prev != nil {
			ne := make([]byte, len(prev)+1)
			copy(ne, prev)
			ne[len(prev)] = prev[0]
			dict = append(dict, ne)
			entry = ne
		} else {
			return out, errors.New("lzw bad code")
		}
		out = append(out, entry...)
		prev = entry
		n := len(dict) + 1
		if n >= 4096 {
			codeLen = 12
		} else if n >= 2048 {
			codeLen = 12
		} else if n >= 1024 {
			codeLen = 11
		} else if n >= 512 {
			codeLen = 10
		}
		if len(out) >= expected && expected > 0 {
			break
		}
	}
	return out, nil
}

func packbitsDecode(src []byte, expected int) []byte {
	out := make([]byte, 0, expected)
	i := 0
	for i < len(src) && len(out) < expected {
		n := int(int8(src[i]))
		i++
		if n >= 0 {
			end := i + n + 1
			if end > len(src) {
				end = len(src)
			}
			out = append(out, src[i:end]...)
			i = end
		} else if n != -128 {
			if i < len(src) {
				for k := 0; k < -n+1; k++ {
					out = append(out, src[i])
				}
				i++
			}
		}
	}
	return out
}

func deflateDecode(src []byte) ([]byte, error) {
	r, err := zlib.NewReader(bytes.NewReader(src))
	if err != nil {
		return nil, err
	}
	defer r.Close()
	return io.ReadAll(r)
}
