func newGTiffImage(tf *tiffFile, ifd *tiffIFD) *gtiffImage {
	im := &gtiffImage{tf: tf, ifd: ifd}
	im.width = int(tf.getUint(ifd, tagImageWidth, 0))
	im.height = int(tf.getUint(ifd, tagImageLength, 0))
	im.spp = int(tf.getUint(ifd, tagSamplesPerPixel, 1))
	im.bps = int(tf.getUint(ifd, tagBitsPerSample, 1))
	im.sampleFmt = int(tf.getUint(ifd, tagSampleFormat, 1))
	im.compression = int(tf.getUint(ifd, tagCompression, 1))
	im.predictor = int(tf.getUint(ifd, tagPredictor, 1))
	im.planar = int(tf.getUint(ifd, tagPlanarConfig, 1))
	if ifd.get(tagTileWidth) != nil {
		im.tiled = true
		im.blockW = int(tf.getUint(ifd, tagTileWidth, 256))
		im.blockH = int(tf.getUint(ifd, tagTileLength, 256))
		im.offsets = tf.uints(ifd.get(tagTileOffsets))
		im.counts = tf.uints(ifd.get(tagTileByteCounts))
	} else {
		im.blockW = im.width
		rps := int(tf.getUint(ifd, tagRowsPerStrip, uint64(im.height)))
		if rps > im.height || rps <= 0 {
			rps = im.height
		}
		im.blockH = rps
		im.offsets = tf.uints(ifd.get(tagStripOffsets))
		im.counts = tf.uints(ifd.get(tagStripByteCounts))
	}
	im.dt = tiffDataType(im.bps, im.sampleFmt)
	return im
}

func tiffDataType(bps, sf int) DataType {
	switch sf {
	case 2:
		switch bps {
		case 8:
			return GDT_Int8
		case 16:
			return GDT_Int16
		case 32:
			return GDT_Int32
		case 64:
			return GDT_Int64
		}
	case 3:
		switch bps {
		case 16:
			return GDT_Float16
		case 32:
			return GDT_Float32
		case 64:
			return GDT_Float64
		}
	case 5:
		switch bps {
		case 32:
			return GDT_CInt16
		case 64:
			return GDT_CInt32
		}
	case 6:
		switch bps {
		case 32:
			return GDT_CFloat32
		case 64:
			return GDT_CFloat32
		case 128:
			return GDT_CFloat64
		}
	default:
		switch {
		case bps <= 8:
			return GDT_Byte
		case bps <= 16:
			return GDT_UInt16
		case bps <= 32:
			return GDT_UInt32
		case bps == 64:
			return GDT_UInt64
		}
	}
	return GDT_Byte
}

func (im *gtiffImage) decodeBlock(idx int, expected int) []byte {
	if idx >= len(im.offsets) || idx >= len(im.counts) {
		return make([]byte, expected)
	}
	off := im.offsets[idx]
	cnt := im.counts[idx]
	if off == 0 || off+cnt > uint64(len(im.tf.data)) {
		return make([]byte, expected)
	}
	raw := im.tf.data[off : off+cnt]
	var dec []byte
	switch im.compression {
	case 1:
		dec = raw
	case 5:
		dec, _ = lzwDecode(raw, expected)
	case 8, 32946:
		dec, _ = deflateDecode(raw)
	case 32773:
		dec = packbitsDecode(raw, expected)
	default:
		dec = make([]byte, expected)
	}
	if len(dec) < expected {
		d2 := make([]byte, expected)
		copy(d2, dec)
		dec = d2
	}
	return dec
}

func (im *gtiffImage) undoPredictor(buf []byte, w, h, nsamp int) {
	bo := im.tf.bo
	bytesPer := im.bps / 8
	if im.predictor == 2 {
		rowLen := w * nsamp * bytesPer
		for y := 0; y < h; y++ {
			row := buf[y*rowLen : (y+1)*rowLen]
			switch bytesPer {
			case 1:
				for i := nsamp; i < w*nsamp; i++ {
					row[i] += row[i-nsamp]
				}
			case 2:
				for i := nsamp; i < w*nsamp; i++ {
					v := bo.Uint16(row[i*2:]) + bo.Uint16(row[(i-nsamp)*2:])
					bo.PutUint16(row[i*2:], v)
				}
			case 4:
				for i := nsamp; i < w*nsamp; i++ {
					v := bo.Uint32(row[i*4:]) + bo.Uint32(row[(i-nsamp)*4:])
					bo.PutUint32(row[i*4:], v)
				}
			case 8:
				for i := nsamp; i < w*nsamp; i++ {
					v := bo.Uint64(row[i*8:]) + bo.Uint64(row[(i-nsamp)*8:])
					bo.PutUint64(row[i*8:], v)
				}
			}
		}
	} else if im.predictor == 3 {
		// floating point predictor
		rowLen := w * nsamp * bytesPer
		tmp := make([]byte, rowLen)
		for y := 0; y < h; y++ {
			row := buf[y*rowLen : (y+1)*rowLen]
			for i := nsamp; i < rowLen; i++ {
				row[i] += row[i-nsamp]
			}
			copy(tmp, row)
			wc := w * nsamp
			for i := 0; i < wc; i++ {
				for b := 0; b < bytesPer; b++ {
					// bytes are stored MSB first planes
					var dst int
					if bo == binary.LittleEndian {
						dst = i*bytesPer + (bytesPer - 1 - b)
					} else {
						dst = i*bytesPer + b
					}
					row[dst] = tmp[b*wc+i]
				}
			}
		}
	}
}

