func (im *gtiffImage) readAll() ([][]float64, [][]float64) {
	nb := im.spp
	w, h := im.width, im.height
	data := make([][]float64, nb)
	var imag [][]float64
	for i := range data {
		data[i] = make([]float64, w*h)
	}
	if im.dt.IsComplex() {
		imag = make([][]float64, nb)
		for i := range imag {
			imag[i] = make([]float64, w*h)
		}
	}
	bx := (w + im.blockW - 1) / im.blockW
	by := (h + im.blockH - 1) / im.blockH
	if im.bps < 8 {
		// sub-byte samples
		im.readAllSubByte(data, bx, by)
		return data, imag
	}
	ssz := im.bps / 8
	planes := 1
	nsampBlock := nb
	if im.planar == 2 {
		planes = nb
		nsampBlock = 1
	}
	for pl := 0; pl < planes; pl++ {
		for yb := 0; yb < by; yb++ {
			for xb := 0; xb < bx; xb++ {
				idx := pl*bx*by + yb*bx + xb
				bw := im.blockW
				bh := im.blockH
				if !im.tiled {
					bh = im.blockH
					if (yb+1)*im.blockH > h {
						bh = h - yb*im.blockH
					}
