				expected := bw * bh * nsampBlock * ssz
				buf := im.decodeBlock(idx, expected)
				if im.predictor > 1 {
					im.undoPredictor(buf, bw, bh, nsampBlock)
				}
				for yy := 0; yy < bh; yy++ {
					y := yb*im.blockH + yy
					if y >= h {
						break
					}
					for xx := 0; xx < bw; xx++ {
						x := xb*im.blockW + xx
						if x >= w {
							break
						}
						for s := 0; s < nsampBlock; s++ {
							o := ((yy*bw+xx)*nsampBlock + s) * ssz
							if o+ssz > len(buf) {
								continue
							}
							re, imv := readSample(im.tf.bo, im.dt, buf[o:o+ssz])
							band := s
							if im.planar == 2 {
								band = pl
							}
							data[band][y*w+x] = re
							if imag != nil {
								imag[band][y*w+x] = imv
							}
						}
					}
				}
			}
		}
	}
	return data, imag
}

