			b.BlockY = main.height
		}
		if main.bps < 8 || (main.bps != 8 && main.bps != 16 && main.bps != 32 && main.bps != 64 && main.bps != 128) {
			b.NBits = main.bps
		}
	}
	// lazy loader for all bands
	loaded := false
	loadAll := func(b *Band) error {
		if loaded {
			return nil
		}
		loaded = true
		d, imv := main.readAll()
		for i, bb := range ds.Bands {
			bb.data = d[i]
			if imv != nil {
				bb.imag = imv[i]
			}
			bb.loaded = true
		}
		return nil
	}
	for _, b := range ds.Bands {
		b.loader = loadAll
	}
	// color interpretation
	nExtraStart := nb - len(extra)
	for i, b := range ds.Bands {
		switch photometric {
		case 0, 1:
			if i == 0 {
				b.ColorInterp = GCI_GrayIndex
			}
		case 2:
			if i < 3 {
				b.ColorInterp = GCI_RedBand + i
			}
		case 3:
			if i == 0 {
				b.ColorInterp = GCI_PaletteIndex
			}
		case 5:
			if i < 4 {
				b.ColorInterp = GCI_CyanBand + i
			}
		case 6:
			if i < 3 {
				b.ColorInterp = GCI_YCbCr_YBand + i
			}
		}
		if i >= nExtraStart && len(extra) > 0 {
			es := extra[i-nExtraStart]
			if es == 1 || es == 2 {
				b.ColorInterp = GCI_AlphaBand
			}
		}
	}
	if photometric == 3 {
		cm := tf.uints(ifd.get(tagColorMap))
		n := 1 << uint(main.bps)
		if len(cm) >= 3*n {
			ct := &ColorTable{}
			for i := 0; i < n; i++ {
				ct.Entries = append(ct.Entries, ColorEntry{int(cm[i] / 257), int(cm[n+i] / 257), int(cm[2*n+i] / 257), 255})
			}
			ds.Bands[0].ColorTable = ct
		}
	}
	// geotransform
	gk := parseGeoKeys(tf, ifd)
	pixelIsPoint := false
	if gk != nil {
		if v, ok := gk.shorts[1025]; ok && v == 2 {
			pixelIsPoint = true
		}
	}
	if e := ifd.get(tagModelTransform); e != nil {
		m := tf.doubles(e)
		if len(m) >= 16 {
			ds.GT = [6]float64{m[3], m[0], m[1], m[7], m[4], m[5]}
			ds.HasGT = true
		}
	} else if e := ifd.get(tagModelTiepoint); e != nil {
		tp := tf.doubles(e)
		sc := tf.doubles(ifd.get(tagModelPixelScale))
		if len(tp) >= 6 && len(sc) >= 2 && len(tp) == 6 {
			ds.GT = [6]float64{tp[3] - tp[0]*sc[0], sc[0], 0, tp[4] + tp[1]*sc[1], 0, -sc[1]}
			ds.HasGT = true
		} else if len(tp) >= 6 {
			// GCPs
			for i := 0; i+6 <= len(tp); i += 6 {
				ds.GCPs = append(ds.GCPs, GCP{ID: strconv.Itoa(len(ds.GCPs) + 1), Pixel: tp[i], Line: tp[i+1], X: tp[i+3], Y: tp[i+4], Z: tp[i+5]})
			}
		}
	}
	if pixelIsPoint && ds.HasGT && CPLTestBool(CPLGetConfigOption("GTIFF_POINT_GEO_IGNORE", "NO")) == false {
		ds.GT[0] -= ds.GT[1]*0.5 + ds.GT[2]*0.5
		ds.GT[3] -= ds.GT[4]*0.5 + ds.GT[5]*0.5
	}
	if gk != nil {
		srs := gk.toSRS()
		if len(ds.GCPs) > 0 {
			ds.GCPSRS = srs
		} else {
			ds.SRS = srs
		}
	}
	// metadata
	if gk != nil || ds.HasGT {
		if pixelIsPoint {
			ds.MD.Set("", "AREA_OR_POINT", "Point")
		} else {
			ds.MD.Set("", "AREA_OR_POINT", "Area")
		}
	}
	for _, t := range []struct {
		tag  uint16
		name string
	}{{tagDocumentName, "TIFFTAG_DOCUMENTNAME"}, {tagImageDescription, "TIFFTAG_IMAGEDESCRIPTION"}, {tagSoftware, "TIFFTAG_SOFTWARE"}, {tagDateTime, "TIFFTAG_DATETIME"}, {tagArtist, "TIFFTAG_ARTIST"}, {tagHostComputer, "TIFFTAG_HOSTCOMPUTER"}, {tagCopyright, "TIFFTAG_COPYRIGHT"}} {
		if e := ifd.get(t.tag); e != nil {
			ds.MD.Set("", t.name, tf.ascii(e))
		}
	}
	if e := ifd.get(tagXResolution); e != nil {
		ds.MD.Set("", "TIFFTAG_XRESOLUTION", cfmt("%.8g", tf.doubles(e)[0]))
	}
	if e := ifd.get(tagYResolution); e != nil {
		ds.MD.Set("", "TIFFTAG_YRESOLUTION", cfmt("%.8g", tf.doubles(e)[0]))
	}
	if e := ifd.get(tagResolutionUnit); e != nil {
		u := tf.uints(e)[0]
		s := map[uint64]string{1: "1 (unitless)", 2: "2 (pixels/inch)", 3: "3 (pixels/cm)"}[u]
		if s == "" {
			s = strconv.Itoa(int(u)) + " (unknown)"
		}
		ds.MD.Set("", "TIFFTAG_RESOLUTIONUNIT", s)
	}
	// GDAL metadata
	if e := ifd.get(tagGDALMetadata); e != nil {
		applyGDALMetadataXML(ds, tf.ascii(e))
	}
	if e := ifd.get(tagGDALNodata); e != nil {
		s := strings.TrimSpace(tf.ascii(e))
		for _, b := range ds.Bands {
			b.HasNoData = true
			b.NoData = parseNodataString(s, b.DataType)
		}
	}
	// image structure
	if c, ok := compressionNames[main.compression]; ok {
		ds.MD.Set("IMAGE_STRUCTURE", "COMPRESSION", c)
	}
	if nb > 1 || true {
		if main.planar == 2 {
			ds.MD.Set("IMAGE_STRUCTURE", "INTERLEAVE", "BAND")
		} else if nb == 1 {
			ds.MD.Set("IMAGE_STRUCTURE", "INTERLEAVE", "BAND")
		} else {
			ds.MD.Set("IMAGE_STRUCTURE", "INTERLEAVE", "PIXEL")
		}
	}
	if main.predictor > 1 && main.compression != 1 {
		ds.MD.Set("IMAGE_STRUCTURE", "PREDICTOR", strconv.Itoa(main.predictor))
	}
	if photometric == 6 {
		ds.MD.Set("IMAGE_STRUCTURE", "SOURCE_COLOR_SPACE", "YCbCr")
	}
	for _, b := range ds.Bands {
		if b.NBits > 0 {
			b.MD.Set("IMAGE_STRUCTURE", "NBITS", strconv.Itoa(b.NBits))
		}
	}
	// overviews & masks
	for i := 1; i < len(tf.IFDs); i++ {
		sub := tf.IFDs[i]
		st := tf.getUint(sub, tagNewSubfileType, 0)
		im := newGTiffImage(tf, sub)
		if st&4 != 0 {
			// mask
			if st&1 == 0 && im.width == main.width && im.height == main.height {
				mb := &Band{DS: ds, DataType: GDT_Byte, BlockX: im.blockW, BlockY: im.blockH, MD: NewMetadata(), Scale: 1, XSize: im.width, YSize: im.height}
				img := im
				mb.loader = func(b *Band) error {
					d, _ := img.readAll()
					for k := range d[0] {
						if d[0][k] != 0 {
							d[0][k] = 255
						}
					}
					b.data = d[0]
					return nil
				}
				ds.MaskBand = mb
				for _, b := range ds.Bands {
					b.MaskFlags = GMF_PER_DATASET
				}
			}
			continue
		}
		if st&1 != 0 && im.spp == nb {
			img := im
			var ovdata [][]float64
			for bi, b := range ds.Bands {
				ob := &Band{DS: ds, Index: b.Index, DataType: im.dt, BlockX: im.blockW, BlockY: im.blockH, MD: NewMetadata(), Scale: 1, XSize: im.width, YSize: im.height, HasNoData: b.HasNoData, NoData: b.NoData}
				k := bi
				ob.loader = func(bb *Band) error {
					if ovdata == nil {
						ovdata, _ = img.readAll()
					}
					bb.data = ovdata[k]
					return nil
				}
				b.Overviews = append(b.Overviews, ob)
			}
		}
	}
	// band-level default mask flags
	for _, b := range ds.Bands {
		if ds.MaskBand != nil {
			continue
		}
		if b.HasNoData {
			b.MaskFlags = GMF_NODATA
		} else if b.ColorInterp != GCI_AlphaBand {
			for _, o := range ds.Bands {
				if o.ColorInterp == GCI_AlphaBand && o != b {
					b.MaskFlags = GMF_PER_DATASET | GMF_ALPHA
				}
			}
		}
	}
	loadPAM(ds)
	ovrFile := oi.Filename + ".ovr"
	if _, ok := vfsStat(ovrFile); ok {
		ds.FileList = append(ds.FileList, ovrFile)
	}
	return ds, nil
}

func parseNodataString(s string, dt DataType) float64 {
	l := strings.ToLower(s)
	switch l {
	case "nan", "-nan":
		return math.NaN()
	case "inf", "+inf":
		return math.Inf(1)
	case "-inf":
		return math.Inf(-1)
	}
	return cplAtof(s)
}

// applyGDALMetadataXML parses the GDAL_METADATA TIFF tag.
func applyGDALMetadataXML(ds *Dataset, xml string) {
	root := ParseXML(xml).Child("GDALMetadata")
	if root == nil {
		return
	}
	for _, it := range root.ChildrenNamed("Item") {
		name := it.AttrDef("name", "")
		domain := it.AttrDef("domain", "")
		sample, hasSample := it.Attr("sample")
		role := it.AttrDef("role", "")
		val := it.InnerText()
		if !hasSample {
			if strings.HasPrefix(domain, "xml:") {
				ds.MD.SetRaw(domain, []string{val})
				continue
			}
			ds.MD.Set(domain, name, val)
			continue
		}
		si := atoiC(sample)
		if si < 0 || si >= len(ds.Bands) {
			continue
		}
		b := ds.Bands[si]
		switch role {
		case "description":
			b.Description = val
		case "offset":
			b.HasOffset = true
			b.Offset = cplAtof(val)
		case "scale":
			b.HasScale = true
			b.Scale = cplAtof(val)
		case "unittype":
			b.Unit = val
		case "colorinterp":
			if c := colorInterpFromName(val); c >= 0 {
				b.ColorInterp = c
			}
		case "":
			b.MD.Set(domain, name, val)
		}
	}
}
EOF
echo ok"}

