cd /workspace/gdalgo && cat > gtiff_read.go <<'EOF'
package main

import (
	"encoding/binary"
	"math"
	"strconv"
	"strings"
)

func init() {
	registerDriver(&Driver{ShortName: "GTiff", LongName: "GeoTIFF", Raster: true, CanOpen: true, CanCreate: true, CanCopy: true, CanUpdate: true, VirtualIO: true,
		Extensions: []string{"tif", "tiff"},
		Identify: func(oi *OpenInfo) bool {
			h := oi.Header
			if len(h) < 4 {
				return false
			}
			return (h[0] == 'I' && h[1] == 'I' && (h[2] == 42 || h[2] == 43) && h[3] == 0) || (h[0] == 'M' && h[1] == 'M' && h[2] == 0 && (h[3] == 42 || h[3] == 43))
		},
		Open:       gtiffOpen,
		Create:     gtiffCreate,
		CreateCopy: gtiffCreateCopy,
	})
}

type gtiffImage struct {
	tf          *tiffFile
	ifd         *tiffIFD
	width       int
	height      int
	spp         int
	bps         int
	sampleFmt   int
	compression int
	predictor   int
	planar      int
	tiled       bool
	blockW      int
	blockH      int
	offsets     []uint64
	counts      []uint64
	dt          DataType
}

func newGTiffImage(tf *tiffFile, ifd *tiffIFD) *gtiffImage {
	im := &gtiffImage{tf: tf, ifd: ifd}
	im.width = int(tf.getUint(ifd, tagImageWidth, 0))
	im.height = int(tf.getUint(ifd, tagImageLength, 0))
	im.spp = int(tf.getUint(ifd, tagSamplesPerPixel, 1))
	im.bps = int(tf.getUint(ifd, tagBitsPerSample, 1))
	im.sampleFmt = int(tf.getUint(ifd, tagSampleFormat, 1))
	im.compression = int(tf.getUint(ifd, tagCompression, 1))
	im.predictor = int(tf.getUint(ifd, tagPredictor, 1))
	im.planar = int(tf.getUint(ifd, tagPlanarConfig, 1))
	if ifd.get(tagTileWidth) != nil {
		im.tiled = true
		im.blockW = int(tf.getUint(ifd, tagTileWidth, 256))
		im.blockH = int(tf.getUint(ifd, tagTileLength, 256))
		im.offsets = tf.uints(ifd.get(tagTileOffsets))
		im.counts = tf.uints(ifd.get(tagTileByteCounts))
	} else {
		im.blockW = im.width
		rps := int(tf.getUint(ifd, tagRowsPerStrip, uint64(im.height)))
		if rps > im.height || rps <= 0 {
			rps = im.height
		}
		im.blockH = rps
		im.offsets = tf.uints(ifd.get(tagStripOffsets))
		im.counts = tf.uints(ifd.get(tagStripByteCounts))
	}
	im.dt = tiffDataType(im.bps, im.sampleFmt)
	return im
}

func tiffDataType(bps, sf int) DataType {
	switch sf {
	case 2:
		switch bps {
		case 8:
			return GDT_Int8
		case 16:
			return GDT_Int16
		case 32:
			return GDT_Int32
		case 64:
			return GDT_Int64
		}
	case 3:
		switch bps {
		case 16:
			return GDT_Float16
		case 32:
			return GDT_Float32
		case 64:
			return GDT_Float64
		}
	case 5:
		switch bps {
		case 32:
			return GDT_CInt16
		case 64:
			return GDT_CInt32
		}
	case 6:
		switch bps {
		case 32:
			return GDT_CFloat32
		case 64:
			return GDT_CFloat32
		case 128:
			return GDT_CFloat64
		}
	default:
		switch {
		case bps <= 8:
			return GDT_Byte
		case bps <= 16:
			return GDT_UInt16
		case bps <= 32:
			return GDT_UInt32
		case bps == 64:
			return GDT_UInt64
		}
	}
	return GDT_Byte
}

func (im *gtiffImage) decodeBlock(idx int, expected int) []byte {
	if idx >= len(im.offsets) || idx >= len(im.counts) {
		return make([]byte, expected)
	}
	off := im.offsets[idx]
	cnt := im.counts[idx]
	if off == 0 || off+cnt > uint64(len(im.tf.data)) {
		return make([]byte, expected)
	}
	raw := im.tf.data[off : off+cnt]
	var dec []byte
	switch im.compression {
	case 1:
		dec = raw
	case 5:
		dec, _ = lzwDecode(raw, expected)
	case 8, 32946:
		dec, _ = deflateDecode(raw)
	case 32773:
		dec = packbitsDecode(raw, expected)
	default:
		dec = make([]byte, expected)
	}
	if len(dec) < expected {
		d2 := make([]byte, expected)
		copy(d2, dec)
		dec = d2
	}
	return dec
}

func (im *gtiffImage) undoPredictor(buf []byte, w, h, nsamp int) {
	bo := im.tf.bo
	bytesPer := im.bps / 8
	if im.predictor == 2 {
		rowLen := w * nsamp * bytesPer
		for y := 0; y < h; y++ {
			row := buf[y*rowLen : (y+1)*rowLen]
			switch bytesPer {
			case 1:
				for i := nsamp; i < w*nsamp; i++ {
					row[i] += row[i-nsamp]
				}
			case 2:
				for i := nsamp; i < w*nsamp; i++ {
					v := bo.Uint16(row[i*2:]) + bo.Uint16(row[(i-nsamp)*2:])
					bo.PutUint16(row[i*2:], v)
				}
			case 4:
				for i := nsamp; i < w*nsamp; i++ {
					v := bo.Uint32(row[i*4:]) + bo.Uint32(row[(i-nsamp)*4:])
					bo.PutUint32(row[i*4:], v)
				}
			case 8:
				for i := nsamp; i < w*nsamp; i++ {
					v := bo.Uint64(row[i*8:]) + bo.Uint64(row[(i-nsamp)*8:])
					bo.PutUint64(row[i*8:], v)
				}
			}
		}
	} else if im.predictor == 3 {
		// floating point predictor
		rowLen := w * nsamp * bytesPer
		tmp := make([]byte, rowLen)
		for y := 0; y < h; y++ {
			row := buf[y*rowLen : (y+1)*rowLen]
			for i := nsamp; i < rowLen; i++ {
				row[i] += row[i-nsamp]
			}
			copy(tmp, row)
			wc := w * nsamp
			for i := 0; i < wc; i++ {
				for b := 0; b < bytesPer; b++ {
					// bytes are stored MSB first planes
					var dst int
					if bo == binary.LittleEndian {
						dst = i*bytesPer + (bytesPer - 1 - b)
					} else {
						dst = i*bytesPer + b
					}
					row[dst] = tmp[b*wc+i]
				}
			}
		}
	}
}

func readSample(bo binary.ByteOrder, dt DataType, b []byte) (float64, float64) {
	switch dt {
	case GDT_Byte:
		return float64(b[0]), 0
	case GDT_Int8:
		return float64(int8(b[0])), 0
	case GDT_UInt16:
		return float64(bo.Uint16(b)), 0
	case GDT_Int16:
		return float64(int16(bo.Uint16(b))), 0
	case GDT_UInt32:
		return float64(bo.Uint32(b)), 0
	case GDT_Int32:
		return float64(int32(bo.Uint32(b))), 0
	case GDT_UInt64:
		return float64(bo.Uint64(b)), 0
	case GDT_Int64:
		return float64(int64(bo.Uint64(b))), 0
	case GDT_Float16:
		return halfToFloat(bo.Uint16(b)), 0
	case GDT_Float32:
		return float64(math.Float32frombits(bo.Uint32(b))), 0
	case GDT_Float64:
		return math.Float64frombits(bo.Uint64(b)), 0
	case GDT_CInt16:
		return float64(int16(bo.Uint16(b))), float64(int16(bo.Uint16(b[2:])))
	case GDT_CInt32:
		return float64(int32(bo.Uint32(b))), float64(int32(bo.Uint32(b[4:])))
	case GDT_CFloat32:
		return float64(math.Float32frombits(bo.Uint32(b))), float64(math.Float32frombits(bo.Uint32(b[4:])))
	case GDT_CFloat64:
		return math.Float64frombits(bo.Uint64(b)), math.Float64frombits(bo.Uint64(b[8:]))
	}
	return 0, 0
}

// readAllBands decodes the whole image into per-band arrays.
func (im *gtiffImage) readAll() ([][]float64, [][]float64) {
	nb := im.spp
	w, h := im.width, im.height
	data := make([][]float64, nb)
	var imag [][]float64
	for i := range data {
		data[i] = make([]float64, w*h)
	}
	if im.dt.IsComplex() {
		imag = make([][]float64, nb)
		for i := range imag {
			imag[i] = make([]float64, w*h)
		}
	}
	bx := (w + im.blockW - 1) / im.blockW
	by := (h + im.blockH - 1) / im.blockH
	if im.bps < 8 {
		// sub-byte samples
		im.readAllSubByte(data, bx, by)
		return data, imag
	}
	ssz := im.bps / 8
	planes := 1
	nsampBlock := nb
	if im.planar == 2 {
		planes = nb
		nsampBlock = 1
	}
	for pl := 0; pl < planes; pl++ {
		for yb := 0; yb < by; yb++ {
			for xb := 0; xb < bx; xb++ {
				idx := pl*bx*by + yb*bx + xb
				bw := im.blockW
				bh := im.blockH
				if !im.tiled {
					bh = im.blockH
					if (yb+1)*im.blockH > h {
						bh = h - yb*im.blockH
					}
				}
				expected := bw * bh * nsampBlock * ssz
				buf := im.decodeBlock(idx, expected)
				if im.predictor > 1 {
					im.undoPredictor(buf, bw, bh, nsampBlock)
				}
				for yy := 0; yy < bh; yy++ {
					y := yb*im.blockH + yy
					if y >= h {
						break
					}
					for xx := 0; xx < bw; xx++ {
						x := xb*im.blockW + xx
						if x >= w {
							break
						}
						for s := 0; s < nsampBlock; s++ {
							o := ((yy*bw+xx)*nsampBlock + s) * ssz
							if o+ssz > len(buf) {
								continue
							}
							re, imv := readSample(im.tf.bo, im.dt, buf[o:o+ssz])
							band := s
							if im.planar == 2 {
								band = pl
							}
							data[band][y*w+x] = re
							if imag != nil {
								imag[band][y*w+x] = imv
							}
						}
					}
				}
			}
		}
	}
	return data, imag
}

func (im *gtiffImage) readAllSubByte(data [][]float64, bx, by int) {
	nb := im.spp
	w, h := im.width, im.height
	planes := 1
	nsampBlock := nb
	if im.planar == 2 {
		planes = nb
		nsampBlock = 1
	}
	for pl := 0; pl < planes; pl++ {
		for yb := 0; yb < by; yb++ {
			for xb := 0; xb < bx; xb++ {
				idx := pl*bx*by + yb*bx + xb
				bw, bh := im.blockW, im.blockH
				rowBits := bw * nsampBlock * im.bps
				rowBytes := (rowBits + 7) / 8
				buf := im.decodeBlock(idx, rowBytes*bh)
				for yy := 0; yy < bh; yy++ {
					y := yb*im.blockH + yy
					if y >= h {
						break
					}
					for xx := 0; xx < bw; xx++ {
						x := xb*im.blockW + xx
						if x >= w {
							break
						}
						for s := 0; s < nsampBlock; s++ {
							bit := (xx*nsampBlock + s) * im.bps
							v := 0
							for k := 0; k < im.bps; k++ {
								bi := yy*rowBytes + (bit+k)/8
								if bi < len(buf) {
									v = v<<1 | int(buf[bi]>>(7-uint((bit+k)%8)))&1
								}
							}
							band := s
							if im.planar == 2 {
								band = pl
							}
							data[band][y*w+x] = float64(v)
						}
					}
				}
			}
		}
	}
}

var compressionNames = map[int]string{5: "LZW", 8: "DEFLATE", 32946: "DEFLATE", 32773: "PACKBITS", 7: "JPEG", 34925: "LZMA", 50000: "ZSTD", 34887: "LERC", 50001: "WEBP", 2: "CCITTRLE", 3: "CCITTFAX3", 4: "CCITTFAX4", 6: "OJPEG"}

func gtiffOpen(oi *OpenInfo) (*Dataset, error) {
	data, err := vfsReadFile(oi.Filename)
	if err != nil {
		return nil, newOpenErr(CPLE_OpenFailed, "%s: No such file or directory", oi.Filename)
	}
	tf, err := parseTIFF(data)
	if err != nil {
		return nil, newOpenErr(CPLE_OpenFailed, "`%s' not recognized as being in a supported file format.", oi.Filename)
	}
	main := newGTiffImage(tf, tf.IFDs[0])
	ds := NewDataset(oi.Filename, main.width, main.height)
	ds.FileList = []string{oi.Filename}
	ds.Extra["gtiff_tf"] = tf
	ds.Extra["gtiff_main"] = main
	ifd := main.ifd
	photometric := int(tf.getUint(ifd, tagPhotometric, 1))
	extra := tf.uints(ifd.get(tagExtraSamples))
	nb := main.spp
	for i := 0; i < nb; i++ {
		b := ds.AddBand(main.dt)
		b.BlockX = main.blockW
		b.BlockY = main.blockH
		if !main.tiled && main.blockH > main.height {
			b.BlockY = main.height
		}
		if main.bps < 8 || (main.bps != 8 && main.bps != 16 && main.bps != 32 && main.bps != 64 && main.bps != 128) {
			b.NBits = main.bps
		}
	}
	// lazy loader for all bands
	loaded := false
	loadAll := func(b *Band) error {
		if loaded {
			return nil
		}
		loaded = true
		d, imv := main.readAll()
		for i, bb := range ds.Bands {
			bb.data = d[i]
			if imv != nil {
				bb.imag = imv[i]
			}
			bb.loaded = true
		}
		return nil
	}
	for _, b := range ds.Bands {
		b.loader = loadAll
	}
	// color interpretation
	nExtraStart := nb - len(extra)
	for i, b := range ds.Bands {
		switch photometric {
		case 0, 1:
			if i == 0 {
				b.ColorInterp = GCI_GrayIndex
			}
		case 2:
			if i < 3 {
				b.ColorInterp = GCI_RedBand + i
			}
		case 3:
			if i == 0 {
				b.ColorInterp = GCI_PaletteIndex
			}
		case 5:
			if i < 4 {
				b.ColorInterp = GCI_CyanBand + i
			}
		case 6:
			if i < 3 {
				b.ColorInterp = GCI_YCbCr_YBand + i
			}
		}
		if i >= nExtraStart && len(extra) > 0 {
			es := extra[i-nExtraStart]
			if es == 1 || es == 2 {
				b.ColorInterp = GCI_AlphaBand
			}
		}
	}
	if photometric == 3 {
		cm := tf.uints(ifd.get(tagColorMap))
		n := 1 << uint(main.bps)
		if len(cm) >= 3*n {
			ct := &ColorTable{}
			for i := 0; i < n; i++ {
				ct.Entries = append(ct.Entries, ColorEntry{int(cm[i] / 257), int(cm[n+i] / 257), int(cm[2*n+i] / 257), 255})
			}
			ds.Bands[0].ColorTable = ct
		}
	}
	// geotransform
	gk := parseGeoKeys(tf, ifd)
	pixelIsPoint := false
	if gk != nil {
		if v, ok := gk.shorts[1025]; ok && v == 2 {
			pixelIsPoint = true
		}
	}
	if e := ifd.get(tagModelTransform); e != nil {
		m := tf.doubles(e)
		if len(m) >= 16 {
			ds.GT = [6]float64{m[3], m[0], m[1], m[7], m[4], m[5]}
			ds.HasGT = true
		}
	} else if e := ifd.get(tagModelTiepoint); e != nil {
		tp := tf.doubles(e)
		sc := tf.doubles(ifd.get(tagModelPixelScale))
		if len(tp) >= 6 && len(sc) >= 2 && len(tp) == 6 {
			ds.GT = [6]float64{tp[3] - tp[0]*sc[0], sc[0], 0, tp[4] + tp[1]*sc[1], 0, -sc[1]}
			ds.HasGT = true
		} else if len(tp) >= 6 {
			// GCPs
			for i := 0; i+6 <= len(tp); i += 6 {
				ds.GCPs = append(ds.GCPs, GCP{ID: strconv.Itoa(len(ds.GCPs) + 1), Pixel: tp[i], Line: tp[i+1], X: tp[i+3], Y: tp[i+4], Z: tp[i+5]})
			}
		}
	}
	if pixelIsPoint && ds.HasGT && CPLTestBool(CPLGetConfigOption("GTIFF_POINT_GEO_IGNORE", "NO")) == false {
		ds.GT[0] -= ds.GT[1]*0.5 + ds.GT[2]*0.5
		ds.GT[3] -= ds.GT[4]*0.5 + ds.GT[5]*0.5
	}
	if gk != nil {
		srs := gk.toSRS()
		if len(ds.GCPs) > 0 {
			ds.GCPSRS = srs
		} else {
			ds.SRS = srs
		}
	}
	// metadata
	if gk != nil || ds.HasGT {
		if pixelIsPoint {
			ds.MD.Set("", "AREA_OR_POINT", "Point")
		} else {
			ds.MD.Set("", "AREA_OR_POINT", "Area")
		}
	}
	for _, t := range []struct {
		tag  uint16
		name string
	}{{tagDocumentName, "TIFFTAG_DOCUMENTNAME"}, {tagImageDescription, "TIFFTAG_IMAGEDESCRIPTION"}, {tagSoftware, "TIFFTAG_SOFTWARE"}, {tagDateTime, "TIFFTAG_DATETIME"}, {tagArtist, "TIFFTAG_ARTIST"}, {tagHostComputer, "TIFFTAG_HOSTCOMPUTER"}, {tagCopyright, "TIFFTAG_COPYRIGHT"}} {
		if e := ifd.get(t.tag); e != nil {
			ds.MD.Set("", t.name, tf.ascii(e))
		}
	}
	if e := ifd.get(tagXResolution); e != nil {
		ds.MD.Set("", "TIFFTAG_XRESOLUTION", cfmt("%.8g", tf.doubles(e)[0]))
	}
	if e := ifd.get(tagYResolution); e != nil {
		ds.MD.Set("", "TIFFTAG_YRESOLUTION", cfmt("%.8g", tf.doubles(e)[0]))
	}
	if e := ifd.get(tagResolutionUnit); e != nil {
		u := tf.uints(e)[0]
		s := map[uint64]string{1: "1 (unitless)", 2: "2 (pixels/inch)", 3: "3 (pixels/cm)"}[u]
		if s == "" {
			s = strconv.Itoa(int(u)) + " (unknown)"
		}
		ds.MD.Set("", "TIFFTAG_RESOLUTIONUNIT", s)
	}
	// GDAL metadata
	if e := ifd.get(tagGDALMetadata); e != nil {
		applyGDALMetadataXML(ds, tf.ascii(e))
	}
	if e := ifd.get(tagGDALNodata); e != nil {
		s := strings.TrimSpace(tf.ascii(e))
		for _, b := range ds.Bands {
			b.HasNoData = true
			b.NoData = parseNodataString(s, b.DataType)
		}
	}
	// image structure
	if c, ok := compressionNames[main.compression]; ok {
		ds.MD.Set("IMAGE_STRUCTURE", "COMPRESSION", c)
	}
	if nb > 1 || true {
		if main.planar == 2 {
			ds.MD.Set("IMAGE_STRUCTURE", "INTERLEAVE", "BAND")
		} else if nb == 1 {
			ds.MD.Set("IMAGE_STRUCTURE", "INTERLEAVE", "BAND")
		} else {
			ds.MD.Set("IMAGE_STRUCTURE", "INTERLEAVE", "PIXEL")
		}
	}
	if main.predictor > 1 && main.compression != 1 {
		ds.MD.Set("IMAGE_STRUCTURE", "PREDICTOR", strconv.Itoa(main.predictor))
	}
	if photometric == 6 {
		ds.MD.Set("IMAGE_STRUCTURE", "SOURCE_COLOR_SPACE", "YCbCr")
	}
	for _, b := range ds.Bands {
		if b.NBits > 0 {
			b.MD.Set("IMAGE_STRUCTURE", "NBITS", strconv.Itoa(b.NBits))
		}
	}
	// overviews & masks
	for i := 1; i < len(tf.IFDs); i++ {
		sub := tf.IFDs[i]
		st := tf.getUint(sub, tagNewSubfileType, 0)
		im := newGTiffImage(tf, sub)
		if st&4 != 0 {
			// mask
			if st&1 == 0 && im.width == main.width && im.height == main.height {
				mb := &Band{DS: ds, DataType: GDT_Byte, BlockX: im.blockW, BlockY: im.blockH, MD: NewMetadata(), Scale: 1, XSize: im.width, YSize: im.height}
				img := im
				mb.loader = func(b *Band) error {
					d, _ := img.readAll()
					for k := range d[0] {
						if d[0][k] != 0 {
							d[0][k] = 255
						}
					}
					b.data = d[0]
					return nil
				}
				ds.MaskBand = mb
				for _, b := range ds.Bands {
					b.MaskFlags = GMF_PER_DATASET
				}
			}
			continue
		}
		if st&1 != 0 && im.spp == nb {
			img := im
			var ovdata [][]float64
			for bi, b := range ds.Bands {
				ob := &Band{DS: ds, Index: b.Index, DataType: im.dt, BlockX: im.blockW, BlockY: im.blockH, MD: NewMetadata(), Scale: 1, XSize: im.width, YSize: im.height, HasNoData: b.HasNoData, NoData: b.NoData}
				k := bi
				ob.loader = func(bb *Band) error {
					if ovdata == nil {
						ovdata, _ = img.readAll()
					}
					bb.data = ovdata[k]
					return nil
				}
				b.Overviews = append(b.Overviews, ob)
			}
		}
	}
	// band-level default mask flags
	for _, b := range ds.Bands {
		if ds.MaskBand != nil {
			continue
		}
		if b.HasNoData {
			b.MaskFlags = GMF_NODATA
		} else if b.ColorInterp != GCI_AlphaBand {
			for _, o := range ds.Bands {
				if o.ColorInterp == GCI_AlphaBand && o != b {
					b.MaskFlags = GMF_PER_DATASET | GMF_ALPHA
				}
			}
		}
	}
	loadPAM(ds)
	ovrFile := oi.Filename + ".ovr"
	if _, ok := vfsStat(ovrFile); ok {
		ds.FileList = append(ds.FileList, ovrFile)
	}
	return ds, nil
}

func parseNodataString(s string, dt DataType) float64 {
	l := strings.ToLower(s)
	switch l {
	case "nan", "-nan":
		return math.NaN()
	case "inf", "+inf":
		return math.Inf(1)
	case "-inf":
		return math.Inf(-1)
	}
	return cplAtof(s)
}

// applyGDALMetadataXML parses the GDAL_METADATA TIFF tag.
func applyGDALMetadataXML(ds *Dataset, xml string) {
	root := ParseXML(xml).Child("GDALMetadata")
	if root == nil {
		return
	}
	for _, it := range root.ChildrenNamed("Item") {
		name := it.AttrDef("name", "")
		domain := it.AttrDef("domain", "")
		sample, hasSample := it.Attr("sample")
		role := it.AttrDef("role", "")
		val := it.InnerText()
		if !hasSample {
			if strings.HasPrefix(domain, "xml:") {
				ds.MD.SetRaw(domain, []string{val})
				continue
			}
			ds.MD.Set(domain, name, val)
			continue
		}
		si := atoiC(sample)
		if si < 0 || si >= len(ds.Bands) {
			continue
		}
		b := ds.Bands[si]
		switch role {
		case "description":
			b.Description = val
		case "offset":
			b.HasOffset = true
			b.Offset = cplAtof(val)
		case "scale":
			b.HasScale = true
			b.Scale = cplAtof(val)
		case "unittype":
			b.Unit = val
		case "colorinterp":
			if c := colorInterpFromName(val); c >= 0 {
				b.ColorInterp = c
			}
		case "":
			b.MD.Set(domain, name, val)
		}
	}
}
