func parseGeoKeys(tf *tiffFile, ifd *tiffIFD) *geoKeys {
	e := ifd.get(tagGeoKeyDirectory)
	if e == nil {
		return nil
	}
	dir := tf.uints(e)
	if len(dir) < 4 {
		return nil
	}
	dbl := tf.doubles(ifd.get(tagGeoDoubleParams))
	asc := ""
	if ae := ifd.get(tagGeoAsciiParams); ae != nil {
		asc = string(ae.data)
	}
	gk := &geoKeys{shorts: map[int]int{}, doubles: map[int][]float64{}, ascii: map[int]string{}}
	n := int(dir[3])
	for i := 0; i < n; i++ {
		if 4+i*4+3 >= len(dir) {
			break
		}
		id := int(dir[4+i*4])
		loc := int(dir[4+i*4+1])
		cnt := int(dir[4+i*4+2])
		val := int(dir[4+i*4+3])
		gk.order = append(gk.order, id)
		switch loc {
		case 0:
			gk.shorts[id] = val
		case tagGeoDoubleParams:
			if val+cnt <= len(dbl) {
				gk.doubles[id] = dbl[val : val+cnt]
			}
		case tagGeoAsciiParams:
			if val+cnt <= len(asc) {
				s := asc[val : val+cnt]
				s = strings.TrimSuffix(s, "|")
				s = strings.TrimRight(s, "\x00")
				gk.ascii[id] = s
			}
		}
	}
	return gk
}

func (gk *geoKeys) short(id int) (int, bool) {
	v, ok := gk.shorts[id]
	return v, ok
}

func (gk *geoKeys) dbl(id int) (float64, bool) {
	v, ok := gk.doubles[id]
	if !ok || len(v) == 0 {
		return 0, false
	}
	return v[0], true
}

func wktQuote(s string) string { return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\"" }

func fmtWKTNum(v float64) string {
	s := cfmt("%.15g", v)
	return s
}

// buildGeogCRSFromEPSG builds a GEOGCRS WKT from the components of an EPSG geographic CRS,
// mimicking how GDAL reconstructs it from GeoTIFF keys.
func buildGeogCRSFromEPSG(code int) *SRS {
	db := pjCreateFromDB("EPSG", strconv.Itoa(code), 3)
	if db == nil {
		return nil
	}
	defer pjDestroy(db)
	name := pjName(db)
	datum := pjDatumForced(db)
	datumName := pjName(datum)
	ell := pjEllipsoid(db)
	ellName := pjName(ell)
	a, b, _, invf := pjEllipsoidParams(ell)
	if b != 0 && a != b {
		invf = a / (a - b)
	}
	pm := pjPrimeMeridian(db)
	pmName := pjName(pm)
	pmLon, _, _ := pjPMParams(pm)
	pjDestroy(datum)
	pjDestroy(ell)
	pjDestroy(pm)
	axes, _ := pjAxes(db)
	angName, angConv := "degree", math.Pi/180
	if len(axes) > 0 {
		angName, angConv = axes[0].UnitName, axes[0].Conv
	}
	return buildGeogCRS(name, datumName, ellName, a, invf, pmName, pmLon, angName, angConv, "EPSG", code, len(axes) == 3)
}

func buildGeogCRS(name, datumName, ellName string, a, invf float64, pmName string, pmLon float64, angName string, angConv float64, auth string, code int, is3D bool) *SRS {
	angUnit := "ANGLEUNIT[" + wktQuote(angName) + "," + fmtWKTNum(angConv) + "]"
	var sb strings.Builder
	sb.WriteString("GEOGCRS[" + wktQuote(name) + ",")
	sb.WriteString("DATUM[" + wktQuote(datumName) + ",ELLIPSOID[" + wktQuote(ellName) + "," + fmtWKTNum(a) + "," + fmtWKTNum(invf) + ",LENGTHUNIT[\"metre\",1]]],")
	sb.WriteString("PRIMEM[" + wktQuote(pmName) + "," + fmtWKTNum(pmLon) + "," + angUnit + "],")
	if is3D {
		sb.WriteString("CS[ellipsoidal,3],AXIS[\"geodetic latitude (Lat)\",north,ORDER[1]," + angUnit + "],AXIS[\"geodetic longitude (Lon)\",east,ORDER[2]," + angUnit + "],AXIS[\"ellipsoidal height (h)\",up,ORDER[3],LENGTHUNIT[\"metre\",1]]")
	} else {
		sb.WriteString("CS[ellipsoidal,2],AXIS[\"geodetic latitude (Lat)\",north,ORDER[1]," + angUnit + "],AXIS[\"geodetic longitude (Lon)\",east,ORDER[2]," + angUnit + "]")
	}
	if auth != "" {
		sb.WriteString(",ID[" + wktQuote(auth) + "," + strconv.Itoa(code) + "]")
	}
	sb.WriteString("]")
	return srsFromWKT(sb.String())
}

func (gk *geoKeys) toSRS() *SRS {
	model, _ := gk.short(1024)
	if pcs, ok := gk.short(3072); ok && pcs > 0 && pcs != 32767 {
		s := srsFromEPSG(pcs)
		if s != nil {
			return gk.withVertical(s)
		}
	}
	if gcs, ok := gk.short(2048); ok && gcs > 0 && gcs != 32767 && model != 1 {
		var s *SRS
		if gcs == 4326 || gcs == 4322 || gcs == 4979 {
			s = srsFromEPSG(gcs)
		} else {
			s = buildGeogCRSFromEPSG(gcs)
			if s == nil {
				s = srsFromEPSG(gcs)
			}
		}
		if s != nil {
			return gk.withVertical(s)
		}
	}
	if model == 3 {
		if gcs, ok := gk.short(2048); ok && gcs > 0 && gcs != 32767 {
			return srsFromEPSG(gcs)
		}
	}
	return gk.userDefinedSRS()
}

func (gk *geoKeys) withVertical(s *SRS) *SRS {
	vcs, ok := gk.short(4096)
	if !ok || vcs <= 0 || vcs == 32767 {
		return s
	}
	v := pjCreateFromDB("EPSG", strconv.Itoa(vcs), 3)
	if v == nil {
		return s
	}
	defer pjDestroy(v)
	name := s.Name() + " + " + pjName(v)
	// try to find a compound CRS by components
	h := pjAsWKT(s.pj, PJ_WKT2_2019, false)
	vw := pjAsWKT(v, PJ_WKT2_2019, false)
	c := srsFromWKT("COMPOUNDCRS[" + wktQuote(name) + "," + h + "," + vw + "]")
	if c == nil {
		return s
	}
	if res := pjIdentify(c.pj, "EPSG"); len(res) > 0 {
		for _, r := range res {
			if r.Conf >= 90 {
				out := newSRSFromPJ(r.Obj)
				for _, r2 := range res {
					if r2.Obj != r.Obj {
						pjDestroy(r2.Obj)
					}
				}
				return out
			}
		}
	}
	return c
}

