import struct, sys, json
# usage: mktiff.py out.tif spec.json
# spec: {"w":..,"h":..,"bands":[[values...],...],"type":"B|H|h|I|i|f|d|b","gt":[...],"epsg":4326,"nodata":"0","tags":{}}
def write(path, spec):
    w=spec['w']; h=spec['h']; bands=spec['bands']; t=spec.get('type','B')
    sf={'B':1,'H':1,'I':1,'b':2,'h':2,'i':2,'f':3,'d':3,'Q':1,'q':2}[t]
    bps=struct.calcsize(t)*8
    nb=len(bands)
    interleave=spec.get('planar',1)
    img=b''
