			}
			root.Set("geoTransform", arr)
		} else if gt[2] == 0 && gt[4] == 0 {
			w("Origin = (%.15f,%.15f)\n", gt[0], gt[3])
			w("Pixel Size = (%.15f,%.15f)\n", gt[1], gt[5])
		} else {
			w("GeoTransform =\n  %.16g, %.16g, %.16g\n  %.16g, %.16g, %.16g\n", gt[0], gt[1], gt[2], gt[3], gt[4], gt[5])
