func runRasterInfo(a *Alg) bool {
	v := a.V("input")
	if len(v.DSs) == 0 || v.DSs[0] == nil {
		return false
	}
	ds := v.DSs[0]
	o := rasterInfoOpts{
		JSON:        strings.EqualFold(a.Str("output-format"), "json"),
		MinMax:      a.Bool("min-max"),
		Stats:       a.Bool("stats"),
		ApproxStats: a.Bool("approx-stats"),
