		NoGCP:       a.Bool("no-gcp"),
		NoMD:        a.Bool("no-md"),
		NoCT:        a.Bool("no-ct"),
		NoFL:        a.Bool("no-fl"),
		Checksum:    a.Bool("checksum"),
