	ds.Close()
	return true
}

func gdalDecToDMS(angle float64, axis string, prec int) string {
	if math.IsNaN(angle) {
		return "Invalid angle"
	}
	eps := (0.5 / 3600.0) * math.Pow(0.1, float64(prec))
	abs := math.Abs(angle) + eps
	if abs > 361 {
		return "Invalid angle"
	}
	deg := int(abs)
	min := int((abs - float64(deg)) * 60)
	sec := abs*3600 - float64(deg)*3600 - float64(min)*60
	if sec > eps*3600 {
		sec -= eps * 3600
	}
	var hemi string
	if strings.EqualFold(axis, "Long") {
		if angle < 0 {
			hemi = "W"
		} else {
			hemi = "E"
		}
	} else if angle < 0 {
		hemi = "S"
	} else {
		hemi = "N"
	}
	f := "%3dd%2d'%" + strconv.Itoa(prec+3) + "." + strconv.Itoa(prec) + "f\"" + hemi
	return cfmt(f, deg, min, sec)
}

func nodataText(b *Band) string {
	if b.DataType == GDT_Int64 {
		return strconv.FormatInt(int64(b.NoData), 10)
	}
	if b.DataType == GDT_UInt64 {
		return strconv.FormatUint(uint64(b.NoData), 10)
	}
	if math.IsNaN(b.NoData) {
		return "nan"
	}
	return cfmt("%.18g", b.NoData)
}

func nodataJSON(b *Band) *JValue {
	if b.DataType == GDT_Int64 || b.DataType == GDT_UInt64 {
		return JInt(int64(b.NoData))
	}
	if math.IsNaN(b.NoData) {
		return JStr("NaN")
	}
	if math.IsInf(b.NoData, 1) {
		return JStr("Infinity")
	}
	if math.IsInf(b.NoData, -1) {
		return JStr("-Infinity")
	}
	if b.DataType.IsFloat() {
		return JDouble(b.NoData)
	}
	return JInt(int64(b.NoData))
}

func stacDataType(dt DataType) string {
	switch dt {
	case GDT_Byte:
		return "uint8"
	case GDT_Int8:
		return "int8"
	case GDT_UInt16:
		return "uint16"
	case GDT_Int16:
		return "int16"
	case GDT_UInt32:
		return "uint32"
	case GDT_Int32:
		return "int32"
	case GDT_UInt64:
		return "uint64"
	case GDT_Int64:
		return "int64"
	case GDT_Float16:
		return "float16"
	case GDT_Float32:
		return "float32"
	case GDT_Float64:
		return "float64"
	case GDT_CInt16:
		return "cint16"
	case GDT_CInt32:
		return "cint32"
	case GDT_CFloat16:
		return "cfloat16"
	case GDT_CFloat32:
		return "cfloat32"
	case GDT_CFloat64:
		return "cfloat64"
	}
	return "other"
}

func mdToJSON(items []string) *JValue {
	o := JNewObject()
	for _, kv := range items {
		i := strings.IndexByte(kv, '=')
		if i < 0 {
			o.Set(kv, JStr(""))
			continue
		}
		o.Set(kv[:i], JStr(kv[i+1:]))
	}
	return o
}

func gdalInfo(ds *Dataset, o rasterInfoOpts) string {
	var sb strings.Builder
	w := func(format string, args ...interface{}) { sb.WriteString(cfmt(format, args...)) }
	root := JNewObject()
	j := o.JSON
	drv := ds.Driver
	if j {
		root.Set("description", JStr(ds.Name))
		root.Set("driverShortName", JStr(drv.ShortName))
		root.Set("driverLongName", JStr(drv.LongName))
	} else {
		w("Driver: %s/%s\n", drv.ShortName, drv.LongName)
	}
	if !o.NoFL {
		files := ds.FileList
		if j {
			fa := JNewArray()
			for _, f := range files {
				fa.Add(JStr(f))
			}
			root.Set("files", fa)
		} else if len(files) == 0 {
			w("Files: none associated\n")
		} else {
			w("Files: %s\n", files[0])
			for _, f := range files[1:] {
				w("       %s\n", f)
			}
		}
	}
	if j {
		root.Set("size", JNewArray().Add(JInt(int64(ds.XSize))).Add(JInt(int64(ds.YSize))))
	} else {
		w("Size is %d, %d\n", ds.XSize, ds.YSize)
	}
	// metadata domain list
	if o.ListMDD {
		doms := ds.MD.DomainList()
		if j {
			arr := JNewArray()
			for _, d := range doms {
				arr.Add(JStr(d))
			}
			root.Set("metadataDomains", arr)
		} else {
			w("Metadata domains:\n")
			for _, d := range doms {
				if d == "" {
					w("  (default)\n")
				} else {
					w("  %s\n", d)
				}
			}
		}
	}
	srs := ds.SRS
	if srs != nil {
		writeCRS(&sb, root, srs, o, j, "coordinateSystem", "Coordinate Reference System")
		if srs.epoch != 0 {
			if j {
				root.Set("coordinateEpoch", JDouble(srs.epoch))
			} else {
				w("Coordinate epoch: %g\n", srs.epoch)
			}
		}
	}
	gt := ds.GT
	if ds.HasGT {
		if j {
			arr := JNewArray()
			for _, v := range gt {
				arr.Add(JDouble(v))
			}
			root.Set("geoTransform", arr)
		} else if gt[2] == 0 && gt[4] == 0 {
			w("Origin = (%.15f,%.15f)\n", gt[0], gt[3])
			w("Pixel Size = (%.15f,%.15f)\n", gt[1], gt[5])
		} else {
			w("GeoTransform =\n  %.16g, %.16g, %.16g\n  %.16g, %.16g, %.16g\n", gt[0], gt[1], gt[2], gt[3], gt[4], gt[5])
		}
	}
	// GCPs
	if len(ds.GCPs) > 0 && !o.NoGCP {
		if j {
			gcps := JNewObject()
			if ds.GCPSRS != nil {
				cs := JNewObject()
				cs.Set("wkt", JStr(ds.GCPSRS.WKT2()))
				cs.Set("dataAxisToSRSAxisMapping", mappingJSON(ds.GCPSRS))
				gcps.Set("coordinateSystem", cs)
			}
			arr := JNewArray()
			for _, g := range ds.GCPs {
				e := JNewObject()
				e.Set("id", JStr(g.ID))
				e.Set("info", JStr(g.Info))
				e.Set("pixel", JDouble(g.Pixel))
				e.Set("line", JDouble(g.Line))
				e.Set("x", JDouble(g.X))
				e.Set("y", JDouble(g.Y))
				e.Set("z", JDouble(g.Z))
				arr.Add(e)
			}
			gcps.Set("gcpList", arr)
			root.Set("gcps", gcps)
		} else {
			if ds.GCPSRS != nil {
				writeCRS(&sb, nil, ds.GCPSRS, o, false, "", "GCP Projection")
			}
			for i, g := range ds.GCPs {
				w("GCP[%3d]: Id=%s, Info=%s\n", i, g.ID, g.Info)
				w("          (%.15g,%.15g) -> (%.15g,%.15g,%.15g)\n", g.Pixel, g.Line, g.X, g.Y, g.Z)
			}
		}
	}
	// metadata
	mdRoot := JNewObject()
	writeMDDomains(&sb, mdRoot, ds.MD, o, j, "", false)
	if j {
		root.Set("metadata", mdRoot)
	}
	// corner coordinates
	var ct *CoordTransform
	var ctWGS84 *CoordTransform
	if srs != nil && ds.HasGT {
		geog := srs.GeogCRS()
		if geog != nil {
			geog.setTraditionalMapping()
			if srs.IsGeographic() {
				ct = NewCoordTransform(srs, geog)
			} else {
				ct = NewCoordTransform(srs, geog)
			}
		}
		w84 := getWGS84().Clone()
		w84.setTraditionalMapping()
		ctWGS84 = NewCoordTransform(srs, w84)
	}
	corner := func(name string, x, y float64) *JValue {
		if !ds.HasGT {
			if j {
				return JNewArray().Add(JDouble(x)).Add(JDouble(y))
			}
			w("%-11s ", name)
			w("(%7.1f,%7.1f)\n", x, y)
			return nil
		}
		gx := gt[0] + gt[1]*x + gt[2]*y
		gy := gt[3] + gt[4]*x + gt[5]*y
		if j {
			return JNewArray().Add(JDouble(gx)).Add(JDouble(gy))
		}
		w("%-11s ", name)
		if math.Abs(gx) < 181 && math.Abs(gy) < 91 {
			w("(%12.7f,%12.7f) ", gx, gy)
		} else {
			w("(%12.3f,%12.3f) ", gx, gy)
		}
		if ct != nil {
			lx, ly, ok := ct.TransformOne(gx, gy)
			if ok {
				w("(%s,", gdalDecToDMS(lx, "Long", 2))
				w("%s)", gdalDecToDMS(ly, "Lat", 2))
			}
		}
		w("\n")
		return nil
	}
	fx, fy := float64(ds.XSize), float64(ds.YSize)
	if j {
		cc := JNewObject()
		cc.Set("upperLeft", corner("upperLeft", 0, 0))
		cc.Set("lowerLeft", corner("lowerLeft", 0, fy))
		cc.Set("lowerRight", corner("lowerRight", fx, fy))
		cc.Set("upperRight", corner("upperRight", fx, 0))
		cc.Set("center", corner("center", fx/2, fy/2))
		root.Set("cornerCoordinates", cc)
		if ctWGS84 != nil {
			pts := [][2]float64{{0, 0}, {0, fy}, {fx, fy}, {fx, 0}, {0, 0}}
			ring := JNewArray()
			okAll := true
			for _, p := range pts {
				gx := gt[0] + gt[1]*p[0] + gt[2]*p[1]
				gy := gt[3] + gt[4]*p[0] + gt[5]*p[1]
				lx, ly, ok := ctWGS84.TransformOne(gx, gy)
				if !ok {
					okAll = false
					break
				}
				ring.Add(JNewArray().Add(JDoublePrec(lx, 7)).Add(JDoublePrec(ly, 7)))
			}
			if okAll {
				poly := JNewObject()
				poly.Set("type", JStr("Polygon"))
				poly.Set("coordinates", JNewArray().Add(ring))
				root.Set("wgs84Extent", poly)
			}
		}
	} else {
		w("Corner Coordinates:\n")
		corner("Upper Left", 0, 0)
		corner("Lower Left", 0, fy)
		corner("Upper Right", fx, 0)
		corner("Lower Right", fx, fy)
		corner("Center", fx/2, fy/2)
	}
	// bands
	bandsArr := JNewArray()
	stacBands := JNewArray()
	eoBands := JNewArray()
	for _, b := range ds.Bands {
		bj := JNewObject()
		stb := JNewObject()
		eob := JNewObject()
		if j {
			bj.Set("band", JInt(int64(b.Index)))
			bj.Set("block", JNewArray().Add(JInt(int64(b.BlockX))).Add(JInt(int64(b.BlockY))))
			bj.Set("type", JStr(b.DataType.String()))
			bj.Set("colorInterpretation", JStr(colorInterpName(b.ColorInterp)))
			stb.Set("data_type", JStr(stacDataType(b.DataType)))
			eob.Set("name", JStr("b"+strconv.Itoa(b.Index)))
			if b.Description != "" {
				bj.Set("description", JStr(b.Description))
				eob.Set("description", JStr(b.Description))
			} else {
				eob.Set("description", JStr(colorInterpName(b.ColorInterp)))
			}
		} else {
			w("Band %d Block=%dx%d Type=%s, ColorInterp=%s\n", b.Index, b.BlockX, b.BlockY, b.DataType.String(), colorInterpName(b.ColorInterp))
			if b.Description != "" {
				w("  Description = %s\n", b.Description)
			}
		}
		// min/max
		mnS, gotMin := b.MD.Get("", "STATISTICS_MINIMUM")
		mxS, gotMax := b.MD.Get("", "STATISTICS_MAXIMUM")
		if gotMin || gotMax || o.MinMax {
			if !j {
				w("  ")
			}
			if gotMin {
				if j {
					bj.Set("min", JDoublePrec(cplAtof(mnS), 3))
				} else {
					w("Min=%.3f ", cplAtof(mnS))
				}
			}
			if gotMax {
				if j {
					bj.Set("max", JDoublePrec(cplAtof(mxS), 3))
				} else {
					w("Max=%.3f ", cplAtof(mxS))
				}
			}
			if o.MinMax {
				mn, mx, ok := b.ComputeMinMax(false)
				if ok {
					if j {
						bj.Set("computedMin", JDoublePrec(mn, 3))
						bj.Set("computedMax", JDoublePrec(mx, 3))
					} else {
						w("  Computed Min/Max=%.3f,%.3f", mn, mx)
					}
				} else if !j {
					// GDAL reports failure
				}
			}
			if !j {
				w("\n")
			}
		}
		st, ok := b.GetStatistics(o.ApproxStats, o.Stats || o.ApproxStats)
		if ok {
			if j {
				bj.Set("minimum", JDoublePrec(st.Min, 3))
				bj.Set("maximum", JDoublePrec(st.Max, 3))
				bj.Set("mean", JDoublePrec(st.Mean, 3))
				bj.Set("stdDev", JDoublePrec(st.StdDev, 3))
				sto := JNewObject()
				sto.Set("minimum", JDoublePrec(st.Min, 3))
				sto.Set("maximum", JDoublePrec(st.Max, 3))
				sto.Set("mean", JDoublePrec(st.Mean, 3))
				sto.Set("stddev", JDoublePrec(st.StdDev, 3))
				stb.Set("stats", sto)
			} else {
				w("  Minimum=%.3f, Maximum=%.3f, Mean=%.3f, StdDev=%.3f\n", st.Min, st.Max, st.Mean, st.StdDev)
			}
		}
		if o.Hist {
			var prog *Progress
			if !j {
				prog = NewProgress()
				sb2 := sb.String()
				out(sb2)
				sb.Reset()
			}
			h, ok := b.GetDefaultHistogram(true, prog)
			if ok {
				if j {
					ho := JNewObject()
					ho.Set("count", JInt(int64(h.Buckets)))
					ho.Set("min", JDouble(h.Min))
					ho.Set("max", JDouble(h.Max))
					arr := JNewArray()
					for _, c := range h.Counts {
						arr.Add(JInt(int64(c)))
					}
					ho.Set("buckets", arr)
					bj.Set("histogram", ho)
				} else {
					w("  %d buckets from %g to %g:\n  ", h.Buckets, h.Min, h.Max)
					for _, c := range h.Counts {
						w("%d ", int64(c))
					}
					w("\n")
				}
			}
		}
		if o.Checksum {
			if j {
				bj.Set("checksum", JInt(int64(b.Checksum())))
			} else {
				w("  Checksum=%d\n", b.Checksum())
			}
		}
		if b.HasNoData && !o.NoNodata {
			if j {
				bj.Set("noDataValue", nodataJSON(b))
				stb.Set("nodata", nodataJSON(b))
			} else {
				w("  NoData Value=%s\n", nodataText(b))
			}
		}
		if len(b.Overviews) > 0 {
			if j {
				arr := JNewArray()
				for _, ov := range b.Overviews {
					oo := JNewObject()
					oo.Set("size", JNewArray().Add(JInt(int64(ov.Width()))).Add(JInt(int64(ov.Height()))))
					if o.Checksum {
						oo.Set("checksum", JInt(int64(ov.Checksum())))
					}
					arr.Add(oo)
				}
				bj.Set("overviews", arr)
			} else {
				w("  Overviews: ")
				for i, ov := range b.Overviews {
					if i > 0 {
						w(", ")
					}
					w("%dx%d", ov.Width(), ov.Height())
					if o.Checksum {
						w("*%d", ov.Checksum())
					}
				}
				w("\n")
			}
		}
		if !o.NoMask {
			flags := b.MaskFlags
			if flags != GMF_ALL_VALID && flags != 0 {
				var names []string
				if flags&GMF_PER_DATASET != 0 {
					names = append(names, "PER_DATASET")
				}
				if flags&GMF_ALPHA != 0 {
					names = append(names, "ALPHA")
				}
				if flags&GMF_NODATA != 0 {
					names = append(names, "NODATA")
				}
				if j {
					mo := JNewObject()
					fa := JNewArray()
					for _, n := range names {
						fa.Add(JStr(n))
					}
					mo.Set("flags", fa)
					if ds.MaskBand != nil && flags&GMF_PER_DATASET != 0 && len(ds.MaskBand.Overviews) > 0 {
						arr := JNewArray()
						for _, ov := range ds.MaskBand.Overviews {
							oo := JNewObject()
							oo.Set("size", JNewArray().Add(JInt(int64(ov.Width()))).Add(JInt(int64(ov.Height()))))
							arr.Add(oo)
						}
						mo.Set("overviews", arr)
					}
					bj.Set("mask", mo)
				} else {
					w("  Mask Flags: ")
					for _, n := range names {
						w("%s ", n)
					}
					w("\n")
					if ds.MaskBand != nil && flags&GMF_PER_DATASET != 0 && len(ds.MaskBand.Overviews) > 0 {
						w("  Overviews of mask band: ")
						for i, ov := range ds.MaskBand.Overviews {
							if i > 0 {
								w(", ")
							}
							w("%dx%d", ov.Width(), ov.Height())
						}
						w("\n")
					}
				}
			}
		}
		if b.Unit != "" {
			if j {
				bj.Set("unit", JStr(b.Unit))
				stb.Set("unit", JStr(b.Unit))
			} else {
				w("  Unit Type: %s\n", b.Unit)
			}
		}
		if len(b.Categories) > 0 {
			if j {
				arr := JNewArray()
				for _, c := range b.Categories {
					arr.Add(JStr(c))
				}
				bj.Set("categories", arr)
			} else {
				w("  Categories:\n")
				for i, c := range b.Categories {
					w("    %3d: %s\n", i, c)
				}
			}
		}
		scale := 1.0
		offset := 0.0
		if b.HasScale {
			scale = b.Scale
		}
		if b.HasOffset {
			offset = b.Offset
		}
		if scale != 1 || offset != 0 {
			if j {
				bj.Set("offset", JDouble(offset))
				bj.Set("scale", JDouble(scale))
				stb.Set("scale", JDouble(scale))
				stb.Set("offset", JDouble(offset))
			} else {
				w("  Offset: %.15g,   Scale:%.15g\n", offset, scale)
			}
		}
		bmd := JNewObject()
		writeMDDomains(&sb, bmd, b.MD, o, j, "  ", true)
		if j {
			bj.Set("metadata", bmd)
		}
		if b.ColorTable != nil && !o.NoCT {
			if j {
				cto := JNewObject()
				cto.Set("palette", JStr("RGB"))
				cto.Set("count", JInt(int64(len(b.ColorTable.Entries))))
				arr := JNewArray()
				for _, e := range b.ColorTable.Entries {
					arr.Add(JNewArray().Add(JInt(int64(e.C1))).Add(JInt(int64(e.C2))).Add(JInt(int64(e.C3))).Add(JInt(int64(e.C4))))
				}
				cto.Set("entries", arr)
				bj.Set("colorTable", cto)
			} else {
				w("  Color Table (RGB with %d entries)\n", len(b.ColorTable.Entries))
				for i, e := range b.ColorTable.Entries {
					w("  %3d: %d,%d,%d,%d\n", i, e.C1, e.C2, e.C3, e.C4)
				}
			}
		}
		if j {
			bandsArr.Add(bj)
			stacBands.Add(stb)
			eoBands.Add(eob)
		}
	}
	if j {
		root.Set("bands", bandsArr)
		stac := JNewObject()
		stac.Set("proj:shape", JNewArray().Add(JInt(int64(ds.YSize))).Add(JInt(int64(ds.XSize))))
		if srs != nil {
			stac.Set("proj:wkt2", JStr(srs.WKT2()))
			auth, code := srs.AuthID()
			if strings.EqualFold(auth, "EPSG") {
				c, _ := strconv.Atoi(code)
				stac.Set("proj:epsg", JInt(int64(c)))
			} else {
				stac.Set("proj:epsg", JNullV())
			}
			if pj, err := ParseJSON(srs.PROJJSON()); err == nil {
				stac.Set("proj:projjson", pj)
			}
		}
		if ds.HasGT {
			stac.Set("proj:transform", JNewArray().Add(JDouble(gt[1])).Add(JDouble(gt[2])).Add(JDouble(gt[0])).Add(JDouble(gt[4])).Add(JDouble(gt[5])).Add(JDouble(gt[3])))
		}
		stac.Set("raster:bands", stacBands)
		stac.Set("eo:bands", eoBands)
		root.Set("stac", stac)
		return root.SerializePretty() + "\n"
	}
	return sb.String()
}

func mappingJSON(s *SRS) *JValue {
	arr := JNewArray()
	for _, m := range s.mapping {
		arr.Add(JInt(int64(m)))
	}
	return arr
}

func writeCRS(sb *strings.Builder, root *JValue, srs *SRS, o rasterInfoOpts, j bool, key, title string) {
	if j {
		cs := JNewObject()
		cs.Set("wkt", JStr(srs.WKT2()))
		if strings.EqualFold(o.CRSFormat, "PROJJSON") {
			cs.Delete("wkt")
			if pj, err := ParseJSON(srs.PROJJSON()); err == nil {
				cs.Set("projjson", pj)
			}
		}
		cs.Set("dataAxisToSRSAxisMapping", mappingJSON(srs))
		root.Set(key, cs)
		return
	}
	format := strings.ToUpper(o.CRSFormat)
	if format == "" {
		format = "AUTO"
	}
	var lines []string
	if format == "AUTO" {
		lines = srs.Summary()
	}
	if lines != nil {
		sb.WriteString(title + ":\n")
		for _, l := range lines {
			sb.WriteString(l + "\n")
		}
	} else if format == "PROJJSON" {
		sb.WriteString(title + " PROJJSON:\n" + srs.PROJJSON() + "\n")
	} else {
		sb.WriteString(title + " WKT:\n" + srs.WKT2() + "\n")
	}
	sb.WriteString("Data axis to CRS axis mapping: " + srs.MappingString() + "\n")
}

func writeMDDomains(sb *strings.Builder, obj *JValue, md *Metadata, o rasterInfoOpts, j bool, indent string, isBand bool) {
	if o.NoMD {
		return
	}
	writeOne := func(domain, title string) {
		items := md.List(domain)
		if len(items) == 0 {
			return
		}
		if j {
			if strings.HasPrefix(domain, "xml:") {
				obj.Set(domain, JNewArray().Add(JStr(items[0])))
				return
			}
			obj.Set(domain, mdToJSON(items))
			return
		}
		sb.WriteString(indent + title + ":\n")
		if strings.HasPrefix(domain, "xml:") {
			sb.WriteString(indent + "  " + items[0] + "\n")
			return
		}
		for _, it := range items {
			sb.WriteString(indent + "  " + it + "\n")
		}
	}
	all := false
	for _, d := range o.MDD {
		if strings.EqualFold(d, "all") {
			all = true
		}
	}
	if all {
		for _, d := range md.DomainList() {
			t := "Metadata"
			if d != "" {
				t = "Metadata (" + d + ")"
			}
			if d == "IMAGE_STRUCTURE" {
				t = "Image Structure Metadata"
			}
			writeOne(d, t)
		}
		return
	}
	writeOne("", "Metadata")
	for _, d := range o.MDD {
		if d != "" && d != "IMAGE_STRUCTURE" {
			writeOne(d, "Metadata ("+d+")")
		}
	}
	writeOne("IMAGE_STRUCTURE", "Image Structure Metadata")
	if !isBand {
		writeOne("SUBDATASETS", "Subdatasets")
		writeOne("GEOLOCATION", "Geolocation")
		writeOne("RPC", "RPC Metadata")
	}
}
