// demoteEnsembles replaces datum ensembles by plain datums (as GDAL does on import from EPSG).
func demoteEnsembles(p pjPtr) pjPtr {
	if p == nil {
		return nil
	}
	js := pjAsPROJJSON(p, false)
	if !strings.Contains(js, "\"datum_ensemble\"") {
		return p
	}
	v, err := ParseJSON(js)
	if err != nil {
		return p
	}
	var walk func(o *JValue)
	walk = func(o *JValue) {
		if o == nil {
			return
		}
		if o.Kind == JArray {
			for _, x := range o.Arr {
				walk(x)
			}
			return
		}
		if o.Kind != JObject {
			return
		}
		if de := o.Get("datum_ensemble"); de != nil {
			d := JNewObject()
			name := de.Get("name").Str()
			name = strings.TrimSuffix(name, " ensemble")
			typ := "GeodeticReferenceFrame"
			if de.Get("ellipsoid") == nil {
				typ = "VerticalReferenceFrame"
			}
			d.Set("type", JStr(typ))
			d.Set("name", JStr(name))
			if e := de.Get("ellipsoid"); e != nil {
				e.Delete("id")
				d.Set("ellipsoid", e)
			}
			if pm := de.Get("prime_meridian"); pm != nil {
				d.Set("prime_meridian", pm)
			}
			// replace key in place keeping order
			for i, k := range o.Keys {
				if k == "datum_ensemble" {
					o.Keys[i] = "datum"
				}
			}
			delete(o.Vals, "datum_ensemble")
			o.Vals["datum"] = d
		}
		for _, k := range o.Keys {
			walk(o.Vals[k])
		}
	}
	walk(v)
	np := pjCreate(v.SerializePlain(false))
	if np == nil {
		return p
	}
	pjDestroy(p)
	return np
}
