func roundupDigits(s []byte, pos int) []byte {
	i := pos
	for i >= 0 {
		if s[i] == '.' || s[i] == '-' {
			i--
			continue
		}
		if s[i] == '9' {
			s[i] = '0'
			i--
			continue
		}
		s[i]++
		return s
	}
	// overflow: prepend 1
	if len(s) > 0 && s[0] == '-' {
		return append([]byte{'-', '1'}, s[1:]...)
	}
	return append([]byte{'1'}, s...)
}

// intelliround removes likely round-off artifacts from fixed-point formatted numbers.
func intelliround(str string) string {
	s := []byte(str)
	n := len(s)
	if n <= 10 {
		return str
	}
	dot := strings.IndexByte(str, '.')
	if dot < 0 || strings.ContainsAny(str, "eE") {
		return str
	}
	before := dot - 1
	if s[0] == '-' {
		before--
	}
	if s[n-2] == '0' && s[n-3] == '0' && s[n-4] == '0' && s[n-5] == '0' && s[n-6] == '0' {
		s = s[:n-1]
	} else if dot < n-8 && (before >= 4 || s[n-3] == '0') && (before >= 5 || s[n-4] == '0') &&
		(before >= 6 || s[n-5] == '0') && (before >= 7 || s[n-6] == '0') && (before >= 8 || s[n-7] == '0') &&
		s[n-8] == '0' && s[n-9] == '0' {
		s = s[:n-8]
	} else if s[n-2] == '9' && s[n-3] == '9' && s[n-4] == '9' && s[n-5] == '9' && s[n-6] == '9' {
		s = s[:n-6]
		s = roundupDigits(s, n-7)
	} else if dot < n-9 && (before >= 4 || s[n-3] == '9') && (before >= 5 || s[n-4] == '9') &&
		(before >= 6 || s[n-5] == '9') && (before >= 7 || s[n-6] == '9') && (before >= 8 || s[n-7] == '9') &&
		s[n-8] == '9' && s[n-9] == '9' {
		s = s[:n-9]
		s = roundupDigits(s, n-10)
	}
	return string(s)
}
