{"command":"cd /workspace/gdalgo && cat > dispatch.go <<'EOF'
package main

import (
	"strings"
)

func init() {
	specialLeaf["info"] = func(def *AlgDef, path []string, args []string) int { return runDispatcher(def, "info", args) }
	specialLeaf["convert"] = func(def *AlgDef, path []string, args []string) int { return runDispatcher(def, "convert", args) }
	extraValidators["raster info"] = func(a *Alg) bool {
		if a.IsSet("crs-format") && strings.EqualFold(a.Str("output-format"), "json") {
			a.ReportError(CPLE_AppDefined, "'crs-format' cannot be set when 'format' is set to 'json'")
			return false
		}
		return true
	}
}

// runDispatcher implements 'gdal info' and 'gdal convert'.
func runDispatcher(def *AlgDef, name string, args []string) int {
	for _, a := range args {
		if a == "-h" || a == "--help" {
			out(def.Help)
			return 0
		}
		if a == "--json-usage" {
			out(def.jsonUsage())
			return 0
		}
	}
	// Step 1: own parse
	quietErrors++
	own := newAlg(def)
	okOwn := own.ParseCommandLine(args)
	quietErrors--
	CPLErrorReset()
	var ds *Dataset
	var rest []string
	if okOwn {
		if own.Bool("quiet") {
			progressEnabled = false
		}
		if !own.Validate() {
			printErrStr(def.shortUsage())
			return 1
		}
		v := own.V("input")
		if len(v.DSs) > 0 {
			ds = v.DSs[0]
		}
		if ds == nil {
			printErrStr(def.shortUsage())
			return 1
		}
		// rebuild remaining args (without input)
		for i := 0; i < len(args); i++ {
			if args[i] == v.DSNames[0] {
				continue
			}
			if args[i] == "-i" || args[i] == "--input" || args[i] == "--dataset" {
				i++
				continue
			}
			if strings.HasPrefix(args[i], "--input=") || strings.HasPrefix(args[i], "--dataset=") {
				continue
			}
			rest = append(rest, args[i])
		}
	} else {
		rdef := getAlgDef([]string{"raster", name})
		vdef := getAlgDef([]string{"vector", name})
		takesValue := func(tok string) bool {
			var n string
			var ad *ArgDef
			if strings.HasPrefix(tok, "--") {
				n = tok[2:]
				if strings.Contains(n, "=") {
					return false
				}
				ad = rdef.ByLong[n]
				if ad == nil {
					ad = vdef.ByLong[n]
				}
			} else if len(tok) == 2 {
				n = tok[1:]
				ad = rdef.ByShort[n]
				if ad == nil {
					ad = vdef.ByShort[n]
				}
			}
			return ad != nil && ad.Type != "boolean"
		}
		var positional []int
		inputIdx := -1
		for i := 0; i < len(args); i++ {
			t := args[i]
			if t == "-i" || t == "--input" || t == "--dataset" {
				if i+1 < len(args) {
					inputIdx = i + 1
					i++
				}
				continue
			}
			if strings.HasPrefix(t, "-") && len(t) > 1 && !isNumericStr(t) {
				if takesValue(t) {
					i++
				}
				continue
			}
			positional = append(positional, i)
		}
		if inputIdx < 0 && len(positional) > 0 {
			if name == "convert" && len(positional) >= 2 {
				inputIdx = positional[len(positional)-2]
			} else {
				inputIdx = positional[len(positional)-1]
			}
		}
		if inputIdx < 0 {
