				continue
			}
			rest = append(rest, args[i])
		}
	} else {
		rdef := getAlgDef([]string{"raster", name})
		vdef := getAlgDef([]string{"vector", name})
		takesValue := func(tok string) bool {
			var n string
			var ad *ArgDef
