{"command":"cd /workspace/gdalgo && cat > geojson_read.go <<'EOF'
package main

import (
	"math"
	"path/filepath"
	"strconv"
	"strings"
)

func init() {
	registerDriver(&Driver{ShortName: "GeoJSON", LongName: "GeoJSON", Vector: true, CanOpen: true, CanCreate: true, CanUpdate: true, VirtualIO: true,
		Extensions: []string{"json", "geojson"},
		Identify: func(oi *OpenInfo) bool {
			if strings.HasPrefix(strings.TrimSpace(oi.Filename), "{") {
				return true
			}
			h := strings.TrimLeft(string(oi.Header), " \t\r\n\xef\xbb\xbf")
			if !strings.HasPrefix(h, "{") {
				return false
			}
			if isESRIJSON(h) || isTopoJSON(h) {
				return false
			}
			return strings.Contains(h, "\"type\"") && (strings.Contains(h, "\"FeatureCollection\"") || strings.Contains(h, "\"Feature\"") || strings.Contains(h, "\"coordinates\"") || strings.Contains(h, "\"geometries\"") || strings.Contains(h, "\"features\""))
		},
		Open:         geojsonOpen,
		CreateVector: geojsonCreate,
	})
}

func isESRIJSON(h string) bool {
	return strings.Contains(h, "\"geometryType\"") || strings.Contains(h, "\"spatialReference\"") && strings.Contains(h, "\"esriGeometry")
}

func isTopoJSON(h string) bool {
	return strings.Contains(h, "\"Topology\"")
}

func geojsonOpen(oi *OpenInfo) (*Dataset, error) {
	var text string
	if strings.HasPrefix(strings.TrimSpace(oi.Filename), "{") {
		text = oi.Filename
	} else {
		data, err := vfsReadFile(oi.Filename)
		if err != nil {
			return nil, newOpenErr(CPLE_OpenFailed, "%s: No such file or directory", oi.Filename)
		}
		text = string(data)
	}
	root, err := ParseJSON(strings.TrimPrefix(text, "\xef\xbb\xbf"))
	if err != nil {
		return nil, newOpenErr(CPLE_OpenFailed, "Failed to read GeoJSON data")
	}
	ds := NewDataset(oi.Filename, 0, 0)
	ds.XSize, ds.YSize = 0, 0
	name := root.Get("name").Str()
	if root.Get("name") == nil || root.Get("name").Kind != JString {
		base := filepath.Base(oi.Filename)
		if ext := filepath.Ext(base); ext != "" {
			base = base[:len(base)-len(ext)]
		}
		name = base
		if strings.HasPrefix(strings.TrimSpace(oi.Filename), "{") {
			name = "OGRGeoJSON"
		}
	}
	l := NewLayer(name)
	l.DS = ds
	buildGeoJSONLayer(l, root)
	ds.Layers = []*Layer{l}
	ds.Description = root.Get("description").Str()
	if d := root.Get("description"); d != nil && d.Kind == JString {
		l.MD.Set("", "DESCRIPTION", d.Str())
	}
	return ds, nil
}

type gjFieldState struct {
	fd       *FieldDefn
	resolved bool
	isJSON   bool
	allTZ    int
	tzMixed  bool
	tzSet    bool
}

// classify a JSON value: returns field type, subtype
func gjValueType(v *JValue) (FieldType, FieldSubType, bool) {
	switch v.Kind {
	case JBool:
		return OFTInteger, OFSTBoolean, true
	case JNumber:
		if v.IsIntegral() {
			if v.IsInt {
				if v.I >= math.MinInt32 && v.I <= math.MaxInt32 {
					return OFTInteger, OFSTNone, true
				}
				return OFTInteger64, OFSTNone, true
			}
			return OFTReal, OFSTNone, true
		}
		return OFTReal, OFSTNone, true
	case JString:
		if _, ok := parseOGRDate(v.S); ok {
			return OFTDate, OFSTNone, true
		}
		if _, ok := parseOGRTime(v.S); ok {
			return OFTTime, OFSTNone, true
		}
		if _, ok := parseOGRDateTime(v.S); ok {
			return OFTDateTime, OFSTNone, true
		}
		return OFTString, OFSTNone, true
	case JArray:
		if len(v.Arr) == 0 {
			return OFTString, OFSTJSON, true
		}
		allInt, allInt64, allNum, allStr, allBool := true, true, true, true, true
		for _, x := range v.Arr {
			switch x.Kind {
			case JNumber:
				allStr = false
				allBool = false
				if !x.IsIntegral() || !x.IsInt {
					allInt = false
					allInt64 = false
				} else if x.I < math.MinInt32 || x.I > math.MaxInt32 {
					allInt = false
				}
			case JString:
				allInt, allInt64, allNum, allBool = false, false, false, false
			case JBool:
				allStr = false
				allNum = false
			default:
				return OFTString, OFSTJSON, true
			}
		}
		if allBool {
			return OFTIntegerList, OFSTBoolean, true
		}
		if allInt {
			return OFTIntegerList, OFSTNone, true
		}
		if allInt64 {
			return OFTInteger64List, OFSTNone, true
		}
		if allNum {
			return OFTRealList, OFSTNone, true
		}
		if allStr {
			return OFTStringList, OFSTNone, true
		}
		return OFTString, OFSTJSON, true
	case JObject:
		return OFTString, OFSTJSON, true
	}
	return OFTString, OFSTNone, false
}

func mergeFieldType(fd *FieldDefn, t FieldType, st FieldSubType) {
	ct := fd.Type
	if ct == t {
		if fd.SubType != st {
			if fd.SubType == OFSTBoolean || st == OFSTBoolean {
				fd.SubType = OFSTNone
			}
		}
		return
	}
	isNum := func(x FieldType) bool { return x == OFTInteger || x == OFTInteger64 || x == OFTReal }
	isDT := func(x FieldType) bool { return x == OFTDate || x == OFTTime || x == OFTDateTime }
	switch {
	case fd.SubType == OFSTJSON:
		return
	case isNum(ct) && isNum(t):
		if ct == OFTReal || t == OFTReal {
			fd.Type = OFTReal
		} else {
			fd.Type = OFTInteger64
		}
		fd.SubType = OFSTNone
	case isDT(ct) && isDT(t):
		if (ct == OFTDate && t == OFTDateTime) || (ct == OFTDateTime && t == OFTDate) {
			fd.Type = OFTDateTime
		} else {
			fd.Type = OFTString
		}
	case ct == OFTString && isDT(t), isDT(ct) && t == OFTString:
		fd.Type = OFTString
		fd.SubType = OFSTNone
	case ct.IsList() && t.IsList():
		if (ct == OFTIntegerList || ct == OFTInteger64List || ct == OFTRealList) && (t == OFTIntegerList || t == OFTInteger64List || t == OFTRealList) {
			if ct == OFTRealList || t == OFTRealList {
				fd.Type = OFTRealList
			} else {
				fd.Type = OFTInteger64List
			}
			fd.SubType = OFSTNone
		} else {
			fd.Type = OFTString
			fd.SubType = OFSTJSON
		}
	case ct.IsList() && isNum(t), isNum(ct) && t.IsList():
		// scalar mixed with list
		if (ct == OFTIntegerList || ct == OFTInteger) && (t == OFTInteger || t == OFTIntegerList) {
			fd.Type = OFTIntegerList
		} else if ct == OFTRealList || t == OFTRealList || ct == OFTReal || t == OFTReal {
			fd.Type = OFTRealList
		} else {
			fd.Type = OFTInteger64List
		}
		fd.SubType = OFSTNone
	case ct == OFTStringList && t == OFTString, ct == OFTString && t == OFTStringList:
		fd.Type = OFTStringList
		fd.SubType = OFSTNone
	default:
		fd.Type = OFTString
		fd.SubType = OFSTJSON
	}
}

func buildGeoJSONLayer(l *Layer, root *JValue) {
	var feats []*JValue
	switch root.Get("type").Str() {
	case "FeatureCollection":
		if f := root.Get("features"); f != nil {
			feats = f.Arr
		}
	case "Feature":
		feats = []*JValue{root}
	default:
		if root.Get("type") != nil {
			// bare geometry
			feats = []*JValue{{Kind: JObject, Keys: []string{"type", "geometry"}, Vals: map[string]*JValue{"type": JStr("Feature"), "geometry": root}}}
		}
	}
	// field schema pass
	states := map[string]*gjFieldState{}
	var order []*gjFieldState
	hasStringID := false
	allIntID := true
	anyID := false
	for _, f := range feats {
		id := f.Get("id")
		if id != nil && id.Kind != JNull {
			anyID = true
			if id.Kind == JString {
				hasStringID = true
				allIntID = false
			} else if !(id.Kind == JNumber && id.IsIntegral()) {
				allIntID = false
			}
		}
	}
	if hasStringID || (anyID && !allIntID) {
		st := &gjFieldState{fd: NewFieldDefn("id", OFTString), resolved: true}
		states["id"] = st
		order = append(order, st)
	}
	for _, f := range feats {
		props := f.Get("properties")
		if props == nil || props.Kind != JObject {
			continue
		}
		for _, k := range props.Keys {
			v := props.Vals[k]
			st := states[k]
			if st == nil {
				st = &gjFieldState{fd: NewFieldDefn(k, OFTString)}
				states[k] = st
				order = append(order, st)
			}
			if v.Kind == JNull {
				continue
			}
			t, sub, _ := gjValueType(v)
			if !st.resolved {
				st.fd.Type = t
				st.fd.SubType = sub
				st.resolved = true
			} else {
				mergeFieldType(st.fd, t, sub)
			}
			if t == OFTDateTime && v.Kind == JString {
				dt, _ := parseOGRDateTime(v.S)
				if !st.tzSet {
					st.allTZ = dt.TZ
					st.tzSet = true
				} else if st.allTZ != dt.TZ {
					st.tzMixed = true
				}
			}
		}
	}
	for _, st := range order {
		fd := st.fd
		if fd.SubType == OFSTBoolean {
			fd.Width = 1
		}
		if fd.Type == OFTDateTime && st.tzSet {
			if st.tzMixed {
				fd.TZFlag = OGR_TZFLAG_MIXED_TZ
			} else {
				fd.TZFlag = st.allTZ
			}
		}
		l.Fields = append(l.Fields, fd)
	}
	// geometry type and CRS
	gtype := -1
	any3D := false
	var geoms []*Geom
	for _, f := range feats {
		g := geojsonToGeom(f.Get("geometry"))
		geoms = append(geoms, g)
		if g == nil {
			continue
		}
		if g.Z {
			any3D = true
		}
		if gtype == -1 {
			gtype = g.T
		} else if gtype != g.T {
			gtype = wkbUnknown
		}
	}
	if gtype == -1 {
		gtype = wkbUnknown
	}
	gf := &GeomFieldDefn{Name: "", Type: makeGeomType(gtype, any3D, false), Nullable: true}
	var srs *SRS
	if crs := root.Get("crs"); crs != nil && crs.Kind == JObject {
		srs = geojsonCRS(crs)
	} else {
		if any3D {
			srs = srsFromEPSG(4979)
		} else {
			srs = wgs84GeoJSON()
		}
	}
	gf.SRS = srs
	l.GeomFields = []*GeomFieldDefn{gf}
	// features
	fid := int64(0)
	for i, f := range feats {
		feat := l.NewFeature()
		id := f.Get("id")
		if id != nil && id.Kind == JNumber && id.IsIntegral() && allIntID && !hasStringID {
			feat.FID = id.IntVal()
		} else {
			feat.FID = fid
		}
		fid++
		if st, ok := states["id"]; ok && st.resolved && (hasStringID || (anyID && !allIntID)) {
			idx := l.FieldIndex("id")
			if id != nil && id.Kind != JNull {
				feat.Fields[idx] = FieldValue{State: 2, S: id.Str()}
			}
		}
		props := f.Get("properties")
		if props != nil && props.Kind == JObject {
			for _, k := range props.Keys {
				idx := -1
				for fi, fd := range l.Fields {
					if fd.Name == k {
						idx = fi
						break
					}
				}
				if idx < 0 {
					continue
				}
				setFieldFromJSON(&feat.Fields[idx], l.Fields[idx], props.Vals[k])
			}
		}
		feat.Geoms[0] = geoms[i]
		l.Features = append(l.Features, feat)
	}
	l.nextFID = fid
	l.loaded = true
}

var wgs84GJ *SRS

func wgs84GeoJSON() *SRS {
	if wgs84GJ == nil {
		wgs84GJ = buildGeogCRSFromEPSG(4326)
	}
	return wgs84GJ.Clone()
}

func geojsonCRS(crs *JValue) *SRS {
	props := crs.Get("properties")
	if props == nil {
		return nil
	}
	switch crs.Get("type").Str() {
	case "name":
		n := props.Get("name").Str()
		u := strings.ToUpper(n)
		if strings.Contains(u, "CRS84") || u == "EPSG:4326" && false {
			return wgs84GeoJSON()
		}
		s, ok := srsFromUserInput(n)
		if ok {
			return s
		}
	case "EPSG":
		code := props.Get("code").IntVal()
		return srsFromEPSG(int(code))
	}
	return nil
}

func setFieldFromJSON(fv *FieldValue, fd *FieldDefn, v *JValue) {
	if v == nil {
		return
	}
	if v.Kind == JNull {
		fv.State = 1
		return
	}
	fv.State = 2
	switch fd.Type {
	case OFTInteger, OFTInteger64:
		if v.Kind == JBool {
			if v.B {
				fv.I = 1
			}
		} else if v.Kind == JNumber {
			fv.I = v.IntVal()
		} else {
			fv.I = int64(atoiC(v.Str()))
		}
	case OFTReal:
		fv.F = v.Num()
	case OFTString:
		if fd.SubType == OFSTJSON {
			if v.Kind == JString {
				fv.S = v.S
			} else {
				fv.S = v.SerializeSpaced(false)
			}
		} else if v.Kind == JString {
			fv.S = v.S
		} else {
			fv.S = v.SerializeSpaced(false)
		}
	case OFTDate, OFTTime, OFTDateTime:
		s := v.Str()
		var dt FieldValue
		ok := false
		if d, k := parseOGRDateTime(s); k {
			dt, ok = d, true
		} else if d, k := parseOGRDate(s); k {
			dt, ok = d, true
		} else if d, k := parseOGRTime(s); k {
			dt, ok = d, true
		}
		if ok {
			dt.State = 2
			*fv = dt
		} else {
			fv.State = 0
		}
	case OFTIntegerList, OFTInteger64List:
		for _, x := range v.Arr {
			if x.Kind == JBool {
				fv.IL = append(fv.IL, int64(b2int(x.B)))
			} else {
				fv.IL = append(fv.IL, x.IntVal())
			}
		}
		if v.Kind != JArray {
			fv.IL = []int64{v.IntVal()}
		}
	case OFTRealList:
		for _, x := range v.Arr {
			fv.FL = append(fv.FL, x.Num())
		}
		if v.Kind != JArray {
			fv.FL = []float64{v.Num()}
		}
	case OFTStringList:
		for _, x := range v.Arr {
			fv.SL = append(fv.SL, x.Str())
		}
		if v.Kind != JArray {
			fv.SL = []string{v.Str()}
		}
	}
}

func geojsonToGeom(g *JValue) *Geom {
	if g == nil || g.Kind != JObject {
		return nil
	}
	t := g.Get("type").Str()
	coords := g.Get("coordinates")
	pt := func(c *JValue, geom *Geom) (Pt, bool) {
		if c == nil || c.Kind != JArray || len(c.Arr) < 2 {
			return Pt{}, false
		}
		p := Pt{X: c.Arr[0].Num(), Y: c.Arr[1].Num()}
		if len(c.Arr) >= 3 {
			p.Z = c.Arr[2].Num()
			geom.Z = true
		}
		return p, true
	}
	ptList := func(c *JValue, geom *Geom) []Pt {
		var r []Pt
		if c == nil {
			return r
		}
		for _, x := range c.Arr {
			if p, ok := pt(x, geom); ok {
				r = append(r, p)
			}
		}
		return r
	}
	switch t {
	case "Point":
		geom := &Geom{T: wkbPoint}
		if p, ok := pt(coords, geom); ok {
			geom.Pts = []Pt{p}
		}
		return geom
	case "LineString":
		geom := &Geom{T: wkbLineString}
		geom.Pts = ptList(coords, geom)
		return geom
	case "Polygon":
		geom := &Geom{T: wkbPolygon}
		if coords != nil {
			for _, r := range coords.Arr {
				ring := &Geom{T: wkbLinearRing}
				ring.Pts = ptList(r, geom)
				geom.Parts = append(geom.Parts, ring)
			}
		}
		propagateZ(geom)
		return geom
	case "MultiPoint":
		geom := &Geom{T: wkbMultiPoint}
		if coords != nil {
			for _, c := range coords.Arr {
				p := &Geom{T: wkbPoint}
				if pp, ok := pt(c, geom); ok {
					p.Pts = []Pt{pp}
				}
				geom.Parts = append(geom.Parts, p)
			}
		}
		propagateZ(geom)
		return geom
	case "MultiLineString":
		geom := &Geom{T: wkbMultiLineString}
		if coords != nil {
			for _, c := range coords.Arr {
				ls := &Geom{T: wkbLineString}
				ls.Pts = ptList(c, geom)
				geom.Parts = append(geom.Parts, ls)
			}
		}
		propagateZ(geom)
		return geom
	case "MultiPolygon":
		geom := &Geom{T: wkbMultiPolygon}
		if coords != nil {
			for _, pc := range coords.Arr {
				poly := &Geom{T: wkbPolygon}
				for _, r := range pc.Arr {
					ring := &Geom{T: wkbLinearRing}
					ring.Pts = ptList(r, geom)
					poly.Parts = append(poly.Parts, ring)
				}
				geom.Parts = append(geom.Parts, poly)
			}
		}
		propagateZ(geom)
		return geom
	case "GeometryCollection":
		geom := &Geom{T: wkbGeometryCollection}
		if gs := g.Get("geometries"); gs != nil {
			for _, sg := range gs.Arr {
				sub := geojsonToGeom(sg)
				if sub != nil {
					if sub.Z {
						geom.Z = true
					}
					geom.Parts = append(geom.Parts, sub)
				}
			}
		}
		propagateZ(geom)
		return geom
	}
	return nil
}

func propagateZ(g *Geom) {
	if g.Z {
		g.SetZ(true)
	}
}

// ---------- date/time parsing ----------

func parseDatePart(s string) (y, m, d int, rest string, ok bool) {
	if len(s) < 10 {
		return
	}
	sep := s[4]
	if sep != '-' && sep != '/' || s[7] != sep {
		return
	}
	for _, i := range []int{0, 1, 2, 3, 5, 6, 8, 9} {
		if s[i] < '0' || s[i] > '9' {
			return
		}
	}
	y = atoiC(s[0:4])
	m = atoiC(s[5:7])
	d = atoiC(s[8:10])
	if m < 1 || m > 12 || d < 1 || d > 31 {
		return
	}
	return y, m, d, s[10:], true
}

func parseTimePart(s string) (h, mi int, sec float64, rest string, ok bool) {
	if len(s) < 5 || s[2] != ':' {
		return
	}
	for _, i := range []int{0, 1, 3, 4} {
		if s[i] < '0' || s[i] > '9' {
			return
		}
	}
	h = atoiC(s[0:2])
	mi = atoiC(s[3:5])
	rest = s[5:]
	if len(rest) >= 3 && rest[0] == ':' && rest[1] >= '0' && rest[1] <= '9' && rest[2] >= '0' && rest[2] <= '9' {
		j := 3
		for j < len(rest) && (rest[j] == '.' || (rest[j] >= '0' && rest[j] <= '9')) {
			j++
		}
		sec, _ = strconv.ParseFloat(rest[1:j], 64)
		rest = rest[j:]
	}
	if h > 23 || mi > 59 || sec >= 62 {
		return
	}
	return h, mi, sec, rest, true
}

func parseTZ(s string) (int, bool) {
	if s == "" {
		return 0, true
	}
	if s == "Z" || s == "z" {
		return 100, true
	}
	if s[0] != '+' && s[0] != '-' {
		return 0, false
	}
	sign := 1
	if s[0] == '-' {
		sign = -1
	}
	r := s[1:]
	var hh, mm int
	switch {
	case len(r) == 2:
		hh = atoiC(r)
	case len(r) == 5 && r[2] == ':':
		hh, mm = atoiC(r[0:2]), atoiC(r[3:5])
	case len(r) == 4:
		hh, mm = atoiC(r[0:2]), atoiC(r[2:4])
	default:
		return 0, false
	}
	return 100 + sign*(hh*4+mm/15), true
}

func parseOGRDate(s string) (FieldValue, bool) {
	y, m, d, rest, ok := parseDatePart(s)
	if !ok || rest != "" {
		return FieldValue{}, false
	}
	return FieldValue{Year: y, Month: m, Day: d}, true
}

func parseOGRTime(s string) (FieldValue, bool) {
	h, mi, sec, rest, ok := parseTimePart(s)
	if !ok || rest != "" {
		return FieldValue{}, false
	}
	return FieldValue{Hour: h, Minute: mi, Second: sec}, true
}

func parseOGRDateTime(s string) (FieldValue, bool) {
	y, m, d, rest, ok := parseDatePart(s)
	if !ok || len(rest) < 1 || (rest[0] != 'T' && rest[0] != ' ') {
		return FieldValue{}, false
	}
	h, mi, sec, rest2, ok := parseTimePart(rest[1:])
	if !ok {
		return FieldValue{}, false
	}
	tz, ok := parseTZ(rest2)
	if !ok {
		return FieldValue{}, false
	}
	return FieldValue{Year: y, Month: m, Day: d, Hour: h, Minute: mi, Second: sec, TZ: tz}, true
}
