func fmtSeconds(sec float64) string {
	if sec != math.Floor(sec) {
		return cfmt("%06.3f", sec)
	}
	return cfmt("%02d", int(sec))
}

func fmtTZ(tz int) string {
	if tz <= 1 {
		return ""
	}
	if tz == 100 {
		return "+00"
	}
	off := (tz - 100) * 15
	sign := byte('+')
	if off < 0 {
		sign = '-'
		off = -off
	}
	h := off / 60
	m := off % 60
	if m == 0 {
		return cfmt("%c%02d", int(sign), h)
	}
	return cfmt("%c%02d%02d", int(sign), h, m)
}

func fmtTZISO(tz int) string {
	if tz <= 1 {
		return ""
	}
	if tz == 100 {
		return "Z"
	}
	off := (tz - 100) * 15
	sign := byte('+')
	if off < 0 {
		sign = '-'
		off = -off
	}
	return cfmt("%c%02d:%02d", int(sign), off/60, off%60)
}

// fieldAsString mimics OGRFeature::GetFieldAsString.
func fieldAsString(fd *FieldDefn, fv *FieldValue) string {
	if fv.State == 1 {
		return "(null)"
	}
	if fv.State == 0 {
		return ""
	}
	switch fd.Type {
	case OFTInteger, OFTInteger64:
		return strconv.FormatInt(fv.I, 10)
	case OFTReal:
		return realAsString(fd, fv.F)
	case OFTString:
		return fv.S
	case OFTDate:
		return cfmt("%04d/%02d/%02d", fv.Year, fv.Month, fv.Day)
	case OFTTime:
		return cfmt("%02d:%02d:", fv.Hour, fv.Minute) + fmtSeconds(fv.Second)
	case OFTDateTime:
		return cfmt("%04d/%02d/%02d %02d:%02d:", fv.Year, fv.Month, fv.Day, fv.Hour, fv.Minute) + fmtSeconds(fv.Second) + fmtTZ(fv.TZ)
	case OFTIntegerList, OFTInteger64List:
		var p []string
		for _, v := range fv.IL {
			p = append(p, strconv.FormatInt(v, 10))
		}
		return "(" + strconv.Itoa(len(fv.IL)) + ":" + strings.Join(p, ",") + ")"
	case OFTRealList:
		var p []string
		for _, v := range fv.FL {
			if fd.Width > 0 {
				p = append(p, cfmt("%*.*f", fd.Width, fd.Precision, v))
			} else {
				p = append(p, cfmt("%.16g", v))
			}
		}
		return "(" + strconv.Itoa(len(fv.FL)) + ":" + strings.Join(p, ",") + ")"
	case OFTStringList:
		return "(" + strconv.Itoa(len(fv.SL)) + ":" + strings.Join(fv.SL, ",") + ")"
	case OFTBinary:
		var sb strings.Builder
		for _, b := range fv.Bin {
			sb.WriteString(cfmt("%02X", int(b)))
		}
		return sb.String()
	}
	return ""
}

func realAsString(fd *FieldDefn, v float64) string {
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	if math.IsNaN(v) {
		return "nan"
	}
	if fd.Width > 0 {
		return cfmt("%.*f", fd.Precision, v)
	}
	return cfmt("%.15g", v)
}

type vectorInfoOpts struct {
	JSON      bool
	Features  bool
	Summary   bool
	Limit     int
	HasLimit  bool
	Layers    []string
	Where     string
	SQL       string
	FID       int64
	HasFID    bool
	Dialect   string
	CRSFormat string
}

func init() {
	registerCommand("vector info", runVectorInfo)
}

func runVectorInfo(a *Alg) bool {
	v := a.V("input")
	if len(v.DSs) == 0 || v.DSs[0] == nil {
		return false
	}
	ds := v.DSs[0]
	o := vectorInfoOpts{
		JSON:      strings.EqualFold(a.Str("output-format"), "json"),
		Features:  a.Bool("features"),
		Summary:   a.Bool("summary"),
		Layers:    a.StrList("input-layer"),
		Where:     a.Str("where"),
		SQL:       a.Str("sql"),
		Dialect:   a.Str("dialect"),
		CRSFormat: a.Str("crs-format"),
	}
	if a.IsSet("limit") {
		o.Limit = a.Int("limit")
		o.HasLimit = true
		o.Features = true
	}
	if a.IsSet("fid") {
		o.FID = int64(a.Int("fid"))
		o.HasFID = true
	}
	if strings.HasPrefix(o.Where, "@") {
		if b, err := vfsReadFile(o.Where[1:]); err == nil {
			o.Where = strings.TrimSpace(string(b))
		}
	}
	if strings.HasPrefix(o.SQL, "@") {
		if b, err := vfsReadFile(o.SQL[1:]); err == nil {
			o.SQL = strings.TrimSpace(string(b))
		}
	}
	s, ok := ogrInfo(ds, o)
	out(s)
	return ok
}

func ogrInfo(ds *Dataset, o vectorInfoOpts) (string, bool) {
	var sb strings.Builder
	w := func(format string, args ...interface{}) { sb.WriteString(cfmt(format, args...)) }
	root := JNewObject()
	j := o.JSON
	if j {
		root.Set("description", JStr(ds.Name))
		root.Set("driverShortName", JStr(ds.Driver.ShortName))
		root.Set("driverLongName", JStr(ds.Driver.LongName))
	} else {
		w("INFO: Open of `%s'\n      using driver `%s' successful.\n", ds.Name, ds.Driver.ShortName)
	}
	var layers []*Layer
	if o.SQL != "" {
		res, err := executeSQL(ds, o.SQL, o.Dialect)
		if err != nil {
			return sb.String(), false
		}
		if res != nil {
			layers = []*Layer{res}
		}
	} else if len(o.Layers) > 0 {
		for _, n := range o.Layers {
			l := ds.GetLayerByName(n)
			if l == nil {
