				return sb.String(), false
			}
			layers = append(layers, l)
		}
	} else {
		layers = ds.Layers
	}
	if !j && ds.Driver.ShortName != "" {
		// dataset metadata (non-default domains not shown)
		md := ds.MD.List("")
		if len(md) > 0 && !o.Summary {
			w("Metadata:\n")
			for _, m := range md {
				w("  %s\n", m)
			}
		}
	}
	layersArr := JNewArray()
	if o.Summary && !j {
		for i, l := range layers {
			gt := l.GeomType()
			if len(l.GeomFields) > 1 {
				var parts []string
				for _, g := range l.GeomFields {
					parts = append(parts, geomTypeName(g.Type))
				}
				w("%d: %s (%s)\n", i+1, l.Name, strings.Join(parts, ", "))
			} else if gt != wkbUnknown || len(l.GeomFields) > 0 {
				w("%d: %s (%s)\n", i+1, l.Name, geomTypeName(gt))
			} else {
				w("%d: %s\n", i+1, l.Name)
			}
		}
		return sb.String(), true
	}
	for _, l := range layers {
		feats := l.Feats()
		if o.Where != "" {
			filtered, err := filterFeatures(l, o.Where)
			if err != nil {
				return sb.String(), false
			}
			feats = filtered
		}
		if o.HasFID {
			var f2 []*Feature
