cd /workspace/gdalgo && cat > vectorinfo.go <<'EOF'
package main

import (
	"math"
	"strconv"
	"strings"
)

func fieldTypeDisplay(fd *FieldDefn) string {
	s := fd.Type.String()
	if fd.SubType != OFSTNone {
		s += "(" + fd.SubType.String() + ")"
	}
	return s
}

func fmtSeconds(sec float64) string {
	if sec != math.Floor(sec) {
		return cfmt("%06.3f", sec)
	}
	return cfmt("%02d", int(sec))
}

func fmtTZ(tz int) string {
	if tz <= 1 {
		return ""
	}
	if tz == 100 {
		return "+00"
	}
	off := (tz - 100) * 15
	sign := byte('+')
	if off < 0 {
		sign = '-'
		off = -off
	}
	h := off / 60
	m := off % 60
	if m == 0 {
		return cfmt("%c%02d", int(sign), h)
	}
	return cfmt("%c%02d%02d", int(sign), h, m)
}

func fmtTZISO(tz int) string {
	if tz <= 1 {
		return ""
	}
	if tz == 100 {
		return "Z"
	}
	off := (tz - 100) * 15
	sign := byte('+')
	if off < 0 {
		sign = '-'
		off = -off
	}
	return cfmt("%c%02d:%02d", int(sign), off/60, off%60)
}

// fieldAsString mimics OGRFeature::GetFieldAsString.
func fieldAsString(fd *FieldDefn, fv *FieldValue) string {
	if fv.State == 1 {
		return "(null)"
	}
	if fv.State == 0 {
		return ""
	}
	switch fd.Type {
	case OFTInteger, OFTInteger64:
		return strconv.FormatInt(fv.I, 10)
	case OFTReal:
		return realAsString(fd, fv.F)
	case OFTString:
		return fv.S
	case OFTDate:
		return cfmt("%04d/%02d/%02d", fv.Year, fv.Month, fv.Day)
	case OFTTime:
		return cfmt("%02d:%02d:", fv.Hour, fv.Minute) + fmtSeconds(fv.Second)
	case OFTDateTime:
		return cfmt("%04d/%02d/%02d %02d:%02d:", fv.Year, fv.Month, fv.Day, fv.Hour, fv.Minute) + fmtSeconds(fv.Second) + fmtTZ(fv.TZ)
	case OFTIntegerList, OFTInteger64List:
		var p []string
		for _, v := range fv.IL {
			p = append(p, strconv.FormatInt(v, 10))
		}
		return "(" + strconv.Itoa(len(fv.IL)) + ":" + strings.Join(p, ",") + ")"
	case OFTRealList:
		var p []string
		for _, v := range fv.FL {
			if fd.Width > 0 {
				p = append(p, cfmt("%*.*f", fd.Width, fd.Precision, v))
			} else {
				p = append(p, cfmt("%.16g", v))
			}
		}
		return "(" + strconv.Itoa(len(fv.FL)) + ":" + strings.Join(p, ",") + ")"
	case OFTStringList:
		return "(" + strconv.Itoa(len(fv.SL)) + ":" + strings.Join(fv.SL, ",") + ")"
	case OFTBinary:
		var sb strings.Builder
		for _, b := range fv.Bin {
			sb.WriteString(cfmt("%02X", int(b)))
		}
		return sb.String()
	}
	return ""
}

func realAsString(fd *FieldDefn, v float64) string {
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	if math.IsNaN(v) {
		return "nan"
	}
	if fd.Width > 0 {
		return cfmt("%.*f", fd.Precision, v)
	}
	return cfmt("%.15g", v)
}

type vectorInfoOpts struct {
	JSON      bool
	Features  bool
	Summary   bool
	Limit     int
	HasLimit  bool
	Layers    []string
	Where     string
	SQL       string
	FID       int64
	HasFID    bool
	Dialect   string
	CRSFormat string
}

func init() {
	registerCommand("vector info", runVectorInfo)
}

func runVectorInfo(a *Alg) bool {
	v := a.V("input")
	if len(v.DSs) == 0 || v.DSs[0] == nil {
		return false
	}
	ds := v.DSs[0]
	o := vectorInfoOpts{
		JSON:      strings.EqualFold(a.Str("output-format"), "json"),
		Features:  a.Bool("features"),
		Summary:   a.Bool("summary"),
		Layers:    a.StrList("input-layer"),
		Where:     a.Str("where"),
		SQL:       a.Str("sql"),
		Dialect:   a.Str("dialect"),
		CRSFormat: a.Str("crs-format"),
	}
	if a.IsSet("limit") {
		o.Limit = a.Int("limit")
		o.HasLimit = true
		o.Features = true
	}
	if a.IsSet("fid") {
		o.FID = int64(a.Int("fid"))
		o.HasFID = true
	}
	if strings.HasPrefix(o.Where, "@") {
		if b, err := vfsReadFile(o.Where[1:]); err == nil {
			o.Where = strings.TrimSpace(string(b))
		}
	}
	if strings.HasPrefix(o.SQL, "@") {
		if b, err := vfsReadFile(o.SQL[1:]); err == nil {
			o.SQL = strings.TrimSpace(string(b))
		}
	}
	s, ok := ogrInfo(ds, o)
	out(s)
	return ok
}

func ogrInfo(ds *Dataset, o vectorInfoOpts) (string, bool) {
	var sb strings.Builder
	w := func(format string, args ...interface{}) { sb.WriteString(cfmt(format, args...)) }
	root := JNewObject()
	j := o.JSON
	if j {
		root.Set("description", JStr(ds.Name))
		root.Set("driverShortName", JStr(ds.Driver.ShortName))
		root.Set("driverLongName", JStr(ds.Driver.LongName))
	} else {
		w("INFO: Open of `%s'\n      using driver `%s' successful.\n", ds.Name, ds.Driver.ShortName)
	}
	var layers []*Layer
	if o.SQL != "" {
		res, err := executeSQL(ds, o.SQL, o.Dialect)
		if err != nil {
			return sb.String(), false
		}
		if res != nil {
			layers = []*Layer{res}
		}
	} else if len(o.Layers) > 0 {
		for _, n := range o.Layers {
			l := ds.GetLayerByName(n)
			if l == nil {
				CPLError(CE_Failure, CPLE_AppDefined, "Couldn't fetch requested layer %s!", n)
				return sb.String(), false
			}
			layers = append(layers, l)
		}
	} else {
		layers = ds.Layers
	}
	if !j && ds.Driver.ShortName != "" {
		// dataset metadata (non-default domains not shown)
		md := ds.MD.List("")
		if len(md) > 0 && !o.Summary {
			w("Metadata:\n")
			for _, m := range md {
				w("  %s\n", m)
			}
		}
	}
	layersArr := JNewArray()
	if o.Summary && !j {
		for i, l := range layers {
			gt := l.GeomType()
			if len(l.GeomFields) > 1 {
				var parts []string
				for _, g := range l.GeomFields {
					parts = append(parts, geomTypeName(g.Type))
				}
				w("%d: %s (%s)\n", i+1, l.Name, strings.Join(parts, ", "))
			} else if gt != wkbUnknown || len(l.GeomFields) > 0 {
				w("%d: %s (%s)\n", i+1, l.Name, geomTypeName(gt))
			} else {
				w("%d: %s\n", i+1, l.Name)
			}
		}
		return sb.String(), true
	}
	for _, l := range layers {
		feats := l.Feats()
		if o.Where != "" {
			filtered, err := filterFeatures(l, o.Where)
			if err != nil {
				return sb.String(), false
			}
			feats = filtered
		}
		if o.HasFID {
			var f2 []*Feature
			for _, f := range feats {
				if f.FID == o.FID {
					f2 = append(f2, f)
				}
			}
			feats = f2
		}
		if j {
			lo := JNewObject()
			lo.Set("name", JStr(l.Name))
			lmd := JNewObject()
			for _, d := range l.MD.DomainList() {
				lmd.Set(d, mdToJSON(l.MD.List(d)))
			}
			lo.Set("metadata", lmd)
			if o.Summary {
				gfa := JNewArray()
				for _, g := range l.GeomFields {
					gfo := JNewObject()
					gfo.Set("name", JStr(g.Name))
					gfo.Set("type", JStr(geomTypeJSONName(g.Type)))
					gfa.Add(gfo)
				}
				lo.Set("geometryFields", gfa)
				layersArr.Add(lo)
				continue
			}
			gfa := JNewArray()
			for gi, g := range l.GeomFields {
				gfo := JNewObject()
				gfo.Set("name", JStr(g.Name))
				gfo.Set("type", JStr(geomTypeJSONName(g.Type)))
				gfo.Set("nullable", JBoolV(g.Nullable))
				if env, ok := extentOf(feats, gi); ok {
					ea := JNewArray()
					if geomTypeHasZ(g.Type) {
						e3, _ := extent3DOf(feats, gi)
						ea.Add(JDoubleI(e3.MinX)).Add(JDoubleI(e3.MinY)).Add(JDoubleI(e3.MinZ)).Add(JDoubleI(e3.MaxX)).Add(JDoubleI(e3.MaxY)).Add(JDoubleI(e3.MaxZ))
					} else {
						ea.Add(JDoubleI(env.MinX)).Add(JDoubleI(env.MinY)).Add(JDoubleI(env.MaxX)).Add(JDoubleI(env.MaxY))
					}
					gfo.Set("extent", ea)
				}
				if g.SRS != nil {
					cs := JNewObject()
					if !strings.EqualFold(o.CRSFormat, "PROJJSON") {
						cs.Set("wkt", JStr(g.SRS.WKT2()))
					}
					if pj, err := ParseJSON(g.SRS.PROJJSON()); err == nil && !strings.EqualFold(o.CRSFormat, "WKT2") {
						cs.Set("projjson", pj)
					}
					cs.Set("dataAxisToSRSAxisMapping", mappingJSON(g.SRS))
					if g.SRS.epoch != 0 {
						cs.Set("coordinateEpoch", JDoubleI(g.SRS.epoch))
					}
					gfo.Set("coordinateSystem", cs)
				}
				gfa.Add(gfo)
			}
			lo.Set("geometryFields", gfa)
			lo.Set("featureCount", JInt(int64(len(feats))))
			if l.FIDColumn != "" {
				lo.Set("fidColumnName", JStr(l.FIDColumn))
			}
			fa := JNewArray()
			for _, fd := range l.Fields {
				fo := JNewObject()
				fo.Set("name", JStr(fd.Name))
				fo.Set("type", JStr(fd.Type.String()))
				if fd.SubType != OFSTNone {
					fo.Set("subType", JStr(fd.SubType.String()))
				}
				if fd.Width > 0 {
					fo.Set("width", JInt(int64(fd.Width)))
				}
				if fd.Precision > 0 {
					fo.Set("precision", JInt(int64(fd.Precision)))
				}
				fo.Set("nullable", JBoolV(fd.Nullable))
				fo.Set("uniqueConstraint", JBoolV(fd.Unique))
				if fd.HasDefault {
					fo.Set("defaultValue", JStr(fd.Default))
				}
				if fd.Alias != "" {
					fo.Set("alias", JStr(fd.Alias))
				}
				if fd.Comment != "" {
					fo.Set("comment", JStr(fd.Comment))
				}
				if fd.Type == OFTDateTime {
					if tz := tzFlagName(fd.TZFlag); tz != "" {
						fo.Set("timezone", JStr(tz))
					}
				}
				fa.Add(fo)
			}
			lo.Set("fields", fa)
			if o.Features {
				fea := JNewArray()
				for i, f := range feats {
					if o.HasLimit && i >= o.Limit {
						break
					}
					fea.Add(featureToInfoJSON(l, f))
				}
				lo.Set("features", fea)
			}
			layersArr.Add(lo)
			continue
		}
		// text
		w("\n")
		w("Layer name: %s\n", l.Name)
		if md := l.MD.List(""); len(md) > 0 {
			w("Metadata:\n")
			for _, m := range md {
				w("  %s\n", m)
			}
		}
		if len(l.GeomFields) > 1 {
			for _, g := range l.GeomFields {
				w("Geometry (%s): %s\n", g.Name, geomTypeName(g.Type))
			}
		} else {
			w("Geometry: %s\n", geomTypeName(l.GeomType()))
		}
		w("Feature Count: %d\n", len(feats))
		for gi, g := range l.GeomFields {
			env, ok := extentOf(feats, gi)
			if !ok {
				continue
			}
			prefix := "Extent: "
			if len(l.GeomFields) > 1 {
				prefix = "Extent (" + g.Name + "): "
			}
			if geomTypeHasZ(g.Type) && false {
				e3, _ := extent3DOf(feats, gi)
				w("%s(%f, %f, %f) - (%f, %f, %f)\n", prefix, e3.MinX, e3.MinY, e3.MinZ, e3.MaxX, e3.MaxY, e3.MaxZ)
			} else {
				w("%s(%f, %f) - (%f, %f)\n", prefix, env.MinX, env.MinY, env.MaxX, env.MaxY)
			}
		}
		for _, g := range l.GeomFields {
			title := "Layer Coordinate Reference System"
			if len(l.GeomFields) > 1 {
				title = "SRS WKT (" + g.Name + ")"
			}
			if g.SRS == nil {
				w("%s: (unknown)\n", title)
				continue
			}
			var tsb strings.Builder
			writeCRS(&tsb, nil, g.SRS, rasterInfoOpts{CRSFormat: o.CRSFormat}, false, "", title)
			sb.WriteString(tsb.String())
			if g.SRS.epoch != 0 {
				w("Coordinate epoch: %g\n", g.SRS.epoch)
			}
		}
		if l.FIDColumn != "" {
			w("FID Column = %s\n", l.FIDColumn)
		}
		for _, g := range l.GeomFields {
			if g.Name != "" {
				w("Geometry Column = %s\n", g.Name)
				break
			}
		}
		for _, fd := range l.Fields {
			line := fd.Name + ": " + fieldTypeDisplay(fd)
			if fd.Type != OFTDate && fd.Type != OFTTime && fd.Type != OFTDateTime {
				line += cfmt(" (%d.%d)", fd.Width, fd.Precision)
			}
			if fd.Type == OFTDateTime {
				if tz := tzFlagName(fd.TZFlag); tz != "" {
					line += " (" + tz + ")"
				}
			}
			if !fd.Nullable {
				line += " NOT NULL"
			}
			if fd.Unique {
				line += " UNIQUE"
			}
			if fd.HasDefault {
				line += " DEFAULT " + fd.Default
			}
			if fd.Alias != "" {
				line += ", alternative name=\"" + fd.Alias + "\""
			}
			w("%s\n", line)
		}
		if o.Features {
			for i, f := range feats {
				if o.HasLimit && i >= o.Limit {
					break
				}
				sb.WriteString(dumpFeature(l, f))
			}
		}
	}
	if j {
		root.Set("layers", layersArr)
		if !o.Summary {
			root.Set("metadata", JNewObject())
			root.Set("domains", JNewObject())
			root.Set("relationships", JNewObject())
		}
		return root.SerializePrettyNoSlash() + "\n", true
	}
	return sb.String(), true
}

func tzFlagName(tz int) string {
	switch {
	case tz == OGR_TZFLAG_MIXED_TZ:
		return "mixed timezones"
	case tz == OGR_TZFLAG_UTC:
		return "UTC"
	case tz == OGR_TZFLAG_LOCALTIME:
		return "localtime"
	case tz > 2:
		off := (tz - 100) * 15
		sign := "+"
		if off < 0 {
			sign = "-"
			off = -off
		}
		return cfmt("%s%02d:%02d", sign, off/60, off%60)
	}
	return ""
}

func extentOf(feats []*Feature, gi int) (Envelope, bool) {
	env := EmptyEnvelope()
	has := false
	for _, f := range feats {
		if gi < len(f.Geoms) && f.Geoms[gi] != nil && !f.Geoms[gi].IsEmpty() {
			env.Merge(f.Geoms[gi].Envelope())
			has = true
		}
	}
	return env, has
}

func extent3DOf(feats []*Feature, gi int) (Envelope3D, bool) {
	env := Envelope3D{Envelope: EmptyEnvelope(), MinZ: math.Inf(1), MaxZ: math.Inf(-1)}
	has := false
	for _, f := range feats {
		if gi < len(f.Geoms) && f.Geoms[gi] != nil && !f.Geoms[gi].IsEmpty() {
			env.Merge3D(f.Geoms[gi].Envelope3D())
			has = true
		}
	}
	return env, has
}

// dumpFeature mimics OGRFeature::DumpReadable.
func dumpFeature(l *Layer, f *Feature) string {
	var sb strings.Builder
	sb.WriteString(cfmt("OGRFeature(%s):%d\n", l.Name, f.FID))
	for i, fd := range l.Fields {
		if i >= len(f.Fields) {
			break
		}
		fv := &f.Fields[i]
		if fv.State == 0 {
			continue
		}
		sb.WriteString(cfmt("  %s (%s) = %s\n", fd.Name, fieldTypeDisplay(fd), fieldAsString(fd, fv)))
	}
	if f.Style != "" {
		sb.WriteString("  Style = " + f.Style + "\n")
	}
	for gi, g := range f.Geoms {
		if g == nil {
			continue
		}
		if len(l.GeomFields) > 1 {
			sb.WriteString("  " + l.GeomFields[gi].Name + " = " + g.WKTOGR() + "\n")
		} else {
			sb.WriteString("  " + g.WKTOGR() + "\n")
		}
	}
	sb.WriteString("\n")
	return sb.String()
}

func featureToInfoJSON(l *Layer, f *Feature) *JValue {
	o := JNewObject()
	o.Set("type", JStr("Feature"))
	props := JNewObject()
	for i, fd := range l.Fields {
		fv := &f.Fields[i]
		if fv.State == 0 {
			continue
		}
		if fv.State == 1 {
			props.Set(fd.Name, JNullV())
			continue
		}
		props.Set(fd.Name, fieldToJSONInfo(fd, fv))
	}
	o.Set("properties", props)
	o.Set("fid", JInt(f.FID))
	if len(l.GeomFields) <= 1 {
		g := f.Geom()
		if g == nil {
			o.Set("geometry", JNullV())
		} else {
			o.Set("geometry", geomToGeoJSONInfo(g))
		}
	} else {
		for gi, gf := range l.GeomFields {
			_ = gf
			g := f.Geoms[gi]
			if gi == 0 {
				if g == nil {
					o.Set("geometry", JNullV())
				} else {
					o.Set("geometry", geomToGeoJSONInfo(g))
				}
			}
		}
	}
	return o
}

func fieldToJSONInfo(fd *FieldDefn, fv *FieldValue) *JValue {
	switch fd.Type {
	case OFTInteger:
		if fd.SubType == OFSTBoolean {
			return JBoolV(fv.I != 0)
		}
		return JInt(fv.I)
	case OFTInteger64:
		if fd.SubType == OFSTBoolean {
			return JBoolV(fv.I != 0)
		}
		return JInt(fv.I)
	case OFTReal:
		return JRawNum(jsonDoubleSig(fv.F))
	case OFTString:
		if fd.SubType == OFSTJSON {
			if v, err := ParseJSON(fv.S); err == nil && (v.Kind == JObject || v.Kind == JArray) {
				return v
			}
		}
		return JStr(fv.S)
	case OFTIntegerList, OFTInteger64List:
		a := JNewArray()
		for _, v := range fv.IL {
			if fd.SubType == OFSTBoolean {
				a.Add(JBoolV(v != 0))
			} else {
				a.Add(JInt(v))
			}
		}
		return a
	case OFTRealList:
		a := JNewArray()
		for _, v := range fv.FL {
			a.Add(JRawNum(jsonDoubleSig(v)))
		}
		return a
	case OFTStringList:
		a := JNewArray()
		for _, v := range fv.SL {
			a.Add(JStr(v))
		}
		return a
	}
	return JStr(fieldAsString(fd, fv))
}

// jsonDoubleSig mimics the significant-figures double serializer (17 digits with roundoff trimming).
func jsonDoubleSig(v float64) string {
	return sigFigFormat(v, 17)
}

func sigFigFormat(v float64, n int) string {
	if math.IsNaN(v) {
		return "NaN"
	}
	if math.IsInf(v, 1) {
		return "Infinity"
	}
	if math.IsInf(v, -1) {
		return "-Infinity"
	}
	s := cfmt("%.*g", n, v)
	dot := strings.IndexByte(s, '.')
	if n > 10 && dot >= 0 && (strings.Contains(s[dot:], "999999") || strings.Contains(s[dot:], "000000")) {
		ok := false
		for i := 1; i <= 3; i++ {
			s2 := cfmt("%.*g", n-i, v)
			d2 := strings.IndexByte(s2, '.')
			if d2 >= 0 && !strings.Contains(s2[d2:], "999999") && !strings.Contains(s2[d2:], "000000") {
				s = s2
				ok = true
				break
			}
		}
		if !ok {
			s = cfmt("%.*g", n, v)
		}
	}
	if !strings.ContainsAny(s, ".e") {
		s += ".0"
	}
	return s
}

// geometry as GeoJSON for vector info output (pretty JSON object)
func geomToGeoJSONInfo(g *Geom) *JValue {
	return geomToGeoJSON(g, func(v float64) *JValue { return JRawNum(formatPrecTrim(v, 15)) })
}

func geomToGeoJSON(g *Geom, num func(float64) *JValue) *JValue {
	o := JNewObject()
	coord := func(p Pt, z bool) *JValue {
		a := JNewArray().Add(num(p.X)).Add(num(p.Y))
		if z {
			a.Add(num(p.Z))
		}
		return a
	}
	ring := func(r *Geom, z bool) *JValue {
		a := JNewArray()
		for _, p := range r.Pts {
			a.Add(coord(p, z))
		}
		return a
	}
	switch g.T {
	case wkbPoint:
		o.Set("type", JStr("Point"))
		if len(g.Pts) == 0 {
			o.Set("coordinates", JNewArray())
		} else {
			o.Set("coordinates", coord(g.Pts[0], g.Z))
		}
	case wkbLineString:
		o.Set("type", JStr("LineString"))
		o.Set("coordinates", ring(g, g.Z))
	case wkbPolygon:
		o.Set("type", JStr("Polygon"))
		a := JNewArray()
		for _, r := range g.Parts {
			a.Add(ring(r, g.Z))
		}
		o.Set("coordinates", a)
	case wkbMultiPoint:
		o.Set("type", JStr("MultiPoint"))
		a := JNewArray()
		for _, p := range g.Parts {
			if len(p.Pts) > 0 {
				a.Add(coord(p.Pts[0], g.Z))
			}
		}
		o.Set("coordinates", a)
	case wkbMultiLineString:
		o.Set("type", JStr("MultiLineString"))
		a := JNewArray()
		for _, p := range g.Parts {
			a.Add(ring(p, g.Z))
		}
		o.Set("coordinates", a)
	case wkbMultiPolygon:
		o.Set("type", JStr("MultiPolygon"))
		a := JNewArray()
		for _, p := range g.Parts {
			pa := JNewArray()
			for _, r := range p.Parts {
				pa.Add(ring(r, g.Z))
			}
			a.Add(pa)
		}
		o.Set("coordinates", a)
	case wkbGeometryCollection:
		o.Set("type", JStr("GeometryCollection"))
		a := JNewArray()
		for _, p := range g.Parts {
			a.Add(geomToGeoJSON(p, num))
		}
		o.Set("geometries", a)
	default:
		lin := g.Linearize()
		if lin.T != g.T {
			return geomToGeoJSON(lin, num)
		}
		return JNullV()
	}
	return o
}
