// ---------- OGR-style WKT number formatting ----------

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func isDoubleAnInt(v float64) bool {
	return v >= math.MinInt32 && v <= math.MaxInt32 && v == math.Trunc(v)
}

// ogrFormatDoubleDefault mimics OGRFormatDouble with default WKT options (precision 15).
func ogrFormatDoubleDefault(v float64) string {
	if math.IsInf(v, 1) {
		return "inf"
	}
	if math.IsInf(v, -1) {
		return "-inf"
	}
	if math.IsNaN(v) {
		return "nan"
	}
	if math.Abs(v) < 1 {
		s := cfmt("%.15f", v)
		s = intelliround(s)
		if strings.Contains(s, ".") {
			s = strings.TrimRight(s, "0")
			s = strings.TrimSuffix(s, ".")
		}
		if s == "-0" {
			return "-0"
		}
		return s
	}
	s := cfmt("%.15G", v)
	return s
}

func ogrWktCoord(x, y float64) string {
	if isDoubleAnInt(x) && isDoubleAnInt(y) {
		return strconv.Itoa(int(x)) + " " + strconv.Itoa(int(y))
	}
	xs := ogrFormatDoubleDefault(x)
	if isAllDigits(xs) {
		xs += ".0"
	}
	ys := ogrFormatDoubleDefault(y)
	if isAllDigits(ys) {
		ys += ".0"
	}
	return xs + " " + ys
}

func ogrWktZ(z float64) string {
	if isDoubleAnInt(z) {
		return strconv.Itoa(int(z))
	}
	return ogrFormatDoubleDefault(z)
}

func (g *Geom) ogrCoord(p Pt) string {
	s := ogrWktCoord(p.X, p.Y)
	if g.Z {
		s += " " + ogrWktZ(p.Z)
	}
	if g.M {
		s += " " + ogrWktZ(p.M)
	}
	return s
}

// WKTOGR exports WKT like OGRGeometry::exportToWkt (ISO variant used in DumpReadable).
func (g *Geom) WKTOGR() string {
	name := wktNames[g.T] + g.wktDimSuffix()
	if g.IsEmpty() {
		return name + " EMPTY"
	}
	return name + " " + g.wktBodyOGR()
}

func (g *Geom) wktBodyOGR() string {
	switch g.T {
	case wkbPoint:
		return "(" + g.ogrCoord(g.Pts[0]) + ")"
	case wkbLineString, wkbLinearRing, wkbCircularString:
		var sb strings.Builder
		sb.WriteString("(")
		for i, p := range g.Pts {
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(g.ogrCoord(p))
		}
		sb.WriteString(")")
		return sb.String()
	case wkbPolygon, wkbTriangle:
		var parts []string
		for _, r := range g.Parts {
			r.Z, r.M = g.Z, g.M
			parts = append(parts, r.wktBodyOGR())
		}
		return "(" + strings.Join(parts, ",") + ")"
	case wkbMultiPoint:
		var parts []string
		for _, p := range g.Parts {
			p.Z, p.M = g.Z, g.M
			if p.IsEmpty() {
				parts = append(parts, "EMPTY")
			} else {
				parts = append(parts, "("+g.ogrCoord(p.Pts[0])+")")
			}
		}
		return "(" + strings.Join(parts, ",") + ")"
	case wkbMultiLineString, wkbMultiPolygon, wkbPolyhedralSurface, wkbTIN:
		var parts []string
		for _, p := range g.Parts {
			p.Z, p.M = g.Z, g.M
			if p.IsEmpty() {
				parts = append(parts, "EMPTY")
			} else {
				parts = append(parts, p.wktBodyOGR())
			}
		}
		return "(" + strings.Join(parts, ",") + ")"
	default:
		var parts []string
		for _, p := range g.Parts {
			if (g.T == wkbCompoundCurve || g.T == wkbCurvePolygon || g.T == wkbMultiCurve || g.T == wkbMultiSurface) && (p.T == wkbLineString || p.T == wkbPolygon) {
				p.Z, p.M = g.Z, g.M
				parts = append(parts, p.wktBodyOGR())
			} else {
				parts = append(parts, p.WKTOGR())
			}
		}
		return "(" + strings.Join(parts, ",") + ")"
	}
}

// Linearize converts curve geometries to linear ones (approximately).
func (g *Geom) Linearize() *Geom {
	switch g.T {
	case wkbCircularString:
		return &Geom{T: wkbLineString, Z: g.Z, M: g.M, Pts: append([]Pt{}, g.Pts...)}
	case wkbCompoundCurve:
		n := &Geom{T: wkbLineString, Z: g.Z, M: g.M}
		for _, p := range g.Parts {
			l := p.Linearize()
			for i, pt := range l.Pts {
				if i == 0 && len(n.Pts) > 0 {
					continue
				}
				n.Pts = append(n.Pts, pt)
			}
		}
		return n
	case wkbCurvePolygon:
		n := &Geom{T: wkbPolygon, Z: g.Z, M: g.M}
		for _, p := range g.Parts {
			r := p.Linearize()
			r.T = wkbLinearRing
			n.Parts = append(n.Parts, r)
		}
		return n
	case wkbMultiCurve:
		n := &Geom{T: wkbMultiLineString, Z: g.Z, M: g.M}
		for _, p := range g.Parts {
			n.Parts = append(n.Parts, p.Linearize())
		}
		return n
	case wkbMultiSurface:
		n := &Geom{T: wkbMultiPolygon, Z: g.Z, M: g.M}
		for _, p := range g.Parts {
			n.Parts = append(n.Parts, p.Linearize())
		}
		return n
	}
	return g
}
