{"command":"cd /workspace/gdalgo && cat > gtiff_write.go <<'EOF'
package main

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"math"
	"os"
	"sort"
	"strconv"
	"strings"
)

type wtag struct {
	tag   uint16
	typ   uint16
	count int
	data  []byte
}

type tiffWriter struct {
	tags map[uint16]*wtag
	bo   binary.ByteOrder
}

func newTiffWriter() *tiffWriter {
	return &tiffWriter{tags: map[uint16]*wtag{}, bo: binary.LittleEndian}
}

func (w *tiffWriter) setShorts(tag uint16, vals ...int) {
	b := make([]byte, 2*len(vals))
	for i, v := range vals {
		w.bo.PutUint16(b[2*i:], uint16(v))
	}
	w.tags[tag] = &wtag{tag, 3, len(vals), b}
}

func (w *tiffWriter) setLongs(tag uint16, vals ...uint64) {
	b := make([]byte, 4*len(vals))
	for i, v := range vals {
		w.bo.PutUint32(b[4*i:], uint32(v))
	}
	w.tags[tag] = &wtag{tag, 4, len(vals), b}
}

func (w *tiffWriter) setShortOrLong(tag uint16, v int) {
	if v < 65536 {
		w.setShorts(tag, v)
	} else {
		w.setLongs(tag, uint64(v))
	}
}

func (w *tiffWriter) setDoubles(tag uint16, vals ...float64) {
	b := make([]byte, 8*len(vals))
	for i, v := range vals {
		w.bo.PutUint64(b[8*i:], math.Float64bits(v))
	}
	w.tags[tag] = &wtag{tag, 12, len(vals), b}
}

func (w *tiffWriter) setASCII(tag uint16, s string) {
	b := append([]byte(s), 0)
	w.tags[tag] = &wtag{tag, 2, len(b), b}
}

func (w *tiffWriter) setRationals(tag uint16, vals ...float64) {
	b := make([]byte, 8*len(vals))
	for i, v := range vals {
		num, den := uint32(v*10000+0.5), uint32(10000)
		if v == math.Trunc(v) {
			num, den = uint32(v), 1
		}
		w.bo.PutUint32(b[8*i:], num)
		w.bo.PutUint32(b[8*i+4:], den)
	}
	w.tags[tag] = &wtag{tag, 5, len(vals), b}
}

// writeImage assembles the TIFF file for a single image (plus optional extra IFDs).
type tiffImageIFD struct {
	w      *tiffWriter
	blocks [][]byte
}

func assembleTIFF(ifds []*tiffImageIFD) []byte {
	var out bytes.Buffer
	bo := binary.LittleEndian
	out.Write([]byte{'I', 'I', 42, 0, 8, 0, 0, 0})
	type fixup struct{ pos int }
	var nextPtrPos int = 4
	for k, im := range ifds {
		w := im.w
		// offsets placeholder
		nb := len(im.blocks)
		counts := make([]uint64, nb)
		maxc := uint64(0)
		for i, b := range im.blocks {
			counts[i] = uint64(len(b))
			if counts[i] > maxc {
				maxc = counts[i]
			}
		}
		offTag, cntTag := uint16(tagStripOffsets), uint16(tagStripByteCounts)
		if _, ok := w.tags[tagTileWidth]; ok {
			offTag, cntTag = tagTileOffsets, tagTileByteCounts
		}
		w.setLongs(offTag, make([]uint64, nb)...)
		if maxc < 65536 && offTag == tagStripOffsets {
			vals := make([]int, nb)
			for i, c := range counts {
				vals[i] = int(c)
			}
			w.setShorts(cntTag, vals...)
		} else {
			w.setLongs(cntTag, counts...)
		}
		var keys []int
		for t := range w.tags {
			keys = append(keys, int(t))
		}
		sort.Ints(keys)
		ifdPos := out.Len()
		if ifdPos%2 == 1 {
			out.WriteByte(0)
			ifdPos++
		}
		bo.PutUint32(out.Bytes()[nextPtrPos:], uint32(ifdPos))
		n := len(keys)
		ifdSize := 2 + n*12 + 4
		dataPos := ifdPos + ifdSize
		// compute out-of-line data positions
		type ent struct {
			t      *wtag
			off    int
			inline bool
		}
		ents := make([]ent, n)
		cur := dataPos
		for i, kk := range keys {
			t := w.tags[uint16(kk)]
			if len(t.data) <= 4 {
				ents[i] = ent{t, 0, true}
			} else {
				if cur%2 == 1 {
					cur++
				}
				ents[i] = ent{t, cur, false}
				cur += len(t.data)
			}
		}
		imgPos := cur
		if imgPos%2 == 1 {
			imgPos++
		}
		// block offsets
		offs := make([]uint64, nb)
		p := imgPos
		for i, b := range im.blocks {
			offs[i] = uint64(p)
			p += len(b)
		}
		ot := w.tags[offTag]
		for i, o := range offs {
			bo.PutUint32(ot.data[4*i:], uint32(o))
		}
		// write IFD
		ifd := make([]byte, ifdSize)
		bo.PutUint16(ifd, uint16(n))
		for i, e := range ents {
			b := ifd[2+i*12:]
			bo.PutUint16(b, e.t.tag)
			bo.PutUint16(b[2:], e.t.typ)
			bo.PutUint32(b[4:], uint32(e.t.count))
			if e.inline {
				copy(b[8:12], e.t.data)
			} else {
				bo.PutUint32(b[8:], uint32(e.off))
			}
		}
		out.Write(ifd)
		nextPtrPos = ifdPos + 2 + n*12
		for _, e := range ents {
			if e.inline {
				continue
			}
			for out.Len() < e.off {
				out.WriteByte(0)
			}
			out.Write(e.t.data)
		}
		for out.Len() < imgPos {
			out.WriteByte(0)
		}
		for _, b := range im.blocks {
			out.Write(b)
		}
		_ = k
	}
	return out.Bytes()
}

// ---------- encoding ----------

func putSample(bo binary.ByteOrder, dt DataType, b []byte, re, im float64) {
	switch dt {
	case GDT_Byte:
		b[0] = byte(clampRound(dt, re))
	case GDT_Int8:
		b[0] = byte(int8(clampRound(dt, re)))
	case GDT_UInt16:
		bo.PutUint16(b, uint16(clampRound(dt, re)))
	case GDT_Int16:
		bo.PutUint16(b, uint16(int16(clampRound(dt, re))))
	case GDT_UInt32:
		bo.PutUint32(b, uint32(clampRound(dt, re)))
	case GDT_Int32:
		bo.PutUint32(b, uint32(int32(clampRound(dt, re))))
	case GDT_UInt64:
		v := clampRound(dt, re)
		if v >= 18446744073709551615 {
			bo.PutUint64(b, math.MaxUint64)
		} else {
			bo.PutUint64(b, uint64(v))
		}
	case GDT_Int64:
		v := clampRound(dt, re)
		if v >= 9223372036854775807 {
			bo.PutUint64(b, uint64(math.MaxInt64))
		} else {
			bo.PutUint64(b, uint64(int64(v)))
		}
	case GDT_Float16:
		bo.PutUint16(b, floatToHalf(float32(re)))
	case GDT_Float32:
		bo.PutUint32(b, math.Float32bits(float32(re)))
	case GDT_Float64:
		bo.PutUint64(b, math.Float64bits(re))
	case GDT_CInt16:
		bo.PutUint16(b, uint16(int16(clampRound(GDT_Int16, re))))
		bo.PutUint16(b[2:], uint16(int16(clampRound(GDT_Int16, im))))
	case GDT_CInt32:
		bo.PutUint32(b, uint32(int32(clampRound(GDT_Int32, re))))
		bo.PutUint32(b[4:], uint32(int32(clampRound(GDT_Int32, im))))
	case GDT_CFloat32:
		bo.PutUint32(b, math.Float32bits(float32(re)))
		bo.PutUint32(b[4:], math.Float32bits(float32(im)))
	case GDT_CFloat64:
		bo.PutUint64(b, math.Float64bits(re))
		bo.PutUint64(b[8:], math.Float64bits(im))
	}
}

func tiffSampleFormat(dt DataType) int {
	switch dt {
	case GDT_Int8, GDT_Int16, GDT_Int32, GDT_Int64:
		return 2
	case GDT_Float16, GDT_Float32, GDT_Float64:
		return 3
	case GDT_CInt16, GDT_CInt32:
		return 5
	case GDT_CFloat32, GDT_CFloat64:
		return 6
	}
	return 1
}

func lzwEncode(src []byte) []byte {
	var out []byte
	var acc uint64
	nbits := 0
	codeLen := 9
	emit := func(code int) {
		acc = acc<<uint(codeLen) | uint64(code)
		nbits += codeLen
		for nbits >= 8 {
			out = append(out, byte(acc>>uint(nbits-8)))
			nbits -= 8
		}
	}
	dict := map[string]int{}
	next := 258
	emit(256)
	if len(src) == 0 {
		emit(257)
		if nbits > 0 {
			out = append(out, byte(acc<<uint(8-nbits)))
		}
		return out
	}
	w := []byte{src[0]}
	code := int(src[0])
	for i := 1; i < len(src); i++ {
		c := src[i]
		wc := append(append([]byte{}, w...), c)
		if v, ok := dict[string(wc)]; ok {
			w = wc
			code = v
			continue
		}
		emit(code)
		dict[string(wc)] = next
		next++
		if next+1 > (1<<uint(codeLen)) && codeLen < 12 {
			codeLen++
		}
		if next >= 4094 {
			emit(256)
			dict = map[string]int{}
			next = 258
			codeLen = 9
		}
		w = []byte{c}
		code = int(c)
	}
	emit(code)
	next++
	if next+1 > (1<<uint(codeLen)) && codeLen < 12 {
		codeLen++
	}
	emit(257)
	if nbits > 0 {
		out = append(out, byte(acc<<uint(8-nbits)))
	}
	return out
}

func packbitsEncode(src []byte) []byte {
	var out []byte
	i := 0
	for i < len(src) {
		// run
		j := i + 1
		for j < len(src) && j-i < 128 && src[j] == src[i] {
			j++
		}
		if j-i >= 2 {
			out = append(out, byte(int8(-(j-i-1))), src[i])
			i = j
			continue
		}
		// literal
		j = i + 1
		for j < len(src) && j-i < 128 && !(j+1 < len(src) && src[j] == src[j+1]) {
			j++
		}
		out = append(out, byte(j-i-1))
		out = append(out, src[i:j]...)
		i = j
	}
	return out
}

func deflateEncode(src []byte, level int) []byte {
	var b bytes.Buffer
	if level < 0 || level > 9 {
		level = 6
	}
	zw, _ := zlib.NewWriterLevel(&b, level)
	zw.Write(src)
	zw.Close()
	return b.Bytes()
}

func applyPredictor(buf []byte, w, h, nsamp, bytesPer int, pred int, bo binary.ByteOrder) {
	rowLen := w * nsamp * bytesPer
	if pred == 2 {
		for y := 0; y < h; y++ {
			row := buf[y*rowLen : (y+1)*rowLen]
			switch bytesPer {
			case 1:
				for i := w*nsamp - 1; i >= nsamp; i-- {
					row[i] -= row[i-nsamp]
				}
			case 2:
				for i := w*nsamp - 1; i >= nsamp; i-- {
					bo.PutUint16(row[i*2:], bo.Uint16(row[i*2:])-bo.Uint16(row[(i-nsamp)*2:]))
				}
			case 4:
				for i := w*nsamp - 1; i >= nsamp; i-- {
					bo.PutUint32(row[i*4:], bo.Uint32(row[i*4:])-bo.Uint32(row[(i-nsamp)*4:]))
				}
			case 8:
				for i := w*nsamp - 1; i >= nsamp; i-- {
					bo.PutUint64(row[i*8:], bo.Uint64(row[i*8:])-bo.Uint64(row[(i-nsamp)*8:]))
				}
			}
		}
	} else if pred == 3 {
		tmp := make([]byte, rowLen)
		wc := w * nsamp
		for y := 0; y < h; y++ {
			row := buf[y*rowLen : (y+1)*rowLen]
			copy(tmp, row)
			for i := 0; i < wc; i++ {
				for b := 0; b < bytesPer; b++ {
					var src int
					if bo == binary.LittleEndian {
						src = i*bytesPer + (bytesPer - 1 - b)
					} else {
						src = i*bytesPer + b
					}
					row[b*wc+i] = tmp[src]
				}
			}
			for i := rowLen - 1; i >= nsamp; i-- {
				row[i] -= row[i-nsamp]
			}
		}
	}
}

// gtiffWriteDataset writes ds into a GeoTIFF file.
func gtiffWriteDataset(name string, ds *Dataset, opts []string, prog *Progress) error {
	data, err := gtiffEncode(ds, opts, prog)
	if err != nil {
		return err
	}
	return vfsWriteFile(name, data)
}

func gtiffEncode(ds *Dataset, opts []string, prog *Progress) ([]byte, error) {
	nb := len(ds.Bands)
	if nb == 0 {
		return nil, newOpenErr(CPLE_NotSupported, "Attempt to create %dx%dx%d TIFF file, need at least one band.", ds.XSize, ds.YSize, nb)
	}
	dt := ds.Bands[0].DataType
	w := newTiffWriter()
	W, H := ds.XSize, ds.YSize
	w.setShortOrLong(tagImageWidth, W)
	w.setShortOrLong(tagImageLength, H)
	bps := dt.Size() * 8
	nbitsOpt := csvFetchDef(opts, "NBITS", "")
	if nbitsOpt != "" {
		bps = atoiC(nbitsOpt)
	} else if v, ok := ds.Bands[0].MD.Get("IMAGE_STRUCTURE", "NBITS"); ok && dt == GDT_Byte {
		bps = atoiC(v)
	}
	bpsList := make([]int, nb)
	for i := range bpsList {
		bpsList[i] = bps
	}
	w.setShorts(tagBitsPerSample, bpsList...)
	comp := strings.ToUpper(csvFetchDef(opts, "COMPRESS", "NONE"))
	compCode := 1
	switch comp {
	case "LZW":
		compCode = 5
	case "DEFLATE", "ZIP":
		compCode = 8
	case "PACKBITS":
		compCode = 32773
	case "NONE":
		compCode = 1
	default:
		compCode = 1
	}
	w.setShorts(tagCompression, compCode)
	// photometric
	photometric := 1
	popt := strings.ToUpper(csvFetchDef(opts, "PHOTOMETRIC", ""))
	ci := func(i int) int { return ds.Bands[i].ColorInterp }
	switch {
	case popt == "RGB":
		photometric = 2
	case popt == "MINISBLACK":
		photometric = 1
	case popt == "MINISWHITE":
		photometric = 0
	case popt == "PALETTE":
		photometric = 3
	case popt == "":
		if nb >= 1 && ds.Bands[0].ColorTable != nil && (dt == GDT_Byte || dt == GDT_UInt16) && nb == 1 {
			photometric = 3
		} else if nb >= 3 && ci(0) == GCI_RedBand && ci(1) == GCI_GreenBand && ci(2) == GCI_BlueBand {
			photometric = 2
		} else if nb >= 3 && ds.Extra["gtiff_default_rgb"] != nil && dt == GDT_Byte {
			photometric = 2
		}
	}
	w.setShorts(tagPhotometric, photometric)
	interleave := strings.ToUpper(csvFetchDef(opts, "INTERLEAVE", "PIXEL"))
	planar := 1
	if interleave == "BAND" && nb > 1 {
		planar = 2
	}
	w.setShorts(tagSamplesPerPixel, nb)
	tiled := CPLTestBool(csvFetchDef(opts, "TILED", "NO"))
	bx, by := W, 0
	ssz := dt.Size()
	if tiled {
		bx = atoiC(csvFetchDef(opts, "BLOCKXSIZE", "256"))
		by = atoiC(csvFetchDef(opts, "BLOCKYSIZE", strconv.Itoa(bx)))
		w.setShortOrLong(tagTileWidth, bx)
		w.setShortOrLong(tagTileLength, by)
	} else {
		if v := csvFetchDef(opts, "BLOCKYSIZE", ""); v != "" {
			by = atoiC(v)
		} else {
			pix := ssz
			if planar == 1 {
				pix *= nb
			}
			by = 8192 / (W * pix)
			if by < 1 {
				by = 1
			}
		}
		if by > H {
			by = H
		}
		w.setShortOrLong(tagRowsPerStrip, by)
	}
	w.setShorts(tagPlanarConfig, planar)
	predictor := atoiC(csvFetchDef(opts, "PREDICTOR", "1"))
	if predictor > 1 && compCode != 1 {
		w.setShorts(tagPredictor, predictor)
	} else {
		predictor = 1
	}
	if photometric == 3 && ds.Bands[0].ColorTable != nil {
		n := 1 << uint(bps)
		cm := make([]int, 3*n)
		for i, e := range ds.Bands[0].ColorTable.Entries {
			if i >= n {
				break
			}
			cm[i] = e.C1 * 257
			cm[n+i] = e.C2 * 257
			cm[2*n+i] = e.C3 * 257
		}
		w.setShorts(tagColorMap, cm...)
	}
	// extra samples
	base := 1
	if photometric == 2 {
		base = 3
	}
	if nb > base {
		es := make([]int, nb-base)
		for i := base; i < nb; i++ {
			if ci(i) == GCI_AlphaBand {
				alpha := strings.ToUpper(csvFetchDef(opts, "ALPHA", "UNASSOCIATED"))
				if alpha == "PREMULTIPLIED" || alpha == "ASSOCIATED" {
					es[i-base] = 1
				} else {
					es[i-base] = 2
				}
			}
		}
		w.setShorts(tagExtraSamples, es...)
	}
	sf := make([]int, nb)
	for i := range sf {
		sf[i] = tiffSampleFormat(dt)
	}
	w.setShorts(tagSampleFormat, sf...)
	// georeferencing
	if ds.HasGT {
		gt := ds.GT
		pixelIsPoint := strings.EqualFold(ds.MD.GetDef("", "AREA_OR_POINT", "Area"), "Point")
		ox, oy := gt[0], gt[3]
		if pixelIsPoint {
			ox += gt[1]*0.5 + gt[2]*0.5
			oy += gt[4]*0.5 + gt[5]*0.5
		}
		if gt[2] == 0 && gt[4] == 0 && gt[5] < 0 {
			w.setDoubles(tagModelPixelScale, gt[1], -gt[5], 0)
			w.setDoubles(tagModelTiepoint, 0, 0, 0, ox, oy, 0)
		} else {
			w.setDoubles(tagModelTransform, gt[1], gt[2], 0, ox, gt[4], gt[5], 0, oy, 0, 0, 0, 0, 0, 0, 0, 1)
		}
	} else if len(ds.GCPs) > 0 {
		var tp []float64
		for _, g := range ds.GCPs {
			tp = append(tp, g.Pixel, g.Line, 0, g.X, g.Y, g.Z)
		}
		w.setDoubles(tagModelTiepoint, tp...)
	}
	srs := ds.SRS
	if srs == nil && len(ds.GCPs) > 0 {
		srs = ds.GCPSRS
	}
	if srs != nil || ds.HasGT {
		writeGeoKeys(w, srs, strings.EqualFold(ds.MD.GetDef("", "AREA_OR_POINT", "Area"), "Point"))
	}
	// GDAL metadata
	if xml := buildGDALMetadataXML(ds); xml != "" {
		w.setASCII(tagGDALMetadata, xml)
	}
	// standard TIFF tags from metadata
	for _, t := range []struct {
		tag  uint16
		name string
	}{{tagDocumentName, "TIFFTAG_DOCUMENTNAME"}, {tagImageDescription, "TIFFTAG_IMAGEDESCRIPTION"}, {tagSoftware, "TIFFTAG_SOFTWARE"}, {tagDateTime, "TIFFTAG_DATETIME"}, {tagArtist, "TIFFTAG_ARTIST"}, {tagHostComputer, "TIFFTAG_HOSTCOMPUTER"}, {tagCopyright, "TIFFTAG_COPYRIGHT"}} {
		if v, ok := ds.MD.Get("", t.name); ok {
			w.setASCII(t.tag, v)
		}
	}
	if b0 := ds.Bands[0]; b0.HasNoData {
		w.setASCII(tagGDALNodata, nodataTIFFString(b0))
	}
	// pixel data
	var blocks [][]byte
	encode := func(raw []byte, bw, bh, nsamp int) []byte {
		if predictor > 1 {
			applyPredictor(raw, bw, bh, nsamp, ssz, predictor, w.bo)
		}
		switch compCode {
		case 5:
			return lzwEncode(raw)
		case 8:
			lvl := atoiC(csvFetchDef(opts, "ZLEVEL", "6"))
			return deflateEncode(raw, lvl)
		case 32773:
			return packbitsEncode(raw)
		}
		return raw
	}
	bandData := make([][]float64, nb)
	bandImag := make([][]float64, nb)
	for i, b := range ds.Bands {
		bandData[i] = b.Data()
		if dt.IsComplex() {
			bandImag[i] = b.Imag()
		}
	}
	planes := 1
	nsamp := nb
	if planar == 2 {
		planes = nb
		nsamp = 1
	}
	if bps < 8 {
		// sub-byte packing (strips only)
		for pl := 0; pl < planes; pl++ {
			for y0 := 0; y0 < H; y0 += by {
				bh := by
				if y0+bh > H {
					bh = H - y0
				}
				rowBytes := (W*nsamp*bps + 7) / 8
				raw := make([]byte, rowBytes*bh)
				for yy := 0; yy < bh; yy++ {
					bit := 0
					for x := 0; x < W; x++ {
						for s := 0; s < nsamp; s++ {
							band := s
							if planar == 2 {
								band = pl
							}
							v := int(clampRound(GDT_Byte, bandData[band][(y0+yy)*W+x]))
							for k := bps - 1; k >= 0; k-- {
								if (v>>uint(k))&1 == 1 {
									raw[yy*rowBytes+bit/8] |= 1 << uint(7-bit%8)
								}
								bit++
							}
						}
					}
				}
				blocks = append(blocks, encode(raw, W, bh, nsamp))
			}
		}
	} else if tiled {
		nbx := (W + bx - 1) / bx
		nby := (H + by - 1) / by
		for pl := 0; pl < planes; pl++ {
			for tyi := 0; tyi < nby; tyi++ {
				for txi := 0; txi < nbx; txi++ {
					raw := make([]byte, bx*by*nsamp*ssz)
					for yy := 0; yy < by; yy++ {
						y := tyi*by + yy
						if y >= H {
							break
						}
						for xx := 0; xx < bx; xx++ {
							x := txi*bx + xx
							if x >= W {
								break
							}
							for s := 0; s < nsamp; s++ {
								band := s
								if planar == 2 {
									band = pl
								}
								im := 0.0
								if bandImag[band] != nil {
									im = bandImag[band][y*W+x]
								}
								putSample(w.bo, dt, raw[((yy*bx+xx)*nsamp+s)*ssz:], bandData[band][y*W+x], im)
							}
						}
					}
					blocks = append(blocks, encode(raw, bx, by, nsamp))
				}
			}
		}
	} else {
		for pl := 0; pl < planes; pl++ {
			for y0 := 0; y0 < H; y0 += by {
				bh := by
				if y0+bh > H {
					bh = H - y0
				}
				raw := make([]byte, W*bh*nsamp*ssz)
				for yy := 0; yy < bh; yy++ {
					y := y0 + yy
					for x := 0; x < W; x++ {
						for s := 0; s < nsamp; s++ {
							band := s
							if planar == 2 {
								band = pl
							}
							im := 0.0
							if bandImag[band] != nil {
								im = bandImag[band][y*W+x]
							}
							putSample(w.bo, dt, raw[((yy*W+x)*nsamp+s)*ssz:], bandData[band][y*W+x], im)
						}
					}
				}
				blocks = append(blocks, encode(raw, W, bh, nsamp))
			}
		}
	}
	ifds := []*tiffImageIFD{{w: w, blocks: blocks}}
	return assembleTIFF(ifds), nil
}

func nodataTIFFString(b *Band) string {
	if math.IsNaN(b.NoData) {
		return "nan"
	}
	if math.IsInf(b.NoData, 1) {
		return "inf"
	}
	if math.IsInf(b.NoData, -1) {
		return "-inf"
	}
	if b.DataType == GDT_Float32 {
		return cfmt("%.9g", b.NoData)
	}
	return cfmt("%.18g", b.NoData)
}

func buildGDALMetadataXML(ds *Dataset) string {
	root := NewXElem("GDALMetadata")
	addItem := func(name, val string, sample int, role, domain string) {
		it := root.AddText("Item", val)
		it.SetAttr("name", name)
		if domain != "" {
			it.SetAttr("domain", domain)
		}
		if sample >= 0 {
			it.SetAttr("sample", strconv.Itoa(sample))
		}
		if role != "" {
			it.SetAttr("role", role)
		}
	}
	skip := map[string]bool{"AREA_OR_POINT": true, "TIFFTAG_DOCUMENTNAME": true, "TIFFTAG_IMAGEDESCRIPTION": true, "TIFFTAG_SOFTWARE": true, "TIFFTAG_DATETIME": true, "TIFFTAG_ARTIST": true, "TIFFTAG_HOSTCOMPUTER": true, "TIFFTAG_COPYRIGHT": true, "TIFFTAG_XRESOLUTION": true, "TIFFTAG_YRESOLUTION": true, "TIFFTAG_RESOLUTIONUNIT": true, "TIFFTAG_MINSAMPLEVALUE": true, "TIFFTAG_MAXSAMPLEVALUE": true}
	for _, d := range ds.MD.Domains {
		if d == "IMAGE_STRUCTURE" || d == "DERIVED_SUBDATASETS" || d == "SUBDATASETS" || strings.HasPrefix(d, "xml:") || d == "COLOR_PROFILE" || d == "RPC" || d == "GEOLOCATION" {
			continue
		}
		for _, kv := range ds.MD.List(d) {
			i := strings.IndexByte(kv, '=')
			if i < 0 {
				continue
			}
			if d == "" && skip[kv[:i]] {
				continue
			}
			addItem(kv[:i], kv[i+1:], -1, "", d)
		}
	}
	for bi, b := range ds.Bands {
		for _, d := range b.MD.Domains {
			if d == "IMAGE_STRUCTURE" {
				continue
			}
			for _, kv := range b.MD.List(d) {
				i := strings.IndexByte(kv, '=')
				if i < 0 {
					continue
				}
				if strings.HasPrefix(kv[:i], "STATISTICS_") && d == "" {
					continue
				}
				addItem(kv[:i], kv[i+1:], bi, "", d)
			}
		}
		if b.HasOffset && b.Offset != 0 || b.HasScale && b.Scale != 1 {
			addItem("OFFSET", cfmt("%.16g", b.Offset), bi, "offset", "")
			addItem("SCALE", cfmt("%.16g", b.Scale), bi, "scale", "")
		}
		if b.Unit != "" {
			addItem("UNITTYPE", b.Unit, bi, "unittype", "")
		}
		if b.Description != "" {
			addItem("DESCRIPTION", b.Description, bi, "description", "")
		}
	}
	if len(root.Children) == 0 {
		return ""
	}
	return strings.TrimRight(root.Serialize(), "\n")
}

func writeGeoKeys(w *tiffWriter, srs *SRS, pixelIsPoint bool) {
	type gkey struct {
		id, loc, count, val int
	}
	var keys []gkey
	var asc strings.Builder
	var dbls []float64
	addShort := func(id, v int) { keys = append(keys, gkey{id, 0, 1, v}) }
	addAscii := func(id int, s string) {
		s += "|"
		keys = append(keys, gkey{id, tagGeoAsciiParams, len(s), asc.Len()})
		asc.WriteString(s)
	}
	addDbl := func(id int, v float64) {
		keys = append(keys, gkey{id, tagGeoDoubleParams, 1, len(dbls)})
		dbls = append(dbls, v)
	}
	raster := 1
	if pixelIsPoint {
		raster = 2
	}
	minor := 0
	if srs == nil {
		addShort(1025, raster)
	} else if srs.IsProjected() && srs.EPSGCode() > 0 && !srs.IsCompound() {
		code := srs.EPSGCode()
		addShort(1024, 1)
		addShort(1025, raster)
		addAscii(1026, srs.Name())
		g := srs.GeogCRS()
		gname := "unknown"
		if g != nil {
			gname = g.Name()
		}
		addAscii(2049, gname)
		addShort(2054, 9102)
		addShort(3072, code)
		lu, conv := srs.LinearUnits()
		unitCode := 9001
		if math.Abs(conv-0.3048) < 1e-10 {
			unitCode = 9002
		} else if math.Abs(conv-0.304800609601219) < 1e-12 {
			unitCode = 9003
		}
		_ = lu
		addShort(3076, unitCode)
	} else if srs.IsGeographic() && srs.EPSGCode() > 0 {
		code := srs.EPSGCode()
		is3D := pjType(srs.pj) == PJ_TYPE_GEOGRAPHIC_3D_CRS
		addShort(1024, 2)
		addShort(1025, raster)
		if is3D {
			minor = 1
			addShort(2048, 4326)
			if code == 4979 {
				addShort(4096, code)
			}
		} else {
			addShort(2048, code)
			addAscii(2049, srs.Name())
			addShort(2054, 9102)
			ell := pjEllipsoid(srs.pj)
			a, _, _, invf := pjEllipsoidParams(ell)
			pjDestroy(ell)
			addDbl(2057, a)
			addDbl(2059, invf)
		}
	} else {
		writeUserDefinedGeoKeys(srs, raster, addShort, addAscii, addDbl)
	}
	sort.SliceStable(keys, func(i, j int) bool { return keys[i].id < keys[j].id })
	dir := []int{1, 1, minor, len(keys)}
	for _, k := range keys {
		dir = append(dir, k.id, k.loc, k.count, k.val)
	}
	w.setShorts(tagGeoKeyDirectory, dir...)
	if len(dbls) > 0 {
		w.setDoubles(tagGeoDoubleParams, dbls...)
	}
	if asc.Len() > 0 {
		w.setASCII(tagGeoAsciiParams, asc.String())
	}
}

func writeUserDefinedGeoKeys(srs *SRS, raster int, addShort func(int, int), addAscii func(int, string), addDbl func(int, float64)) {
	if srs.IsGeographic() {
		addShort(1024, 2)
		addShort(1025, raster)
		addShort(2048, 32767)
		addAscii(2049, "GCS Name = "+srs.Name()+"|Primem = Greenwich|")
		addShort(2054, 9102)
		ell := pjEllipsoid(srs.pj)
		a, _, _, invf := pjEllipsoidParams(ell)
		pjDestroy(ell)
		addDbl(2057, a)
		addDbl(2059, invf)
		addDbl(2061, 0)
		return
	}
	addShort(1024, 1)
	addShort(1025, raster)
	addAscii(1026, srs.Name())
	addShort(2048, 32767)
	g := srs.GeogCRS()
	gname := "unknown"
	if g != nil {
		gname = g.Name()
	}
	addAscii(2049, "GCS Name = "+gname+"|Primem = Greenwich|")
	ell := pjEllipsoid(srs.pj)
	a, _, _, invf := pjEllipsoidParams(ell)
	pjDestroy(ell)
	addShort(2054, 9102)
	addDbl(2057, a)
	addDbl(2059, invf)
	addDbl(2061, 0)
	addShort(3072, 32767)
	addShort(3074, 32767)
	h, own := srs.horizontalPJ()
	op := pjCoordOp(h)
	method, _, mcode := pjMethodInfo(op)
	params := map[string]float64{}
	for _, p := range pjParams(op) {
		params[p.Code] = p.Value
	}
	pjDestroy(op)
	if own {
		pjDestroy(h)
	}
	_ = method
	switch mcode {
	case "9807":
		addShort(3075, 1)
		addDbl(3080, params["8802"])
		addDbl(3081, params["8801"])
		addDbl(3082, params["8806"])
		addDbl(3083, params["8807"])
		addDbl(3092, params["8805"])
	case "9804":
		addShort(3075, 7)
		addDbl(3080, params["8802"])
		addDbl(3081, params["8801"])
		addDbl(3082, params["8806"])
		addDbl(3083, params["8807"])
		addDbl(3092, params["8805"])
	case "9802":
		addShort(3075, 8)
		addDbl(3078, params["8823"])
		addDbl(3079, params["8824"])
		addDbl(3084, params["8822"])
		addDbl(3085, params["8821"])
		addDbl(3086, params["8826"])
		addDbl(3087, params["8827"])
	case "9820":
		addShort(3075, 10)
		addDbl(3082, params["8806"])
		addDbl(3083, params["8807"])
		addDbl(3088, params["8802"])
		addDbl(3089, params["8801"])
	case "9822":
		addShort(3075, 11)
		addDbl(3078, params["8823"])
		addDbl(3079, params["8824"])
		addDbl(3080, params["8822"])
		addDbl(3081, params["8821"])
		addDbl(3082, params["8826"])
		addDbl(3083, params["8827"])
	}
	addShort(3076, 9001)
}

// ---------- driver entry points ----------

type gtiffPending struct {
	name string
	opts []string
}

func gtiffCreate(name string, x, y, nb int, dt DataType, opts []string) (*Dataset, error) {
	ds := NewDataset(name, x, y)
	ds.Driver = getDriverByName("GTiff")
	for i := 0; i < nb; i++ {
		b := ds.AddBand(dt)
		b.data = make([]float64, x*y)
		if dt.IsComplex() {
			b.imag = make([]float64, x*y)
		}
		b.loaded = true
	}
	if nb >= 3 && dt == GDT_Byte && strings.ToUpper(csvFetchDef(opts, "PHOTOMETRIC", "")) == "" {
		ds.Extra["gtiff_default_rgb"] = true
		ds.Bands[0].ColorInterp = GCI_RedBand
		ds.Bands[1].ColorInterp = GCI_GreenBand
		ds.Bands[2].ColorInterp = GCI_BlueBand
		if nb == 4 {
			ds.Bands[3].ColorInterp = GCI_AlphaBand
		}
	} else if nb > 0 {
		ds.Bands[0].ColorInterp = GCI_GrayIndex
	}
	ds.FileList = []string{name}
	ds.OnClose = func(d *Dataset) error {
		return gtiffWriteDataset(name, d, opts, nil)
	}
	return ds, nil
}

func gtiffCreateCopy(name string, src *Dataset, opts []string, prog *Progress) (*Dataset, error) {
	if err := gtiffWriteDataset(name, src, opts, prog); err != nil {
		return nil, err
	}
	return nil, nil
}

func removeFileIfExists(name string) {
	if _, err := os.Stat(name); err == nil {
		os.Remove(name)
	}
}
