func gtiffCreate(name string, x, y, nb int, dt DataType, opts []string) (*Dataset, error) {
	ds := NewDataset(name, x, y)
	ds.Driver = getDriverByName("GTiff")
	for i := 0; i < nb; i++ {
		b := ds.AddBand(dt)
		b.data = make([]float64, x*y)
		if dt.IsComplex() {
			b.imag = make([]float64, x*y)
		}
		b.loaded = true
	}
	if nb >= 3 && dt == GDT_Byte && strings.ToUpper(csvFetchDef(opts, "PHOTOMETRIC", "")) == "" {
		ds.Extra["gtiff_default_rgb"] = true
		ds.Bands[0].ColorInterp = GCI_RedBand
		ds.Bands[1].ColorInterp = GCI_GreenBand
		ds.Bands[2].ColorInterp = GCI_BlueBand
		if nb == 4 {
			ds.Bands[3].ColorInterp = GCI_AlphaBand
		}
	} else if nb > 0 {
		ds.Bands[0].ColorInterp = GCI_GrayIndex
	}
	ds.FileList = []string{name}
	ds.OnClose = func(d *Dataset) error {
		return gtiffWriteDataset(name, d, opts, nil)
	}
	return ds, nil
}

func gtiffCreateCopy(name string, src *Dataset, opts []string, prog *Progress) (*Dataset, error) {
	if err := gtiffWriteDataset(name, src, opts, prog); err != nil {
		return nil, err
	}
	return nil, nil
}

func removeFileIfExists(name string) {
	if _, err := os.Stat(name); err == nil {
		os.Remove(name)
	}
}
