// guessDriverForOutput returns the output driver for a filename (or explicit format).
func guessDriverForOutput(name string, raster bool) *Driver {
	ext := fileExt(name)
	low := strings.ToLower(name)
	if strings.HasSuffix(low, ".shp.zip") {
		ext = "shp.zip"
	}
	for _, d := range drivers {
		if raster && !d.Raster || !raster && !d.Vector {
			continue
		}
		if raster && !(d.CanCreate || d.CanCopy) {
			continue
		}
		if !raster && !d.CanCreate {
			continue
		}
		for _, e := range d.Extensions {
			if e == ext {
				return d
			}
		}
	}
	return nil
}

func (a *Alg) outputDriver(name string, raster bool, reportPrefix bool) *Driver {
	if f := a.Str("output-format"); f != "" {
		return getDriverByName(f)
	}
	if strings.HasPrefix(name, "/vsistdout") {
		if raster {
			return getDriverByName("GTiff")
		}
		return getDriverByName("GeoJSON")
	}
	d := guessDriverForOutput(name, raster)
	if d != nil {
		return d
	}
	if fileExt(name) == "" && raster {
		return getDriverByName("GTiff")
	}
	return nil
}

func parseNodataArg(s string) (float64, bool) {
	l := strings.ToLower(s)
	switch l {
	case "none":
		return 0, false
	case "nan":
		return math.NaN(), true
	case "inf", "+inf":
		return math.Inf(1), true
	case "-inf":
		return math.Inf(-1), true
	}
	v, _ := parseRealStrict(s)
	return v, true
}

func nodataRepresentable(dt DataType, v float64) bool {
	if dt.IsFloat() {
		if dt == GDT_Float32 && !math.IsNaN(v) && !math.IsInf(v, 0) && math.Abs(v) > math.MaxFloat32 {
			return false
		}
		return true
	}
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return false
	}
	mn, mx := dt.Range()
	return v >= mn && v <= mx && v == math.Trunc(v)
}

func (a *Alg) parseCRSArg(name string) (*SRS, bool) {
	v := a.Str(name)
	if v == "" {
		return nil, true
	}
	if strings.EqualFold(v, "none") || strings.EqualFold(v, "null") {
		return nil, true
	}
	s, ok := srsFromUserInputReport(v)
	if !ok {
		a.ReportError(CPLE_AppDefined, "Invalid value for '%s' argument", name)
		return nil, false
	}
	return s, true
}

// srsFromUserInputReport emits PROJ-like errors on failure.
func srsFromUserInputReport(v string) (*SRS, bool) {
	s, ok := srsFromUserInput(v)
	if ok {
		return s, true
	}
	u := strings.ToUpper(strings.TrimSpace(v))
	if strings.HasPrefix(u, "EPSG:") || strings.HasPrefix(u, "ESRI:") || strings.HasPrefix(u, "IAU_2015:") {
		code := strings.TrimSpace(v[strings.IndexByte(v, ':')+1:])
		if isIntegerStr(code) {
			CPLError(CE_Failure, CPLE_AppDefined, "PROJ: proj_create_from_database: crs not found")
		}
	}
	return nil, false
}

func deleteExistingDataset(name string) {
	if strings.HasPrefix(name, "/vsimem/") {
		vfsRemove(name)
		return
	}
	st, err := os.Stat(name)
	if err != nil {
		return
	}
	if st.IsDir() {
		return
	}
	low := strings.ToLower(name)
	if strings.HasSuffix(low, ".shp") || strings.HasSuffix(low, ".dbf") || strings.HasSuffix(low, ".shx") {
		base := name[:len(name)-4]
		for _, e := range []string{".shp", ".shx", ".dbf", ".prj", ".cpg", ".qix", ".sbn", ".sbx", ".qmd"} {
			os.Remove(base + e)
			os.Remove(base + strings.ToUpper(e))
		}
		return
	}
	os.Remove(name)
	os.Remove(name + ".aux.xml")
}

func runRasterCreate(a *Alg) bool {
	outName := a.DSName("output")
	var like *Dataset
	if v := a.V("input"); len(v.DSs) > 0 {
		like = v.DSs[0]
	}
	w, h := 0, 0
	nb := a.Int("band-count")
	dt := GDT_Byte
	if a.IsSet("size") {
		sz := a.IntList("size")
		w, h = sz[0], sz[1]
	} else if like != nil {
		w, h = like.XSize, like.YSize
	} else {
		a.ReportError(CPLE_IllegalArg, "Argument 'size' should be specified, or 'like' dataset should be specified")
		return false
	}
	if like != nil {
		if !a.IsSet("band-count") {
			nb = len(like.Bands)
		}
		if !a.IsSet("output-data-type") && len(like.Bands) > 0 {
			dt = like.Bands[0].DataType
		}
	}
	if a.IsSet("output-data-type") {
		dt = dataTypeFromName(a.Str("output-data-type"))
	}
	burn := a.RealList("burn")
	if len(burn) > 1 && len(burn) != nb {
		a.ReportError(CPLE_IllegalArg, "One or %d values should be provided for argument 'burn', given there are %d bands", nb, nb)
		return false
	}
	drv := a.outputDriver(outName, true, true)
	if drv == nil {
		a.ReportError(CPLE_AppDefined, "Cannot guess driver for %s", outName)
		return false
	}
	ds := NewDataset(outName, w, h)
	ds.Driver = drv
	for i := 0; i < nb; i++ {
		b := ds.AddBand(dt)
		b.data = make([]float64, w*h)
		if dt.IsComplex() {
			b.imag = make([]float64, w*h)
		}
		b.loaded = true
		b.BlockX = w
	}
	if like != nil {
		if like.SRS != nil {
			ds.SRS = like.SRS
		}
		if like.HasGT {
			ds.GT = like.GT
			ds.HasGT = true
		}
		for i, b := range ds.Bands {
			if i < len(like.Bands) && like.Bands[i].HasNoData {
				b.HasNoData = true
				b.NoData = like.Bands[i].NoData
			}
		}
		if a.Bool("copy-metadata") {
			for _, d := range like.MD.Domains {
				if d == "IMAGE_STRUCTURE" || d == "DERIVED_SUBDATASETS" {
					continue
				}
				for _, kv := range like.MD.List(d) {
					if i := strings.IndexByte(kv, '='); i >= 0 {
						ds.MD.Set(d, kv[:i], kv[i+1:])
					}
				}
			}
			for i, b := range ds.Bands {
				if i < len(like.Bands) {
					lb := like.Bands[i]
					for _, d := range lb.MD.Domains {
						if d == "IMAGE_STRUCTURE" {
							continue
						}
						for _, kv := range lb.MD.List(d) {
							if j := strings.IndexByte(kv, '='); j >= 0 {
								b.MD.Set(d, kv[:j], kv[j+1:])
							}
						}
					}
					b.Description = lb.Description
					b.HasOffset, b.Offset, b.HasScale, b.Scale, b.Unit = lb.HasOffset, lb.Offset, lb.HasScale, lb.Scale, lb.Unit
					b.ColorInterp = lb.ColorInterp
					b.ColorTable = lb.ColorTable
				}
			}
		}
	}
	if a.IsSet("crs") {
		s, ok := a.parseCRSArg("crs")
		if !ok {
			return false
		}
		ds.SRS = s
	}
	if a.IsSet("bbox") {
		bb := a.RealList("bbox")
		ds.GT = [6]float64{bb[0], (bb[2] - bb[0]) / float64(w), 0, bb[3], 0, -(bb[3] - bb[1]) / float64(h)}
		ds.HasGT = true
	}
	if a.IsSet("nodata") {
		v, has := parseNodataArg(a.Str("nodata"))
		if has && !nodataRepresentable(dt, v) {
			a.ReportError(CPLE_AppDefined, "Setting nodata value failed as it cannot be represented on its data type")
			return false
		}
		for _, b := range ds.Bands {
			b.HasNoData = has
			b.NoData = v
		}
	}
	for _, kv := range a.StrList("metadata") {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			ds.MD.Set("", kv[:i], kv[i+1:])
		}
	}
	for i, b := range ds.Bands {
		fill := 0.0
		if len(burn) == 1 {
			fill = burn[0]
		} else if len(burn) > 1 {
			fill = burn[i]
		} else if b.HasNoData {
			fill = b.NoData
		}
		if fill != 0 {
			fv := clampRound(dt, fill)
			for k := range b.data {
				b.data[k] = fv
			}
		}
	}
	finalizeNewRaster(ds, drv, a.StrList("creation-option"))
	if a.Bool("overwrite") {
		deleteExistingDataset(outName)
	}
	return writeRasterOutput(a, ds, drv, outName, a.StrList("creation-option"), nil)
}

// finalizeNewRaster sets driver-specific defaults (color interpretation, block size, interleave).
func finalizeNewRaster(ds *Dataset, drv *Driver, co []string) {
	if drv.ShortName == "GTiff" || drv.ShortName == "COG" {
		nb := len(ds.Bands)
		if nb == 0 {
			return
		}
		dt := ds.Bands[0].DataType
		allUndef := true
		for _, b := range ds.Bands {
			if b.ColorInterp != GCI_Undefined {
				allUndef = false
			}
		}
		if allUndef {
			if nb >= 3 && dt == GDT_Byte && csvFetchDef(co, "PHOTOMETRIC", "") == "" {
				ds.Bands[0].ColorInterp = GCI_RedBand
				ds.Bands[1].ColorInterp = GCI_GreenBand
				ds.Bands[2].ColorInterp = GCI_BlueBand
				if nb == 4 {
					ds.Bands[3].ColorInterp = GCI_AlphaBand
				}
			} else {
				ds.Bands[0].ColorInterp = GCI_GrayIndex
			}
		}
	}
	if drv.ShortName == "MEM" {
		for _, b := range ds.Bands {
			b.BlockX = ds.XSize
			b.BlockY = 1
		}
	}
}

