{"command":"cd /workspace/gdalgo && cat > geojson_write.go <<'EOF'
package main

import (
	"math"
	"strconv"
	"strings"
)

func geojsonCreate(name string, opts []string) (*Dataset, error) {
	ds := NewDataset(name, 0, 0)
	ds.Driver = geojsonDriver
	return ds, nil
}

func gjNum(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "null"
	}
	if math.Abs(v) > 1e50 {
		return cfmt("%.17g", v)
	}
	return formatPrecTrim(v, 15)
}

func gjNumPrec(prec int) func(float64) string {
	return func(v float64) string {
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return "null"
		}
		if math.Abs(v) > 1e50 {
			return cfmt("%.17g", v)
		}
		return formatPrecTrim(v, prec)
	}
}

func geomToGeoJSONString(g *Geom, num func(float64) string, keepZ bool) string {
	var sb strings.Builder
	coord := func(p Pt, z bool) {
		sb.WriteString("[" + num(p.X) + "," + num(p.Y))
		if z {
			sb.WriteString("," + num(p.Z))
		}
		sb.WriteString("]")
	}
	pts := func(ps []Pt, z bool) {
		sb.WriteString("[")
		for i, p := range ps {
			if i > 0 {
				sb.WriteString(",")
			}
			coord(p, z)
		}
		sb.WriteString("]")
	}
	z := g.Z && keepZ
	switch g.T {
	case wkbPoint:
		sb.WriteString(`{"type":"Point","coordinates":`)
		if len(g.Pts) == 0 {
			sb.WriteString("[]")
		} else {
			coord(g.Pts[0], z)
		}
		sb.WriteString("}")
	case wkbLineString:
		sb.WriteString(`{"type":"LineString","coordinates":`)
		pts(g.Pts, z)
		sb.WriteString("}")
	case wkbPolygon:
		sb.WriteString(`{"type":"Polygon","coordinates":[`)
		for i, r := range g.Parts {
			if i > 0 {
				sb.WriteString(",")
			}
			pts(r.Pts, z)
		}
		sb.WriteString("]}")
	case wkbMultiPoint:
		sb.WriteString(`{"type":"MultiPoint","coordinates":[`)
		first := true
		for _, p := range g.Parts {
			if len(p.Pts) == 0 {
				continue
			}
			if !first {
				sb.WriteString(",")
			}
			first = false
			coord(p.Pts[0], z)
		}
		sb.WriteString("]}")
	case wkbMultiLineString:
		sb.WriteString(`{"type":"MultiLineString","coordinates":[`)
		for i, p := range g.Parts {
			if i > 0 {
				sb.WriteString(",")
			}
			pts(p.Pts, z)
		}
		sb.WriteString("]}")
	case wkbMultiPolygon:
		sb.WriteString(`{"type":"MultiPolygon","coordinates":[`)
		for i, p := range g.Parts {
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString("[")
			for k, r := range p.Parts {
				if k > 0 {
					sb.WriteString(",")
				}
				pts(r.Pts, z)
			}
			sb.WriteString("]")
		}
		sb.WriteString("]}")
	case wkbGeometryCollection:
		sb.WriteString(`{"type":"GeometryCollection","geometries":[`)
		for i, p := range g.Parts {
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(geomToGeoJSONString(p, num, keepZ))
		}
		sb.WriteString("]}")
	default:
		lin := g.Linearize()
		if lin.T != g.T {
			return geomToGeoJSONString(lin, num, keepZ)
		}
		return "null"
	}
	return sb.String()
}

func jsonQuote(s string) string {
	v := JStr(s)
	return v.SerializePlain(false)
}

func fmtISODateTime(fv *FieldValue, t FieldType) string {
	sec := func() string {
		if fv.Second != math.Floor(fv.Second) {
			return cfmt("%06.3f", fv.Second)
		}
		return cfmt("%02d", int(fv.Second))
	}
	switch t {
	case OFTDate:
		return cfmt("%04d-%02d-%02d", fv.Year, fv.Month, fv.Day)
	case OFTTime:
		return cfmt("%02d:%02d:", fv.Hour, fv.Minute) + sec()
	}
	return cfmt("%04d-%02d-%02dT%02d:%02d:", fv.Year, fv.Month, fv.Day, fv.Hour, fv.Minute) + sec() + fmtTZISO(fv.TZ)
}

func fieldToGeoJSONValue(fd *FieldDefn, fv *FieldValue) string {
	if fv.State == 1 {
		return "null"
	}
	switch fd.Type {
	case OFTInteger, OFTInteger64:
		if fd.SubType == OFSTBoolean {
			if fv.I != 0 {
				return "true"
			}
			return "false"
		}
		return strconv.FormatInt(fv.I, 10)
	case OFTReal:
		if math.IsNaN(fv.F) || math.IsInf(fv.F, 0) {
			return "null"
		}
		return sigFigFormat(fv.F, 17)
	case OFTString:
		if fd.SubType == OFSTJSON {
			if v, err := ParseJSON(fv.S); err == nil && (v.Kind == JObject || v.Kind == JArray) {
				return v.SerializePlain(false)
			}
		}
		return jsonQuote(fv.S)
	case OFTDate, OFTTime, OFTDateTime:
		return jsonQuote(fmtISODateTime(fv, fd.Type))
	case OFTIntegerList, OFTInteger64List:
		var p []string
		for _, v := range fv.IL {
			if fd.SubType == OFSTBoolean {
				if v != 0 {
					p = append(p, "true")
				} else {
					p = append(p, "false")
				}
			} else {
				p = append(p, strconv.FormatInt(v, 10))
			}
		}
		return "[" + strings.Join(p, ",") + "]"
	case OFTRealList:
		var p []string
		for _, v := range fv.FL {
			p = append(p, sigFigFormat(v, 17))
		}
		return "[" + strings.Join(p, ",") + "]"
	case OFTStringList:
		var p []string
		for _, v := range fv.SL {
			p = append(p, jsonQuote(v))
		}
		return "[" + strings.Join(p, ",") + "]"
	case OFTBinary:
		return jsonQuote(fieldAsString(fd, fv))
	}
	return "null"
}

func geojsonCRSMember(srs *SRS) string {
	if srs == nil {
		return ""
	}
	auth, code := srs.AuthID()
	if auth == "" {
		return ""
	}
	if strings.EqualFold(auth, "EPSG") && code == "4326" {
		return `"crs": { "type": "name", "properties": { "name": "urn:ogc:def:crs:OGC:1.3:CRS84" } },` + "\n"
	}
	if strings.EqualFold(auth, "OGC") && code == "CRS84" {
		return `"crs": { "type": "name", "properties": { "name": "urn:ogc:def:crs:OGC:1.3:CRS84" } },` + "\n"
	}
	return `"crs": { "type": "name", "properties": { "name": "urn:ogc:def:crs:` + auth + `::` + code + `" } },` + "\n"
}

func geojsonFeatureString(l *Layer, f *Feature, num func(float64) string, keepZ bool, writeID bool) string {
	var sb strings.Builder
	sb.WriteString(`{"type":"Feature",`)
	if writeID && f.FID >= 0 {
		sb.WriteString(`"id":` + strconv.FormatInt(f.FID, 10) + `,`)
	}
	sb.WriteString(`"properties":{`)
	first := true
	for i, fd := range l.Fields {
		if i >= len(f.Fields) {
			break
		}
		fv := &f.Fields[i]
		if fv.State == 0 {
			continue
		}
		if !first {
			sb.WriteString(",")
		}
		first = false
		sb.WriteString(jsonQuote(fd.Name) + ":" + fieldToGeoJSONValue(fd, fv))
	}
	sb.WriteString(`},"geometry":`)
	g := f.Geom()
	if g == nil {
		sb.WriteString("null")
	} else {
		sb.WriteString(geomToGeoJSONString(g, num, keepZ))
	}
	sb.WriteString("}")
	return sb.String()
}

// geojsonSerialize writes the dataset's first layer (GeoJSON supports one layer).
func geojsonSerialize(ds *Dataset, lco []string) string {
	var sb strings.Builder
	if len(ds.Layers) == 0 {
		return ""
	}
	l := ds.Layers[0]
	rfc := CPLTestBool(csvFetchDef(lco, "RFC7946", "NO"))
	prec := 15
	if rfc {
		prec = 7
	}
	if v, ok := csvFetch(lco, "COORDINATE_PRECISION"); ok {
		prec = atoiC(v)
	}
	num := gjNumPrec(prec)
	sb.WriteString("{\n\"type\": \"FeatureCollection\",\n")
	sb.WriteString("\"name\": " + jsonQuote(l.Name) + ",\n")
	if desc, ok := csvFetch(lco, "DESCRIPTION"); ok {
		sb.WriteString("\"description\": " + jsonQuote(desc) + ",\n")
	}
	if !rfc {
		sb.WriteString(geojsonCRSMember(l.SRS()))
	}
	sb.WriteString("\"features\": [\n")
	writeID := CPLTestBool(csvFetchDef(lco, "WRITE_ID", "NO"))
	for i, f := range l.Features {
		if i > 0 {
			sb.WriteString(",\n")
		}
		sb.WriteString(geojsonFeatureString(l, f, num, true, writeID))
	}
	if len(l.Features) == 0 {
		sb.WriteString("\n")
	}
	sb.WriteString("\n]\n}\n")
	return sb.String()
}

func geojsonSeqSerialize(ds *Dataset, lco []string) string {
	var sb strings.Builder
	rs := CPLTestBool(csvFetchDef(lco, "RS", "NO"))
	for _, l := range ds.Layers {
		for _, f := range l.Features {
			if rs {
				sb.WriteString("\x1e")
			}
			sb.WriteString(geojsonFeatureString(l, f, gjNumPrec(15), true, false))
			sb.WriteString("\n")
		}
	}
	return sb.String()
}
EOF
