// createLayer creates an output layer mirroring src schema.
func (o *vecOut) createLayer(name string, src *Layer, gtype int, srs *SRS) (*Layer, error) {
	if o.drv.ShortName == "GeoJSON" && len(o.ds.Layers) > 0 {
		CPLError(CE_Failure, CPLE_NotSupported, "GeoJSON driver does not support creating more than a single layer")
