		for _, fd := range src.Fields {
			l.Fields = append(l.Fields, fd.Clone())
		}
	}
	o.ds.Layers = append(o.ds.Layers, l)
	return l, nil
}

// addFeature converts and appends a feature. Returns error if the driver rejects it.
func (o *vecOut) addFeature(l *Layer, src *Layer, f *Feature, fieldMap []int) error {
	nf := l.NewFeature()
	nf.FID = f.FID
	for i, si := range fieldMap {
		if si >= 0 && si < len(f.Fields) {
			nf.Fields[i] = convertFieldValue(src.Fields[si], l.Fields[i], f.Fields[si])
		}
	}
	if len(nf.Geoms) > 0 && len(f.Geoms) > 0 && f.Geoms[0] != nil {
		nf.Geoms[0] = f.Geoms[0].Clone()
	}
	g := nf.Geom()
	switch o.drv.ShortName {
	case "GeoJSON", "GeoJSONSeq":
		if g != nil && g.Z && !geomTypeHasZ(l.GeomType()) && !o.warnedZ[l] {
			o.warnedZ[l] = true
			CPLError(CE_Warning, CPLE_AppDefined, "Attempt to write Z geometries to layer %s that does not support them. Z component will be discarded", l.Name)
		}
		if o.drv.ShortName == "GeoJSON" {
			nf.FID = -1
		}
	case "ESRI Shapefile":
		if err := shpCheckFeature(o.shp[l], l, nf); err != nil {
