func convertFieldValue(sfd, dfd *FieldDefn, v FieldValue) FieldValue {
	if v.State != 2 || sfd.Type == dfd.Type {
		r := v
		if v.State == 2 && dfd.Type == OFTString && dfd.Width > 0 && len(r.S) > dfd.Width {
			r.S = r.S[:dfd.Width]
		}
		return r
	}
	r := FieldValue{State: 2}
	switch dfd.Type {
	case OFTString:
		r.S = fieldAsString(sfd, &v)
		if sfd.Type == OFTDateTime || sfd.Type == OFTDate || sfd.Type == OFTTime {
			r.S = fieldAsString(sfd, &v)
		}
		if dfd.Width > 0 && len(r.S) > dfd.Width {
			r.S = r.S[:dfd.Width]
		}
	case OFTInteger, OFTInteger64:
		switch sfd.Type {
		case OFTReal:
			r.I = int64(v.F)
		case OFTString:
			r.I = int64(atoiC(v.S))
		default:
			r.I = v.I
		}
	case OFTReal:
		switch sfd.Type {
		case OFTInteger, OFTInteger64:
			r.F = float64(v.I)
		case OFTString:
			r.F = cplAtof(v.S)
		default:
			r.F = v.F
		}
	case OFTDate, OFTDateTime, OFTTime:
		r = v
		if sfd.Type == OFTString {
			if d, ok := parseOGRDateTime(v.S); ok {
				d.State = 2
				r = d
			} else if d, ok := parseOGRDate(v.S); ok {
				d.State = 2
				r = d
			} else {
				r = FieldValue{}
			}
		}
	default:
		r = v
	}
	return r
}

func (o *vecOut) close() bool {
	switch o.drv.ShortName {
	case "GeoJSON":
		s := geojsonSerialize(o.ds, o.lco)
		if o.toStdout {
			out(s)
			return true
		}
		if err := vfsWriteFile(o.name, []byte(s)); err != nil {
			CPLError(CE_Failure, CPLE_OpenFailed, "Failed to create GeoJSON datasource: %s: %s", o.name, "No such file or directory")
			return false
		}
	case "GeoJSONSeq":
		s := geojsonSeqSerialize(o.ds, o.lco)
		if o.toStdout {
			out(s)
			return true
		}
		vfsWriteFile(o.name, []byte(s))
	case "ESRI Shapefile":
		return shpWriteDataset(o)
	case "MEM":
	}
	return true
}

func runVectorConvert(a *Alg) bool {
	src := a.V("input").DSs[0]
	outName := a.DSName("output")
	drv := a.vectorOutputDriver(outName)
	if drv == nil {
		CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
		return false
	}
	if !drv.CanCreate {
		CPLError(CE_Failure, CPLE_AppDefined, "Output driver %s does not support creation", drv.ShortName)
		return false
	}
	return vectorTranslate(a, src, src.Layers, drv, outName)
}

// vectorTranslate copies layers into a new output dataset.
func vectorTranslate(a *Alg, src *Dataset, layers []*Layer, drv *Driver, outName string) bool {
	if names := a.StrList("input-layer"); len(names) > 0 {
		layers = nil
		for _, n := range names {
			l := src.GetLayerByName(n)
			if l == nil {
				CPLError(CE_Failure, CPLE_AppDefined, "Couldn't fetch requested layer '%s'!", n)
				return false
			}
			layers = append(layers, l)
		}
	}
	if a.Bool("overwrite") {
		deleteExistingDataset(outName)
	}
	o := newVecOut(drv, outName, a.StrList("creation-option"), a.StrList("layer-creation-option"))
	if drv.ShortName == "ESRI Shapefile" {
		if !shpPrepareOutput(o, len(layers)) {
			return false
		}
	}
	prog := NewProgress()
	if o.toStdout {
		prog.enabled = false
	}
	total := 0
	for _, l := range layers {
		total += len(l.Feats())
	}
	prog.Update(0)
	done := 0
	skipErrors := a.Bool("skip-errors")
	for _, sl := range layers {
		name := sl.Name
		if ol := a.Str("output-layer"); ol != "" {
			name = ol
		}
		gtype := sl.GeomType()
		var srs *SRS
		if len(sl.GeomFields) > 0 {
			srs = sl.GeomFields[0].SRS
		}
		dl, err := o.createLayer(name, sl, gtype, srs)
		if err != nil {
			return false
		}
		fieldMap := make([]int, len(dl.Fields))
		for i, fd := range dl.Fields {
			fieldMap[i] = -1
			if st := o.shp[dl]; st != nil {
				fieldMap[i] = st.srcIndex[i]
				continue
			}
			for si, sfd := range sl.Fields {
				if sfd.Name == fd.Name {
					fieldMap[i] = si
					break
				}
			}
		}
		for _, f := range sl.Feats() {
			if err := o.addFeature(dl, sl, f, fieldMap); err != nil {
				CPLError(CE_Failure, CPLE_AppDefined, "Unable to write feature %d from layer %s.", f.FID, sl.Name)
				if !skipErrors {
					CPLError(CE_Failure, CPLE_AppDefined, "Failed to write layer '%s'. Use --skip-errors to ignore errors and continue writing.", sl.Name)
					o.close()
					return false
				}
			}
			done++
			if total > 0 {
				prog.Update(float64(done) / float64(total))
			}
		}
	}
	if !o.close() {
		return false
	}
	prog.Update(1)
	return true
}

func fileExists(name string) bool {
	_, err := os.Stat(name)
	return err == nil
}
