// ESRIWKT exports the CRS as ESRI WKT1.
func (s *SRS) ESRIWKT() string {
	if s == nil {
		return ""
	}
	return pjAsWKTOpts(s.pj, PJ_WKT1_ESRI, "MULTILINE=NO")
}

// srsFromESRIWKT imports an ESRI .prj and tries to identify it, as GDAL's shapefile driver does.
func srsFromESRIWKT(wkt string) *SRS {
	p := pjCreateFromWKT(wkt)
	if p == nil {
		return nil
	}
	s := newSRSFromPJ(p)
	if s.EPSGCode() != 0 {
		return s
	}
	res := pjIdentify(p, "EPSG")
	var best pjPtr
	for _, r := range res {
		if r.Conf == 100 && best == nil {
			best = r.Obj
		} else {
			pjDestroy(r.Obj)
		}
	}
	if best != nil {
		code, _ := strconv.Atoi(pjIDCode(best, 0))
		pjDestroy(best)
		if s.IsGeographic() {
			if g := buildGeogCRSFromEPSG(code); g != nil {
				return g
			}
		}
		if e := srsFromEPSG(code); e != nil {
			return e
		}
	}
	return s
}
