cd /workspace/gdalgo && cat > shapefile.go <<'EOF'
package main

import (
	"encoding/binary"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

func init() {
	shapeDriver.Identify = func(oi *OpenInfo) bool {
		low := strings.ToLower(oi.Filename)
		if oi.IsDir {
			return true
		}
		return strings.HasSuffix(low, ".shp") || strings.HasSuffix(low, ".dbf") || strings.HasSuffix(low, ".shz") || strings.HasSuffix(low, ".shp.zip")
	}
	shapeDriver.Open = shpOpen
	shapeDriver.CreateVector = func(name string, opts []string) (*Dataset, error) { return nil, nil }
}

func shpOpen(oi *OpenInfo) (*Dataset, error) {
	ds := NewDataset(oi.Filename, 0, 0)
	if oi.IsDir {
		names, _ := vfsReadDir(oi.Filename)
		var shps []string
		for _, n := range names {
			if strings.HasSuffix(strings.ToLower(n), ".shp") {
				shps = append(shps, n)
			}
		}
		sort.Strings(shps)
		if len(shps) == 0 {
			return nil, nil
		}
		for _, n := range shps {
			l, err := shpReadLayer(filepath.Join(oi.Filename, n))
			if err == nil {
				l.DS = ds
				ds.Layers = append(ds.Layers, l)
			}
		}
		return ds, nil
	}
	if !oi.Exists {
		return nil, newOpenErr(CPLE_OpenFailed, "%s: No such file or directory", oi.Filename)
	}
	l, err := shpReadLayer(oi.Filename)
	if err != nil {
		return nil, err
	}
	l.DS = ds
	ds.Layers = []*Layer{l}
	return ds, nil
}

func shpSibling(path, ext string) string {
	base := path[:len(path)-len(filepath.Ext(path))]
	for _, e := range []string{strings.ToLower(ext), strings.ToUpper(ext)} {
		if _, ok := vfsStat(base + e); ok {
			return base + e
		}
	}
	return ""
}

func latin1ToUTF8(b []byte) string {
	if utf8.Valid(b) {
		ascii := true
		for _, c := range b {
			if c >= 0x80 {
				ascii = false
				break
			}
		}
		if ascii {
			return string(b)
		}
	}
	r := make([]rune, len(b))
	for i, c := range b {
		r[i] = rune(c)
	}
	return string(r)
}

func utf8ToLatin1(s string) []byte {
	var b []byte
	for _, r := range s {
		if r < 256 {
			b = append(b, byte(r))
		} else {
			b = append(b, '?')
		}
	}
	return b
}

func shpReadLayer(path string) (*Layer, error) {
	base := filepath.Base(path)
	name := base[:len(base)-len(filepath.Ext(base))]
	l := NewLayer(name)
	shpPath := path
	if strings.HasSuffix(strings.ToLower(path), ".dbf") {
		shpPath = shpSibling(path, ".shp")
	}
	dbfPath := shpSibling(path, ".dbf")
	var geoms []*Geom
	shpType := 0
	hasShp := shpPath != ""
	if hasShp {
		data, err := vfsReadFile(shpPath)
		if err != nil {
			return nil, newOpenErr(CPLE_OpenFailed, "%s: No such file or directory", path)
		}
		if len(data) < 100 {
			return nil, newOpenErr(CPLE_OpenFailed, "`%s' not recognized as being in a supported file format.", path)
		}
		shpType = int(binary.LittleEndian.Uint32(data[32:]))
		p := 100
		for p+8 <= len(data) {
			cl := int(binary.BigEndian.Uint32(data[p+4:])) * 2
			if p+8+cl > len(data) {
				break
			}
			geoms = append(geoms, shpParseRecord(data[p+8:p+8+cl]))
			p += 8 + cl
		}
	}
	// DBF
	var recs [][]byte
	type dbfField struct {
		name      string
		typ       byte
		width     int
		decimals  int
		off       int
	}
	var dfields []dbfField
	if dbfPath != "" {
		d, err := vfsReadFile(dbfPath)
		if err == nil && len(d) >= 32 {
			nrec := int(binary.LittleEndian.Uint32(d[4:]))
			hs := int(binary.LittleEndian.Uint16(d[8:]))
			rs := int(binary.LittleEndian.Uint16(d[10:]))
			y, m, dd := int(d[1])+1900, int(d[2]), int(d[3])
			l.MD.Set("", "DBF_DATE_LAST_UPDATE", cfmt("%04d-%02d-%02d", y, m, dd))
			off := 1
			for i := 32; i+32 <= hs && d[i] != 0x0d; i += 32 {
				fn := d[i : i+11]
				if k := strings.IndexByte(string(fn), 0); k >= 0 {
					fn = fn[:k]
				}
				f := dbfField{name: latin1ToUTF8(fn), typ: d[i+11], width: int(d[i+16]), decimals: int(d[i+17]), off: off}
				off += f.width
				dfields = append(dfields, f)
			}
			for r := 0; r < nrec; r++ {
				st := hs + r*rs
				if st+rs > len(d) {
					break
				}
				recs = append(recs, d[st:st+rs])
			}
		}
	}
	for _, f := range dfields {
		fd := NewFieldDefn(f.name, OFTString)
		fd.Width = f.width
		switch f.typ {
		case 'N', 'F':
			if f.decimals > 0 {
				fd.Type = OFTReal
				fd.Precision = f.decimals
			} else if f.width < 10 {
				fd.Type = OFTInteger
			} else if f.width < 19 {
				fd.Type = OFTInteger64
			} else {
				fd.Type = OFTReal
			}
		case 'L':
			fd.Type = OFTInteger
			fd.SubType = OFSTBoolean
		case 'D':
			fd.Type = OFTDate
			fd.Width = 0
		}
		l.Fields = append(l.Fields, fd)
	}
	// geometry type
	gt := wkbUnknown
	switch shpType {
	case 1:
		gt = wkbPoint
	case 3:
		gt = wkbLineString
	case 5:
		gt = wkbPolygon
	case 8:
		gt = wkbMultiPoint
	case 11:
		gt = makeGeomType(wkbPoint, true, false)
	case 13:
		gt = makeGeomType(wkbLineString, true, false)
	case 15:
		gt = makeGeomType(wkbPolygon, true, false)
	case 18:
		gt = makeGeomType(wkbMultiPoint, true, false)
	case 21:
		gt = makeGeomType(wkbPoint, false, true)
	case 23:
		gt = makeGeomType(wkbLineString, false, true)
	case 25:
		gt = makeGeomType(wkbPolygon, false, true)
	case 28:
		gt = makeGeomType(wkbMultiPoint, false, true)
	case 0:
		gt = wkbNone
	}
	if hasShp {
		gf := &GeomFieldDefn{Name: "", Type: gt, Nullable: true}
		if prj := shpSibling(shpPath, ".prj"); prj != "" {
			if b, err := vfsReadFile(prj); err == nil {
				gf.SRS = srsFromESRIWKT(strings.TrimSpace(string(b)))
			}
		}
		l.GeomFields = []*GeomFieldDefn{gf}
	}
	n := len(recs)
	if len(geoms) > n {
		n = len(geoms)
	}
	for i := 0; i < n; i++ {
		f := l.NewFeature()
		f.FID = int64(i)
		if i < len(recs) {
			rec := recs[i]
			for fi, df := range dfields {
				if df.off+df.width > len(rec) {
					continue
				}
				raw := rec[df.off : df.off+df.width]
				s := strings.TrimSpace(latin1ToUTF8(raw))
				fd := l.Fields[fi]
				fv := &f.Fields[fi]
				switch fd.Type {
				case OFTString:
					st := strings.TrimRight(latin1ToUTF8(raw), " ")
					if st == "" {
						fv.State = 1
					} else {
						fv.State = 2
						fv.S = st
					}
				case OFTInteger, OFTInteger64:
					if fd.SubType == OFSTBoolean {
						if s == "" || s == "?" {
							fv.State = 1
						} else {
							fv.State = 2
							if s == "T" || s == "t" || s == "Y" || s == "y" {
								fv.I = 1
							}
						}
						continue
					}
					if s == "" || strings.HasPrefix(s, "*") {
						fv.State = 1
					} else {
						fv.State = 2
						fv.I, _ = strconv.ParseInt(s, 10, 64)
					}
				case OFTReal:
					if s == "" || strings.HasPrefix(s, "*") {
						fv.State = 1
					} else {
						fv.State = 2
						fv.F = cplAtof(s)
					}
				case OFTDate:
					if len(s) == 8 && isAllDigits(s) && s != "00000000" {
						fv.State = 2
						fv.Year, fv.Month, fv.Day = atoiC(s[0:4]), atoiC(s[4:6]), atoiC(s[6:8])
					} else {
						fv.State = 1
					}
				}
			}
		}
		if i < len(geoms) && len(f.Geoms) > 0 {
			f.Geoms[0] = geoms[i]
		}
		l.Features = append(l.Features, f)
	}
	l.nextFID = int64(n)
	l.loaded = true
	return l, nil
}

func shpParseRecord(b []byte) *Geom {
	if len(b) < 4 {
		return nil
	}
	le := binary.LittleEndian
	t := int(le.Uint32(b))
	f64 := func(o int) float64 {
		if o+8 > len(b) {
			return 0
		}
		return math.Float64frombits(le.Uint64(b[o:]))
	}
	hasZ := t == 11 || t == 13 || t == 15 || t == 18
	hasM := t == 21 || t == 23 || t == 25 || t == 28
	switch t {
	case 0:
		return nil
	case 1, 11, 21:
		g := &Geom{T: wkbPoint, Z: hasZ, M: hasM}
		p := Pt{X: f64(4), Y: f64(12)}
		if hasZ {
			p.Z = f64(20)
			if len(b) >= 36 {
				p.M = f64(28)
			}
		} else if hasM {
			p.M = f64(20)
		}
		g.Pts = []Pt{p}
		if hasZ && len(b) >= 36 {
			// M present in PointZ (optional) - ignore M unless meaningful
		}
		return g
	case 8, 18, 28:
		n := int(le.Uint32(b[36:]))
		g := &Geom{T: wkbMultiPoint, Z: hasZ, M: hasM}
		zoff := 40 + 16*n + 16
		for i := 0; i < n; i++ {
			p := Pt{X: f64(40 + 16*i), Y: f64(48 + 16*i)}
			if hasZ {
				p.Z = f64(zoff + 8*i)
			}
			g.Parts = append(g.Parts, &Geom{T: wkbPoint, Z: hasZ, M: hasM, Pts: []Pt{p}})
		}
		return g
	case 3, 13, 23, 5, 15, 25:
		np := int(le.Uint32(b[36:]))
		npt := int(le.Uint32(b[40:]))
		parts := make([]int, np)
		for i := 0; i < np; i++ {
			parts[i] = int(le.Uint32(b[44+4*i:]))
		}
		ptOff := 44 + 4*np
		zoff := ptOff + 16*npt + 16
		moff := zoff
		if hasZ {
			moff = zoff + 8*npt + 16
		} else if hasM {
			moff = ptOff + 16*npt + 16
		}
		var rings [][]Pt
		for i := 0; i < np; i++ {
			st := parts[i]
			en := npt
			if i+1 < np {
				en = parts[i+1]
			}
			var pts []Pt
			for k := st; k < en; k++ {
				p := Pt{X: f64(ptOff + 16*k), Y: f64(ptOff + 16*k + 8)}
				if hasZ {
					p.Z = f64(zoff + 8*k)
				}
				if hasM && moff+8*k+8 <= len(b) {
					p.M = f64(moff + 8*k)
				}
				pts = append(pts, p)
			}
			rings = append(rings, pts)
		}
		if t == 3 || t == 13 || t == 23 {
			if len(rings) == 1 {
				return &Geom{T: wkbLineString, Z: hasZ, M: hasM, Pts: rings[0]}
			}
			g := &Geom{T: wkbMultiLineString, Z: hasZ, M: hasM}
			for _, r := range rings {
				g.Parts = append(g.Parts, &Geom{T: wkbLineString, Z: hasZ, M: hasM, Pts: r})
			}
			return g
		}
		return shpBuildPolygon(rings, hasZ, hasM)
	}
	return nil
}

// ring orientation: shapefile outer rings are clockwise
func ringIsClockwise(pts []Pt) bool {
	return ringArea(pts) < 0
}

func pointInRing(x, y float64, pts []Pt) bool {
	in := false
	n := len(pts)
	for i, j := 0, n-1; i < n; j, i = i, i+1 {
		if (pts[i].Y > y) != (pts[j].Y > y) && x < (pts[j].X-pts[i].X)*(y-pts[i].Y)/(pts[j].Y-pts[i].Y)+pts[i].X {
			in = !in
		}
	}
	return in
}

func shpBuildPolygon(rings [][]Pt, hasZ, hasM bool) *Geom {
	var outers []*Geom
	var holes [][]Pt
	for _, r := range rings {
		if ringIsClockwise(r) || len(rings) == 1 {
			outers = append(outers, &Geom{T: wkbPolygon, Z: hasZ, M: hasM, Parts: []*Geom{{T: wkbLinearRing, Z: hasZ, M: hasM, Pts: r}}})
		} else {
			holes = append(holes, r)
		}
	}
	if len(outers) == 0 {
		for _, h := range holes {
			outers = append(outers, &Geom{T: wkbPolygon, Z: hasZ, M: hasM, Parts: []*Geom{{T: wkbLinearRing, Z: hasZ, M: hasM, Pts: h}}})
		}
		holes = nil
	}
	for _, h := range holes {
		placed := false
		if len(h) > 0 {
			for _, o := range outers {
				if pointInRing(h[0].X, h[0].Y, o.Parts[0].Pts) {
					o.Parts = append(o.Parts, &Geom{T: wkbLinearRing, Z: hasZ, M: hasM, Pts: h})
					placed = true
					break
				}
			}
		}
		if !placed && len(outers) > 0 {
			outers[0].Parts = append(outers[0].Parts, &Geom{T: wkbLinearRing, Z: hasZ, M: hasM, Pts: h})
		}
	}
	if len(outers) == 1 {
		return outers[0]
	}
	return &Geom{T: wkbMultiPolygon, Z: hasZ, M: hasM, Parts: outers}
}

// ---------------- writer ----------------

type shpLayerState struct {
	shpType  int
	srcIndex []int
	fields   []dbfOutField
	path     string
}

type dbfOutField struct {
	name     string
	typ      byte
	width    int
	decimals int
}

func shpPrepareOutput(o *vecOut, nLayers int) bool {
	low := strings.ToLower(o.name)
	if strings.HasSuffix(low, ".shp") || strings.HasSuffix(low, ".dbf") {
		return true
	}
	// directory output
	if st, ok := vfsStat(o.name); ok && st.IsDir {
		return true
	}
	if err := vfsMkdir(o.name); err != nil {
		CPLError(CE_Failure, CPLE_AppDefined, "Failed to create directory %s for shapefile datastore.", o.name)
		return false
	}
	return true
}

func launderShpName(name string, used map[string]bool) string {
	n := name
	b := utf8ToLatin1(n)
	if len(b) > 10 {
		n = latin1ToUTF8(b[:10])
	}
	if used[strings.ToUpper(n)] {
		for i := 1; i < 100; i++ {
			suffix := "_" + strconv.Itoa(i)
			base := latin1ToUTF8(utf8ToLatin1(n))
			bb := utf8ToLatin1(base)
			if len(bb)+len(suffix) > 10 {
				bb = bb[:10-len(suffix)]
			}
			cand := latin1ToUTF8(bb) + suffix
			if !used[strings.ToUpper(cand)] {
				n = cand
				break
			}
		}
	}
	return n
}

func shpPrepareLayer(o *vecOut, l *Layer, src *Layer) (*shpLayerState, error) {
	st := &shpLayerState{}
	low := strings.ToLower(o.name)
	if strings.HasSuffix(low, ".shp") || strings.HasSuffix(low, ".dbf") {
		st.path = o.name[:len(o.name)-4]
		if len(o.ds.Layers) > 0 {
			st.path = filepath.Join(filepath.Dir(o.name), l.Name)
		}
	} else {
		st.path = filepath.Join(o.name, l.Name)
	}
	gt := l.GeomType()
	st.shpType = shpTypeFor(gt)
	used := map[string]bool{}
	if src != nil {
		for si, fd := range src.Fields {
			nf := fd.Clone()
			df := dbfOutField{}
			switch fd.Type {
			case OFTInteger:
				if fd.SubType == OFSTBoolean {
					df.typ, df.width = 'L', 1
					nf.Width = 1
				} else {
					df.typ = 'N'
					df.width = fd.Width
					if df.width == 0 {
						df.width = 9
					}
					nf.Width = df.width
				}
				nf.Precision = 0
			case OFTInteger64:
				df.typ = 'N'
				df.width = fd.Width
				if df.width == 0 {
					df.width = 18
				}
				nf.Width = df.width
				nf.Precision = 0
			case OFTReal:
				df.typ = 'N'
				df.width, df.decimals = fd.Width, fd.Precision
				if df.width == 0 {
					df.width, df.decimals = 24, 15
				}
				nf.Width, nf.Precision = df.width, df.decimals
			case OFTDate:
				df.typ, df.width = 'D', 8
				nf.Width = 0
			case OFTDateTime:
				CPLError(CE_Warning, CPLE_NotSupported, "Field %s created as String field, though DateTime requested.", fd.Name)
				df.typ, df.width = 'C', 29
				nf.Type = OFTString
				nf.Width = 29
			case OFTTime:
				CPLError(CE_Warning, CPLE_NotSupported, "Field %s create as date field, though Time requested.", fd.Name)
				df.typ, df.width = 'C', 12
				nf.Type = OFTString
				nf.Width = 12
			default:
				df.typ = 'C'
				df.width = fd.Width
				if df.width == 0 {
					df.width = 80
				}
				if df.width > 254 {
					df.width = 254
				}
				nf.Type = OFTString
				nf.SubType = OFSTNone
				nf.Width = df.width
			}
			newName := launderShpName(fd.Name, used)
			if newName != fd.Name {
				CPLError(CE_Warning, CPLE_NotSupported, "Normalized/laundered field name: '%s' to '%s'", fd.Name, newName)
			}
			used[strings.ToUpper(newName)] = true
			nf.Name = newName
			df.name = newName
			l.Fields = append(l.Fields, nf)
			st.fields = append(st.fields, df)
			st.srcIndex = append(st.srcIndex, si)
		}
	}
	return st, nil
}

func shpTypeFor(gt int) int {
	flat := geomTypeFlat(gt)
	z := geomTypeHasZ(gt)
	m := geomTypeHasM(gt)
	base := 0
	switch flat {
	case wkbPoint:
		base = 1
	case wkbLineString, wkbMultiLineString:
		base = 3
	case wkbPolygon, wkbMultiPolygon:
		base = 5
	case wkbMultiPoint:
		base = 8
	case wkbNone:
		return 0
	default:
		return -1
	}
	if z {
		return base + 10
	}
	if m {
		return base + 20
	}
	return base
}

func shpCheckFeature(st *shpLayerState, l *Layer, f *Feature) error {
	g := f.Geom()
	if g == nil {
		return nil
	}
	if st.shpType == -1 {
		gt := g.Type()
		if g.T == wkbGeometryCollection {
			return newOpenErr(CPLE_AppDefined, "")
		}
		st.shpType = shpTypeFor(gt)
		if len(l.GeomFields) > 0 {
			l.GeomFields[0].Type = shpLayerGeomType(st.shpType)
		}
	}
	base := st.shpType % 10
	ok := false
	switch base {
	case 1:
		ok = g.T == wkbPoint
		if !ok {
			CPLError(CE_Failure, CPLE_AppDefined, "Attempt to write non-point (%s) geometry to point shapefile.", wktNames[g.T])
		}
	case 3:
		ok = g.T == wkbLineString || g.T == wkbMultiLineString
		if !ok {
			CPLError(CE_Failure, CPLE_AppDefined, "Attempt to write non-linestring (%s) geometry to ARC type shapefile.", wktNames[g.T])
		}
	case 5:
		ok = g.T == wkbPolygon || g.T == wkbMultiPolygon
		if !ok {
			CPLError(CE_Failure, CPLE_AppDefined, "Attempt to write non-polygon (%s) geometry to POLYGON type shapefile.", wktNames[g.T])
		}
	case 8:
		ok = g.T == wkbMultiPoint || g.T == wkbPoint
		if !ok {
			CPLError(CE_Failure, CPLE_AppDefined, "Attempt to write non-multipoint (%s) geometry to multipoint shapefile.", wktNames[g.T])
		}
	}
	if !ok {
		return newOpenErr(CPLE_AppDefined, "")
	}
	return nil
}

func shpLayerGeomType(t int) int {
	switch t {
	case 1:
		return wkbPoint
	case 3:
		return wkbLineString
	case 5:
		return wkbPolygon
	case 8:
		return wkbMultiPoint
	case 11:
		return makeGeomType(wkbPoint, true, false)
	case 13:
		return makeGeomType(wkbLineString, true, false)
	case 15:
		return makeGeomType(wkbPolygon, true, false)
	case 18:
		return makeGeomType(wkbMultiPoint, true, false)
	}
	return wkbUnknown
}

func shpWriteDataset(o *vecOut) bool {
	for _, l := range o.ds.Layers {
		st := o.shp[l]
		if st == nil {
			continue
		}
		if st.shpType == -1 {
			st.shpType = 0
			for _, f := range l.Features {
				if g := f.Geom(); g != nil {
					st.shpType = shpTypeFor(g.Type())
					break
				}
			}
			if st.shpType < 0 {
				st.shpType = 0
			}
		}
		if err := shpWriteLayer(st, l); err != nil {
			return false
		}
	}
	return true
}

func shpEncodeGeom(g *Geom, shpType int) []byte {
	le := binary.LittleEndian
	var b []byte
	u32 := func(v int) { b = le.AppendUint32(b, uint32(v)) }
	f64 := func(v float64) { b = le.AppendUint64(b, math.Float64bits(v)) }
	if g == nil || g.IsEmpty() {
		u32(0)
		return b
	}
	hasZ := shpType >= 11 && shpType <= 18
	hasM := shpType >= 21
	base := shpType % 10
	env := g.Envelope()
	switch base {
	case 1:
		u32(shpType)
		p := g.Pts[0]
		f64(p.X)
		f64(p.Y)
		if hasZ {
			f64(p.Z)
			f64(0)
		}
		if hasM {
			f64(p.M)
		}
	case 8:
		var pts []Pt
		if g.T == wkbPoint {
			pts = g.Pts
		} else {
			for _, p := range g.Parts {
				pts = append(pts, p.Pts...)
			}
		}
		u32(shpType)
		f64(env.MinX)
		f64(env.MinY)
		f64(env.MaxX)
		f64(env.MaxY)
		u32(len(pts))
		for _, p := range pts {
			f64(p.X)
			f64(p.Y)
		}
		if hasZ {
			mn, mx := zRange(pts)
			f64(mn)
			f64(mx)
			for _, p := range pts {
				f64(p.Z)
			}
			f64(0)
			f64(0)
			for range pts {
				f64(0)
			}
		}
	case 3, 5:
		var parts [][]Pt
		if base == 3 {
			if g.T == wkbLineString {
				parts = [][]Pt{g.Pts}
			} else {
				for _, p := range g.Parts {
					parts = append(parts, p.Pts)
				}
			}
		} else {
			var polys []*Geom
			if g.T == wkbPolygon {
				polys = []*Geom{g}
			} else {
				polys = g.Parts
			}
			for _, poly := range polys {
				for ri, r := range poly.Parts {
					pts := append([]Pt{}, r.Pts...)
					cw := ringIsClockwise(pts)
					if (ri == 0 && !cw) || (ri > 0 && cw) {
						for i, j := 0, len(pts)-1; i < j; i, j = i+1, j-1 {
							pts[i], pts[j] = pts[j], pts[i]
						}
					}
					parts = append(parts, pts)
				}
			}
		}
		var all []Pt
		u32(shpType)
		f64(env.MinX)
		f64(env.MinY)
		f64(env.MaxX)
		f64(env.MaxY)
		u32(len(parts))
		n := 0
		for _, p := range parts {
			n += len(p)
		}
		u32(n)
		idx := 0
		for _, p := range parts {
			u32(idx)
			idx += len(p)
		}
		for _, p := range parts {
			for _, pt := range p {
				f64(pt.X)
				f64(pt.Y)
				all = append(all, pt)
			}
		}
		if hasZ {
			mn, mx := zRange(all)
			f64(mn)
			f64(mx)
			for _, p := range all {
				f64(p.Z)
			}
			f64(0)
			f64(0)
			for range all {
				f64(0)
			}
		}
	}
	return b
}

func zRange(pts []Pt) (float64, float64) {
	mn, mx := math.Inf(1), math.Inf(-1)
	for _, p := range pts {
		mn = math.Min(mn, p.Z)
		mx = math.Max(mx, p.Z)
	}
	if len(pts) == 0 {
		return 0, 0
	}
	return mn, mx
}

func shpWriteLayer(st *shpLayerState, l *Layer) error {
	be := binary.BigEndian
	le := binary.LittleEndian
	var recs [][]byte
	env := EmptyEnvelope()
	zmin, zmax := 0.0, 0.0
	firstZ := true
	for _, f := range l.Features {
		g := f.Geom()
		recs = append(recs, shpEncodeGeom(g, st.shpType))
		if g != nil && !g.IsEmpty() {
			env.Merge(g.Envelope())
			if g.Z {
				e3 := g.Envelope3D()
				if firstZ {
					zmin, zmax = e3.MinZ, e3.MaxZ
					firstZ = false
				} else {
					zmin = math.Min(zmin, e3.MinZ)
					zmax = math.Max(zmax, e3.MaxZ)
				}
			}
		}
	}
	if !env.IsInit() {
		env = Envelope{}
	}
	header := func(fileLen int) []byte {
		h := make([]byte, 100)
		be.PutUint32(h, 9994)
		be.PutUint32(h[24:], uint32(fileLen/2))
		le.PutUint32(h[28:], 1000)
		le.PutUint32(h[32:], uint32(st.shpType))
		le.PutUint64(h[36:], math.Float64bits(env.MinX))
		le.PutUint64(h[44:], math.Float64bits(env.MinY))
		le.PutUint64(h[52:], math.Float64bits(env.MaxX))
		le.PutUint64(h[60:], math.Float64bits(env.MaxY))
		le.PutUint64(h[68:], math.Float64bits(zmin))
		le.PutUint64(h[76:], math.Float64bits(zmax))
		return h
	}
	shpLen := 100
	for _, r := range recs {
		shpLen += 8 + len(r)
	}
	shp := header(shpLen)
	shx := header(100 + 8*len(recs))
	off := 100
	for i, r := range recs {
		rh := make([]byte, 8)
		be.PutUint32(rh, uint32(i+1))
		be.PutUint32(rh[4:], uint32(len(r)/2))
		shp = append(shp, rh...)
		shp = append(shp, r...)
		xr := make([]byte, 8)
		be.PutUint32(xr, uint32(off/2))
		be.PutUint32(xr[4:], uint32(len(r)/2))
		shx = append(shx, xr...)
		off += 8 + len(r)
	}
	if st.shpType != 0 || len(l.GeomFields) > 0 {
		if err := vfsWriteFile(st.path+".shp", shp); err != nil {
			CPLError(CE_Failure, CPLE_OpenFailed, "Failed to open Shapefile `%s'.", st.path+".shp")
			return err
		}
		vfsWriteFile(st.path+".shx", shx)
	}
	// DBF
	var dbf []byte
	now := time.Now()
	nf := len(st.fields)
	recSize := 1
	for _, f := range st.fields {
		recSize += f.width
	}
	hs := 32 + 32*nf + 1
	if nf == 0 {
		recSize = 2
		hs = 32 + 32 + 1
	}
	h := make([]byte, 32)
	h[0] = 3
	h[1] = byte(now.Year() - 1900)
	h[2] = byte(now.Month())
	h[3] = byte(now.Day())
	le.PutUint32(h[4:], uint32(len(l.Features)))
	le.PutUint16(h[8:], uint16(hs))
	le.PutUint16(h[10:], uint16(recSize))
	h[29] = 0x57
	dbf = append(dbf, h...)
	if nf == 0 {
		fd := make([]byte, 32)
		copy(fd, "FID")
		fd[11] = 'N'
		fd[16] = 1
		dbf = append(dbf, fd...)
	}
	for _, f := range st.fields {
		fd := make([]byte, 32)
		copy(fd, utf8ToLatin1(f.name))
		fd[11] = f.typ
		fd[16] = byte(f.width)
		fd[17] = byte(f.decimals)
		dbf = append(dbf, fd...)
	}
	dbf = append(dbf, 0x0d)
	for _, feat := range l.Features {
		rec := make([]byte, recSize)
		for i := range rec {
			rec[i] = ' '
		}
		if nf == 0 {
			rec[1] = '0'
		}
		pos := 1
		for i, f := range st.fields {
			fv := feat.Fields[i]
			fdefn := l.Fields[i]
			var s []byte
			switch f.typ {
			case 'C':
				if fv.State == 2 {
					s = utf8ToLatin1(fieldAsString(fdefn, &fv))
					if fdefn.Type == OFTString && fdefn.Width == 29 && false {
					}
				}
				if len(s) > f.width {
					s = s[:f.width]
				}
				copy(rec[pos:], s)
			case 'N':
				if fv.State != 2 {
					for k := 0; k < f.width; k++ {
						rec[pos+k] = '*'
					}
				} else {
					var str string
					if f.decimals > 0 || fdefn.Type == OFTReal {
						str = cfmt("%*.*f", f.width, f.decimals, fv.F)
					} else {
						str = cfmt("%*d", f.width, fv.I)
					}
					if len(str) > f.width {
						str = str[:f.width]
					}
					copy(rec[pos:], str)
				}
			case 'L':
				if fv.State != 2 {
					rec[pos] = '?'
				} else if fv.I != 0 {
					rec[pos] = 'T'
				} else {
					rec[pos] = 'F'
				}
			case 'D':
				if fv.State == 2 {
					copy(rec[pos:], cfmt("%04d%02d%02d", fv.Year, fv.Month, fv.Day))
				}
			}
			pos += f.width
		}
		dbf = append(dbf, rec...)
	}
	dbf = append(dbf, 0x1a)
	if err := vfsWriteFile(st.path+".dbf", dbf); err != nil {
		return err
	}
	if srs := l.SRS(); srs != nil {
		vfsWriteFile(st.path+".prj", []byte(srs.ESRIWKT()))
	}
	return nil
}

func removeIfExists(p string) {
	if _, err := os.Stat(p); err == nil {
		os.Remove(p)
	}
}
