package main

import (
	"math"
	"strconv"
	"strings"
)

func init() {
	registerCommand("raster select", runRasterSelect)
	registerCommand("raster set-type", runRasterSetType)
	registerCommand("raster scale", runRasterScale)
	registerCommand("raster unscale", runRasterUnscale)
	registerCommand("raster clip", runRasterClip)
	registerCommand("raster resize", runRasterResize)
	registerCommand("raster edit", runRasterEdit)
	registerCommand("raster nodata-to-alpha", runRasterNodataToAlpha)
}

func srcRaster(a *Alg) *Dataset {
	v := a.V("input")
	if len(v.DSs) == 0 {
		return nil
	}
	return v.DSs[0]
}

// writeRasterResult writes a computed dataset to the 'output' argument.
func writeRasterResult(a *Alg, ds *Dataset) bool {
	outName := a.DSName("output")
	drv := a.outputDriver(outName, true, false)
	if drv == nil {
		CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
		return false
	}
	prog := NewProgress()
	if strings.HasPrefix(outName, "/vsistdout") {
		prog.enabled = false
	}
	if a.Bool("overwrite") {
		deleteExistingDataset(outName)
	}
	prog.Update(0)
	ds.Driver = drv
	if !writeRasterOutput(a, ds, drv, outName, a.StrList("creation-option"), prog) {
		return false
	}
	prog.Update(1)
	return true
}

// cloneRasterStructure creates a new dataset with same georeferencing and metadata.
func cloneRasterStructure(src *Dataset, w, h int) *Dataset {
	ds := NewDataset(src.Name, w, h)
	ds.SRS = src.SRS
	ds.GT = src.GT
	ds.HasGT = src.HasGT
	ds.MD = src.MD.Clone()
	ds.GCPs = src.GCPs
	ds.GCPSRS = src.GCPSRS
	return ds
}

func copyBandProps(dst, src *Band) {
	dst.HasNoData = src.HasNoData
	dst.NoData = src.NoData
	dst.ColorInterp = src.ColorInterp
	dst.ColorTable = src.ColorTable
	dst.Description = src.Description
	dst.MD = src.MD.Clone()
	dst.HasOffset, dst.Offset, dst.HasScale, dst.Scale = src.HasOffset, src.Offset, src.HasScale, src.Scale
	dst.Unit = src.Unit
	dst.Categories = src.Categories
	dst.BlockX, dst.BlockY = src.BlockX, src.BlockY
}

func newBandFrom(ds *Dataset, src *Band, dt DataType, data []float64) *Band {
	b := ds.AddBand(dt)
	copyBandProps(b, src)
	b.data = data
	b.loaded = true
	return b
}

func parseBandSpec(src *Dataset, spec string) (int, bool) {
	if n, err := strconv.Atoi(spec); err == nil {
		return n, true
	}
	ci := colorInterpFromName(spec)
	if ci >= 0 {
		for i, b := range src.Bands {
			if b.ColorInterp == ci {
				return i + 1, true
			}
		}
	}
	return 0, false
}

func runRasterSelect(a *Alg) bool {
	src := srcRaster(a)
	specs := a.StrList("band")
	var idx []int
	for _, s := range specs {
		n, ok := parseBandSpec(src, s)
		if !ok || n < 1 || n > len(src.Bands) {
			a.ReportError(CPLE_IllegalArg, "Invalid band specification: %s", s)
			return false
		}
		idx = append(idx, n)
	}
	if a.Bool("exclude") {
		ex := map[int]bool{}
		for _, i := range idx {
			ex[i] = true
		}
		idx = nil
		for i := range src.Bands {
			if !ex[i+1] {
				idx = append(idx, i+1)
			}
		}
	}
	ds := cloneRasterStructure(src, src.XSize, src.YSize)
	for _, i := range idx {
		sb := src.Bands[i-1]
		b := newBandFrom(ds, sb, sb.DataType, sb.Data())
		if sb.DataType.IsComplex() {
			b.imag = sb.Imag()
		}
	}
	if len(idx) > 0 && idx[0] != 1 && ds.Bands[0].ColorInterp == GCI_Undefined {
		// first band becomes gray when written as MINISBLACK; keep undefined
	}
	return writeRasterResult(a, ds)
}

func convertDataToType(data []float64, dt DataType) []float64 {
	out := make([]float64, len(data))
	for i, v := range data {
		out[i] = clampRound(dt, v)
	}
	return out
}

func runRasterSetType(a *Alg) bool {
	src := srcRaster(a)
	dt := dataTypeFromName(a.Str("output-data-type"))
	ds := cloneRasterStructure(src, src.XSize, src.YSize)
	for _, sb := range src.Bands {
		b := newBandFrom(ds, sb, dt, convertDataToType(sb.Data(), dt))
		if dt.IsComplex() && sb.DataType.IsComplex() {
			b.imag = convertDataToType(sb.Imag(), dt)
		}
		if b.HasNoData {
			b.NoData = clampRound(dt, b.NoData)
		}
		removeStatsMD(b)
	}
	return writeRasterResult(a, ds)
}

func removeStatsMD(b *Band) {
	for _, k := range []string{"STATISTICS_MINIMUM", "STATISTICS_MAXIMUM", "STATISTICS_MEAN", "STATISTICS_STDDEV", "STATISTICS_VALID_PERCENT", "STATISTICS_APPROXIMATE"} {
		b.MD.Unset("", k)
	}
}

func runRasterScale(a *Alg) bool {
	src := srcRaster(a)
	dt := GDT_Unknown
	if a.IsSet("output-data-type") {
		dt = dataTypeFromName(a.Str("output-data-type"))
	}
	only := 0
	if a.IsSet("band") {
		only = a.Int("band")
	}
	ds := cloneRasterStructure(src, src.XSize, src.YSize)
	for i, sb := range src.Bands {
		odt := dt
		if odt == GDT_Unknown {
			odt = sb.DataType
		}
		if only != 0 && i+1 != only {
			newBandFrom(ds, sb, odt, convertDataToType(sb.Data(), odt))
			continue
		}
		smin, smax := a.Real("src-min"), a.Real("src-max")
		if !a.IsSet("src-min") || !a.IsSet("src-max") {
			mn, mx, _ := sb.ComputeMinMax(false)
			if !a.IsSet("src-min") {
				smin = mn
			}
			if !a.IsSet("src-max") {
				smax = mx
			}
		}
		dmin, dmax := a.Real("dst-min"), a.Real("dst-max")
		if !a.IsSet("dst-min") {
			dmin = 0
			if odt != GDT_Byte {
				dmin, _ = odt.Range()
				if odt.IsFloat() {
					dmin = 0
				}
			}
		}
		if !a.IsSet("dst-max") {
			dmax = 255
			if odt != GDT_Byte && !odt.IsFloat() {
				_, dmax = odt.Range()
			}
		}
		if !a.IsSet("dst-min") && !a.IsSet("dst-max") && odt != GDT_Byte && !odt.IsFloat() {
			dmin, dmax = odt.Range()
		}
		exp := a.Real("exponent")
		hasExp := a.IsSet("exponent")
		noClip := a.Bool("no-clip")
		data := sb.Data()
		valid := sb.validMask()
		out := make([]float64, len(data))
		for k, v := range data {
			if !valid[k] {
				out[k] = clampRound(odt, v)
				continue
			}
			var r float64
			if hasExp {
				t := 0.0
				if smax != smin {
					t = (v - smin) / (smax - smin)
				}
				if !noClip {
					t = math.Max(0, math.Min(1, t))
				}
				r = dmin + (dmax-dmin)*math.Pow(t, exp)
			} else {
				if smax == smin {
					r = dmin
				} else {
					r = (v-smin)*(dmax-dmin)/(smax-smin) + dmin
				}
				if !noClip {
					lo, hi := math.Min(dmin, dmax), math.Max(dmin, dmax)
					r = math.Max(lo, math.Min(hi, r))
				}
			}
			out[k] = clampRound(odt, r)
		}
		b := newBandFrom(ds, sb, odt, out)
		removeStatsMD(b)
		if b.HasNoData {
			b.NoData = clampRound(odt, b.NoData)
		}
	}
	return writeRasterResult(a, ds)
}

func runRasterUnscale(a *Alg) bool {
	src := srcRaster(a)
	dt := GDT_Float32
	if a.IsSet("output-data-type") {
		dt = dataTypeFromName(a.Str("output-data-type"))
	}
	ds := cloneRasterStructure(src, src.XSize, src.YSize)
	for _, sb := range src.Bands {
		scale, offset := 1.0, 0.0
		if sb.HasScale {
			scale = sb.Scale
		}
		if sb.HasOffset {
			offset = sb.Offset
		}
		odt := dt
		if !a.IsSet("output-data-type") && sb.DataType == GDT_Float64 {
			odt = GDT_Float64
		}
		data := sb.Data()
		valid := sb.validMask()
		out := make([]float64, len(data))
		for k, v := range data {
			if !valid[k] {
				out[k] = clampRound(odt, v)
				continue
			}
			out[k] = clampRound(odt, v*scale+offset)
		}
		b := newBandFrom(ds, sb, odt, out)
		b.HasScale, b.Scale, b.HasOffset, b.Offset = false, 1, false, 0
		removeStatsMD(b)
		if b.HasNoData {
			b.NoData = clampRound(odt, b.NoData*scale+offset)
		}
	}
	return writeRasterResult(a, ds)
}

// window extraction
func extractWindow(src *Dataset, xoff, yoff, w, h int) *Dataset {
	ds := cloneRasterStructure(src, w, h)
	if src.HasGT {
		gt := src.GT
		ds.GT = [6]float64{gt[0] + float64(xoff)*gt[1] + float64(yoff)*gt[2], gt[1], gt[2], gt[3] + float64(xoff)*gt[4] + float64(yoff)*gt[5], gt[4], gt[5]}
	}
	for _, sb := range src.Bands {
		sd := sb.Data()
		out := make([]float64, w*h)
		fill := 0.0
		if sb.HasNoData {
			fill = sb.NoData
		}
		for y := 0; y < h; y++ {
			sy := y + yoff
			for x := 0; x < w; x++ {
				sx := x + xoff
				if sx < 0 || sy < 0 || sx >= src.XSize || sy >= src.YSize {
					out[y*w+x] = fill
					continue
				}
				out[y*w+x] = sd[sy*src.XSize+sx]
			}
		}
		b := newBandFrom(ds, sb, sb.DataType, out)
		removeStatsMD(b)
		b.BlockX, b.BlockY = w, 1
	}
	return ds
}

func runRasterClip(a *Alg) bool {
	src := srcRaster(a)
	var xoff, yoff, w, h int
	switch {
	case a.IsSet("window"):
		win := a.IntList("window")
		xoff, yoff, w, h = win[0], win[1], win[2], win[3]
		if !a.Bool("allow-bbox-outside-source") && (xoff < 0 || yoff < 0 || xoff+w > src.XSize || yoff+h > src.YSize) {
			a.ReportError(CPLE_IllegalArg, "Window %d,%d,%d,%d is at least partially outside raster extent (%d,%d,%d,%d). Use --allow-bbox-outside-source if this is desired.", xoff, yoff, w, h, 0, 0, src.XSize, src.YSize)
			return false
		}
	case a.IsSet("bbox"):
		bb := a.RealList("bbox")
		if !src.HasGT {
			a.ReportError(CPLE_AppDefined, "Clipping is not possible because the input dataset has no geotransform.")
			return false
		}
		if a.IsSet("bbox-crs") && src.SRS != nil {
			s, _ := srsFromUserInput(a.Str("bbox-crs"))
			if s != nil && !s.IsSame(src.SRS) {
				ct := NewCoordTransform(s, src.SRS)
				if ct != nil {
					xs := []float64{bb[0], bb[2], bb[0], bb[2]}
					ys := []float64{bb[1], bb[1], bb[3], bb[3]}
					ct.Transform(xs, ys, nil)
					bb = []float64{math.Min(xs[0], xs[2]), math.Min(ys[0], ys[1]), math.Max(xs[1], xs[3]), math.Max(ys[2], ys[3])}
				}
			}
		}
		gt := src.GT
		x0 := (bb[0] - gt[0]) / gt[1]
		x1 := (bb[2] - gt[0]) / gt[1]
		y0 := (bb[3] - gt[3]) / gt[5]
		y1 := (bb[1] - gt[3]) / gt[5]
		if x0 > x1 {
			x0, x1 = x1, x0
		}
		if y0 > y1 {
			y0, y1 = y1, y0
		}
		eps := 1e-8
		xoff = int(math.Floor(x0 + eps))
		yoff = int(math.Floor(y0 + eps))
		xe := int(math.Ceil(x1 - eps))
		ye := int(math.Ceil(y1 - eps))
		w, h = xe-xoff, ye-yoff
		if !a.Bool("allow-bbox-outside-source") && (xoff < 0 || yoff < 0 || xe > src.XSize || ye > src.YSize) {
			a.ReportError(CPLE_AppDefined, "Clipping box is at least partially outside the extent of the input dataset. Use --allow-bbox-outside-source if this is desired.")
			return false
		}
	default:
		a.ReportError(CPLE_AppDefined, "--bbox, --window, --geometry or --like must be specified")
		return false
	}
	if w <= 0 || h <= 0 {
		a.ReportError(CPLE_AppDefined, "Clipping window is empty")
		return false
	}
	ds := extractWindow(src, xoff, yoff, w, h)
	return writeRasterResult(a, ds)
}

func runRasterResize(a *Alg) bool {
	src := srcRaster(a)
	w, h := src.XSize, src.YSize
	if a.IsSet("size") {
		sz := a.StrList("size")
		parse := func(s string, full int) int {
			if strings.HasSuffix(s, "%") {
				return int(math.Round(cplAtof(s[:len(s)-1]) / 100 * float64(full)))
			}
			return atoiC(s)
		}
		if len(sz) == 2 {
			w = parse(sz[0], src.XSize)
			h = parse(sz[1], src.YSize)
		}
	} else if a.IsSet("resolution") {
		r := a.RealList("resolution")
		w = int(math.Round(float64(src.XSize) * src.GT[1] / r[0]))
		h = int(math.Round(float64(src.YSize) * math.Abs(src.GT[5]) / r[1]))
	}
	ds := cloneRasterStructure(src, w, h)
	if src.HasGT {
		gt := src.GT
		ds.GT = [6]float64{gt[0], gt[1] * float64(src.XSize) / float64(w), gt[2] * float64(src.YSize) / float64(h), gt[3], gt[4] * float64(src.XSize) / float64(w), gt[5] * float64(src.YSize) / float64(h)}
	}
	alg := a.Str("resampling")
	for _, sb := range src.Bands {
		out := resampleBand(sb, src.XSize, src.YSize, w, h, alg)
		b := newBandFrom(ds, sb, sb.DataType, out)
		removeStatsMD(b)
		b.BlockX, b.BlockY = w, 1
	}
	return writeRasterResult(a, ds)
}

// resampleBand resamples a whole band to a new size.
func resampleBand(sb *Band, sw, sh, w, h int, alg string) []float64 {
	sd := sb.Data()
	out := make([]float64, w*h)
	xr := float64(sw) / float64(w)
	yr := float64(sh) / float64(h)
	valid := sb.validMask()
	nd := 0.0
	if sb.HasNoData {
		nd = sb.NoData
	}
	get := func(x, y int) (float64, bool) {
		if x < 0 {
			x = 0
		}
		if y < 0 {
			y = 0
		}
		if x >= sw {
			x = sw - 1
		}
		if y >= sh {
			y = sh - 1
		}
		return sd[y*sw+x], valid[y*sw+x]
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			sx := (float64(x) + 0.5) * xr
			sy := (float64(y) + 0.5) * yr
			var v float64
			switch alg {
			case "bilinear":
				fx := sx - 0.5
				fy := sy - 0.5
				x0 := int(math.Floor(fx))
				y0 := int(math.Floor(fy))
				dx := fx - float64(x0)
				dy := fy - float64(y0)
				sum, wsum := 0.0, 0.0
				for j := 0; j <= 1; j++ {
					for i := 0; i <= 1; i++ {
						vv, ok := get(x0+i, y0+j)
						if !ok {
							continue
						}
						wx := 1 - dx
						if i == 1 {
							wx = dx
						}
						wy := 1 - dy
						if j == 1 {
							wy = dy
						}
						sum += vv * wx * wy
						wsum += wx * wy
					}
				}
				if wsum > 0 {
					v = sum / wsum
				} else {
					v = nd
				}
			case "average", "mode":
				x0 := int(math.Floor(float64(x) * xr))
				x1 := int(math.Ceil(float64(x+1) * xr))
				y0 := int(math.Floor(float64(y) * yr))
				y1 := int(math.Ceil(float64(y+1) * yr))
				if x1 <= x0 {
					x1 = x0 + 1
				}
				if y1 <= y0 {
					y1 = y0 + 1
				}
				sum, n := 0.0, 0
				counts := map[float64]int{}
				for yy := y0; yy < y1 && yy < sh; yy++ {
					for xx := x0; xx < x1 && xx < sw; xx++ {
						vv, ok := get(xx, yy)
						if !ok {
							continue
						}
						sum += vv
						n++
						counts[vv]++
					}
				}
				if n == 0 {
					v = nd
				} else if alg == "average" {
					v = sum / float64(n)
				} else {
					best, bc := 0.0, -1
					for k, c := range counts {
						if c > bc || (c == bc && k < best) {
							best, bc = k, c
						}
					}
					v = best
				}
			default:
				ix := int(math.Floor(sx))
				iy := int(math.Floor(sy))
				v, _ = get(ix, iy)
			}
			out[y*w+x] = clampRound(sb.DataType, v)
		}
	}
	return out
}

func runRasterNodataToAlpha(a *Alg) bool {
	src := srcRaster(a)
	ds := cloneRasterStructure(src, src.XSize, src.YSize)
	n := src.XSize * src.YSize
	alpha := make([]float64, n)
	for i := range alpha {
		alpha[i] = 255
	}
	for _, sb := range src.Bands {
		v := sb.validMask()
		for i := range alpha {
			if !v[i] {
				alpha[i] = 0
			}
		}
	}
	for _, sb := range src.Bands {
		b := newBandFrom(ds, sb, sb.DataType, sb.Data())
		b.HasNoData = false
	}
	ab := ds.AddBand(src.Bands[0].DataType)
	ab.data = alpha
	ab.loaded = true
	ab.ColorInterp = GCI_AlphaBand
	return writeRasterResult(a, ds)
}
