		opts = append(opts, "COMPRESS="+c)
	}
	if p, ok := ds.MD.Get("IMAGE_STRUCTURE", "PREDICTOR"); ok {
		opts = append(opts, "PREDICTOR="+p)
	}
	if im, ok := ds.Extra["gtiff_main"].(*gtiffImage); ok {
		if im.tiled {
			opts = append(opts, "TILED=YES", "BLOCKXSIZE="+strconv.Itoa(im.blockW), "BLOCKYSIZE="+strconv.Itoa(im.blockH))
		} else {
			opts = append(opts, "BLOCKYSIZE="+strconv.Itoa(im.blockH))
		}
		if im.planar == 2 {
			opts = append(opts, "INTERLEAVE=BAND")
		}
		ph := int(im.tf.getUint(im.ifd, tagPhotometric, 1))
		switch ph {
		case 2:
			opts = append(opts, "PHOTOMETRIC=RGB")
		case 3:
			opts = append(opts, "PHOTOMETRIC=PALETTE")
		case 1:
			opts = append(opts, "PHOTOMETRIC=MINISBLACK")
		}
	}
	return opts
}

func init() {
	registerCommand("raster edit", runRasterEdit)
}

func runRasterEdit(a *Alg) bool {
	v := a.V("dataset")
	if len(v.DSs) == 0 || v.DSs[0] == nil {
		return false
	}
	ds := v.DSs[0]
	for _, b := range ds.Bands {
		b.Load()
	}
	aux := a.Bool("auxiliary")
	isGTiff := ds.Driver != nil && ds.Driver.ShortName == "GTiff"
	if a.IsSet("crs") {
		s, ok := a.parseCRSArg("crs")
		if !ok {
			return false
		}
		ds.SRS = s
		if aux {
			ds.Extra["pam_srs"] = true
			ds.PAMDirty = true
		}
	}
	if a.IsSet("bbox") {
		bb := a.RealList("bbox")
		ds.GT = [6]float64{bb[0], (bb[2] - bb[0]) / float64(ds.XSize), 0, bb[3], 0, -(bb[3] - bb[1]) / float64(ds.YSize)}
		ds.HasGT = true
		if aux {
			ds.Extra["pam_gt"] = true
			ds.PAMDirty = true
		}
	}
	if a.IsSet("nodata") {
		val, has := parseNodataArg(a.Str("nodata"))
		for _, b := range ds.Bands {
			if has && !nodataRepresentable(b.DataType, val) {
				a.ReportError(CPLE_AppDefined, "Setting nodata value failed as it cannot be represented on its data type")
				return false
			}
			b.HasNoData = has
			b.NoData = val
			if has {
				b.MaskFlags = GMF_NODATA
			} else {
				b.MaskFlags = GMF_ALL_VALID
			}
		}
	}
	bandValue := func(spec string) (int, string, bool) {
		if i := strings.IndexByte(spec, '='); i >= 0 {
			if strings.EqualFold(spec[:i], "all") {
				return 0, spec[i+1:], true
			}
			n, err := strconv.Atoi(spec[:i])
			if err != nil || n < 1 || n > len(ds.Bands) {
				a.ReportError(CPLE_IllegalArg, "Invalid band number '%s'", spec[:i])
				return -1, "", false
			}
			return n, spec[i+1:], true
		}
		return 0, spec, true
	}
	for _, spec := range a.StrList("color-interpretation") {
		n, val, ok := bandValue(spec)
		if !ok {
			return false
		}
		ci := colorInterpFromName(val)
		if ci < 0 {
			a.ReportError(CPLE_IllegalArg, "Invalid value '%s' for color interpretation", val)
			return false
		}
		for i, b := range ds.Bands {
			if n == 0 || n == i+1 {
				b.ColorInterp = ci
			}
		}
	}
	for _, kind := range []string{"scale", "offset"} {
		for _, spec := range a.StrList(kind) {
			n, val, ok := bandValue(spec)
			if !ok {
				return false
			}
			f, okf := parseRealStrict(val)
			if !okf {
				a.ReportError(CPLE_IllegalArg, "Invalid value '%s' for %s", val, kind)
				return false
			}
			for i, b := range ds.Bands {
				if n == 0 || n == i+1 {
					if kind == "scale" {
						b.HasScale, b.Scale = true, f
						if !b.HasOffset {
							b.HasOffset = true
						}
					} else {
						b.HasOffset, b.Offset = true, f
						if !b.HasScale {
							b.HasScale, b.Scale = true, 1
						}
					}
				}
			}
		}
	}
	for _, kv := range a.StrList("metadata") {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			ds.MD.Set("", kv[:i], kv[i+1:])
		}
	}
	for _, k := range a.StrList("unset-metadata") {
		ds.MD.Unset("", k)
	}
	for _, d := range a.StrList("unset-metadata-domain") {
		if dd := ds.MD.dom(d, false); dd != nil {
			dd.Keys = nil
			dd.Vals = map[string]string{}
			dd.Raw = nil
		}
	}
	if a.Bool("stats") || a.Bool("approx-stats") {
		prog := NewProgress()
		prog.Update(0)
		for _, b := range ds.Bands {
			st, ok := b.ComputeStats(a.Bool("approx-stats"))
			if ok {
				if isGTiff && !aux {
					b.MD.Set("", "STATISTICS_MINIMUM", fmt14g(st.Min))
					b.MD.Set("", "STATISTICS_MAXIMUM", fmt14g(st.Max))
					b.MD.Set("", "STATISTICS_MEAN", fmt14g(st.Mean))
					b.MD.Set("", "STATISTICS_STDDEV", fmt14g(st.StdDev))
					b.MD.Set("", "STATISTICS_VALID_PERCENT", cfmt("%.4g", 100.0*float64(st.ValidCount)/float64(st.Total)))
				} else {
					b.SetStatsMetadata(st)
				}
			}
		}
		prog.Update(1)
	}
	if a.Bool("hist") {
		for _, b := range ds.Bands {
			b.GetDefaultHistogram(true, nil)
		}
	}
	if isGTiff && !aux {
		opts := append(gtiffReopenOptions(ds), "UPDATE_MODE=YES")
		if err := gtiffWriteDataset(ds.Name, ds, opts, nil); err != nil {
			return false
		}
		ds.PAMDirty = false
		if ds.PAMLoaded {
			ds.PAMDirty = true
		}
	}
	ds.Close()
	return true
}
