	}
	prog := NewProgress()
	outName := a.DSName("output")
	if strings.HasPrefix(outName, "/vsistdout") {
		prog.enabled = false
	}
	dialect := a.Str("dialect")
	if dialect == "" || strings.EqualFold(dialect, "muparser") {
		prog.Update(0)
		prog.Update(0.5)
		CPLError(CE_Failure, CPLE_IllegalArg, "Dialect 'muparser' is not supported by this GDAL build. A GDAL build with muparser is needed.")
		return false
	}
	ref := dss[0]
	for _, d := range dss[1:] {
		if (d.XSize != ref.XSize || d.YSize != ref.YSize) && !a.Bool("no-check-extent") {
			a.ReportError(CPLE_AppDefined, "Inputs do not have the same dimensions.")
			return false
		}
	}
	ds := cloneRasterStructure(ref, ref.XSize, ref.YSize)
	ds.MD = NewMetadata()
	n := ref.XSize * ref.YSize
	flatten := a.Bool("flatten")
	for _, expr := range a.StrList("calc") {
		fn := strings.ToLower(strings.TrimSpace(expr))
		known := map[string]bool{"sum": true, "mean": true, "min": true, "max": true, "median": true, "mode": true, "mul": true, "diff": true, "div": true, "geometric_mean": true, "harmonic_mean": true, "sqrt": true, "log10": true, "inv": true, "round": true, "exp": true, "dB": true, "conj": true, "real": true, "imag": true}
		if !known[fn] {
			a.ReportError(CPLE_NotSupported, "'%s' is a unknown builtin function", expr)
			return false
		}
		// build band groups
		var groups [][]*Band
		if len(dss) == 1 || flatten {
			if flatten || len(dss) == 1 && len(ref.Bands) == 1 {
				var all []*Band
				for _, d := range dss {
					all = append(all, d.Bands...)
				}
				groups = append(groups, all)
			} else {
				for _, b := range ref.Bands {
					groups = append(groups, []*Band{b})
				}
			}
		} else {
			nb := len(ref.Bands)
			for bi := 0; bi < nb; bi++ {
				var g []*Band
				for _, d := range dss {
					if bi < len(d.Bands) {
						g = append(g, d.Bands[bi])
					}
				}
				groups = append(groups, g)
			}
		}
		single := map[string]bool{"sqrt": true, "log10": true, "inv": true, "round": true, "exp": true}
		for _, g := range groups {
			if single[fn] && len(g) != 1 {
				if fn == "round" {
					CPLError(CE_Failure, CPLE_AppDefined, "round: input must be a single band")
				}
				return false
			}
			dt := GDT_Float64
			if fn == "min" || fn == "max" || fn == "mode" {
				dt = g[0].DataType
				for _, b := range g {
					if b.DataType != dt {
						dt = GDT_Float64
					}
				}
			}
			out := make([]float64, n)
			datas := make([][]float64, len(g))
			valids := make([][]bool, len(g))
			for i, b := range g {
				datas[i] = b.Data()
				valids[i] = b.validMask()
			}
			nd := 0.0
			hasND := false
			if g[0].HasNoData {
				nd, hasND = g[0].NoData, true
			}
			if a.IsSet("nodata") {
				nd, hasND = parseNodataArg(a.Str("nodata"))
			}
			propagate := a.Bool("propagate-nodata")
			vals := make([]float64, 0, len(g))
			for k := 0; k < n; k++ {
				vals = vals[:0]
				anyInvalid := false
				for i := range g {
					if !valids[i][k] {
						anyInvalid = true
						continue
					}
					vals = append(vals, datas[i][k])
				}
				if len(vals) == 0 || (propagate && anyInvalid) {
					out[k] = nd
					continue
				}
				var r float64
				switch fn {
				case "sum":
					for _, v := range vals {
						r += v
					}
				case "mean":
					for _, v := range vals {
						r += v
					}
					r /= float64(len(vals))
				case "min":
					r = math.Inf(1)
					for _, v := range vals {
						r = math.Min(r, v)
					}
				case "max":
					r = math.Inf(-1)
					for _, v := range vals {
						r = math.Max(r, v)
					}
				case "median":
					s := append([]float64{}, vals...)
					sort.Float64s(s)
					if len(s)%2 == 1 {
						r = s[len(s)/2]
					} else {
						r = (s[len(s)/2-1] + s[len(s)/2]) / 2
					}
				case "mode":
					counts := map[float64]int{}
					best, bc := 0.0, 0
					for _, v := range vals {
						counts[v]++
						if counts[v] > bc {
							best, bc = v, counts[v]
						}
					}
					r = best
				case "mul":
					r = 1
					for _, v := range vals {
						r *= v
					}
				case "diff":
					r = vals[0]
					if len(vals) > 1 {
						r = vals[0] - vals[1]
					}
				case "div":
					r = vals[0]
					if len(vals) > 1 {
						r = vals[0] / vals[1]
					}
				case "geometric_mean":
					p := 1.0
					for _, v := range vals {
						p *= v
					}
					r = math.Pow(p, 1/float64(len(vals)))
				case "harmonic_mean":
					s := 0.0
					for _, v := range vals {
						s += 1 / v
					}
					r = float64(len(vals)) / s
				case "sqrt":
					r = math.Sqrt(vals[0])
				case "log10":
					r = math.Log10(vals[0])
				case "inv":
					r = 1 / vals[0]
				case "round":
					r = math.Round(vals[0])
				case "exp":
					r = math.Exp(vals[0])
				}
				out[k] = r
			}
			if a.IsSet("output-data-type") {
				dt = dataTypeFromName(a.Str("output-data-type"))
			}
			b := ds.AddBand(dt)
			b.data = convertDataToType(out, dt)
			b.loaded = true
			b.BlockX, b.BlockY = g[0].BlockX, g[0].BlockY
			b.HasNoData, b.NoData = hasND, nd
		}
	}
	if a.Bool("overwrite") {
		deleteExistingDataset(outName)
	}
	drv := a.outputDriver(outName, true, false)
	if drv == nil {
		CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
		return false
	}
	finalizeNewRaster(ds, drv, nil)
	prog.Update(0)
	ds.Driver = drv
	if !writeRasterOutput(a, ds, drv, outName, a.StrList("creation-option"), prog) {
		return false
	}
	prog.Update(1)
	return true
}
