{"command":"cd /workspace/gdalgo && rm sql_stub.go && cat > ogrsql.go <<'EOF'
package main

import (
	"math"
	"sort"
	"strconv"
	"strings"
)

// ---------------- tokenizer ----------------

type sqlTok struct {
	kind int // 0 ident, 1 string, 2 number, 3 op, 4 eof
	s    string
	pos  int
	quoted bool
}

func sqlTokenize(s string) ([]sqlTok, error) {
	var toks []sqlTok
	i := 0
	for i < len(s) {
		c := s[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		st := i
		switch {
		case c == '\'':
			var sb strings.Builder
			i++
			for i < len(s) {
				if s[i] == '\'' {
					if i+1 < len(s) && s[i+1] == '\'' {
						sb.WriteByte('\'')
						i += 2
						continue
					}
					break
				}
				sb.WriteByte(s[i])
				i++
			}
			if i >= len(s) {
				return nil, &sqlErr{"unterminated string", st}
			}
			i++
			toks = append(toks, sqlTok{kind: 1, s: sb.String(), pos: st})
		case c == '"':
			var sb strings.Builder
			i++
			for i < len(s) && s[i] != '"' {
				sb.WriteByte(s[i])
				i++
			}
			i++
			toks = append(toks, sqlTok{kind: 0, s: sb.String(), pos: st, quoted: true})
		case (c >= '0' && c <= '9') || (c == '.' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9'):
			for i < len(s) && ((s[i] >= '0' && s[i] <= '9') || s[i] == '.') {
				i++
			}
			if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
				j := i + 1
				if j < len(s) && (s[j] == '+' || s[j] == '-') {
					j++
				}
				if j < len(s) && s[j] >= '0' && s[j] <= '9' {
					i = j
					for i < len(s) && s[i] >= '0' && s[i] <= '9' {
						i++
					}
				}
			}
			toks = append(toks, sqlTok{kind: 2, s: s[st:i], pos: st})
		case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c >= 0x80:
			for i < len(s) && ((s[i] >= 'a' && s[i] <= 'z') || (s[i] >= 'A' && s[i] <= 'Z') || s[i] == '_' || (s[i] >= '0' && s[i] <= '9') || s[i] >= 0x80 || s[i] == '.') {
				i++
			}
			toks = append(toks, sqlTok{kind: 0, s: s[st:i], pos: st})
		default:
			two := ""
			if i+1 < len(s) {
				two = s[i : i+2]
			}
			if two == "<=" || two == ">=" || two == "<>" || two == "!=" || two == "||" || two == "==" {
				toks = append(toks, sqlTok{kind: 3, s: two, pos: st})
				i += 2
			} else {
				toks = append(toks, sqlTok{kind: 3, s: string(c), pos: st})
				i++
			}
		}
	}
	toks = append(toks, sqlTok{kind: 4, pos: len(s)})
	return toks, nil
}

type sqlErr struct {
	msg string
	pos int
}

func (e *sqlErr) Error() string { return e.msg }

// ---------------- AST ----------------

type sqlNode struct {
	op       string // "lit", "col", "unary", "bin", "func", "in", "between", "like", "isnull", "star", "cast"
	val      sqlVal
	name     string
	args     []*sqlNode
	not      bool
	ci       bool
	castType string
}

type sqlVal struct {
	kind int // 0 null, 1 int, 2 real, 3 string
	i    int64
	f    float64
	s    string
}

func (v sqlVal) num() float64 {
	if v.kind == 1 {
		return float64(v.i)
	}
	if v.kind == 3 {
		return cplAtof(v.s)
	}
	return v.f
}

func (v sqlVal) str() string {
	switch v.kind {
	case 1:
		return strconv.FormatInt(v.i, 10)
	case 2:
		return cfmt("%.15g", v.f)
	case 3:
		return v.s
	}
	return ""
}

type sqlParser struct {
	toks []sqlTok
	p    int
	src  string
}

func (p *sqlParser) peek() sqlTok { return p.toks[p.p] }
func (p *sqlParser) next() sqlTok {
	t := p.toks[p.p]
	if p.p < len(p.toks)-1 {
		p.p++
	}
	return t
}

func (p *sqlParser) isKW(kw string) bool {
	t := p.peek()
	return t.kind == 0 && !t.quoted && strings.EqualFold(t.s, kw)
}

func (p *sqlParser) acceptKW(kw string) bool {
	if p.isKW(kw) {
		p.next()
		return true
	}
	return false
}

func (p *sqlParser) isOp(op string) bool {
	t := p.peek()
	return t.kind == 3 && t.s == op
}

func (p *sqlParser) syntaxErr() error {
	t := p.peek()
	if t.kind == 4 {
		return &sqlErr{"syntax error, unexpected end of string", t.pos}
	}
	what := ""
	switch t.kind {
	case 0:
		what = "identifier"
	case 1:
		what = "string"
	case 2:
		if strings.ContainsAny(t.s, ".eE") {
			what = "floating point number"
		} else {
			what = "integer number"
		}
	default:
		what = "'" + t.s + "'"
	}
	return &sqlErr{"syntax error, unexpected " + what, t.pos}
}

var sqlReserved = map[string]bool{"AND": true, "OR": true, "NOT": true, "LIKE": true, "ILIKE": true, "IN": true, "BETWEEN": true, "IS": true, "NULL": true, "FROM": true, "WHERE": true, "ORDER": true, "BY": true, "AS": true, "ASC": true, "DESC": true, "LIMIT": true, "OFFSET": true, "ESCAPE": true, "SELECT": true, "DISTINCT": true, "JOIN": true, "LEFT": true, "ON": true, "CAST": true}

func (p *sqlParser) parseExpr() (*sqlNode, error) { return p.parseOr() }

func (p *sqlParser) parseOr() (*sqlNode, error) {
	l, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.acceptKW("OR") {
		r, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		l = &sqlNode{op: "bin", name: "OR", args: []*sqlNode{l, r}}
	}
	return l, nil
}

func (p *sqlParser) parseAnd() (*sqlNode, error) {
	l, err := p.parseNot()
	if err != nil {
		return nil, err
	}
	for p.acceptKW("AND") {
		r, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		l = &sqlNode{op: "bin", name: "AND", args: []*sqlNode{l, r}}
	}
	return l, nil
}

func (p *sqlParser) parseNot() (*sqlNode, error) {
	if p.acceptKW("NOT") {
		e, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		return &sqlNode{op: "unary", name: "NOT", args: []*sqlNode{e}}, nil
	}
	return p.parseCmp()
}

func (p *sqlParser) parseCmp() (*sqlNode, error) {
	l, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t.kind == 3 && (t.s == "=" || t.s == "==" || t.s == "<>" || t.s == "!=" || t.s == "<" || t.s == ">" || t.s == "<=" || t.s == ">=") {
			p.next()
			r, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			op := t.s
			if op == "==" {
				op = "="
			}
			if op == "!=" {
				op = "<>"
			}
			l = &sqlNode{op: "bin", name: op, args: []*sqlNode{l, r}}
			continue
		}
		not := false
		save := p.p
		if p.isKW("NOT") {
			p.next()
			not = true
		}
		switch {
		case p.isKW("LIKE") || p.isKW("ILIKE"):
			ci := p.isKW("ILIKE")
			p.next()
			r, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			n := &sqlNode{op: "like", args: []*sqlNode{l, r}, not: not, ci: ci}
			if p.acceptKW("ESCAPE") {
				e, err := p.parseAdd()
				if err != nil {
					return nil, err
				}
				n.args = append(n.args, e)
			}
			l = n
			continue
		case p.isKW("IN"):
			p.next()
			if !p.isOp("(") {
				return nil, p.syntaxErr()
			}
			p.next()
			n := &sqlNode{op: "in", args: []*sqlNode{l}, not: not}
			for {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				n.args = append(n.args, e)
				if p.isOp(",") {
					p.next()
					continue
				}
				break
			}
			if !p.isOp(")") {
				return nil, p.syntaxErr()
			}
			p.next()
			l = n
			continue
		case p.isKW("BETWEEN"):
			p.next()
			lo, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			if !p.acceptKW("AND") {
				return nil, p.syntaxErr()
			}
			hi, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			l = &sqlNode{op: "between", args: []*sqlNode{l, lo, hi}, not: not}
			continue
		}
		if not {
			p.p = save
		}
		if p.isKW("IS") {
			p.next()
			n := p.acceptKW("NOT")
			if !p.acceptKW("NULL") {
				return nil, p.syntaxErr()
			}
			l = &sqlNode{op: "isnull", args: []*sqlNode{l}, not: n}
			continue
		}
		return l, nil
	}
}

func (p *sqlParser) parseAdd() (*sqlNode, error) {
	l, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for p.isOp("+") || p.isOp("-") || p.isOp("||") {
		op := p.next().s
		r, err := p.parseMul()
		if err != nil {
			return nil, err
		}
		l = &sqlNode{op: "bin", name: op, args: []*sqlNode{l, r}}
	}
	return l, nil
}

func (p *sqlParser) parseMul() (*sqlNode, error) {
	l, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.isOp("*") || p.isOp("/") || p.isOp("%") {
		op := p.next().s
		r, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		l = &sqlNode{op: "bin", name: op, args: []*sqlNode{l, r}}
	}
	return l, nil
}

func (p *sqlParser) parseUnary() (*sqlNode, error) {
	if p.isOp("-") {
		p.next()
		e, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		if e.op == "lit" && e.val.kind == 1 {
			e.val.i = -e.val.i
			return e, nil
		}
		if e.op == "lit" && e.val.kind == 2 {
			e.val.f = -e.val.f
			return e, nil
		}
		return &sqlNode{op: "unary", name: "-", args: []*sqlNode{e}}, nil
	}
	if p.isOp("+") {
		p.next()
		return p.parseUnary()
	}
	return p.parsePrimary()
}

func (p *sqlParser) parsePrimary() (*sqlNode, error) {
	t := p.peek()
	switch t.kind {
	case 1:
		p.next()
		return &sqlNode{op: "lit", val: sqlVal{kind: 3, s: t.s}}, nil
	case 2:
		p.next()
		if !strings.ContainsAny(t.s, ".eE") {
			if v, err := strconv.ParseInt(t.s, 10, 64); err == nil {
				return &sqlNode{op: "lit", val: sqlVal{kind: 1, i: v}}, nil
			}
		}
		f, _ := strconv.ParseFloat(t.s, 64)
		return &sqlNode{op: "lit", val: sqlVal{kind: 2, f: f}}, nil
	case 3:
		if t.s == "(" {
			p.next()
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if !p.isOp(")") {
				return nil, p.syntaxErr()
			}
			p.next()
			return e, nil
		}
		if t.s == "*" {
			p.next()
			return &sqlNode{op: "star"}, nil
		}
		return nil, p.syntaxErr()
	case 0:
		if !t.quoted && strings.EqualFold(t.s, "NULL") {
			p.next()
			return &sqlNode{op: "lit", val: sqlVal{kind: 0}}, nil
		}
		if !t.quoted && strings.EqualFold(t.s, "CAST") {
			p.next()
			if !p.isOp("(") {
				return nil, p.syntaxErr()
			}
			p.next()
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if !p.acceptKW("AS") {
				return nil, p.syntaxErr()
			}
			tt := p.next()
			typ := strings.ToLower(tt.s)
			if p.isOp("(") {
				for !p.isOp(")") && p.peek().kind != 4 {
					p.next()
				}
				p.next()
			}
			if !p.isOp(")") {
				return nil, p.syntaxErr()
			}
			p.next()
			return &sqlNode{op: "cast", args: []*sqlNode{e}, castType: typ}, nil
		}
		if !t.quoted && sqlReserved[strings.ToUpper(t.s)] {
			return nil, p.syntaxErr()
		}
		p.next()
		if !t.quoted && p.isOp("(") {
			p.next()
			n := &sqlNode{op: "func", name: strings.ToUpper(t.s)}
			if p.acceptKW("DISTINCT") {
				n.not = true
			}
			if !p.isOp(")") {
				for {
					e, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					n.args = append(n.args, e)
					if p.isOp(",") {
						p.next()
						continue
					}
					break
				}
			}
			if !p.isOp(")") {
				return nil, p.syntaxErr()
			}
			p.next()
			return n, nil
		}
		return &sqlNode{op: "col", name: t.s}, nil
	}
	return nil, p.syntaxErr()
}

func formatSQLParseError(src string, e *sqlErr) string {
	return "SQL Expression Parsing Error: " + e.msg + ". Occurred around :\n" + src + "\n" + strings.Repeat(" ", e.pos) + "^"
}

// ---------------- binding & evaluation ----------------

type sqlCtx struct {
	l *Layer
	f *Feature
}

var specialFields = []string{"FID", "OGR_GEOMETRY", "OGR_STYLE", "OGR_GEOM_WKT", "OGR_GEOM_AREA"}

func (n *sqlNode) bind(l *Layer) error {
	if n.op == "col" {
		name := n.name
		if i := strings.LastIndexByte(name, '.'); i >= 0 && l.FieldIndex(name) < 0 {
			if strings.EqualFold(name[:i], l.Name) {
				name = name[i+1:]
				n.name = name
			}
		}
		if l.FieldIndex(name) < 0 {
			ok := false
			for _, s := range specialFields {
				if strings.EqualFold(s, name) {
					ok = true
				}
			}
			if !ok {
				return &sqlErr{"\"" + n.name + "\" not recognised as an available field.", -1}
			}
		}
	}
	for _, a := range n.args {
		if err := a.bind(l); err != nil {
			return err
		}
	}
	return nil
}

func fieldToSQLVal(fd *FieldDefn, fv *FieldValue) sqlVal {
	if fv.State != 2 {
		return sqlVal{}
	}
	switch fd.Type {
	case OFTInteger, OFTInteger64:
		return sqlVal{kind: 1, i: fv.I}
	case OFTReal:
		return sqlVal{kind: 2, f: fv.F}
	}
	return sqlVal{kind: 3, s: fieldAsString(fd, fv)}
}

func (n *sqlNode) colType(l *Layer) int {
	switch n.op {
	case "lit":
		return n.val.kind
	case "col":
		idx := l.FieldIndex(n.name)
		if idx >= 0 {
			switch l.Fields[idx].Type {
			case OFTInteger, OFTInteger64:
				return 1
			case OFTReal:
				return 2
			}
			return 3
		}
		switch strings.ToUpper(n.name) {
		case "FID":
			return 1
		case "OGR_GEOM_AREA":
			return 2
		}
		return 3
	case "bin":
		switch n.name {
		case "+", "-", "*", "/", "%":
			a, b := n.args[0].colType(l), n.args[1].colType(l)
			if a == 2 || b == 2 {
				return 2
			}
			if a == 3 || b == 3 {
				return 3
			}
			return 1
		case "||":
			return 3
		}
		return 1
	case "func":
		switch n.name {
		case "CONCAT", "SUBSTR", "LOWER", "UPPER", "HSTORE_GET_VALUE":
			return 3
		case "COUNT":
			return 1
		case "SUM", "MIN", "MAX":
			if len(n.args) > 0 {
				return n.args[0].colType(l)
			}
		case "AVG":
			return 2
		case "LENGTH":
			return 1
		}
		return 2
	case "cast":
		switch {
		case strings.HasPrefix(n.castType, "int"):
			return 1
		case strings.HasPrefix(n.castType, "float"), strings.HasPrefix(n.castType, "real"), strings.HasPrefix(n.castType, "numeric"):
			return 2
		}
		return 3
	case "unary":
		if n.name == "-" {
			return n.args[0].colType(l)
		}
		return 1
	}
	return 1
}

func (n *sqlNode) typeCheck(l *Layer) error {
	for _, a := range n.args {
		if err := a.typeCheck(l); err != nil {
			return err
		}
	}
	if n.op == "bin" {
		switch n.name {
		case "=", "<>", "<", ">", "<=", ">=":
			a, b := n.args[0].colType(l), n.args[1].colType(l)
			if a == 0 || b == 0 {
				return nil
			}
			if (a == 3) != (b == 3) {
				return &sqlErr{"Type mismatch or improper type of arguments to " + n.name + " operator.", -1}
			}
		}
	}
	return nil
}

func (n *sqlNode) eval(c *sqlCtx) sqlVal {
	switch n.op {
	case "lit":
		return n.val
	case "col":
		idx := c.l.FieldIndex(n.name)
		if idx >= 0 {
			return fieldToSQLVal(c.l.Fields[idx], &c.f.Fields[idx])
		}
		switch strings.ToUpper(n.name) {
		case "FID":
			return sqlVal{kind: 1, i: c.f.FID}
		case "OGR_GEOMETRY":
			if g := c.f.Geom(); g != nil {
				return sqlVal{kind: 3, s: wktNames[g.T]}
			}
			return sqlVal{}
		case "OGR_GEOM_WKT":
			if g := c.f.Geom(); g != nil {
				return sqlVal{kind: 3, s: g.WKTOGR()}
			}
			return sqlVal{}
		case "OGR_GEOM_AREA":
			if g := c.f.Geom(); g != nil {
				return sqlVal{kind: 2, f: g.Area()}
			}
			return sqlVal{}
		case "OGR_STYLE":
			if c.f.Style != "" {
				return sqlVal{kind: 3, s: c.f.Style}
			}
			return sqlVal{}
		}
		return sqlVal{}
	case "unary":
		v := n.args[0].eval(c)
		if n.name == "NOT" {
			if v.kind == 0 {
				return sqlVal{}
			}
			return boolVal(!truthy(v))
		}
		switch v.kind {
		case 1:
			return sqlVal{kind: 1, i: -v.i}
		case 2:
			return sqlVal{kind: 2, f: -v.f}
		}
		return sqlVal{}
	case "bin":
		if n.name == "AND" {
			a := n.args[0].eval(c)
			b := n.args[1].eval(c)
			if (a.kind != 0 && !truthy(a)) || (b.kind != 0 && !truthy(b)) {
				return boolVal(false)
			}
			if a.kind == 0 || b.kind == 0 {
				return sqlVal{}
			}
			return boolVal(true)
		}
		if n.name == "OR" {
			a := n.args[0].eval(c)
			b := n.args[1].eval(c)
			if truthy(a) || truthy(b) {
				return boolVal(true)
			}
			if a.kind == 0 || b.kind == 0 {
				return sqlVal{}
			}
			return boolVal(false)
		}
		a := n.args[0].eval(c)
		b := n.args[1].eval(c)
		if a.kind == 0 || b.kind == 0 {
			return sqlVal{}
		}
		switch n.name {
		case "=", "<>", "<", ">", "<=", ">=":
			cmp := compareSQL(a, b)
			switch n.name {
			case "=":
				return boolVal(cmp == 0)
			case "<>":
				return boolVal(cmp != 0)
			case "<":
				return boolVal(cmp < 0)
			case ">":
				return boolVal(cmp > 0)
			case "<=":
				return boolVal(cmp <= 0)
			case ">=":
				return boolVal(cmp >= 0)
			}
		case "||":
			return sqlVal{kind: 3, s: a.str() + b.str()}
		case "+", "-", "*", "/", "%":
			if a.kind == 3 || b.kind == 3 {
				if n.name == "+" {
					return sqlVal{kind: 3, s: a.str() + b.str()}
				}
				return sqlVal{}
			}
			if a.kind == 1 && b.kind == 1 {
				switch n.name {
				case "+":
					return sqlVal{kind: 1, i: a.i + b.i}
				case "-":
					return sqlVal{kind: 1, i: a.i - b.i}
				case "*":
					return sqlVal{kind: 1, i: a.i * b.i}
				case "/":
					if b.i == 0 {
						return sqlVal{}
					}
					return sqlVal{kind: 1, i: a.i / b.i}
				case "%":
					if b.i == 0 {
						return sqlVal{}
					}
					return sqlVal{kind: 1, i: a.i % b.i}
				}
			}
			x, y := a.num(), b.num()
			switch n.name {
			case "+":
				return sqlVal{kind: 2, f: x + y}
			case "-":
				return sqlVal{kind: 2, f: x - y}
			case "*":
				return sqlVal{kind: 2, f: x * y}
			case "/":
				return sqlVal{kind: 2, f: x / y}
			case "%":
				return sqlVal{kind: 2, f: math.Mod(x, y)}
			}
		}
	case "like":
		a := n.args[0].eval(c)
		b := n.args[1].eval(c)
		if a.kind == 0 || b.kind == 0 {
			return sqlVal{}
		}
		esc := byte(0)
		if len(n.args) > 2 {
			e := n.args[2].eval(c).str()
			if len(e) > 0 {
				esc = e[0]
			}
		}
		m := likeMatch(a.str(), b.str(), n.ci, esc)
		return boolVal(m != n.not)
	case "in":
		a := n.args[0].eval(c)
		if a.kind == 0 {
			return sqlVal{}
		}
		found := false
		for _, e := range n.args[1:] {
			v := e.eval(c)
			if v.kind != 0 && compareSQL(a, v) == 0 {
				found = true
				break
			}
		}
		return boolVal(found != n.not)
	case "between":
		a := n.args[0].eval(c)
		lo := n.args[1].eval(c)
		hi := n.args[2].eval(c)
		if a.kind == 0 || lo.kind == 0 || hi.kind == 0 {
			return sqlVal{}
		}
		r := compareSQL(a, lo) >= 0 && compareSQL(a, hi) <= 0
		return boolVal(r != n.not)
	case "isnull":
		v := n.args[0].eval(c)
		return boolVal((v.kind == 0) != n.not)
	case "cast":
		v := n.args[0].eval(c)
		if v.kind == 0 {
			return v
		}
		switch {
		case strings.HasPrefix(n.castType, "int"):
			if v.kind == 3 {
				return sqlVal{kind: 1, i: int64(atoiC(v.s))}
			}
			return sqlVal{kind: 1, i: int64(v.num())}
		case strings.HasPrefix(n.castType, "float"), strings.HasPrefix(n.castType, "real"), strings.HasPrefix(n.castType, "numeric"):
			return sqlVal{kind: 2, f: v.num()}
		}
		return sqlVal{kind: 3, s: v.str()}
	case "func":
		var vals []sqlVal
		for _, a := range n.args {
			vals = append(vals, a.eval(c))
		}
		switch n.name {
		case "CONCAT":
			var sb strings.Builder
			for _, v := range vals {
				sb.WriteString(v.str())
			}
			return sqlVal{kind: 3, s: sb.String()}
		case "LOWER":
			if len(vals) > 0 && vals[0].kind != 0 {
				return sqlVal{kind: 3, s: strings.ToLower(vals[0].str())}
			}
		case "UPPER":
			if len(vals) > 0 && vals[0].kind != 0 {
				return sqlVal{kind: 3, s: strings.ToUpper(vals[0].str())}
			}
		case "LENGTH":
			if len(vals) > 0 && vals[0].kind != 0 {
				return sqlVal{kind: 1, i: int64(len([]rune(vals[0].str())))}
			}
		case "SUBSTR":
			if len(vals) >= 2 && vals[0].kind != 0 {
				s := []rune(vals[0].str())
				st := int(vals[1].num())
				if st > 0 {
					st--
				} else if st < 0 {
					st = len(s) + st
				}
				if st < 0 {
					st = 0
				}
				if st > len(s) {
					st = len(s)
				}
				en := len(s)
				if len(vals) >= 3 {
					en = st + int(vals[2].num())
					if en > len(s) {
						en = len(s)
					}
				}
				if en < st {
					en = st
				}
				return sqlVal{kind: 3, s: string(s[st:en])}
			}
		case "ABS":
			if len(vals) > 0 {
				if vals[0].kind == 1 {
					if vals[0].i < 0 {
						return sqlVal{kind: 1, i: -vals[0].i}
					}
					return vals[0]
				}
				return sqlVal{kind: 2, f: math.Abs(vals[0].num())}
			}
		}
		return sqlVal{}
	}
	return sqlVal{}
}

func boolVal(b bool) sqlVal {
	if b {
		return sqlVal{kind: 1, i: 1}
	}
	return sqlVal{kind: 1, i: 0}
}

func truthy(v sqlVal) bool {
	switch v.kind {
	case 1:
		return v.i != 0
	case 2:
		return v.f != 0
	case 3:
		return v.s != ""
	}
	return false
}

func compareSQL(a, b sqlVal) int {
	if a.kind == 3 || b.kind == 3 {
		x, y := a.str(), b.str()
		if x < y {
			return -1
		}
		if x > y {
			return 1
		}
		return 0
	}
	if a.kind == 1 && b.kind == 1 {
		if a.i < b.i {
			return -1
		}
		if a.i > b.i {
			return 1
		}
		return 0
	}
	x, y := a.num(), b.num()
	if x < y {
		return -1
	}
	if x > y {
		return 1
	}
	return 0
}

func likeMatch(s, pat string, ci bool, esc byte) bool {
	if ci {
		s = strings.ToLower(s)
		pat = strings.ToLower(pat)
	}
	var rec func(si, pi int) bool
	rec = func(si, pi int) bool {
		for pi < len(pat) {
			c := pat[pi]
			if esc != 0 && c == esc && pi+1 < len(pat) {
				if si >= len(s) || s[si] != pat[pi+1] {
					return false
				}
				si++
				pi += 2
				continue
			}
			if c == '%' {
				for k := si; k <= len(s); k++ {
					if rec(k, pi+1) {
						return true
					}
				}
				return false
			}
			if si >= len(s) {
				return false
			}
			if c == '_' {
				_, size := utf8DecodeRune(s[si:])
				si += size
				pi++
				continue
			}
			if s[si] != c {
				return false
			}
			si++
			pi++
		}
		return si == len(s)
	}
	return rec(0, 0)
}

func utf8DecodeRune(s string) (rune, int) {
	for i, r := range s {
		if i == 0 {
			sz := len(string(r))
			return r, sz
		}
	}
	return 0, 1
}

// parseWhere parses and binds a where clause for a layer.
func parseWhere(l *Layer, where string) (*sqlNode, error) {
	toks, err := sqlTokenize(where)
	if err != nil {
		return nil, err
	}
	p := &sqlParser{toks: toks, src: where}
	e, err := p.parseExpr()
	if err != nil {
		if se, ok := err.(*sqlErr); ok {
			CPLError(CE_Failure, CPLE_AppDefined, "%s", formatSQLParseError(where, se))
		}
		return nil, err
	}
	if p.peek().kind != 4 {
		se := p.syntaxErr().(*sqlErr)
		CPLError(CE_Failure, CPLE_AppDefined, "%s", formatSQLParseError(where, se))
		return nil, se
	}
	if err := e.bind(l); err != nil {
		CPLError(CE_Failure, CPLE_AppDefined, "%s", err.Error())
		return nil, err
	}
	if err := e.typeCheck(l); err != nil {
		CPLError(CE_Failure, CPLE_AppDefined, "%s", err.Error())
		return nil, err
	}
	return e, nil
}

func filterFeatures(l *Layer, where string) ([]*Feature, error) {
	e, err := parseWhere(l, where)
	if err != nil {
		return nil, err
	}
	var res []*Feature
	for _, f := range l.Feats() {
		v := e.eval(&sqlCtx{l: l, f: f})
		if v.kind != 0 && truthy(v) {
			res = append(res, f)
		}
	}
	return res, nil
}

// ---------------- SELECT ----------------

type selCol struct {
	expr  *sqlNode
	alias string
	star  bool
}

func executeSQL(ds *Dataset, sql, dialect string) (*Layer, error) {
	if dialect != "" && !strings.EqualFold(dialect, "OGRSQL") {
		if strings.EqualFold(dialect, "SQLITE") {
			CPLError(CE_Failure, CPLE_NotSupported, "The SQLite driver needs to be compiled to support the SQLite SQL dialect")
			return nil, &sqlErr{"sqlite", -1}
		}
	}
	toks, err := sqlTokenize(sql)
	if err != nil {
		return nil, err
	}
	p := &sqlParser{toks: toks, src: sql}
	if !p.acceptKW("SELECT") {
		CPLError(CE_Failure, CPLE_AppDefined, "Unsupported SQL statement: %s", sql)
		return nil, &sqlErr{"unsupported", -1}
	}
	distinct := p.acceptKW("DISTINCT")
	var cols []selCol
	for {
		if p.isOp("*") {
			p.next()
			cols = append(cols, selCol{star: true})
		} else {
			e, err := p.parseExpr()
			if err != nil {
				se := err.(*sqlErr)
				CPLError(CE_Failure, CPLE_AppDefined, "SQL Expression Parsing Error: %s. Occurred around :\n%s\n%s^", se.msg, sql, strings.Repeat(" ", se.pos))
				return nil, err
			}
			c := selCol{expr: e}
			if p.acceptKW("AS") {
				c.alias = p.next().s
			} else if t := p.peek(); t.kind == 0 && !sqlReserved[strings.ToUpper(t.s)] {
				c.alias = p.next().s
			}
			cols = append(cols, c)
		}
		if p.isOp(",") {
			p.next()
			continue
		}
		break
	}
	if !p.acceptKW("FROM") {
		CPLError(CE_Failure, CPLE_AppDefined, "SQL Expression Parsing Error: syntax error. Occurred around :\n%s", sql)
		return nil, &sqlErr{"no from", -1}
	}
	tt := p.next()
	tname := tt.s
	l := ds.GetLayerByName(tname)
	if l == nil {
		CPLError(CE_Failure, CPLE_AppDefined, "SELECT from table %s failed, no such table/featureclass.", tname)
		return nil, &sqlErr{"no table", -1}
	}
	if t := p.peek(); t.kind == 0 && !sqlReserved[strings.ToUpper(t.s)] {
		p.next() // table alias
	}
	var where *sqlNode
	if p.acceptKW("WHERE") {
		where, err = p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := where.bind(l); err != nil {
			CPLError(CE_Failure, CPLE_AppDefined, "%s", err.Error())
			return nil, err
		}
	}
	type ordItem struct {
		e    *sqlNode
		desc bool
	}
	var order []ordItem
	if p.acceptKW("ORDER") {
		p.acceptKW("BY")
		for {
			e, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			oi := ordItem{e: e}
			if p.acceptKW("DESC") {
				oi.desc = true
			} else {
				p.acceptKW("ASC")
			}
			order = append(order, oi)
			if p.isOp(",") {
				p.next()
				continue
			}
			break
		}
	}
	limit, offset := -1, 0
	for {
		if p.acceptKW("LIMIT") {
			limit = int(cplAtof(p.next().s))
			continue
		}
		if p.acceptKW("OFFSET") {
			offset = int(cplAtof(p.next().s))
			continue
		}
		break
	}
	for _, c := range cols {
		if c.expr != nil {
			if err := c.expr.bind(l); err != nil {
				CPLError(CE_Failure, CPLE_AppDefined, "%s", err.Error())
				return nil, err
			}
		}
	}
	// filter
	var feats []*Feature
	for _, f := range l.Feats() {
		if where != nil {
			v := where.eval(&sqlCtx{l: l, f: f})
			if v.kind == 0 || !truthy(v) {
				continue
			}
		}
		feats = append(feats, f)
	}
	// order
	if len(order) > 0 {
		sort.SliceStable(feats, func(i, j int) bool {
			for _, o := range order {
				a := o.e.eval(&sqlCtx{l: l, f: feats[i]})
				b := o.e.eval(&sqlCtx{l: l, f: feats[j]})
				if a.kind == 0 && b.kind == 0 {
					continue
				}
				if a.kind == 0 {
					return !o.desc
				}
				if b.kind == 0 {
					return o.desc
				}
				c := compareSQL(a, b)
				if c == 0 {
					continue
				}
				if o.desc {
					return c > 0
				}
				return c < 0
			}
			return false
		})
	}
	res := NewLayer(l.Name)
	res.GeomFields = []*GeomFieldDefn{}
	for _, g := range l.GeomFields {
		gg := *g
		res.GeomFields = append(res.GeomFields, &gg)
	}
	// aggregates?
	isAgg := false
	for _, c := range cols {
		if c.expr != nil && c.expr.op == "func" && (c.expr.name == "COUNT" || c.expr.name == "SUM" || c.expr.name == "AVG" || c.expr.name == "MIN" || c.expr.name == "MAX") {
			isAgg = true
		}
	}
	type outCol struct {
		srcIdx int
		expr   *sqlNode
		fd     *FieldDefn
	}
	var ocols []outCol
	for _, c := range cols {
		if c.star {
			for i, fd := range l.Fields {
				ocols = append(ocols, outCol{srcIdx: i, fd: fd.Clone()})
			}
			continue
		}
		name := c.alias
		if c.expr.op == "col" {
			idx := l.FieldIndex(c.expr.name)
			if name == "" {
				name = c.expr.name
				if idx >= 0 {
					name = l.Fields[idx].Name
				}
			}
			if idx >= 0 {
				fd := l.Fields[idx].Clone()
				fd.Name = name
				ocols = append(ocols, outCol{srcIdx: idx, fd: fd})
				continue
			}
		}
		if name == "" {
			if c.expr.op == "func" {
				arg := "*"
				if len(c.expr.args) > 0 {
					if c.expr.args[0].op == "col" {
						arg = c.expr.args[0].name
					} else if c.expr.args[0].op != "star" {
						arg = "expr"
					}
				}
				name = c.expr.name + "_" + arg
			} else {
				name = "FIELD_" + strconv.Itoa(len(ocols)+1)
			}
		}
		var fd *FieldDefn
		switch c.expr.colType(l) {
		case 1:
			fd = NewFieldDefn(name, OFTInteger)
			if c.expr.op == "func" && (c.expr.name == "MIN" || c.expr.name == "MAX" || c.expr.name == "SUM") && len(c.expr.args) > 0 && c.expr.args[0].op == "col" {
				if idx := l.FieldIndex(c.expr.args[0].name); idx >= 0 {
					fd.Type = l.Fields[idx].Type
				}
			}
			if c.expr.op == "func" && c.expr.name == "COUNT" {
				fd.Type = OFTInteger
			}
		case 2:
			fd = NewFieldDefn(name, OFTReal)
		default:
			fd = NewFieldDefn(name, OFTString)
		}
		ocols = append(ocols, outCol{srcIdx: -1, expr: c.expr, fd: fd})
	}
	for _, oc := range ocols {
		res.Fields = append(res.Fields, oc.fd)
	}
	if isAgg {
		f := res.NewFeature()
		f.FID = 0
		for i, oc := range ocols {
			if oc.expr == nil || oc.expr.op != "func" {
				continue
			}
			var vals []sqlVal
			for _, ft := range feats {
				if len(oc.expr.args) == 0 || oc.expr.args[0].op == "star" {
					vals = append(vals, sqlVal{kind: 1, i: 1})
				} else {
					v := oc.expr.args[0].eval(&sqlCtx{l: l, f: ft})
					if v.kind != 0 {
						vals = append(vals, v)
					}
				}
			}
			fv := FieldValue{State: 2}
			switch oc.expr.name {
			case "COUNT":
				fv.I = int64(len(vals))
			case "SUM":
				s := 0.0
				for _, v := range vals {
					s += v.num()
				}
				fv.F = s
				fv.I = int64(s)
			case "AVG":
				s := 0.0
				for _, v := range vals {
					s += v.num()
				}
				if len(vals) == 0 {
					fv.State = 1
				} else {
					fv.F = s / float64(len(vals))
				}
			case "MIN", "MAX":
				if len(vals) == 0 {
					fv.State = 1
				} else {
					best := vals[0]
					for _, v := range vals[1:] {
						c := compareSQL(v, best)
						if (oc.expr.name == "MIN" && c < 0) || (oc.expr.name == "MAX" && c > 0) {
							best = v
						}
					}
					fv.I = int64(best.num())
					fv.F = best.num()
					fv.S = best.str()
				}
			}
			f.Fields[i] = fv
		}
		res.Features = []*Feature{f}
		res.GeomFields = nil
		res.loaded = true
		return res, nil
	}
	seen := map[string]bool{}
	count := 0
	for _, ft := range feats {
		nf := res.NewFeature()
		nf.FID = ft.FID
		for i, oc := range ocols {
			if oc.srcIdx >= 0 {
				nf.Fields[i] = ft.Fields[oc.srcIdx]
				continue
			}
			v := oc.expr.eval(&sqlCtx{l: l, f: ft})
			switch v.kind {
			case 0:
				nf.Fields[i] = FieldValue{State: 1}
			case 1:
				nf.Fields[i] = FieldValue{State: 2, I: v.i, F: float64(v.i), S: v.str()}
			case 2:
				nf.Fields[i] = FieldValue{State: 2, F: v.f, I: int64(v.f), S: v.str()}
			case 3:
				nf.Fields[i] = FieldValue{State: 2, S: v.s}
			}
		}
		if distinct {
			var key strings.Builder
			for i := range ocols {
				key.WriteString(fieldAsString(res.Fields[i], &nf.Fields[i]) + "\x00")
			}
			if seen[key.String()] {
				continue
			}
			seen[key.String()] = true
			nf.Geoms = make([]*Geom, len(res.GeomFields))
		} else {
			for gi := range res.GeomFields {
				if gi < len(ft.Geoms) && ft.Geoms[gi] != nil {
					nf.Geoms[gi] = ft.Geoms[gi].Clone()
				}
			}
		}
		if count < offset {
			count++
			continue
		}
		count++
		if limit >= 0 && len(res.Features) >= limit {
			break
		}
		res.Features = append(res.Features, nf)
	}
	if distinct {
		res.GeomFields = nil
		for _, f := range res.Features {
			f.Geoms = nil
		}
	}
	res.loaded = true
	return res, nil
}
