func srcVector(a *Alg) *Dataset {
	v := a.V("input")
	if len(v.DSs) == 0 {
		return nil
	}
	return v.DSs[0]
}

// selectLayers returns the input layers honoring --input-layer.
func selectInputLayers(a *Alg, ds *Dataset) ([]*Layer, bool) {
	names := a.StrList("input-layer")
	if len(names) == 0 {
		return ds.Layers, true
	}
	var res []*Layer
	for _, n := range names {
		l := ds.GetLayerByName(n)
		if l == nil {
			CPLError(CE_Failure, CPLE_AppDefined, "Couldn't fetch requested layer '%s'!", n)
			return nil, false
		}
		res = append(res, l)
	}
	return res, true
}

func isActive(a *Alg, l *Layer) bool {
	al := a.Str("active-layer")
	return al == "" || al == l.Name
}

// cloneLayerSchema creates an empty layer with same schema.
func cloneLayerSchema(l *Layer) *Layer {
	n := NewLayer(l.Name)
	for _, fd := range l.Fields {
		n.Fields = append(n.Fields, fd.Clone())
	}
	for _, g := range l.GeomFields {
		gg := *g
		n.GeomFields = append(n.GeomFields, &gg)
	}
	n.MD = l.MD.Clone()
	n.FIDColumn = l.FIDColumn
	n.loaded = true
	return n
}

// writeVectorResult writes layers to the output argument.
func writeVectorResult(a *Alg, src *Dataset, layers []*Layer) bool {
	outName := a.DSName("output")
	drv := a.vectorOutputDriver(outName)
	if drv == nil {
		CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
		return false
	}
	saved := a.Vals["input-layer"]
	delete(a.Vals, "input-layer")
	ok := vectorTranslate(a, src, layers, drv, outName)
	if saved != nil {
		a.Vals["input-layer"] = saved
	}
	return ok
}

func runVectorFilter(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	where := a.Str("where")
	if strings.HasPrefix(where, "@") {
		if b, err := vfsReadFile(where[1:]); err == nil {
			where = strings.TrimSpace(string(b))
		}
	}
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		feats := l.Feats()
		if where != "" {
			f2, err := filterFeatures(l, where)
			if err != nil {
				return false
			}
			feats = f2
		}
		if a.IsSet("bbox") {
			bb := a.RealList("bbox")
			env := Envelope{bb[0], bb[1], bb[2], bb[3]}
			var f2 []*Feature
			for _, f := range feats {
				g := f.Geom()
				if g != nil && !g.IsEmpty() && g.Envelope().Intersects(env) {
					f2 = append(f2, f)
				}
			}
			feats = f2
		}
		nl := cloneLayerSchema(l)
		nl.Features = feats
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorSelect(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	fields := a.StrList("fields")
	exclude := a.Bool("exclude")
	ignoreMissing := a.Bool("ignore-missing-fields")
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		var keep []int
		keepGeom := map[int]bool{}
		if exclude {
			ex := map[string]bool{}
			for _, f := range fields {
				ex[strings.ToLower(f)] = true
			}
			for i, fd := range l.Fields {
				if !ex[strings.ToLower(fd.Name)] {
					keep = append(keep, i)
				}
			}
			for gi, g := range l.GeomFields {
				if !ex[strings.ToLower(g.Name)] && !(g.Name == "" && ex["_ogr_geometry_"]) {
					keepGeom[gi] = true
				}
			}
		} else {
			for _, fn := range fields {
				idx := l.FieldIndex(fn)
				if idx < 0 {
					found := false
					for gi, g := range l.GeomFields {
						if strings.EqualFold(g.Name, fn) || (g.Name == "" && strings.EqualFold(fn, "_ogr_geometry_")) {
							keepGeom[gi] = true
							found = true
						}
					}
					if !found && !ignoreMissing {
						a.ReportError(CPLE_AppDefined, "Field '%s' does not exist in layer '%s'.", fn, l.Name)
						return false
					}
					continue
				}
				keep = append(keep, idx)
			}
			if len(l.GeomFields) == 1 && l.GeomFields[0].Name == "" {
				// unnamed geometry kept only if requested via _ogr_geometry_
			}
		}
		nl := NewLayer(l.Name)
		nl.MD = l.MD.Clone()
		var gidx []int
		for gi, g := range l.GeomFields {
			if keepGeom[gi] {
				gg := *g
				nl.GeomFields = append(nl.GeomFields, &gg)
				gidx = append(gidx, gi)
			}
		}
		for _, i := range keep {
			nl.Fields = append(nl.Fields, l.Fields[i].Clone())
		}
		for _, f := range l.Feats() {
			nf := nl.NewFeature()
			nf.FID = f.FID
			for k, i := range keep {
				nf.Fields[k] = f.Fields[i]
			}
			for k, gi := range gidx {
				if gi < len(f.Geoms) {
					nf.Geoms[k] = f.Geoms[gi]
				}
			}
			nl.Features = append(nl.Features, nf)
		}
		nl.loaded = true
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorSQL(a *Alg) bool {
	src := srcVector(a)
	var outLayers []*Layer
	for _, q := range a.StrList("sql") {
		if strings.HasPrefix(q, "@") {
			if b, err := vfsReadFile(q[1:]); err == nil {
				q = strings.TrimSpace(string(b))
			}
		}
		l, err := executeSQL(src, q, a.Str("dialect"))
		if err != nil || l == nil {
			return false
		}
		if ol := a.Str("output-layer"); ol != "" && len(a.StrList("sql")) == 1 {
			l.Name = ol
		}
		outLayers = append(outLayers, l)
	}
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, src, outLayers)
	if saved != nil {
		a.Vals["output-layer"] = saved
	}
	return ok
}

func transformGeom(g *Geom, ct *CoordTransform) bool {
	if g == nil {
		return true
	}
	ok := true
	g.forEachPt(func(p *Pt) {
		xs, ys := []float64{p.X}, []float64{p.Y}
		var zs []float64
		if g.Z {
			zs = []float64{p.Z}
		}
		r := ct.Transform(xs, ys, zs)
		if !r[0] {
			ok = false
		}
		p.X, p.Y = xs[0], ys[0]
		if zs != nil {
			p.Z = zs[0]
		}
	})
	return ok
}

func runVectorReproject(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	dst, ok := a.parseCRSArg("dst-crs")
	if !ok || dst == nil {
		return false
	}
	var srcOverride *SRS
	if a.IsSet("src-crs") {
		srcOverride, ok = a.parseCRSArg("src-crs")
		if !ok {
			return false
		}
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		var cts []*CoordTransform
		for _, g := range nl.GeomFields {
			s := g.SRS
			if srcOverride != nil {
				s = srcOverride
			}
			if s == nil {
				CPLError(CE_Failure, CPLE_AppDefined, "Layer '%s' has no source CRS. Please specify --src-crs", l.Name)
				return false
			}
			cts = append(cts, NewCoordTransform(s, dst))
			g.SRS = dst
		}
		for _, f := range l.Feats() {
			nf := f.Clone()
			for gi, g := range nf.Geoms {
				if gi < len(cts) && cts[gi] != nil && g != nil {
					transformGeom(g, cts[gi])
				}
			}
			nl.Features = append(nl.Features, nf)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorSwapXY(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		for _, f := range l.Feats() {
			nf := f.Clone()
			for _, g := range nf.Geoms {
				if g != nil {
					g.forEachPt(func(p *Pt) { p.X, p.Y = p.Y, p.X })
				}
			}
			nl.Features = append(nl.Features, nf)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func parseGeomTypeName(s string) (int, bool) {
	u := strings.ToUpper(strings.ReplaceAll(s, " ", ""))
	z, m := false, false
	switch {
	case strings.HasSuffix(u, "ZM"):
		z, m = true, true
		u = u[:len(u)-2]
	case strings.HasSuffix(u, "25D"):
		z = true
		u = u[:len(u)-3]
	case strings.HasSuffix(u, "Z") && u != "TIN" && !strings.HasSuffix(u, "TINZ") || strings.HasSuffix(u, "TINZ"):
		z = true
		u = u[:len(u)-1]
	case strings.HasSuffix(u, "M") && u != "M":
		m = true
		u = u[:len(u)-1]
	}
	for k, v := range wktNames {
		if v == u {
			return makeGeomType(k, z, m), true
		}
	}
	if u == "NONE" {
		return wkbNone, true
	}
	if u == "GEOMETRY" || u == "UNKNOWN" {
		return makeGeomType(wkbUnknown, z, m), true
	}
	return 0, false
}

func forceToMulti(g *Geom) *Geom {
	switch g.T {
	case wkbPoint:
		return &Geom{T: wkbMultiPoint, Z: g.Z, M: g.M, Parts: []*Geom{g}}
	case wkbLineString:
		return &Geom{T: wkbMultiLineString, Z: g.Z, M: g.M, Parts: []*Geom{g}}
	case wkbPolygon:
		return &Geom{T: wkbMultiPolygon, Z: g.Z, M: g.M, Parts: []*Geom{g}}
	case wkbGeometryCollection:
		allPt, allLn, allPg := true, true, true
		for _, p := range g.Parts {
			allPt = allPt && p.T == wkbPoint
			allLn = allLn && p.T == wkbLineString
			allPg = allPg && p.T == wkbPolygon
		}
		if len(g.Parts) > 0 {
			if allPt {
				return &Geom{T: wkbMultiPoint, Z: g.Z, M: g.M, Parts: g.Parts}
			}
			if allLn {
				return &Geom{T: wkbMultiLineString, Z: g.Z, M: g.M, Parts: g.Parts}
			}
			if allPg {
				return &Geom{T: wkbMultiPolygon, Z: g.Z, M: g.M, Parts: g.Parts}
			}
		}
	}
	return g
}

func forceToSingle(g *Geom) *Geom {
	if (g.T == wkbMultiPoint || g.T == wkbMultiLineString || g.T == wkbMultiPolygon || g.T == wkbGeometryCollection) && len(g.Parts) == 1 {
		p := g.Parts[0]
		p.Z, p.M = g.Z, g.M
		return p
	}
	return g
}

// forceGeomType mimics OGRGeometryFactory::forceTo for common cases.
func forceGeomType(g *Geom, t int) (*Geom, bool) {
	flat := geomTypeFlat(t)
	z, m := geomTypeHasZ(t), geomTypeHasM(t)
	var r *Geom
	switch flat {
	case wkbUnknown:
		r = g
	case wkbMultiPoint, wkbMultiLineString, wkbMultiPolygon:
		r = forceToMulti(g)
	case wkbPoint, wkbLineString, wkbPolygon:
		r = forceToSingle(g)
		if flat == wkbPolygon && r.T == wkbLineString && len(r.Pts) >= 4 {
			r = &Geom{T: wkbPolygon, Z: r.Z, M: r.M, Parts: []*Geom{{T: wkbLinearRing, Z: r.Z, M: r.M, Pts: r.Pts}}}
		}
		if flat == wkbLineString && r.T == wkbPolygon && len(r.Parts) == 1 {
			r = &Geom{T: wkbLineString, Z: r.Z, M: r.M, Pts: r.Parts[0].Pts}
		}
	case wkbGeometryCollection:
		if g.T == wkbMultiPoint || g.T == wkbMultiLineString || g.T == wkbMultiPolygon {
			r = &Geom{T: wkbGeometryCollection, Z: g.Z, M: g.M, Parts: g.Parts}
		} else if g.T != wkbGeometryCollection {
			r = &Geom{T: wkbGeometryCollection, Z: g.Z, M: g.M, Parts: []*Geom{g}}
		} else {
			r = g
		}
	default:
		r = g
	}
	if flat != wkbUnknown && r.T != flat {
		return g, false
	}
	if flat != wkbUnknown || t != wkbUnknown {
		if z != r.Z {
			r.SetZ(z)
		}
		if m != r.M {
			r.SetM(m)
		}
	}
	return r, true
}

func runVectorSetGeomType(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		newType := -1
		if a.IsSet("geometry-type") {
			t, ok := parseGeomTypeName(a.Str("geometry-type"))
			if !ok {
				a.ReportError(CPLE_IllegalArg, "Invalid geometry type '%s'", a.Str("geometry-type"))
				return false
			}
			newType = t
		}
		computeType := func(t int) int {
			if newType >= 0 {
				return newType
			}
			flat := geomTypeFlat(t)
			z, m := geomTypeHasZ(t), geomTypeHasM(t)
			if a.Bool("multi") {
				switch flat {
				case wkbPoint:
					flat = wkbMultiPoint
				case wkbLineString:
					flat = wkbMultiLineString
				case wkbPolygon:
					flat = wkbMultiPolygon
				}
			}
			if a.Bool("single") {
				switch flat {
				case wkbMultiPoint:
					flat = wkbPoint
				case wkbMultiLineString:
					flat = wkbLineString
				case wkbMultiPolygon:
					flat = wkbPolygon
				}
			}
			if a.Bool("linear") {
				switch flat {
				case wkbCircularString, wkbCompoundCurve:
					flat = wkbLineString
				case wkbCurvePolygon:
					flat = wkbPolygon
				case wkbMultiCurve:
					flat = wkbMultiLineString
				case wkbMultiSurface:
					flat = wkbMultiPolygon
				}
			}
			switch a.Str("dim") {
			case "XY":
				z, m = false, false
			case "XYZ":
				z, m = true, false
			case "XYM":
				z, m = false, true
			case "XYZM":
				z, m = true, true
			}
			return makeGeomType(flat, z, m)
		}
		if !a.Bool("feature-only") {
			for _, g := range nl.GeomFields {
				g.Type = computeType(g.Type)
			}
		}
		for _, f := range l.Feats() {
			nf := f.Clone()
			skip := false
			if !a.Bool("layer-only") {
				for gi, g := range nf.Geoms {
					if g == nil {
						continue
					}
					t := computeType(g.Type())
					ng, ok := forceGeomType(g, t)
					if !ok && a.Bool("skip") {
						skip = true
					}
					nf.Geoms[gi] = ng
				}
			}
			if !skip {
				nl.Features = append(nl.Features, nf)
			}
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorExplode(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		newType := -1
		if a.IsSet("geometry-type") {
			t, ok := parseGeomTypeName(a.Str("geometry-type"))
			if ok {
				newType = t
			}
		}
		for _, g := range nl.GeomFields {
			if newType >= 0 {
				g.Type = newType
			} else {
				flat := geomTypeFlat(g.Type)
				switch flat {
				case wkbMultiPoint:
					flat = wkbPoint
				case wkbMultiLineString:
					flat = wkbLineString
				case wkbMultiPolygon:
					flat = wkbPolygon
				case wkbGeometryCollection:
					flat = wkbUnknown
				}
				g.Type = makeGeomType(flat, geomTypeHasZ(g.Type), geomTypeHasM(g.Type))
			}
		}
		fid := int64(0)
		for _, f := range l.Feats() {
			g := f.Geom()
			var parts []*Geom
			if g != nil && (g.T == wkbMultiPoint || g.T == wkbMultiLineString || g.T == wkbMultiPolygon || g.T == wkbGeometryCollection || g.T == wkbMultiCurve || g.T == wkbMultiSurface) {
				for _, p := range g.Parts {
					pc := p.Clone()
					pc.Z, pc.M = g.Z, g.M
					parts = append(parts, pc)
				}
			} else {
				parts = []*Geom{g}
			}
			for _, p := range parts {
				nf := f.Clone()
				if len(nf.Geoms) > 0 {
					nf.Geoms[0] = p
					if newType >= 0 && p != nil {
						np, ok := forceGeomType(p, newType)
						if !ok && a.Bool("skip-on-type-mismatch") {
							continue
						}
						nf.Geoms[0] = np
					}
				}
				nf.FID = fid
				fid++
				nl.Features = append(nl.Features, nf)
			}
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func segmentizeGeom(g *Geom, maxLen float64) {
	if g == nil {
		return
	}
	switch g.T {
	case wkbLineString, wkbLinearRing:
		if len(g.Pts) < 2 {
			return
		}
		out := []Pt{g.Pts[0]}
		for i := 1; i < len(g.Pts); i++ {
			a, b := g.Pts[i-1], g.Pts[i]
			d := math.Hypot(b.X-a.X, b.Y-a.Y)
			if d > maxLen {
				n := int(math.Ceil(d/maxLen)) - 1
				for k := 1; k <= n; k++ {
					t := float64(k) / float64(n+1)
					out = append(out, Pt{X: a.X + (b.X-a.X)*t, Y: a.Y + (b.Y-a.Y)*t, Z: a.Z + (b.Z-a.Z)*t, M: a.M + (b.M-a.M)*t})
				}
			}
			out = append(out, b)
		}
		g.Pts = out
	default:
		for _, p := range g.Parts {
			segmentizeGeom(p, maxLen)
		}
	}
}

func runVectorSegmentize(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	maxLen := a.Real("max-length")
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		for _, f := range l.Feats() {
			nf := f.Clone()
			for _, g := range nf.Geoms {
				segmentizeGeom(g, maxLen)
			}
			nl.Features = append(nl.Features, nf)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorRenameLayer(a *Alg) bool {
	src := srcVector(a)
	var outLayers []*Layer
	in := a.Str("input-layer")
	newName := a.Str("output-layer")
	for _, l := range src.Layers {
		nl := cloneLayerSchema(l)
		nl.Features = l.Feats()
		if (in == "" && len(src.Layers) == 1 || l.Name == in) && newName != "" {
			nl.Name = newName
		}
		name := nl.Name
		if a.Bool("lower-case") {
			name = strings.ToLower(name)
		}
		if a.IsSet("max-length") && len(name) > a.Int("max-length") {
			name = name[:a.Int("max-length")]
		}
		nl.Name = name
		outLayers = append(outLayers, nl)
	}
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, src, outLayers)
	a.Vals["output-layer"] = saved
	return ok
}

func parseFieldTypeSpec(s string) (FieldType, FieldSubType, bool) {
	if t, ok := fieldTypeFromName(s); ok {
		return t, OFSTNone, true
	}
	if st, ok := subTypeFromName(s); ok {
		switch st {
		case OFSTBoolean, OFSTInt16:
			return OFTInteger, st, true
		case OFSTFloat32:
			return OFTReal, st, true
		case OFSTJSON, OFSTUUID:
			return OFTString, st, true
		}
	}
	return 0, 0, false
}

func runVectorSetFieldType(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	dt, dst, ok := parseFieldTypeSpec(a.Str("field-type"))
	if !ok {
		a.ReportError(CPLE_IllegalArg, "Invalid target type: %s", a.Str("field-type"))
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		var changed []int
		for i, fd := range nl.Fields {
			match := false
			if a.IsSet("field-name") {
				match = fd.Name == a.Str("field-name")
			} else if a.IsSet("src-field-type") {
				st, sst, _ := parseFieldTypeSpec(a.Str("src-field-type"))
				match = fd.Type == st && (sst == OFSTNone || fd.SubType == sst)
			}
			if match {
				changed = append(changed, i)
			}
		}
		if a.IsSet("field-name") && len(changed) == 0 {
			a.ReportError(CPLE_AppDefined, "Cannot find field '%s' in layer '%s'", a.Str("field-name"), l.Name)
			return false
		}
		srcDefs := make([]*FieldDefn, len(nl.Fields))
		for i := range nl.Fields {
			srcDefs[i] = l.Fields[i]
		}
		for _, i := range changed {
			nl.Fields[i].Type = dt
			nl.Fields[i].SubType = dst
			nl.Fields[i].Width = 0
			nl.Fields[i].Precision = 0
		}
		for _, f := range l.Feats() {
			nf := f.Clone()
			for _, i := range changed {
				nf.Fields[i] = convertFieldValue(srcDefs[i], nl.Fields[i], f.Fields[i])
			}
			nl.Features = append(nl.Features, nf)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorMakePoint(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		xi := l.FieldIndex(a.Str("x"))
		yi := l.FieldIndex(a.Str("y"))
		zi := -1
		if a.IsSet("z") {
			zi = l.FieldIndex(a.Str("z"))
		}
		if xi < 0 {
			a.ReportError(CPLE_AppDefined, "Specified X field name '%s' does not exist", a.Str("x"))
			return false
		}
		if yi < 0 {
			a.ReportError(CPLE_AppDefined, "Specified Y field name '%s' does not exist", a.Str("y"))
			return false
		}
		nl := cloneLayerSchema(l)
		var srs *SRS
		if a.IsSet("dst-crs") {
			srs, _ = a.parseCRSArg("dst-crs")
		}
		gt := wkbPoint
		if zi >= 0 {
			gt = makeGeomType(wkbPoint, true, false)
		}
		nl.GeomFields = []*GeomFieldDefn{{Name: "", Type: gt, SRS: srs, Nullable: true}}
		if a.Bool("keep-fields") == false && false {
		}
		for _, f := range l.Feats() {
			nf := f.Clone()
			nf.Geoms = []*Geom{nil}
			xv, yv := fieldToSQLVal(l.Fields[xi], &f.Fields[xi]), fieldToSQLVal(l.Fields[yi], &f.Fields[yi])
			if xv.kind != 0 && yv.kind != 0 {
				if zi >= 0 {
					nf.Geoms[0] = NewPointZ(xv.num(), yv.num(), fieldToSQLVal(l.Fields[zi], &f.Fields[zi]).num())
				} else {
					nf.Geoms[0] = NewPoint(xv.num(), yv.num())
				}
			}
			nl.Features = append(nl.Features, nf)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorConcat(a *Alg) bool {
	var srcs []*Dataset
	for _, n := range a.StrList("input") {
		ds := OpenDataset(n, OF_VECTOR, a.StrList("input-format"), a.StrList("open-option"), true)
		if ds == nil {
			return false
		}
		srcs = append(srcs, ds)
	}
	mode := a.Str("mode")
	var dst *SRS
	if a.IsSet("dst-crs") {
		dst, _ = a.parseCRSArg("dst-crs")
	}
	var outLayers []*Layer
	byName := map[string]*Layer{}
	for _, ds := range srcs {
		for _, l := range ds.Layers {
			key := l.Name
			if mode == "single" {
				key = "merged"
				if a.IsSet("output-layer") {
					key = a.Str("output-layer")
				}
			} else if mode == "stack" {
				key = l.Name + "\x00" + ds.Name
			}
			ol := byName[key]
			if ol == nil {
				ol = cloneLayerSchema(l)
				if mode == "single" {
					ol.Name = key
				}
				if dst != nil {
					for _, g := range ol.GeomFields {
						g.SRS = dst
					}
				}
				byName[key] = ol
				outLayers = append(outLayers, ol)
			} else {
				for _, fd := range l.Fields {
					if ol.FieldIndex(fd.Name) < 0 {
						ol.AddField(fd.Clone())
					}
				}
				if len(ol.GeomFields) > 0 && len(l.GeomFields) > 0 && ol.GeomFields[0].Type != l.GeomFields[0].Type {
					ol.GeomFields[0].Type = wkbUnknown
				}
			}
			var ct *CoordTransform
			if dst != nil && l.SRS() != nil {
				ct = NewCoordTransform(l.SRS(), dst)
			}
			for _, f := range l.Feats() {
				nf := ol.NewFeature()
				for i, fd := range l.Fields {
					oi := ol.FieldIndex(fd.Name)
					if oi >= 0 {
						nf.Fields[oi] = convertFieldValue(fd, ol.Fields[oi], f.Fields[i])
					}
				}
				if len(f.Geoms) > 0 && len(nf.Geoms) > 0 && f.Geoms[0] != nil {
					nf.Geoms[0] = f.Geoms[0].Clone()
					if ct != nil {
						transformGeom(nf.Geoms[0], ct)
					}
				}
				ol.AddFeature(nf)
			}
		}
	}
	for _, l := range outLayers {
		l.loaded = true
	}
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, srcs[0], outLayers)
	a.Vals["output-layer"] = saved
	return ok
}
