cd /workspace/gdalgo && cat > dem.go <<'EOF'
package main

import (
	"math"
	"strings"
)

func init() {
	for _, n := range []string{"hillshade", "slope", "aspect", "tri", "tpi", "roughness"} {
		name := n
		registerCommand("raster "+name, func(a *Alg) bool { return runDEM(a, name) })
	}
}

type demParams struct {
	alg        string
	invEW      float64
	invNS      float64
	zfactor    float64
	xscale     float64
	yscale     float64
	sinAlt     float64
	cosAzCosAltZ float64
	sinAzCosAltZ float64
	squareZ    float64
	az, alt    float64
	percent    bool
	azimuthConv bool
	zeroFlat   bool
	wilson     bool
	zt         bool
	variant    string
}

func horn(w *[9]float64) (float64, float64) {
	x := (w[0] + w[3] + w[3] + w[6]) - (w[2] + w[5] + w[5] + w[8])
	y := (w[6] + w[7] + w[7] + w[8]) - (w[0] + w[1] + w[1] + w[2])
	return x, y
}

func demCompute(p *demParams, w *[9]float64, nd float64) float64 {
	const d2r = math.Pi / 180
	switch p.alg {
	case "hillshade":
		var x, y float64
		if p.zt {
			x = (w[3] - w[5]) * p.invEW * 4
			y = (w[7] - w[1]) * p.invNS * 4
		} else {
			hx, hy := horn(w)
			x = hx * p.invEW
			y = hy * p.invNS
		}
		xxyy := x*x + y*y
		switch p.variant {
		case "combined":
			slope := math.Atan(math.Sqrt(xxyy) * p.zfactor)
			_ = slope
			cang := (p.sinAlt - (y*p.cosAzCosAltZ - x*p.sinAzCosAltZ)) / math.Sqrt(1+p.squareZ*xxyy)
			cang = math.Acos(math.Max(-1, math.Min(1, cang)))
			cang = 1 - cang*math.Atan(math.Sqrt(p.squareZ*xxyy))/(math.Pi/2)/(math.Pi/2)
			if cang <= 0 {
				return 1
			}
			return 1 + 254*cang
		case "multidirectional":
			zsq := p.squareZ * xxyy
			sinAlt := math.Sin(p.alt * d2r)
			cosAltZ := math.Cos(p.alt*d2r) * p.zfactor
			val225 := sinAlt - (y*math.Cos(225*d2r)*cosAltZ - x*math.Sin(225*d2r)*cosAltZ)
			_ = val225
			aspect := math.Atan2(y, x)
			w225 := 0.5 * (1 - math.Cos(2*(aspect-225*d2r)))
			w270 := 0.5 * (1 - math.Cos(2*(aspect-270*d2r)))
			w315 := 0.5 * (1 - math.Cos(2*(aspect-315*d2r)))
			w360 := 0.5 * (1 - math.Cos(2*(aspect-360*d2r)))
			f := func(az float64) float64 {
				return 1 - (y*math.Cos(az*d2r)-x*math.Sin(az*d2r))*cosAltZ/sinAlt
			}
			cang := (w225*f(225) + w270*f(270) + w315*f(315) + w360*f(360)) * sinAlt / math.Sqrt(1+zsq) / 2
			if cang <= 0 {
				return 1
			}
			return 1 + 254*cang
		}
		cang := (p.sinAlt - (y*p.cosAzCosAltZ - x*p.sinAzCosAltZ)) / math.Sqrt(1+p.squareZ*xxyy)
		if cang <= 0 {
			return 1
		}
		return 1 + 254*cang
	case "slope":
		var dx, dy float64
		if p.zt {
			dx = (w[3] - w[5]) * p.invEW * 4
			dy = (w[7] - w[1]) * p.invNS * 4
		} else {
			hx, hy := horn(w)
			dx = hx * p.invEW
			dy = hy * p.invNS
		}
		dx /= p.xscale
		dy /= p.yscale
		key := dx*dx + dy*dy
		if p.percent {
			return 100 * math.Sqrt(key)
		}
		return math.Atan(math.Sqrt(key)) / d2r
	case "aspect":
		var dx, dy float64
		if p.zt {
			dx = w[5] - w[3]
			dy = w[7] - w[1]
		} else {
			dx = (w[2] + w[5] + w[5] + w[8]) - (w[0] + w[3] + w[3] + w[6])
			dy = (w[6] + w[7] + w[7] + w[8]) - (w[0] + w[1] + w[1] + w[2])
		}
		asp := math.Atan2(dy, -dx) / d2r
		if dx == 0 && dy == 0 {
			if p.zeroFlat {
				return 0
			}
			return nd
		}
		if p.azimuthConv {
			if asp > 90 {
				asp = 450 - asp
			} else {
				asp = 90 - asp
			}
		} else if asp < 0 {
			asp += 360
		}
		if asp == 360 {
			asp = 0
		}
		return asp
	case "tri":
		if p.wilson {
			s := 0.0
			for k := 0; k < 9; k++ {
				if k != 4 {
					s += math.Abs(w[k] - w[4])
				}
			}
			return s / 8
		}
		s := 0.0
		for k := 0; k < 9; k++ {
			if k != 4 {
				d := w[k] - w[4]
				s += d * d
			}
		}
		return math.Sqrt(s)
	case "tpi":
		s := 0.0
		for k := 0; k < 9; k++ {
			if k != 4 {
				s += w[k]
			}
		}
		return w[4] - s/8
	case "roughness":
		mn, mx := w[0], w[0]
		for k := 1; k < 9; k++ {
			mn = math.Min(mn, w[k])
			mx = math.Max(mx, w[k])
		}
		return mx - mn
	}
	return nd
}

func runDEM(a *Alg, alg string) bool {
	src := srcRaster(a)
	bi := 1
	if a.IsSet("band") {
		bi = a.Int("band")
	}
	if bi < 1 || bi > len(src.Bands) {
		a.ReportError(CPLE_IllegalArg, "Invalid band number: %d", bi)
		return false
	}
	sb := src.Bands[bi-1]
	W, H := src.XSize, src.YSize
	data := sb.Data()
	hasND := sb.HasNoData
	snd := sb.NoData
	ewres, nsres := src.GT[1], src.GT[5]
	p := &demParams{alg: alg, zfactor: 1, xscale: 1, yscale: 1}
	if a.IsSet("zfactor") {
		p.zfactor = a.Real("zfactor")
	}
	if a.IsSet("xscale") {
		p.xscale = a.Real("xscale")
	}
	if a.IsSet("yscale") {
		p.yscale = a.Real("yscale")
	}
	if !a.IsSet("xscale") && !a.IsSet("yscale") && src.SRS != nil && src.SRS.IsGeographic() && (alg == "hillshade" || alg == "slope") {
		// scale computed from latitude at center
		lat := src.GT[3] + src.GT[5]*float64(H)/2
		p.yscale = 6378137 * math.Pi / 180
		p.xscale = p.yscale * math.Cos(lat*math.Pi/180)
	}
	p.zt = strings.EqualFold(a.Str("gradient-alg"), "ZevenbergenThorne")
	if alg == "hillshade" {
		p.az = 315
		p.alt = 45
		if a.IsSet("azimuth") {
			p.az = a.Real("azimuth")
		}
		if a.IsSet("altitude") {
			p.alt = a.Real("altitude")
		}
		p.variant = a.Str("variant")
		const d2r = math.Pi / 180
		p.invEW = 1 / (ewres * 8 * p.xscale)
		p.invNS = 1 / (nsres * 8 * p.yscale)
		if p.zt {
			p.invEW = 1 / (ewres * 8 * p.xscale)
			p.invNS = 1 / (nsres * 8 * p.yscale)
		}
		azR := p.az * d2r
		altR := p.alt * d2r
		p.sinAlt = math.Sin(altR)
		p.cosAzCosAltZ = math.Cos(azR) * math.Cos(altR) * p.zfactor
		p.sinAzCosAltZ = math.Sin(azR) * math.Cos(altR) * p.zfactor
		p.squareZ = p.zfactor * p.zfactor
	} else {
		p.invEW = 1 / (ewres * 8)
		p.invNS = 1 / (nsres * 8)
	}
	if alg == "slope" {
		p.percent = strings.EqualFold(a.Str("unit"), "percent")
		if p.zt {
			p.invEW = 1 / (ewres * 8)
			p.invNS = 1 / (nsres * 8)
		}
	}
	p.azimuthConv = !strings.EqualFold(a.Str("convention"), "trigonometric-angle")
	p.zeroFlat = a.Bool("zero-for-flat")
	p.wilson = strings.EqualFold(a.Str("algorithm"), "Wilson")
	computeEdges := !a.Bool("no-edges")
	dt := GDT_Float32
	dnd := -9999.0
	if alg == "hillshade" {
		dt = GDT_Byte
		dnd = 0
	}
	out := make([]float64, W*H)
	for i := range out {
		out[i] = dnd
	}
	isND := func(v float64) bool {
		if !hasND {
			return false
		}
		if math.IsNaN(snd) {
			return math.IsNaN(v)
		}
		return v == snd || (sb.DataType == GDT_Float32 && float32(v) == float32(snd))
	}
	get := func(x, y int) float64 { return data[y*W+x] }
	interp := func(a, b float64) float64 {
		if isND(a) || isND(b) {
			return snd
		}
		return 2*a - b
	}
	compute := func(w *[9]float64) float64 {
		if isND(w[4]) {
			return dnd
		}
		if hasND {
			for k := 0; k < 9; k++ {
				if isND(w[k]) {
					if computeEdges {
						w[k] = w[4]
					} else {
						return dnd
					}
				}
			}
		}
		return demCompute(p, w, dnd)
	}
	var w [9]float64
	if H < 3 || W < 3 {
		if !computeEdges {
			goto done
		}
	}
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			interior := y > 0 && y < H-1 && x > 0 && x < W-1
			if !interior && !computeEdges {
				continue
			}
			jmin, jmax := x-1, x+1
			if y == 0 || y == H-1 {
				if x == 0 {
					jmin = x
				}
				if x == W-1 {
					jmax = x
				}
				if H == 1 {
					continue
				}
				if y == 0 {
					w[0] = interp(get(jmin, 0), get(jmin, 1))
					w[1] = interp(get(x, 0), get(x, 1))
					w[2] = interp(get(jmax, 0), get(jmax, 1))
					w[3], w[4], w[5] = get(jmin, 0), get(x, 0), get(jmax, 0)
					w[6], w[7], w[8] = get(jmin, 1), get(x, 1), get(jmax, 1)
				} else {
					w[0], w[1], w[2] = get(jmin, y-1), get(x, y-1), get(jmax, y-1)
					w[3], w[4], w[5] = get(jmin, y), get(x, y), get(jmax, y)
					w[6] = interp(get(jmin, y), get(jmin, y-1))
					w[7] = interp(get(x, y), get(x, y-1))
					w[8] = interp(get(jmax, y), get(jmax, y-1))
				}
			} else if x == 0 {
				if W == 1 {
					continue
				}
				for r := 0; r < 3; r++ {
					yy := y - 1 + r
					w[r*3] = interp(get(0, yy), get(1, yy))
					w[r*3+1] = get(0, yy)
					w[r*3+2] = get(1, yy)
				}
			} else if x == W-1 {
				for r := 0; r < 3; r++ {
					yy := y - 1 + r
					w[r*3] = get(x-1, yy)
					w[r*3+1] = get(x, yy)
					w[r*3+2] = interp(get(x, yy), get(x-1, yy))
				}
			} else {
				for r := 0; r < 3; r++ {
					for c := 0; c < 3; c++ {
						w[r*3+c] = get(x-1+c, y-1+r)
					}
				}
			}
			v := compute(&w)
			if dt == GDT_Float32 {
				v = float64(float32(v))
			}
			out[y*W+x] = v
		}
	}
done:
	ds := cloneRasterStructure(src, W, H)
	ds.MD = NewMetadata()
	b := ds.AddBand(dt)
	b.data = convertDataToType(out, dt)
	b.loaded = true
	b.HasNoData = true
	b.NoData = dnd
	b.ColorInterp = GCI_GrayIndex
	return writeRasterResult(a, ds)
}
