{"command":"cd /workspace/gdalgo && cat > warp.go <<'EOF'
package main

import (
	"math"
	"sort"
	"strings"
)

func init() {
	registerCommand("raster reproject", runRasterReproject)
}

type genTransformer struct {
	srcGT, srcInvGT [6]float64
	ct             *CoordTransform // src -> dst (nil if identity)
}

func invGeoTransform(gt [6]float64) ([6]float64, bool) {
	det := gt[1]*gt[5] - gt[2]*gt[4]
	if det == 0 {
		return [6]float64{}, false
	}
	inv := 1 / det
	var r [6]float64
	r[0] = (gt[2]*gt[3] - gt[0]*gt[5]) * inv
	r[1] = gt[5] * inv
	r[4] = -gt[4] * inv
	r[3] = (-gt[1]*gt[3] + gt[0]*gt[4]) * inv
	r[2] = -gt[2] * inv
	r[5] = gt[1] * inv
	return r, true
}

func applyGT(gt [6]float64, x, y float64) (float64, float64) {
	return gt[0] + gt[1]*x + gt[2]*y, gt[3] + gt[4]*x + gt[5]*y
}

// suggestedWarpOutput mimics GDALSuggestedWarpOutput2.
func suggestedWarpOutput(src *Dataset, ct *CoordTransform) ([6]float64, int, int, Envelope, bool) {
	nx, ny := float64(src.XSize), float64(src.YSize)
	steps := 20
	var px, py []float64
	for i := 0; i <= steps; i++ {
		r := float64(i) / float64(steps)
		if i == steps {
			r = 1
		}
		px = append(px, r*nx)
		py = append(py, 0)
		px = append(px, r*nx)
		py = append(py, ny)
		px = append(px, 0)
		py = append(py, r*ny)
		px = append(px, nx)
		py = append(py, r*ny)
	}
	xs := make([]float64, len(px))
	ys := make([]float64, len(py))
	for i := range px {
		xs[i], ys[i] = applyGT(src.GT, px[i], py[i])
	}
	ok := make([]bool, len(xs))
	if ct != nil {
		ok = ct.Transform(xs, ys, nil)
	} else {
		for i := range ok {
			ok[i] = true
		}
	}
	env := EmptyEnvelope()
	any := false
	for i := range xs {
		if ok[i] {
			env.MergePt(xs[i], ys[i])
			any = true
		}
	}
	if !any {
		return [6]float64{}, 0, 0, env, false
	}
	// diagonal between UL (index 0) and LR (last)
	last := len(xs) - 1
	var diag float64
	if ok[0] && ok[last] {
		diag = math.Hypot(xs[0]-xs[last], ys[0]-ys[last])
	} else {
		diag = math.Hypot(env.MaxX-env.MinX, env.MaxY-env.MinY)
	}
	res := diag / math.Sqrt(nx*nx+ny*ny)
	w := int((env.MaxX-env.MinX)/res + 0.5)
	h := int((env.MaxY-env.MinY)/res + 0.5)
	if w < 1 {
		w = 1
	}
	if h < 1 {
		h = 1
	}
	env.MaxX = env.MinX + float64(w)*res
	env.MinY = env.MaxY - float64(h)*res
	gt := [6]float64{env.MinX, res, 0, env.MaxY, 0, -res}
	return gt, w, h, env, true
}

func runRasterReproject(a *Alg) bool {
	src := srcRaster(a)
	srcSRS := src.SRS
	if a.IsSet("src-crs") {
		s, ok := a.parseCRSArg("src-crs")
		if !ok {
			return false
		}
		srcSRS = s
	}
	var dstSRS *SRS
	var like *Dataset
	if v := a.V("like"); len(v.DSs) > 0 {
		like = v.DSs[0]
	}
	if a.IsSet("dst-crs") {
		s, ok := a.parseCRSArg("dst-crs")
		if !ok {
			return false
		}
		dstSRS = s
	} else if like != nil {
		dstSRS = like.SRS
	} else {
		dstSRS = srcSRS
	}
	if !src.HasGT {
		CPLError(CE_Failure, CPLE_AppDefined, "Unable to compute a transformation between pixel/line and georeferenced coordinates for %s.", src.Name)
		return false
	}
	var ct *CoordTransform
	if srcSRS != nil && dstSRS != nil && !srcSRS.IsSame(dstSRS) {
		ct = NewCoordTransform(srcSRS, dstSRS)
		if ct == nil {
			CPLError(CE_Failure, CPLE_AppDefined, "Cannot find coordinate operations")
			return false
		}
	} else if srcSRS != nil && dstSRS != nil && srcSRS.IsSame(dstSRS) && !sameMapping(srcSRS, dstSRS) {
		ct = NewCoordTransform(srcSRS, dstSRS)
	}
	gt, w, h, env, ok := suggestedWarpOutput(src, ct)
	if !ok {
		CPLError(CE_Failure, CPLE_AppDefined, "Cannot compute bounding box of projected coordinates.")
		return false
	}
	if like != nil {
		gt, w, h = like.GT, like.XSize, like.YSize
	} else {
		if a.IsSet("bbox") {
			bb := a.RealList("bbox")
			env = Envelope{bb[0], bb[1], bb[2], bb[3]}
		}
		if a.IsSet("resolution") {
			r := a.RealList("resolution")
			w = int((env.MaxX-env.MinX)/r[0] + 0.5)
			h = int((env.MaxY-env.MinY)/r[1] + 0.5)
			if !a.IsSet("bbox") {
				w = int(math.Round((env.MaxX - env.MinX) / r[0]))
				h = int(math.Round((env.MaxY - env.MinY) / r[1]))
			}
			gt = [6]float64{env.MinX, r[0], 0, env.MaxY, 0, -r[1]}
		} else if a.IsSet("size") {
			sz := a.IntList("size")
			w, h = sz[0], sz[1]
			gt = [6]float64{env.MinX, (env.MaxX - env.MinX) / float64(w), 0, env.MaxY, 0, -(env.MaxY - env.MinY) / float64(h)}
		} else if a.IsSet("bbox") {
			res := gt[1]
			w = int((env.MaxX-env.MinX)/res + 0.5)
			h = int((env.MaxY-env.MinY)/res + 0.5)
			gt = [6]float64{env.MinX, (env.MaxX - env.MinX) / float64(w), 0, env.MaxY, 0, -(env.MaxY - env.MinY) / float64(h)}
		}
	}
	ds := warpDataset(src, ct, gt, w, h, a.Str("resampling"))
	ds.SRS = dstSRS
	return writeRasterResult(a, ds)
}

func sameMapping(a, b *SRS) bool {
	if len(a.mapping) != len(b.mapping) {
		return false
	}
	for i := range a.mapping {
		if a.mapping[i] != b.mapping[i] {
			return false
		}
	}
	return true
}

// warpDataset resamples src into a new grid.
func warpDataset(src *Dataset, ct *CoordTransform, gt [6]float64, w, h int, resampling string) *Dataset {
	ds := cloneRasterStructure(src, w, h)
	ds.GT = gt
	ds.HasGT = true
	ds.MD = NewMetadata()
	if v, ok := src.MD.Get("", "AREA_OR_POINT"); ok {
		ds.MD.Set("", "AREA_OR_POINT", v)
	}
	srcInv, _ := invGeoTransform(src.GT)
	// compute source pixel coordinates for each dst pixel center
	n := w * h
	spx := make([]float64, n)
	spy := make([]float64, n)
	okv := make([]bool, n)
	xs := make([]float64, w)
	ys := make([]float64, w)
	for j := 0; j < h; j++ {
		for i := 0; i < w; i++ {
			xs[i], ys[i] = applyGT(gt, float64(i)+0.5, float64(j)+0.5)
		}
		var oks []bool
		if ct != nil {
			oks = ct.Inverse(xs, ys, nil)
		} else {
			oks = make([]bool, w)
			for i := range oks {
				oks[i] = true
			}
		}
		for i := 0; i < w; i++ {
			k := j*w + i
			if !oks[i] {
				continue
			}
			spx[k], spy[k] = applyGT(srcInv, xs[i], ys[i])
			okv[k] = true
		}
	}
	// scale (for downsampling kernels)
	xscale, yscale := 1.0, 1.0
	if w > 1 && h > 1 {
		dx := math.Abs(spx[w-1+w*(h/2)] - spx[w*(h/2)])
		if dx > 0 {
			xscale = float64(w-1) / dx
		}
		dy := math.Abs(spy[(h-1)*w+w/2] - spy[w/2])
		if dy > 0 {
			yscale = float64(h-1) / dy
		}
	}
	if xscale > 1 {
		xscale = 1
	}
	if yscale > 1 {
		yscale = 1
	}
	resampling = strings.ToLower(resampling)
	for _, sb := range src.Bands {
		sd := sb.Data()
		valid := sb.validMask()
		out := make([]float64, n)
		fill := 0.0
		if sb.HasNoData {
			fill = sb.NoData
		}
		sw, sh := src.XSize, src.YSize
		for k := 0; k < n; k++ {
			out[k] = fill
			if !okv[k] {
				continue
			}
			x, y := spx[k], spy[k]
			if x < 0 || y < 0 || x >= float64(sw) || y >= float64(sh) {
				if resampling == "nearest" || resampling == "" {
					continue
				}
				if x < -0.5 || y < -0.5 || x > float64(sw)+0.5 || y > float64(sh)+0.5 {
					continue
				}
			}
			v, ok := resamplePoint(sd, valid, sw, sh, x, y, resampling, xscale, yscale)
			if ok {
				out[k] = clampRound(sb.DataType, v)
			}
		}
		b := newBandFrom(ds, sb, sb.DataType, out)
		removeStatsMD(b)
		b.BlockX, b.BlockY = w, 1
	}
	return ds
}

func cubicKernel(x float64) float64 {
	x = math.Abs(x)
	a := -0.5
	if x <= 1 {
		return ((a+2)*x-(a+3))*x*x + 1
	}
	if x < 2 {
		return ((a*x-5*a)*x+8*a)*x - 4*a
	}
	return 0
}

func resamplePoint(sd []float64, valid []bool, sw, sh int, x, y float64, alg string, xscale, yscale float64) (float64, bool) {
	get := func(i, j int) (float64, bool) {
		if i < 0 || j < 0 || i >= sw || j >= sh {
			return 0, false
		}
		k := j*sw + i
		return sd[k], valid[k]
	}
	switch alg {
	case "bilinear", "cubic", "cubicspline", "lanczos":
		radius := 1.0
		kern := func(t float64) float64 { return math.Max(0, 1-math.Abs(t)) }
		if alg == "cubic" {
			radius = 2
			kern = cubicKernel
		} else if alg == "cubicspline" {
			radius = 2
			kern = func(t float64) float64 {
				t = math.Abs(t)
				if t < 1 {
					return (3*t*t*t - 6*t*t + 4) / 6
				}
				if t < 2 {
					return (2 - t) * (2 - t) * (2 - t) / 6
				}
				return 0
			}
		} else if alg == "lanczos" {
			radius = 3
			kern = func(t float64) float64 {
				if t == 0 {
					return 1
				}
				if math.Abs(t) >= 3 {
					return 0
				}
				pt := math.Pi * t
				return 3 * math.Sin(pt) * math.Sin(pt/3) / (pt * pt)
			}
		}
		fx := x - 0.5
		fy := y - 0.5
		rx := radius / xscale
		ry := radius / yscale
		x0 := int(math.Floor(fx - rx + 1))
		x1 := int(math.Floor(fx + rx))
		y0 := int(math.Floor(fy - ry + 1))
		y1 := int(math.Floor(fy + ry))
		sum, wsum := 0.0, 0.0
		for j := y0; j <= y1; j++ {
			wy := kern((float64(j) - fy) * yscale)
			if wy == 0 {
				continue
			}
			for i := x0; i <= x1; i++ {
				wx := kern((float64(i) - fx) * xscale)
				if wx == 0 {
					continue
				}
				v, ok := get(i, j)
				if !ok {
					continue
				}
				sum += v * wx * wy
				wsum += wx * wy
			}
		}
		if wsum == 0 {
			return 0, false
		}
		return sum / wsum, true
	case "average", "rms", "mode", "min", "max", "med", "q1", "q3", "sum":
		hx := 0.5 / xscale
		hy := 0.5 / yscale
		x0 := int(math.Floor(x - hx + 1e-9))
		x1 := int(math.Ceil(x + hx - 1e-9))
		y0 := int(math.Floor(y - hy + 1e-9))
		y1 := int(math.Ceil(y + hy - 1e-9))
		var vals []float64
		for j := y0; j < y1; j++ {
			for i := x0; i < x1; i++ {
				v, ok := get(i, j)
				if ok {
					vals = append(vals, v)
				}
			}
		}
		if len(vals) == 0 {
			return 0, false
		}
		switch alg {
		case "average":
			s := 0.0
			for _, v := range vals {
				s += v
			}
			return s / float64(len(vals)), true
		case "rms":
			s := 0.0
			for _, v := range vals {
				s += v * v
			}
			return math.Sqrt(s / float64(len(vals))), true
		case "sum":
			s := 0.0
			for _, v := range vals {
				s += v
			}
			return s, true
		case "min":
			m := vals[0]
			for _, v := range vals {
				m = math.Min(m, v)
			}
			return m, true
		case "max":
			m := vals[0]
			for _, v := range vals {
				m = math.Max(m, v)
			}
			return m, true
		case "mode":
			counts := map[float64]int{}
			best, bc := 0.0, 0
			for _, v := range vals {
				counts[v]++
				if counts[v] > bc {
					best, bc = v, counts[v]
				}
			}
			return best, true
		default:
			sort.Float64s(vals)
			q := 0.5
			if alg == "q1" {
				q = 0.25
			} else if alg == "q3" {
				q = 0.75
			}
			return vals[int(q*float64(len(vals)-1)+0.5)], true
		}
	}
	// nearest
	i := int(math.Floor(x))
	j := int(math.Floor(y))
	return get(i, j)
}
