{"command":"cd /workspace/gdalgo && cat > pipeline.go <<'EOF'
package main

import (
	"strings"
)

func init() {
	specialLeaf["raster pipeline"] = func(def *AlgDef, path []string, args []string) int { return runPipeline(def, "raster", args) }
	specialLeaf["vector pipeline"] = func(def *AlgDef, path []string, args []string) int { return runPipeline(def, "vector", args) }
	specialLeaf["pipeline"] = func(def *AlgDef, path []string, args []string) int { return runPipeline(def, "", args) }
}

// pipeline capture state
var pipelineCapture bool
var pipelineCaptured *Dataset

type stepSection struct {
	name    string
	text    string
	isVector bool
}

func parseStepSections(help string) []stepSection {
	var res []stepSection
	lines := strings.Split(help, "\n")
	for i := 0; i < len(lines); i++ {
		l := lines[i]
		if strings.HasPrefix(l, "* ") && i+1 < len(lines) && strings.HasPrefix(lines[i+1], "---") {
			name := strings.Fields(l[2:])[0]
			j := i + 2
			for j < len(lines) && !(strings.HasPrefix(lines[j], "* ") && j+1 < len(lines) && strings.HasPrefix(lines[j+1], "---")) {
				j++
			}
			text := strings.Join(lines[i:j], "\n")
			res = append(res, stepSection{name: name, text: text, isVector: strings.Contains(text, "vector")})
			i = j - 1
		}
	}
	return res
}

func parseStepHelpOptions(text string) []helpOpt {
	var res []helpOpt
	section := ""
	for _, l := range strings.Split(text, "\n") {
		if strings.HasSuffix(l, ":") && !strings.HasPrefix(l, " ") {
			section = l
			continue
		}
		if !strings.HasPrefix(l, "  -") {
			continue
		}
		rest := l[2:]
		k := strings.Index(rest, "  ")
		optstr := rest
		if k >= 0 {
			optstr = rest[:k]
		}
		parts := strings.Split(optstr, ", ")
		ho := helpOpt{section: section}
		for i, p := range parts {
			if i == len(parts)-1 {
				if sp := strings.IndexByte(p, ' '); sp >= 0 {
					ho.metavar = p[sp+1:]
					p = p[:sp]
				}
			}
			ho.names = append(ho.names, p)
		}
		res = append(res, ho)
	}
	return res
}

var stepDefCache = map[string]*AlgDef{}

// stepDef builds the AlgDef for a pipeline step.
func stepDef(kind, name string, pipeDef *AlgDef, isVector bool) *AlgDef {
	key := kind + "/" + name
	if isVector {
		key += "/v"
	}
	if d, ok := stepDefCache[key]; ok {
		return d
	}
	var node *JValue
	if pa := pipeDef.Node.Get("pipeline_algorithms"); pa != nil {
		for _, n := range pa.Arr {
			if n.Get("name").Str() == name {
				full := n.Get("full_path")
				isV := full != nil && len(full.Arr) > 1 && full.Arr[1].Str() == "vector"
				if kind == "" && isV != isVector && (name == "read" || name == "write" || name == "info") {
					continue
				}
				node = n
				break
			}
		}
	}
	if node == nil {
		return nil
	}
	d := &AlgDef{Name: name, Node: node, ByLong: map[string]*ArgDef{}, ByShort: map[string]*ArgDef{}}
	for _, sec := range []string{"input_arguments", "output_arguments", "input_output_arguments"} {
		if node.Get(sec) == nil {
			continue
		}
		for _, a := range node.Get(sec).Arr {
			d.Args = append(d.Args, argDefFromJSON(a, sec))
		}
	}
	d.Args = append(d.Args, commonHiddenArgs()...)
	var section string
	for _, s := range parseStepSections(pipeDef.Help) {
		if s.name == name && (kind != "" || s.isVector == isVector || (name != "read" && name != "write" && name != "info")) {
			section = s.text
			break
		}
	}
	d.Help = section
	// names from section
	hopts := parseStepHelpOptions(section)
	byName := map[string]*ArgDef{}
	for _, a := range d.Args {
		byName[a.Name] = a
	}
	for _, ho := range hopts {
		var target *ArgDef
		for _, n := range ho.names {
			if strings.HasPrefix(n, "--") {
				if a, ok := byName[n[2:]]; ok {
					target = a
					break
				}
			}
		}
		if target == nil {
			continue
		}
		for _, n := range ho.names {
			if strings.HasPrefix(n, "--") {
				if n[2:] != target.Name {
					target.Aliases = append(target.Aliases, n[2:])
				}
			} else if strings.HasPrefix(n, "-") {
				target.Short = n[1:]
			}
		}
		if ho.metavar != "" && target.Metavar == "" {
			target.Metavar = ho.metavar
		}
		if ho.section == "Positional arguments:" {
			target.Positional = true
			d.Positionals = append(d.Positionals, target)
		}
	}
	for _, a := range d.Args {
		if a.Name == "output-string" || a.Name == "return-code" {
			continue
		}
		d.ByLong[a.Name] = a
		for _, al := range a.Aliases {
			d.ByLong[al] = a
		}
		if a.Short != "" {
			d.ByShort[a.Short] = a
		}
	}
	d.Path = []string{kind, name}
	stepDefCache[key] = d
	return d
}

func splitPipelineArgs(args []string) []string {
	if len(args) == 1 && strings.Contains(args[0], " ") {
		return tokenizeOptLine(args[0])
	}
	return args
}

func runPipeline(def *AlgDef, kind string, args []string) int {
	label := def.PathStr
	usage := def.shortUsage()
	// leading options
	i := 0
	quiet := false
	for i < len(args) && args[i] != "!" && strings.HasPrefix(args[i], "-") {
		switch args[i] {
		case "-h", "--help":
			for k := 0; k < 4 && kind != "vector"; k++ {
				nztmWarning()
			}
			out(def.Help)
			return 0
		case "--json-usage":
			if kind != "vector" {
				nztmWarning()
			}
			out(def.jsonUsage())
			return 0
		case "-q", "--quiet":
			quiet = true
		case "--progress":
		case "--skip-errors":
		default:
			CPLError(CE_Failure, CPLE_IllegalArg, "pipeline: Option '%s' is unknown.", args[i])
			printErrStr(usage)
			return 1
		}
		i++
	}
	_ = label
	rest := splitPipelineArgs(args[i:])
	var steps [][]string
	cur := []string{}
	for _, t := range rest {
		if t == "!" {
			if len(cur) > 0 {
				steps = append(steps, cur)
			}
			cur = []string{}
			continue
		}
		cur = append(cur, t)
	}
	if len(cur) > 0 {
		steps = append(steps, cur)
	}
	for _, st := range steps {
		for _, t := range st {
			if t == "--help" || t == "-h" {
				for k := 0; k < 4 && kind != "vector"; k++ {
					nztmWarning()
				}
				out(def.Help)
				return 0
			}
		}
	}
	if len(steps) < 2 {
		CPLError(CE_Failure, CPLE_AppDefined, "pipeline: At least 2 steps must be provided")
		printErrStr(usage)
		return 1
	}
	if quiet {
		progressEnabled = false
	}
	// determine first-step dataset type for generic pipeline
	isVector := kind == "vector"
	if kind == "" && steps[0][0] == "read" && len(steps[0]) > 1 {
		for _, t := range steps[0][1:] {
			if !strings.HasPrefix(t, "-") {
				ds := OpenDataset(t, OF_RASTER|OF_VECTOR, nil, nil, false)
				if ds != nil && len(ds.Bands) == 0 {
					isVector = true
				}
				break
			}
		}
	}
	effKind := kind
	if effKind == "" {
		if isVector {
			effKind = "vector"
		} else {
			effKind = "raster"
		}
	}
	firstOK := map[string]bool{"read": true, "calc": true, "concat": true, "create": true, "mosaic": true, "stack": true}
	lastOK := map[string]bool{"write": true, "compare": true, "external": true, "info": true, "tee": true, "tile": true, "update": true}
	var algs []*Alg
	for si, st := range steps {
		name := st[0]
		sd := stepDef(kind, name, def, isVector)
		if sd == nil {
			CPLError(CE_Failure, CPLE_AppDefined, "pipeline: unknown step name: %s", name)
			printErrStr(usage)
			return 1
		}
		if si == 0 && !firstOK[name] {
			CPLError(CE_Failure, CPLE_AppDefined, "pipeline: First step should be 'read', 'calc', 'concat', 'create', 'mosaic' or 'stack'")
			printErrStr(usage)
			return 1
		}
		alg := newAlg(sd)
		if !alg.ParseCommandLine(st[1:]) {
			if shouldPrintUsageAfterError() {
				printErrStr(usage)
			}
			return 1
		}
		algs = append(algs, alg)
	}
	lastName := steps[len(steps)-1][0]
	if !lastOK[lastName] {
		nztmWarning()
		CPLError(CE_Failure, CPLE_AppDefined, "pipeline: Last step should be 'write', 'compare', 'external', 'info', 'tee', 'tile' or 'update'")
		printErrStr(usage)
		return 1
	}
	// validation (opens read datasets)
	for _, alg := range algs {
		if !alg.Validate() {
			printErrStr(usage)
			return 1
		}
	}
	// execution
	var curDS *Dataset
	derived := false
	for si, alg := range algs {
		name := steps[si][0]
		switch {
		case name == "read":
			v := alg.V("input")
			if len(v.DSs) == 0 || v.DSs[0] == nil {
				return 1
			}
			curDS = v.DSs[0]
			if layers := alg.StrList("input-layer"); len(layers) > 0 && isVector {
				nds := NewDataset(curDS.Name, 0, 0)
				nds.Driver = curDS.Driver
				for _, ln := range layers {
					l := curDS.GetLayerByName(ln)
					if l == nil {
						CPLError(CE_Failure, CPLE_AppDefined, "read: Cannot find source layer '%s'", ln)
						return 1
					}
					nds.Layers = append(nds.Layers, l)
				}
				curDS = nds
				derived = true
			}
		case name == "write":
			if isVector {
				src := curDS
				iv := &ArgVal{Def: &ArgDef{Name: "input"}, Set: true, DSs: []*Dataset{src}, DSNames: []string{src.Name}}
				alg.Vals["input"] = iv
				outName := alg.DSName("output")
				drv := alg.vectorOutputDriver(outName)
				if drv == nil {
					CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
					return 1
				}
				if !vectorTranslate(alg, src, src.Layers, drv, outName) {
					return 1
				}
			} else {
				if !writeRasterResult(alg, copyForOutput(curDS, nil)) {
					return 1
				}
			}
		case name == "info":
			if isVector {
				o := vectorInfoOpts{JSON: strings.EqualFold(alg.Str("output-format"), "json"), Features: alg.Bool("features"), Summary: alg.Bool("summary"), Where: alg.Str("where"), SQL: alg.Str("sql")}
				if derived {
					o.Layers = []string{"__derived__"}
				}
				ds := curDS
				if derived {
					o.Layers = nil
					s, ok := ogrInfoDerived(ds, o)
					out(s)
					if !ok {
						return 1
					}
				} else {
					s, ok := ogrInfo(ds, o)
					out(s)
					if !ok {
						return 1
					}
				}
			} else {
				o := rasterInfoOpts{JSON: strings.EqualFold(alg.Str("output-format"), "json"), MinMax: alg.Bool("min-max"), Stats: alg.Bool("stats"), ApproxStats: alg.Bool("approx-stats"), Hist: alg.Bool("hist"), NoGCP: alg.Bool("no-gcp"), NoMD: alg.Bool("no-md"), NoCT: alg.Bool("no-ct"), NoFL: alg.Bool("no-fl"), Checksum: alg.Bool("checksum"), ListMDD: alg.Bool("list-mdd")}
				ds := curDS
				if derived {
					ds = copyForOutput(curDS, vrtDriver)
					ds.Name = curDS.Name
					ds.FileList = curDS.FileList
				}
				out(gdalInfo(ds, o))
			}
		default:
			key := effKind + " " + name
			f := commands[key]
			if f == nil {
				CPLError(CE_Failure, CPLE_NotSupported, "%s: step not supported", name)
				return 1
			}
			iv := &ArgVal{Def: &ArgDef{Name: "input"}, Set: true, DSs: []*Dataset{curDS}, DSNames: []string{curDS.Name}}
			alg.Vals["input"] = iv
			alg.Vals["output"] = &ArgVal{Def: &ArgDef{Name: "output"}, Set: true, DSNames: []string{"<pipeline>"}}
			pipelineCapture = true
			pipelineCaptured = nil
			ok := f(alg)
			pipelineCapture = false
			if !ok || pipelineCaptured == nil {
				return 1
			}
			nd := pipelineCaptured
			if nd.Name == "" || nd.Name == "<pipeline>" {
				nd.Name = curDS.Name
			}
			if len(nd.FileList) == 0 {
				nd.FileList = curDS.FileList
			}
			if nd.Driver == nil {
				nd.Driver = curDS.Driver
			}
			curDS = nd
			derived = true
		}
	}
	return 0
}

func ogrInfoDerived(ds *Dataset, o vectorInfoOpts) (string, bool) {
	saved := ds.Driver
	ds.Driver = &Driver{ShortName: "(null)", LongName: "(null)"}
	o.Layers = nil
	s, ok := ogrInfo(ds, o)
	ds.Driver = saved
	return s, ok
}
