type stepSection struct {
	name    string
	text    string
	isVector bool
}

func parseStepSections(help string) []stepSection {
	var res []stepSection
	lines := strings.Split(help, "\n")
	for i := 0; i < len(lines); i++ {
		l := lines[i]
		if strings.HasPrefix(l, "* ") && i+1 < len(lines) && strings.HasPrefix(lines[i+1], "---") {
			name := strings.Fields(l[2:])[0]
			j := i + 2
			for j < len(lines) && !(strings.HasPrefix(lines[j], "* ") && j+1 < len(lines) && strings.HasPrefix(lines[j+1], "---")) {
				j++
			}
			text := strings.Join(lines[i:j], "\n")
			res = append(res, stepSection{name: name, text: text, isVector: strings.Contains(text, "vector")})
			i = j - 1
		}
	}
	return res
}

func parseStepHelpOptions(text string) []helpOpt {
	var res []helpOpt
	section := ""
	for _, l := range strings.Split(text, "\n") {
		if strings.HasSuffix(l, ":") && !strings.HasPrefix(l, " ") {
			section = l
			continue
		}
		if !strings.HasPrefix(l, "  -") {
			continue
		}
		rest := l[2:]
		k := strings.Index(rest, "  ")
		optstr := rest
		if k >= 0 {
			optstr = rest[:k]
		}
		parts := strings.Split(optstr, ", ")
		ho := helpOpt{section: section}
		for i, p := range parts {
			if i == len(parts)-1 {
				if sp := strings.IndexByte(p, ' '); sp >= 0 {
					ho.metavar = p[sp+1:]
					p = p[:sp]
				}
			}
			ho.names = append(ho.names, p)
		}
		res = append(res, ho)
	}
	return res
}

var stepDefCache = map[string]*AlgDef{}

// stepDef builds the AlgDef for a pipeline step.
func stepDef(kind, name string, pipeDef *AlgDef, isVector bool) *AlgDef {
	key := kind + "/" + name
	if isVector {
		key += "/v"
	}
	if d, ok := stepDefCache[key]; ok {
		return d
	}
	var node *JValue
	if pa := pipeDef.Node.Get("pipeline_algorithms"); pa != nil {
		for _, n := range pa.Arr {
			if n.Get("name").Str() == name {
				full := n.Get("full_path")
				isV := full != nil && len(full.Arr) > 1 && full.Arr[1].Str() == "vector"
				if kind == "" && isV != isVector && (name == "read" || name == "write" || name == "info") {
					continue
