		d.ByLong[a.Name] = a
		for _, al := range a.Aliases {
			d.ByLong[al] = a
		}
		if a.Short != "" {
			d.ByShort[a.Short] = a
		}
	}
	d.Path = []string{kind, name}
	stepDefCache[key] = d
	return d
}

