				src := curDS
				iv := &ArgVal{Def: &ArgDef{Name: "input"}, Set: true, DSs: []*Dataset{src}, DSNames: []string{src.Name}}
				alg.Vals["input"] = iv
				outName := alg.DSName("output")
				drv := alg.vectorOutputDriver(outName)
				if drv == nil {
					CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
					return 1
				}
				if !vectorTranslate(alg, src, src.Layers, drv, outName) {
					return 1
				}
			} else {
				if !writeRasterResult(alg, copyForOutput(curDS, nil)) {
					return 1
				}
			}
		case name == "info":
			if isVector {
				o := vectorInfoOpts{JSON: strings.EqualFold(alg.Str("output-format"), "json"), Features: alg.Bool("features"), Summary: alg.Bool("summary"), Where: alg.Str("where"), SQL: alg.Str("sql")}
				if derived {
					o.Layers = []string{"__derived__"}
				}
				ds := curDS
				if derived {
					o.Layers = nil
					s, ok := ogrInfoDerived(ds, o)
					out(s)
					if !ok {
						return 1
					}
				} else {
					s, ok := ogrInfo(ds, o)
					out(s)
					if !ok {
						return 1
					}
				}
			} else {
				o := rasterInfoOpts{JSON: strings.EqualFold(alg.Str("output-format"), "json"), MinMax: alg.Bool("min-max"), Stats: alg.Bool("stats"), ApproxStats: alg.Bool("approx-stats"), Hist: alg.Bool("hist"), NoGCP: alg.Bool("no-gcp"), NoMD: alg.Bool("no-md"), NoCT: alg.Bool("no-ct"), NoFL: alg.Bool("no-fl"), Checksum: alg.Bool("checksum"), ListMDD: alg.Bool("list-mdd")}
				ds := curDS
				if derived {
					ds = copyForOutput(curDS, vrtDriver)
					ds.Name = curDS.Name
					ds.FileList = curDS.FileList
				}
				out(gdalInfo(ds, o))
			}
		default:
			key := effKind + " " + name
			f := commands[key]
			if f == nil {
				CPLError(CE_Failure, CPLE_NotSupported, "%s: step not supported", name)
				return 1
			}
			iv := &ArgVal{Def: &ArgDef{Name: "input"}, Set: true, DSs: []*Dataset{curDS}, DSNames: []string{curDS.Name}}
			alg.Vals["input"] = iv
			alg.Vals["output"] = &ArgVal{Def: &ArgDef{Name: "output"}, Set: true, DSNames: []string{"<pipeline>"}}
			pipelineCapture = true
			pipelineCaptured = nil
			ok := f(alg)
			pipelineCapture = false
			if !ok || pipelineCaptured == nil {
				return 1
			}
			nd := pipelineCaptured
			if nd.Name == "" || nd.Name == "<pipeline>" {
				nd.Name = curDS.Name
			}
			if len(nd.FileList) == 0 {
				nd.FileList = curDS.FileList
			}
			if nd.Driver == nil {
				nd.Driver = curDS.Driver
			}
			curDS = nd
			derived = true
		}
	}
	return 0
}

func ogrInfoDerived(ds *Dataset, o vectorInfoOpts) (string, bool) {
	saved := ds.Driver
	ds.Driver = &Driver{ShortName: "(null)", LongName: "(null)"}
	o.Layers = nil
	s, ok := ogrInfo(ds, o)
	ds.Driver = saved
	return s, ok
}
