{"command":"cd /workspace/gdalgo && cat > mosaic.go <<'EOF'
package main

import (
	"math"
	"os"
	"strings"
)

func init() {
	registerCommand("raster mosaic", func(a *Alg) bool { return runMosaicStack(a, false) })
	registerCommand("raster stack", func(a *Alg) bool { return runMosaicStack(a, true) })
}

func expandInputList(names []string) []string {
	var res []string
	for _, n := range names {
		if strings.HasPrefix(n, "@") {
			if b, err := os.ReadFile(n[1:]); err == nil {
				for _, l := range strings.Split(string(b), "\n") {
					l = strings.TrimSpace(l)
					if l != "" {
						res = append(res, l)
					}
				}
			}
			continue
		}
		res = append(res, n)
	}
	return res
}

func runMosaicStack(a *Alg, stack bool) bool {
	var srcs []*Dataset
	if v := a.V("input"); len(v.DSs) > 0 && v.DSs[0] != nil && pipelineCapture {
		srcs = v.DSs
	} else {
		for _, n := range expandInputList(a.StrList("input")) {
			ds := OpenDataset(n, OF_RASTER, a.StrList("input-format"), a.StrList("open-option"), true)
			if ds == nil {
				CPLError(CE_Failure, CPLE_AppDefined, "Can't open %s.", n)
				return false
			}
			srcs = append(srcs, ds)
		}
	}
	if len(srcs) == 0 {
		return false
	}
	ref := srcs[0]
	name := "mosaic"
	if stack {
		name = "stack"
	}
	for _, s := range srcs[1:] {
		if (ref.SRS == nil) != (s.SRS == nil) || (ref.SRS != nil && !ref.SRS.IsSame(s.SRS)) {
			en, gn := "", ""
			if ref.SRS != nil {
				en = ref.SRS.Name()
			}
			if s.SRS != nil {
				gn = s.SRS.Name()
			}
			CPLError(CE_Failure, CPLE_AppDefined, "gdal raster %s does not support heterogeneous projection: expected %s, got %s.", name, en, gn)
			return false
		}
		if !stack && len(s.Bands) != len(ref.Bands) {
			CPLError(CE_Failure, CPLE_AppDefined, "gdal raster mosaic does not support heterogeneous band numbers: expected %d, got %d.", len(ref.Bands), len(s.Bands))
			return false
		}
	}
	env := EmptyEnvelope()
	xres, yres := 0.0, 0.0
	minRes, maxRes := math.Inf(1), 0.0
	for _, s := range srcs {
		gt := s.GT
		x0, y0 := gt[0], gt[3]
		x1 := gt[0] + gt[1]*float64(s.XSize)
		y1 := gt[3] + gt[5]*float64(s.YSize)
		env.MergePt(x0, y0)
		env.MergePt(x1, y1)
		xres += gt[1]
		yres += math.Abs(gt[5])
		minRes = math.Min(minRes, gt[1])
		maxRes = math.Max(maxRes, gt[1])
	}
	resMode := a.Str("resolution")
	switch {
	case resMode == "" || resMode == "same" || resMode == "average":
		xres /= float64(len(srcs))
		yres /= float64(len(srcs))
		if resMode == "same" || resMode == "" {
			for _, s := range srcs {
				if s.GT[1] != ref.GT[1] || s.GT[5] != ref.GT[5] {
					CPLError(CE_Failure, CPLE_AppDefined, "Datasets have not the same resolution. Use 'resolution' argument to specify the resolution")
					return false
				}
			}
			xres, yres = ref.GT[1], math.Abs(ref.GT[5])
		}
	case resMode == "highest":
		xres, yres = math.Inf(1), math.Inf(1)
		for _, s := range srcs {
			xres = math.Min(xres, s.GT[1])
			yres = math.Min(yres, math.Abs(s.GT[5]))
		}
	case resMode == "lowest":
		xres, yres = 0, 0
		for _, s := range srcs {
			xres = math.Max(xres, s.GT[1])
			yres = math.Max(yres, math.Abs(s.GT[5]))
		}
	default:
		parts := strings.Split(resMode, ",")
		if len(parts) == 2 {
			xres, yres = cplAtof(parts[0]), cplAtof(parts[1])
		}
	}
	if a.IsSet("bbox") {
		bb := a.RealList("bbox")
		env = Envelope{bb[0], bb[1], bb[2], bb[3]}
	}
	if a.Bool("target-aligned-pixels") {
		env.MinX = math.Floor(env.MinX/xres) * xres
		env.MaxX = math.Ceil(env.MaxX/xres) * xres
		env.MinY = math.Floor(env.MinY/yres) * yres
		env.MaxY = math.Ceil(env.MaxY/yres) * yres
	}
	w := int((env.MaxX-env.MinX)/xres + 0.5)
	h := int((env.MaxY-env.MinY)/yres + 0.5)
	gt := [6]float64{env.MinX, xres, 0, env.MaxY, 0, -yres}
	ds := cloneRasterStructure(ref, w, h)
	ds.GT = gt
	ds.MD = NewMetadata()
	if v, ok := ref.MD.Get("", "AREA_OR_POINT"); ok {
		ds.MD.Set("", "AREA_OR_POINT", v)
	}
	srcND := a.RealList("src-nodata")
	dstND := a.RealList("dst-nodata")
	place := func(dst []float64, s *Dataset, sb *Band, ndOverride []float64, bi int) {
		sd := sb.Data()
		valid := sb.validMask()
		if len(ndOverride) > 0 {
			nd := ndOverride[0]
			if bi < len(ndOverride) {
				nd = ndOverride[bi]
			}
			for k, v := range sd {
				valid[k] = v != nd
			}
		}
		sinv, _ := invGeoTransform(s.GT)
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				gx, gy := applyGT(gt, float64(x)+0.5, float64(y)+0.5)
				px, py := applyGT(sinv, gx, gy)
				ix, iy := int(math.Floor(px)), int(math.Floor(py))
				if ix < 0 || iy < 0 || ix >= s.XSize || iy >= s.YSize {
					continue
				}
				k := iy*s.XSize + ix
				if !valid[k] {
					continue
				}
				dst[y*w+x] = sd[k]
			}
		}
	}
	bandSel := a.IntList("band")
	if stack {
		for _, s := range srcs {
			bands := s.Bands
			if len(bandSel) > 0 {
				bands = nil
				for _, b := range bandSel {
					if b >= 1 && b <= len(s.Bands) {
						bands = append(bands, s.Bands[b-1])
					}
				}
			}
			for bi, sb := range bands {
				out := make([]float64, w*h)
				nd := 0.0
				hasND := sb.HasNoData
				if hasND {
					nd = sb.NoData
				}
				if len(dstND) > 0 {
					nd, hasND = dstND[0], true
				}
				for k := range out {
					out[k] = nd
				}
				place(out, s, sb, srcND, bi)
				b := newBandFrom(ds, sb, sb.DataType, out)
				b.HasNoData, b.NoData = hasND, nd
				if a.Bool("hide-nodata") {
					b.HasNoData = false
				}
				removeStatsMD(b)
				b.ColorInterp = GCI_Undefined
				b.BlockX, b.BlockY = w, 1
				if len(ds.Bands) == 1 {
					b.ColorInterp = GCI_GrayIndex
				}
			}
		}
	} else {
		nb := len(ref.Bands)
		idx := make([]int, 0, nb)
		if len(bandSel) > 0 {
			idx = append(idx, bandSel...)
		} else {
			for i := 1; i <= nb; i++ {
				idx = append(idx, i)
			}
		}
		for bi, bn := range idx {
			rb := ref.Bands[bn-1]
			out := make([]float64, w*h)
			nd := 0.0
			hasND := rb.HasNoData
			if hasND {
				nd = rb.NoData
			}
			if len(dstND) > 0 {
				nd, hasND = dstND[0], true
				if bi < len(dstND) {
					nd = dstND[bi]
				}
			}
			for k := range out {
				out[k] = nd
			}
			for _, s := range srcs {
				place(out, s, s.Bands[bn-1], srcND, bi)
			}
			b := newBandFrom(ds, rb, rb.DataType, out)
			b.HasNoData, b.NoData = hasND, nd
			if a.Bool("hide-nodata") {
				b.HasNoData = false
			}
			removeStatsMD(b)
			b.BlockX, b.BlockY = w, 1
		}
	}
	return writeRasterResult(a, ds)
}
