{"command":"cd /workspace/gdalgo && cat > polygonize.go <<'EOF'
package main

import (
	"math"
	"sort"
)

func init() {
	registerCommand("raster polygonize", runPolygonize)
}

type ipt struct{ x, y int }

// traceRings builds closed rings (in pixel corner coords) for a set of pixels.
func traceRings(mask func(x, y int) bool, pix []ipt) [][]ipt {
	// directed edges with interior on the left in pixel space (y down): for each pixel,
	// edges: top (x,y)->(x+1,y) if above not in set ... we orient so that traversal
	// goes down along left side: left edge (x,y)->(x,y+1)
	next := map[ipt][]ipt{}
	add := func(a, b ipt) { next[a] = append(next[a], b) }
	for _, p := range pix {
		x, y := p.x, p.y
		if !mask(x-1, y) {
			add(ipt{x, y}, ipt{x, y + 1})
		}
		if !mask(x, y+1) {
			add(ipt{x, y + 1}, ipt{x + 1, y + 1})
		}
		if !mask(x+1, y) {
			add(ipt{x + 1, y + 1}, ipt{x + 1, y})
		}
		if !mask(x, y-1) {
			add(ipt{x + 1, y}, ipt{x, y})
		}
	}
	used := map[[2]ipt]bool{}
	var rings [][]ipt
	// deterministic start ordering
	var starts []ipt
	for k := range next {
		starts = append(starts, k)
	}
	sort.Slice(starts, func(i, j int) bool {
		if starts[i].y != starts[j].y {
			return starts[i].y < starts[j].y
		}
		return starts[i].x < starts[j].x
	})
	for _, s := range starts {
		for _, t := range next[s] {
			if used[[2]ipt{s, t}] {
				continue
			}
			ring := []ipt{s}
			used[[2]ipt{s, t}] = true
			prev, cur := s, t
			for cur != s {
				ring = append(ring, cur)
				cands := next[cur]
				var nxt ipt
				found := false
				if len(cands) == 1 {
					nxt = cands[0]
					found = !used[[2]ipt{cur, nxt}]
				} else {
					// choose turn: prefer right turn (keeps components separate at diagonal touches)
					dx, dy := cur.x-prev.x, cur.y-prev.y
					// directions in order: right turn, straight, left turn (in y-down coords)
					order := [][2]int{{-dy, dx}, {dx, dy}, {dy, -dx}}
					for _, o := range order {
						c := ipt{cur.x + o[0], cur.y + o[1]}
						for _, cc := range cands {
							if cc == c && !used[[2]ipt{cur, cc}] {
								nxt = cc
								found = true
								break
							}
						}
						if found {
							break
						}
					}
				}
				if !found {
					break
				}
				used[[2]ipt{cur, nxt}] = true
				prev, cur = cur, nxt
			}
			rings = append(rings, ring)
		}
	}
	return rings
}

func simplifyRing(r []ipt) []ipt {
	n := len(r)
	var out []ipt
	for i := 0; i < n; i++ {
		a := r[(i-1+n)%n]
		b := r[i]
		c := r[(i+1)%n]
		if (b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x) != 0 {
			out = append(out, b)
		}
	}
	return out
}

func ringAreaI(r []ipt) int {
	s := 0
	n := len(r)
	for i := 0; i < n; i++ {
		a, b := r[i], r[(i+1)%n]
		s += a.x*b.y - b.x*a.y
	}
	return s
}

func rotateToTopLeft(r []ipt) []ipt {
	best := 0
	for i, p := range r {
		if p.y < r[best].y || (p.y == r[best].y && p.x < r[best].x) {
			best = i
		}
	}
	return append(append([]ipt{}, r[best:]...), r[:best]...)
}

func runPolygonize(a *Alg) bool {
	src := srcRaster(a)
	bi := 1
	if a.IsSet("band") {
		bi = a.Int("band")
	}
	if bi < 1 || bi > len(src.Bands) {
		a.ReportError(CPLE_IllegalArg, "Invalid band number: %d", bi)
		return false
	}
	b := src.Bands[bi-1]
	W, H := src.XSize, src.YSize
	data := b.Data()
	valid := b.validMask()
	diag := a.Bool("connect-diagonal-pixels")
	labels := make([]int, W*H)
	for i := range labels {
		labels[i] = -1
	}
	type comp struct {
		val      float64
		pix      []ipt
		lastRow  int
		firstIdx int
	}
	var comps []*comp
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			k := y*W + x
			if labels[k] >= 0 || !valid[k] {
				continue
			}
			c := &comp{val: data[k], firstIdx: len(comps)}
			id := len(comps)
			comps = append(comps, c)
			stack := []ipt{{x, y}}
			labels[k] = id
			for len(stack) > 0 {
				p := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				c.pix = append(c.pix, p)
				if p.y > c.lastRow {
					c.lastRow = p.y
				}
				nb := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
				if diag {
					nb = append(nb, [2]int{1, 1}, [2]int{1, -1}, [2]int{-1, 1}, [2]int{-1, -1})
				}
				for _, d := range nb {
					nx, ny := p.x+d[0], p.y+d[1]
					if nx < 0 || ny < 0 || nx >= W || ny >= H {
						continue
					}
					nk := ny*W + nx
					if labels[nk] < 0 && valid[nk] && data[nk] == c.val {
						labels[nk] = id
						stack = append(stack, ipt{nx, ny})
					}
				}
			}
		}
	}
	// emission order: by last row then first appearance
	order := make([]*comp, len(comps))
	copy(order, comps)
	sort.SliceStable(order, func(i, j int) bool {
		li, lj := order[i].lastRow, order[j].lastRow
		if li == H-1 {
			li = H
		}
		if lj == H-1 {
			lj = H
		}
		if li != lj {
			return li < lj
		}
		return order[i].firstIdx < order[j].firstIdx
	})
	field := a.Str("attribute-name")
	if field == "" {
		field = "DN"
	}
	lname := a.Str("output-layer")
	if lname == "" {
		lname = "polygonize"
	}
	l := NewLayer(lname)
	ft := OFTInteger
	if b.DataType.IsFloat() {
		ft = OFTReal
	} else if b.DataType == GDT_Int64 || b.DataType == GDT_UInt64 || b.DataType == GDT_UInt32 {
		ft = OFTInteger64
	}
	l.Fields = []*FieldDefn{NewFieldDefn(field, ft)}
	l.GeomFields = []*GeomFieldDefn{{Name: "", Type: wkbPolygon, SRS: src.SRS, Nullable: true}}
	gt := src.GT
	toGeo := func(p ipt) Pt {
		x, y := applyGT(gt, float64(p.x), float64(p.y))
		return Pt{X: x, Y: y}
	}
	for _, c := range order {
		id := c.firstIdx
		mask := func(x, y int) bool {
			if x < 0 || y < 0 || x >= W || y >= H {
				return false
			}
			return labels[y*W+x] == id
		}
		rings := traceRings(mask, c.pix)
		var outer []ipt
		var holes [][]ipt
		for _, r := range rings {
			r = simplifyRing(r)
			if len(r) < 3 {
				continue
			}
			ar := ringAreaI(r)
			if ar > 0 {
				// in y-down coords positive => CCW visually => outer (by construction)
				if outer == nil || abs(ar) > abs(ringAreaI(outer)) {
					if outer != nil {
						holes = append(holes, outer)
					}
					outer = r
				} else {
					holes = append(holes, r)
				}
			} else {
				holes = append(holes, r)
			}
		}
		if outer == nil {
			continue
		}
		poly := &Geom{T: wkbPolygon}
		mk := func(r []ipt) *Geom {
			r = rotateToTopLeft(r)
			g := &Geom{T: wkbLinearRing}
			for _, p := range r {
				g.Pts = append(g.Pts, toGeo(p))
			}
			g.Pts = append(g.Pts, toGeo(r[0]))
			return g
		}
		poly.Parts = append(poly.Parts, mk(outer))
		sort.SliceStable(holes, func(i, j int) bool {
			ti, tj := rotateToTopLeft(holes[i])[0], rotateToTopLeft(holes[j])[0]
			if ti.y != tj.y {
				return ti.y < tj.y
			}
			return ti.x < tj.x
		})
		for _, h := range holes {
			poly.Parts = append(poly.Parts, mk(h))
		}
		f := l.NewFeature()
		f.Fields[0].State = 2
		if ft == OFTReal {
			f.Fields[0].F = c.val
		} else {
			f.Fields[0].I = int64(c.val)
		}
		f.Geoms[0] = poly
		l.AddFeature(f)
	}
	l.loaded = true
	ds := NewDataset(src.Name, 0, 0)
	ds.Layers = []*Layer{l}
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, ds, []*Layer{l})
	if saved != nil {
		a.Vals["output-layer"] = saved
