cd /workspace/gdalgo && rm cog_vrt_stub.go && cat > vrt.go <<'EOF'
package main

import (
	"math"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type vrtSource struct {
	path     string
	band     int
	srcDS    *Dataset
	sx, sy   int
	sw, sh   int
	dx, dy   int
	dw, dh   int
	nodata   *float64
}

func init() {
	vrtDriver.Identify = func(oi *OpenInfo) bool {
		return strings.Contains(string(oi.Header), "<VRTDataset")
	}
	vrtDriver.Open = vrtOpen
}

func cogWriteDataset(name string, ds *Dataset, co []string, prog *Progress) error {
	opts := append([]string{"TILED=YES", "BLOCKXSIZE=512", "BLOCKYSIZE=512", "COMPRESS=LZW"}, co...)
	return gtiffWriteDataset(name, ds, opts, prog)
}

func absPath(p string) string {
	if filepath.IsAbs(p) || isVSI(p) {
		return p
	}
	a, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return a
}

func relPathFrom(vrtPath, src string) (string, bool) {
	if isVSI(src) {
		return src, false
	}
	base := filepath.Dir(absPath(vrtPath))
	rel, err := filepath.Rel(base, absPath(src))
	if err != nil || strings.HasPrefix(rel, "..") {
		return absPath(src), false
	}
	return rel, true
}

func gtString(gt [6]float64) string {
	var p []string
	for _, v := range gt {
		p = append(p, cfmt("%24.16e", v))
	}
	return strings.Join(p, ",")
}

func vrtWriteDataset(name string, ds *Dataset, co []string) error {
	root := NewXElem("VRTDataset")
	root.SetAttr("rasterXSize", strconv.Itoa(ds.XSize))
	root.SetAttr("rasterYSize", strconv.Itoa(ds.YSize))
	if ds.SRS != nil {
		e := root.AddText("SRS", ds.SRS.WKT1())
		e.Attrs = []XAttr{{"dataAxisToSRSAxisMapping", ds.SRS.MappingString()}}
	}
	if ds.HasGT {
		root.AddText("GeoTransform", gtString(ds.GT))
	}
	addMetadataXML(root, filterMD(ds.MD))
	for i, b := range ds.Bands {
		bn := root.AddElem("VRTRasterBand")
		bn.SetAttr("dataType", b.DataType.String())
		bn.SetAttr("band", strconv.Itoa(i+1))
		if b.HasNoData {
			bn.AddText("NoDataValue", nodataTIFFString(b))
		}
		if b.Description != "" {
			bn.AddText("Description", b.Description)
		}
		addMetadataXML(bn, filterMD(b.MD))
		if b.ColorInterp != GCI_Undefined {
			bn.AddText("ColorInterp", colorInterpName(b.ColorInterp))
		}
		if b.HasOffset && b.Offset != 0 {
			bn.AddText("Offset", cfmt("%.16g", b.Offset))
		}
		if b.HasScale && b.Scale != 1 {
			bn.AddText("Scale", cfmt("%.16g", b.Scale))
		}
		if b.Unit != "" {
			bn.AddText("UnitType", b.Unit)
		}
		if b.ColorTable != nil {
			ct := bn.AddElem("ColorTable")
			for _, e := range b.ColorTable.Entries {
				en := ct.AddElem("Entry")
				en.SetAttr("c1", strconv.Itoa(e.C1))
				en.SetAttr("c2", strconv.Itoa(e.C2))
				en.SetAttr("c3", strconv.Itoa(e.C3))
				en.SetAttr("c4", strconv.Itoa(e.C4))
			}
		}
		srcs, _ := b.DS.Extra["vrt_sources"+strconv.Itoa(i)].([]vrtSource)
		if srcs == nil {
			CPLError(CE_Failure, CPLE_NotSupported, "VRT output of a computed dataset is not supported")
			return newOpenErr(CPLE_NotSupported, "")
		}
		for _, s := range srcs {
			tag := "SimpleSource"
			if s.nodata != nil {
				tag = "ComplexSource"
			}
			sn := bn.AddElem(tag)
			rel, isRel := relPathFrom(name, s.path)
			fe := sn.AddText("SourceFilename", rel)
			if isRel {
				fe.SetAttr("relativeToVRT", "1")
			} else {
				fe.SetAttr("relativeToVRT", "0")
			}
			sn.AddText("SourceBand", strconv.Itoa(s.band))
			sb := s.srcDS.Bands[s.band-1]
			sp := sn.AddElem("SourceProperties")
			sp.SetAttr("RasterXSize", strconv.Itoa(s.srcDS.XSize))
			sp.SetAttr("RasterYSize", strconv.Itoa(s.srcDS.YSize))
			sp.SetAttr("DataType", sb.DataType.String())
			sp.SetAttr("BlockXSize", strconv.Itoa(sb.BlockX))
			sp.SetAttr("BlockYSize", strconv.Itoa(sb.BlockY))
			sr := sn.AddElem("SrcRect")
			sr.SetAttr("xOff", strconv.Itoa(s.sx))
			sr.SetAttr("yOff", strconv.Itoa(s.sy))
			sr.SetAttr("xSize", strconv.Itoa(s.sw))
			sr.SetAttr("ySize", strconv.Itoa(s.sh))
			dr := sn.AddElem("DstRect")
			dr.SetAttr("xOff", strconv.Itoa(s.dx))
			dr.SetAttr("yOff", strconv.Itoa(s.dy))
			dr.SetAttr("xSize", strconv.Itoa(s.dw))
			dr.SetAttr("ySize", strconv.Itoa(s.dh))
			if s.nodata != nil {
				sn.AddText("NODATA", cfmt("%.18g", *s.nodata))
			}
		}
	}
	return vfsWriteFile(name, []byte(root.Serialize()))
}

func filterMD(md *Metadata) *Metadata {
	n := NewMetadata()
	for _, d := range md.Domains {
		if d == "DERIVED_SUBDATASETS" {
			continue
		}
		for _, kv := range md.List(d) {
			if i := strings.IndexByte(kv, '='); i >= 0 {
				if d == "IMAGE_STRUCTURE" && kv[:i] != "INTERLEAVE" {
					continue
				}
				n.Set(d, kv[:i], kv[i+1:])
			}
		}
	}
	return n
}

// attachFileSources records 1:1 sources for each band of a file-backed dataset.
func attachFileSources(dst *Dataset, src *Dataset, bandIdx []int) {
	for i, bi := range bandIdx {
		dst.Extra["vrt_sources"+strconv.Itoa(i)] = []vrtSource{{path: src.Name, band: bi, srcDS: src, sw: src.XSize, sh: src.YSize, dw: src.XSize, dh: src.YSize}}
	}
}

func vrtOpen(oi *OpenInfo) (*Dataset, error) {
	data, err := vfsReadFile(oi.Filename)
	if err != nil {
		return nil, newOpenErr(CPLE_OpenFailed, "%s: No such file or directory", oi.Filename)
	}
	root := ParseXML(string(data)).Child("VRTDataset")
	if root == nil {
		return nil, newOpenErr(CPLE_OpenFailed, "`%s' not recognized as being in a supported file format.", oi.Filename)
	}
	w := atoiC(root.AttrDef("rasterXSize", "0"))
	h := atoiC(root.AttrDef("rasterYSize", "0"))
	ds := NewDataset(oi.Filename, w, h)
	ds.FileList = []string{oi.Filename}
	if s := root.Child("SRS"); s != nil {
		if srs, ok := srsFromUserInput(s.InnerText()); ok {
			if m, ok := s.Attr("dataAxisToSRSAxisMapping"); ok {
				var mp []int
				for _, x := range strings.Split(m, ",") {
					mp = append(mp, atoiC(x))
				}
				srs.mapping = mp
			}
			ds.SRS = srs
		}
	}
	if g := root.Child("GeoTransform"); g != nil {
		parts := strings.Split(g.InnerText(), ",")
		if len(parts) == 6 {
			for i := range parts {
				ds.GT[i] = cplAtof(strings.TrimSpace(parts[i]))
			}
			ds.HasGT = true
		}
	}
	parseMetadataXML(root, ds.MD)
	vrtDir := filepath.Dir(oi.Filename)
	opened := map[string]*Dataset{}
	for _, bn := range root.ChildrenNamed("VRTRasterBand") {
		dt := dataTypeFromName(bn.AttrDef("dataType", "Byte"))
		b := ds.AddBand(dt)
		b.BlockX, b.BlockY = 128, 128
		if w < 128 {
			b.BlockX = w
		}
		if h < 128 {
			b.BlockY = h
		}
		if nd := bn.Child("NoDataValue"); nd != nil {
			b.HasNoData = true
			b.NoData = parseNodataString(nd.InnerText(), dt)
		}
		if ci := bn.Child("ColorInterp"); ci != nil {
			if c := colorInterpFromName(ci.InnerText()); c >= 0 {
				b.ColorInterp = c
			}
		}
		if d := bn.Child("Description"); d != nil {
			b.Description = d.InnerText()
		}
		if o := bn.Child("Offset"); o != nil {
			b.HasOffset, b.Offset = true, cplAtof(o.InnerText())
		}
		if s := bn.Child("Scale"); s != nil {
			b.HasScale, b.Scale = true, cplAtof(s.InnerText())
		}
		if u := bn.Child("UnitType"); u != nil {
			b.Unit = u.InnerText()
		}
		parseMetadataXML(bn, b.MD)
		if ct := bn.Child("ColorTable"); ct != nil {
			t := &ColorTable{}
			for _, e := range ct.ChildrenNamed("Entry") {
				t.Entries = append(t.Entries, ColorEntry{atoiC(e.AttrDef("c1", "0")), atoiC(e.AttrDef("c2", "0")), atoiC(e.AttrDef("c3", "0")), atoiC(e.AttrDef("c4", "255"))})
			}
			b.ColorTable = t
		}
		var srcs []vrtSource
		for _, c := range bn.Children {
			if c.IsText || (c.Name != "SimpleSource" && c.Name != "ComplexSource" && c.Name != "AveragedSource") {
				continue
			}
			fn := c.ChildText("SourceFilename", "")
			fe := c.Child("SourceFilename")
			if fe != nil && fe.AttrDef("relativeToVRT", "0") == "1" {
				fn = filepath.Join(vrtDir, fn)
			}
			s := vrtSource{path: fn, band: atoiC(c.ChildText("SourceBand", "1"))}
			if sr := c.Child("SrcRect"); sr != nil {
				s.sx, s.sy = atoiC(sr.AttrDef("xOff", "0")), atoiC(sr.AttrDef("yOff", "0"))
				s.sw, s.sh = atoiC(sr.AttrDef("xSize", "0")), atoiC(sr.AttrDef("ySize", "0"))
			}
			if dr := c.Child("DstRect"); dr != nil {
				s.dx, s.dy = atoiC(dr.AttrDef("xOff", "0")), atoiC(dr.AttrDef("yOff", "0"))
				s.dw, s.dh = atoiC(dr.AttrDef("xSize", "0")), atoiC(dr.AttrDef("ySize", "0"))
			}
			if nd := c.Child("NODATA"); nd != nil {
				v := cplAtof(nd.InnerText())
				s.nodata = &v
			}
			if _, ok := opened[fn]; !ok {
				opened[fn] = OpenDataset(fn, OF_RASTER, nil, nil, false)
				if opened[fn] != nil {
					ds.FileList = append(ds.FileList, fn)
				}
			}
			s.srcDS = opened[fn]
			srcs = append(srcs, s)
		}
		bb := b
		bb.loader = func(band *Band) error {
			out := make([]float64, w*h)
			if band.HasNoData {
				for i := range out {
					out[i] = band.NoData
				}
			}
			for _, s := range srcs {
				if s.srcDS == nil || s.band < 1 || s.band > len(s.srcDS.Bands) {
					continue
				}
				sb := s.srcDS.Bands[s.band-1]
				sd := sb.Data()
				sv := sb.validMask()
				for y := 0; y < s.dh; y++ {
					ty := s.dy + y
					if ty < 0 || ty >= h {
						continue
					}
					syf := float64(s.sy) + (float64(y)+0.5)*float64(s.sh)/float64(s.dh)
					sy := int(math.Floor(syf))
					if sy < 0 || sy >= s.srcDS.YSize {
						continue
					}
					for x := 0; x < s.dw; x++ {
						tx := s.dx + x
						if tx < 0 || tx >= w {
							continue
						}
						sx := int(math.Floor(float64(s.sx) + (float64(x)+0.5)*float64(s.sw)/float64(s.dw)))
						if sx < 0 || sx >= s.srcDS.XSize {
							continue
						}
						k := sy*s.srcDS.XSize + sx
						v := sd[k]
						if s.nodata != nil && v == *s.nodata {
							continue
						}
						if !sv[k] && sb.HasNoData {
							continue
						}
						out[ty*w+tx] = v
					}
				}
			}
			band.data = out
			return nil
		}
		ds.Extra["vrt_sources"+strconv.Itoa(len(ds.Bands)-1)] = srcs
	}
	setDefaultMaskFlags(ds)
	_ = os.Stat
	return ds, nil
}
