package main

import (
	"math"
	"strings"
)

func init() {
	registerCommand("raster pixel-info", runPixelInfo)
}

func runPixelInfo(a *Alg) bool {
	src := srcRaster(a)
	pos := a.RealList("position")
	if len(pos)%2 != 0 {
		a.ReportError(CPLE_IllegalArg, "Even number of values expected for 'position'")
		return false
	}
	bands := a.IntList("band")
	if len(bands) == 0 {
		for i := range src.Bands {
			bands = append(bands, i+1)
		}
	}
	posCRS := a.Str("position-crs")
	var ct *CoordTransform
	if posCRS != "" && !strings.EqualFold(posCRS, "pixel") && !strings.EqualFold(posCRS, "dataset") && src.SRS != nil {
		if s, ok := srsFromUserInput(posCRS); ok {
			ct = NewCoordTransform(s, src.SRS)
		}
	}
	inv, _ := invGeoTransform(src.GT)
	root := JNewObject()
	root.Set("type", JStr("FeatureCollection"))
	var outSRS *SRS
	if src.SRS != nil {
		outSRS = src.SRS
		auth, code := src.SRS.AuthID()
		name := ""
		if strings.EqualFold(auth, "EPSG") && code == "4326" {
			name = "urn:ogc:def:crs:OGC:1.3:CRS84"
		} else if auth != "" {
			name = "urn:ogc:def:crs:" + auth + "::" + code
		}
		if name != "" {
			crs := JNewObject()
			crs.Set("type", JStr("name"))
			p := JNewObject()
			p.Set("name", JStr(name))
			crs.Set("properties", p)
			root.Set("crs", crs)
		}
	}
	feats := JNewArray()
	for i := 0; i+1 < len(pos); i += 2 {
		x, y := pos[i], pos[i+1]
		col, line := x, y
		if strings.EqualFold(posCRS, "dataset") {
			col, line = applyGT(inv, x, y)
		} else if ct != nil {
			gx, gy, _ := ct.TransformOne(x, y)
			col, line = applyGT(inv, gx, gy)
		}
		f := JNewObject()
		f.Set("type", JStr("Feature"))
		props := JNewObject()
		props.Set("input_coordinate", JNewArray().Add(JDouble(x)).Add(JDouble(y)))
		props.Set("column", JDouble(col))
		props.Set("line", JDouble(line))
		ba := JNewArray()
		ix, iy := int(math.Floor(col)), int(math.Floor(line))
		for _, bn := range bands {
			bo := JNewObject()
			bo.Set("band_number", JInt(int64(bn)))
			if bn >= 1 && bn <= len(src.Bands) && ix >= 0 && iy >= 0 && ix < src.XSize && iy < src.YSize {
				b := src.Bands[bn-1]
				k := iy*src.XSize + ix
				v := b.Data()[k]
				if b.validMask()[k] {
					if b.DataType.IsFloat() {
						bo.Set("raw_value", JDouble(v))
					} else {
						bo.Set("raw_value", JInt(int64(v)))
					}
					sc, off := 1.0, 0.0
					if b.HasScale {
						sc = b.Scale
					}
					if b.HasOffset {
						off = b.Offset
					}
					bo.Set("unscaled_value", JDouble(v*sc+off))
				}
			}
			ba.Add(bo)
		}
		props.Set("bands", ba)
		f.Set("properties", props)
		if outSRS != nil && src.HasGT {
			gx, gy := applyGT(src.GT, col, line)
			g := JNewObject()
			g.Set("type", JStr("Point"))
			g.Set("coordinates", JNewArray().Add(JDouble(gx)).Add(JDouble(gy)))
			f.Set("geometry", g)
		} else {
			f.Set("geometry", JNullV())
		}
		feats.Add(f)
	}
	root.Set("features", feats)
	out(root.SerializePrettyNoSlash())
	return true
}
EOF
