{"command":"cd /workspace/gdalgo && cat > rasterize.go <<'EOF'
package main

import (
	"math"
	"sort"
	"strings"
)

func init() {
	registerCommand("vector rasterize", runRasterize)
}

// burnPolygon fills polygon (rings in pixel space) into out using GDAL-like scanline rule.
func burnPolygon(rings [][]Pt, w, h int, set func(x, y int)) {
	miny, maxy := math.Inf(1), math.Inf(-1)
	for _, r := range rings {
		for _, p := range r {
			miny = math.Min(miny, p.Y)
			maxy = math.Max(maxy, p.Y)
		}
	}
	if math.IsInf(miny, 0) {
		return
	}
	j0 := int(math.Floor(miny))
	j1 := int(math.Ceil(maxy))
	if j0 < 0 {
		j0 = 0
	}
	if j1 > h-1 {
		j1 = h - 1
	}
	for j := j0; j <= j1; j++ {
		y := float64(j) + 0.5
		var xs []float64
		for _, r := range rings {
			n := len(r)
			for i := 0; i+1 < n; i++ {
				a, b := r[i], r[i+1]
				y1, y2, x1, x2 := a.Y, b.Y, a.X, b.X
				if y1 > y2 {
					y1, y2 = y2, y1
					x1, x2 = x2, x1
				}
				if y1 == y2 {
					continue
				}
				if (y >= y1 && y < y2) || (y == y2 && y == maxy) {
					xs = append(xs, (y-y1)*(x2-x1)/(y2-y1)+x1)
				}
			}
		}
		sort.Float64s(xs)
		for k := 0; k+1 < len(xs); k += 2 {
			xa := int(math.Floor(xs[k] + 0.5))
			xb := int(math.Floor(xs[k+1] + 0.5))
			if xa < 0 {
				xa = 0
			}
			if xb > w {
				xb = w
			}
			for x := xa; x < xb; x++ {
				set(x, j)
			}
		}
	}
}

func burnLine(pts []Pt, w, h int, allTouched bool, set func(x, y int)) {
	for i := 0; i+1 < len(pts); i++ {
		a, b := pts[i], pts[i+1]
		dx, dy := b.X-a.X, b.Y-a.Y
		n := int(math.Ceil(math.Max(math.Abs(dx), math.Abs(dy))*4)) + 1
		for k := 0; k <= n; k++ {
			t := float64(k) / float64(n)
			x := a.X + dx*t
			y := a.Y + dy*t
			ix, iy := int(math.Floor(x)), int(math.Floor(y))
			if ix == w && x == float64(w) {
				ix = w - 1
			}
			if iy == h && y == float64(h) {
				iy = h - 1
			}
			if ix >= 0 && iy >= 0 && ix < w && iy < h {
				set(ix, iy)
			}
		}
	}
}

func runRasterize(a *Alg) bool {
	src := srcVector(a)
	var layers []*Layer
	if a.IsSet("sql") {
		l, err := executeSQL(src, a.Str("sql"), a.Str("dialect"))
		if err != nil {
			return false
		}
		layers = []*Layer{l}
	} else if a.IsSet("input-layer") {
		l := src.GetLayerByName(a.Str("input-layer"))
		if l == nil {
			CPLError(CE_Failure, CPLE_AppDefined, "Unable to find layer \"%s\".", a.Str("input-layer"))
			return false
		}
		layers = []*Layer{l}
	} else {
		layers = src.Layers
	}
	burn := a.RealList("burn")
	attr := a.Str("attribute-name")
	use3D := a.Bool("3d")
	if len(burn) == 0 && attr == "" && !use3D {
		a.ReportError(CPLE_AppDefined, "At least one of --burn, --attribute-name or --3d must be specified")
		return false
	}
	env := EmptyEnvelope()
	var srs *SRS
	for _, l := range layers {
		feats := l.Feats()
		if a.IsSet("where") {
			f2, err := filterFeatures(l, a.Str("where"))
			if err != nil {
				return false
			}
			feats = f2
		}
		if e, ok := extentOf(feats, 0); ok {
			env.Merge(e)
		}
		if srs == nil {
			srs = l.SRS()
		}
	}
	if a.IsSet("crs") {
		srs, _ = a.parseCRSArg("crs")
	}
	var gt [6]float64
	var w, h int
	if a.IsSet("extent") {
		e := a.RealList("extent")
		env = Envelope{e[0], e[1], e[2], e[3]}
	}
	switch {
	case a.IsSet("size"):
		sz := a.IntList("size")
		w, h = sz[0], sz[1]
		gt = [6]float64{env.MinX, (env.MaxX - env.MinX) / float64(w), 0, env.MaxY, 0, -(env.MaxY - env.MinY) / float64(h)}
	case a.IsSet("resolution"):
		r := a.RealList("resolution")
		if !a.IsSet("extent") {
			env.MinX -= r[0] / 2
			env.MaxX += r[0] / 2
			env.MinY -= r[1] / 2
			env.MaxY += r[1] / 2
		}
		if a.Bool("target-aligned-pixels") {
			env.MinX = math.Floor(env.MinX/r[0]) * r[0]
			env.MaxX = math.Ceil(env.MaxX/r[0]) * r[0]
			env.MinY = math.Floor(env.MinY/r[1]) * r[1]
			env.MaxY = math.Ceil(env.MaxY/r[1]) * r[1]
		}
		w = int((env.MaxX-env.MinX)/r[0] + 0.5)
		h = int((env.MaxY-env.MinY)/r[1] + 0.5)
		gt = [6]float64{env.MinX, r[0], 0, env.MaxY, 0, -r[1]}
	default:
		a.ReportError(CPLE_AppDefined, "One of --size or --resolution is required")
		return false
	}
	dt := GDT_Float64
	if a.IsSet("output-data-type") {
		dt = dataTypeFromName(a.Str("output-data-type"))
	}
	nb := 1
	if len(burn) > 1 {
		nb = len(burn)
	}
	ds := NewDataset(src.Name, w, h)
	ds.GT = gt
	ds.HasGT = true
	ds.SRS = srs
	nd := 0.0
	hasND := true
	if a.IsSet("nodata") {
		nd, hasND = parseNodataArg(a.Str("nodata"))
	}
	init := a.RealList("init")
	inv, _ := invGeoTransform(gt)
	for bi := 0; bi < nb; bi++ {
		b := ds.AddBand(dt)
		data := make([]float64, w*h)
		iv := 0.0
		if len(init) > 0 {
			iv = init[0]
			if bi < len(init) {
				iv = init[bi]
			}
		}
		for k := range data {
			data[k] = iv
		}
		for _, l := range layers {
			ai := -1
			if attr != "" {
				ai = l.FieldIndex(attr)
				if ai < 0 {
					CPLError(CE_Failure, CPLE_AppDefined, "Failed to find field %s on layer %s.", attr, l.Name)
					return false
				}
			}
			feats := l.Feats()
			if a.IsSet("where") {
				feats, _ = filterFeatures(l, a.Str("where"))
			}
			for _, f := range feats {
				g := f.Geom()
				if g == nil {
					continue
				}
				val := 0.0
				if len(burn) > 0 {
					val = burn[0]
					if bi < len(burn) {
						val = burn[bi]
					}
				}
				if ai >= 0 {
					val = fieldToSQLVal(l.Fields[ai], &f.Fields[ai]).num()
				}
				toPix := func(p Pt) Pt {
					x, y := applyGT(inv, p.X, p.Y)
					return Pt{X: x, Y: y, Z: p.Z}
				}
				var burnGeom func(g *Geom)
				burnGeom = func(g *Geom) {
					set := func(x, y int) {
						v := val
						if use3D {
							v = 0
						}
						data[y*w+x] = v
					}
					switch g.T {
					case wkbPoint:
						for _, p := range g.Pts {
							pp := toPix(p)
							ix, iy := int(math.Floor(pp.X)), int(math.Floor(pp.Y))
							if ix >= 0 && iy >= 0 && ix < w && iy < h {
								if use3D {
									data[iy*w+ix] = p.Z
								} else {
									data[iy*w+ix] = val
								}
							}
						}
					case wkbLineString, wkbLinearRing:
						var pts []Pt
						for _, p := range g.Pts {
							pts = append(pts, toPix(p))
						}
						burnLine(pts, w, h, a.Bool("all-touched"), set)
					case wkbPolygon:
						var rings [][]Pt
						for _, r := range g.Parts {
							var pts []Pt
							for _, p := range r.Pts {
								pts = append(pts, toPix(p))
							}
							rings = append(rings, pts)
						}
						burnPolygon(rings, w, h, set)
						if a.Bool("all-touched") {
							for _, r := range rings {
