{"command":"cd /workspace/gdalgo && cat > reclassify_ovr.go <<'EOF'
package main

import (
	"math"
	"strconv"
	"strings"
)

func init() {
	registerCommand("raster reclassify", runReclassify)
	registerCommand("raster overview add", runOverviewAdd)
	registerCommand("raster overview delete", runOverviewDelete)
}

type reclassRule struct {
	lo, hi       float64
	loIncl, hiIncl bool
	isDefault    bool
	isNaN        bool
	val          float64
	noData       bool
	pass         bool
}

func parseReclassMapping(m string) ([]reclassRule, bool) {
	var rules []reclassRule
	sep := ";"
	if strings.Contains(m, "\n") && !strings.Contains(m, ";") {
		sep = "\n"
	}
	for _, part := range strings.Split(m, sep) {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		eq := strings.LastIndexByte(part, '=')
		if eq < 0 {
			CPLError(CE_Failure, CPLE_AppDefined, "Interval must be followed by '='")
			return nil, false
		}
		lhs := strings.TrimSpace(part[:eq])
		rhs := strings.TrimSpace(part[eq+1:])
		var r reclassRule
		switch strings.ToUpper(rhs) {
		case "NO_DATA":
			r.noData = true
		case "PASS_THROUGH":
			r.pass = true
		default:
			v, ok := parseRealStrict(rhs)
			if !ok {
				CPLError(CE_Failure, CPLE_AppDefined, "Invalid output value: %s", rhs)
				return nil, false
			}
			r.val = v
		}
		switch {
		case strings.EqualFold(lhs, "DEFAULT"):
			r.isDefault = true
		case strings.EqualFold(lhs, "NO_DATA"):
			r.isNaN = true
		case (strings.HasPrefix(lhs, "[") || strings.HasPrefix(lhs, "(")) && (strings.HasSuffix(lhs, "]") || strings.HasSuffix(lhs, ")")):
			inner := lhs[1 : len(lhs)-1]
			ps := strings.Split(inner, ",")
			if len(ps) != 2 {
				return nil, false
			}
			parse := func(s string) float64 {
				s = strings.TrimSpace(s)
				if strings.EqualFold(s, "-inf") {
					return math.Inf(-1)
				}
				if strings.EqualFold(s, "inf") || strings.EqualFold(s, "+inf") {
					return math.Inf(1)
				}
				return cplAtof(s)
			}
			r.lo, r.hi = parse(ps[0]), parse(ps[1])
			r.loIncl = lhs[0] == '['
			r.hiIncl = lhs[len(lhs)-1] == ']'
		default:
			v, ok := parseRealStrict(lhs)
			if !ok {
				return nil, false
			}
			r.lo, r.hi, r.loIncl, r.hiIncl = v, v, true, true
		}
		rules = append(rules, r)
	}
	return rules, true
}

func runReclassify(a *Alg) bool {
	src := srcRaster(a)
	m := a.Str("mapping")
	if strings.HasPrefix(m, "@") {
		b, err := vfsReadFile(m[1:])
		if err != nil {
			CPLError(CE_Failure, CPLE_FileIO, "Cannot open %s", m[1:])
			return false
		}
		m = string(b)
	}
	rules, ok := parseReclassMapping(m)
	if !ok {
		return false
	}
	ds := cloneRasterStructure(src, src.XSize, src.YSize)
	for _, sb := range src.Bands {
		dt := sb.DataType
		if a.IsSet("output-data-type") {
			dt = dataTypeFromName(a.Str("output-data-type"))
		}
		data := sb.Data()
		valid := sb.validMask()
		out := make([]float64, len(data))
		for k, v := range data {
			if !valid[k] {
				out[k] = v
				continue
			}
			matched := false
			for _, r := range rules {
				if r.isDefault || r.isNaN {
					continue
				}
				in := (v > r.lo || (r.loIncl && v == r.lo)) && (v < r.hi || (r.hiIncl && v == r.hi))
				if in {
					matched = true
					if r.noData {
						if !sb.HasNoData {
							CPLError(CE_Failure, CPLE_AppDefined, "Value mapped to NO_DATA, but NoData value is not set")
							return false
						}
						out[k] = sb.NoData
					} else if r.pass {
						out[k] = v
					} else {
						out[k] = r.val
					}
					break
				}
			}
			if !matched {
				found := false
				for _, r := range rules {
					if r.isDefault {
						found = true
						if r.noData {
							if !sb.HasNoData {
								CPLError(CE_Failure, CPLE_AppDefined, "Value mapped to NO_DATA, but NoData value is not set")
								return false
							}
							out[k] = sb.NoData
						} else if r.pass {
							out[k] = v
						} else {
							out[k] = r.val
						}
					}
				}
				if !found {
					CPLError(CE_Failure, CPLE_AppDefined, "Encountered value %s with no specified mapping", cfmt("%g", v))
					return false
				}
			}
		}
		b := newBandFrom(ds, sb, dt, convertDataToType(out, dt))
		removeStatsMD(b)
	}
	return writeRasterResult(a, ds)
}

func overviewBand(sb *Band, f int, resampling string) *Band {
