{"command":"cd /workspace/gdalgo && cat > vector_algs2.go <<'EOF'
package main

import (
	"sort"
	"strings"
)

func init() {
	registerCommand("vector clip", runVectorClip)
	registerCommand("vector simplify", func(a *Alg) bool {
		CPLError(CE_Failure, CPLE_NotSupported, "simplify: This algorithm is only supported for builds against GEOS")
		return false
	})
	registerCommand("vector sort", runVectorSort)
	registerCommand("vector edit", runVectorEdit)
	registerCommand("vector combine", runVectorCombine)
}

func runVectorClip(a *Alg) bool {
	src := srcVector(a)
	if !a.IsSet("bbox") && !a.IsSet("geometry") && !a.IsSet("like") {
		a.ReportError(CPLE_AppDefined, "--bbox, --geometry or --like must be specified")
		return false
	}
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	outName := a.DSName("output")
	drv := a.vectorOutputDriver(outName)
	if drv == nil {
		CPLError(CE_Failure, CPLE_AppDefined, "Cannot guess driver for %s", outName)
		return false
	}
	if a.Bool("overwrite") {
		deleteExistingDataset(outName)
	}
	o := newVecOut(drv, outName, a.StrList("creation-option"), a.StrList("layer-creation-option"))
	for _, l := range layers {
		dl, err := o.createLayer(l.Name, l, l.GeomType(), l.SRS())
		if err != nil {
			return false
		}
		_ = dl
		if len(l.Feats()) > 0 {
			CPLError(CE_Failure, CPLE_NotSupported, "GEOS support not enabled.")
			CPLError(CE_Failure, CPLE_AppDefined, "Failed to write layer '%s'. Use --skip-errors to ignore errors and continue writing.", l.Name)
			o.close()
			return false
		}
	}
	return o.close()
}

func hilbertCode(n uint32, x, y uint32) uint32 {
	var rx, ry, s, d uint32
	for s = n / 2; s > 0; s /= 2 {
		if x&s > 0 {
			rx = 1
		} else {
			rx = 0
		}
		if y&s > 0 {
			ry = 1
		} else {
			ry = 0
		}
		d += s * s * ((3 * rx) ^ ry)
		if ry == 0 {
			if rx == 1 {
				x = s - 1 - x
				y = s - 1 - y
			}
			x, y = y, x
		}
	}
	return d
}

func runVectorSort(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		feats := append([]*Feature{}, l.Feats()...)
		env, _ := extentOf(feats, 0)
		type item struct {
			f    *Feature
			code uint32
			null bool
		}
		var items []item
		const n = 1 << 16
		for _, f := range feats {
			g := f.Geom()
			if g == nil || g.IsEmpty() {
				items = append(items, item{f: f, null: true})
				continue
			}
			e := g.Envelope()
			cx := (e.MinX + e.MaxX) / 2
			cy := (e.MinY + e.MaxY) / 2
			w := env.MaxX - env.MinX
			h := env.MaxY - env.MinY
			var hx, hy uint32
			if w > 0 {
				hx = uint32((n - 1) * (cx - env.MinX) / w)
			}
			if h > 0 {
				hy = uint32((n - 1) * (cy - env.MinY) / h)
			}
			items = append(items, item{f: f, code: hilbertCode(n, hx, hy)})
		}
		sort.SliceStable(items, func(i, j int) bool {
			if items[i].null != items[j].null {
				return !items[i].null
			}
			return items[i].code < items[j].code
		})
		for _, it := range items {
			nl.Features = append(nl.Features, it.f)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorEdit(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := cloneLayerSchema(l)
		nl.Features = l.Feats()
		if a.IsSet("crs") {
			s, ok := a.parseCRSArg("crs")
			if !ok {
				return false
			}
			for _, g := range nl.GeomFields {
				g.SRS = s
			}
		}
		if a.IsSet("geometry-type") {
			if t, ok := parseGeomTypeName(a.Str("geometry-type")); ok {
				for _, g := range nl.GeomFields {
					g.Type = t
				}
			}
		}
		for _, kv := range a.StrList("metadata") {
			if i := strings.IndexByte(kv, '='); i >= 0 {
				nl.MD.Set("", kv[:i], kv[i+1:])
			}
		}
		for _, k := range a.StrList("unset-metadata") {
			nl.MD.Unset("", k)
		}
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}

func runVectorCombine(a *Alg) bool {
	src := srcVector(a)
	layers, ok := selectInputLayers(a, src)
	if !ok {
		return false
	}
	var outLayers []*Layer
	for _, l := range layers {
		if !isActive(a, l) {
			outLayers = append(outLayers, l)
			continue
		}
		nl := NewLayer(l.Name)
		gt := wkbGeometryCollection
		ft := geomTypeFlat(l.GeomType())
		switch ft {
		case wkbPoint, wkbMultiPoint:
			gt = wkbMultiPoint
		case wkbLineString, wkbMultiLineString:
			gt = wkbMultiLineString
		case wkbPolygon, wkbMultiPolygon:
			gt = wkbMultiPolygon
		}
		nl.GeomFields = []*GeomFieldDefn{{Name: "", Type: makeGeomType(gt, geomTypeHasZ(l.GeomType()), false), SRS: l.SRS(), Nullable: true}}
		groupBy := a.StrList("group-by")
		var keys []int
		for _, gname := range groupBy {
			idx := l.FieldIndex(gname)
			if idx < 0 {
				a.ReportError(CPLE_AppDefined, "Specified group-by field '%s' does not exist in layer '%s'", gname, l.Name)
				return false
			}
			keys = append(keys, idx)
			nl.Fields = append(nl.Fields, l.Fields[idx].Clone())
		}
		groups := map[string]*Feature{}
		var order []string
		for _, f := range l.Feats() {
			var kb strings.Builder
			for _, k := range keys {
				kb.WriteString(fieldAsString(l.Fields[k], &f.Fields[k]) + "\x00")
			}
			key := kb.String()
			nf := groups[key]
			if nf == nil {
				nf = nl.NewFeature()
				for i, k := range keys {
					nf.Fields[i] = f.Fields[k]
				}
				nf.Geoms[0] = &Geom{T: gt}
				groups[key] = nf
				order = append(order, key)
			}
			g := f.Geom()
			if g == nil {
				continue
			}
			c := nf.Geoms[0]
			if g.Z {
				c.Z = true
			}
			if gt != wkbGeometryCollection && (g.T == wkbMultiPoint || g.T == wkbMultiLineString || g.T == wkbMultiPolygon) {
				for _, p := range g.Parts {
					c.Parts = append(c.Parts, p.Clone())
				}
			} else {
				c.Parts = append(c.Parts, g.Clone())
			}
		}
		for _, k := range order {
			nl.AddFeature(groups[k])
		}
		nl.loaded = true
		outLayers = append(outLayers, nl)
	}
	return writeVectorResult(a, src, outLayers)
}
