func runFootprint(a *Alg) bool {
	src := srcRaster(a)
	bands := a.IntList("band")
	if len(bands) == 0 {
		for i := range src.Bands {
			bands = append(bands, i+1)
		}
	}
	W, H := src.XSize, src.YSize
	mask := make([]bool, W*H)
	inter := strings.EqualFold(a.Str("combine-bands"), "intersection")
	srcND := a.RealList("src-nodata")
	for bi, bn := range bands {
		b := src.Bands[bn-1]
		v := b.validMask()
		if len(srcND) > 0 {
			nd := srcND[0]
			if bi < len(srcND) {
				nd = srcND[bi]
			}
			d := b.Data()
			for k := range v {
				v[k] = d[k] != nd
			}
		}
		for k := range mask {
			if bi == 0 {
				mask[k] = v[k]
			} else if inter {
				mask[k] = mask[k] && v[k]
			} else {
				mask[k] = mask[k] || v[k]
			}
		}
	}
	// connected components of valid pixels (8-connected), emitted like polygonize
	labels := make([]int, W*H)
	for i := range labels {
		labels[i] = -1
	}
	type comp struct {
		pix     []ipt
		lastRow int
		id      int
	}
	var comps []*comp
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			k := y*W + x
			if !mask[k] || labels[k] >= 0 {
				continue
			}
			c := &comp{id: len(comps)}
			comps = append(comps, c)
			stack := []ipt{{x, y}}
			labels[k] = c.id
			for len(stack) > 0 {
				p := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				c.pix = append(c.pix, p)
				if p.y > c.lastRow {
					c.lastRow = p.y
				}
				for _, d := range [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} {
					nx, ny := p.x+d[0], p.y+d[1]
					if nx < 0 || ny < 0 || nx >= W || ny >= H {
						continue
					}
					nk := ny*W + nx
					if mask[nk] && labels[nk] < 0 {
						labels[nk] = c.id
						stack = append(stack, ipt{nx, ny})
					}
				}
			}
		}
	}
	pixelCS := strings.EqualFold(a.Str("coordinate-system"), "pixel")
	gt := src.GT
	if pixelCS || !src.HasGT {
		gt = [6]float64{0, 1, 0, 0, 0, 1}
	}
	var dst *SRS
	if a.IsSet("dst-crs") {
		dst, _ = a.parseCRSArg("dst-crs")
	}
	var ct *CoordTransform
	if dst != nil && src.SRS != nil && !pixelCS {
		ct = NewCoordTransform(src.SRS, dst)
	}
	mp := &Geom{T: wkbMultiPolygon}
	for _, c := range comps {
		id := c.id
		m := func(x, y int) bool {
			if x < 0 || y < 0 || x >= W || y >= H {
				return false
			}
			return labels[y*W+x] == id
		}
		rings := traceRings(m, c.pix, false)
		var outer []ipt
		var holes [][]ipt
		for _, r := range rings {
			r = simplifyRing(r)
			if len(r) < 3 {
				continue
			}
			if -ringAreaI(r) > 0 && (outer == nil || abs(ringAreaI(r)) > abs(ringAreaI(outer))) {
				if outer != nil {
					holes = append(holes, outer)
				}
				outer = r
			} else {
				holes = append(holes, r)
			}
		}
		if outer == nil {
			continue
		}
		mk := func(r []ipt) *Geom {
			r = rotateToTopLeft(r)
			g := &Geom{T: wkbLinearRing}
			for _, p := range append(r, r[0]) {
				x, y := applyGT(gt, float64(p.x), float64(p.y))
				g.Pts = append(g.Pts, Pt{X: x, Y: y})
			}
			return g
		}
		poly := &Geom{T: wkbPolygon, Parts: []*Geom{mk(outer)}}
		for _, h := range holes {
			poly.Parts = append(poly.Parts, mk(h))
		}
		mp.Parts = append(mp.Parts, poly)
	}
	if ct != nil {
		transformGeom(mp, ct)
	}
	lname := a.Str("output-layer")
	if lname == "" {
		lname = "footprint"
	}
	l := NewLayer(lname)
	outSRS := src.SRS
	if dst != nil {
		outSRS = dst
	}
	if pixelCS {
		outSRS = nil
	}
	l.GeomFields = []*GeomFieldDefn{{Name: "", Type: wkbMultiPolygon, SRS: outSRS, Nullable: true}}
	locField := a.Str("location-field")
	if locField == "" {
		locField = "location"
	}
	if !a.Bool("no-location-field") {
		l.Fields = []*FieldDefn{NewFieldDefn(locField, OFTString)}
	}
	loc := src.Name
	if a.Bool("absolute-path") {
		loc = absPath(loc)
	}
	addFeat := func(g *Geom) {
		f := l.NewFeature()
		if !a.Bool("no-location-field") {
			f.Fields[0] = FieldValue{State: 2, S: loc}
		}
		f.Geoms[0] = g
		l.AddFeature(f)
	}
	if a.Bool("split-multipolygons") {
		for _, p := range mp.Parts {
			addFeat(&Geom{T: wkbMultiPolygon, Parts: []*Geom{p}})
		}
	} else if len(mp.Parts) > 0 {
		addFeat(mp)
	}
	l.loaded = true
	ds := NewDataset(src.Name, 0, 0)
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, ds, []*Layer{l})
	if saved != nil {
		a.Vals["output-layer"] = saved
	}
	_ = filepath.Base
	return ok
}

func runAsFeatures(a *Alg) bool {
	src := srcRaster(a)
	bands := a.IntList("band")
	if len(bands) == 0 {
		for i := range src.Bands {
			bands = append(bands, i+1)
		}
	}
	gtype := strings.ToLower(a.Str("geometry-type"))
	lname := a.Str("output-layer")
	if lname == "" {
		lname = "pixels"
	}
	l := NewLayer(lname)
	switch gtype {
	case "point":
		l.GeomFields = []*GeomFieldDefn{{Name: "", Type: wkbPoint, SRS: src.SRS, Nullable: true}}
	case "polygon":
		l.GeomFields = []*GeomFieldDefn{{Name: "", Type: wkbPolygon, SRS: src.SRS, Nullable: true}}
	}
	if a.Bool("include-xy") {
		l.Fields = append(l.Fields, NewFieldDefn("CENTER_X", OFTReal), NewFieldDefn("CENTER_Y", OFTReal))
	}
	if a.Bool("include-row-col") {
		l.Fields = append(l.Fields, NewFieldDefn("ROW", OFTInteger), NewFieldDefn("COL", OFTInteger))
	}
	for _, bn := range bands {
		ft := OFTReal
		l.Fields = append(l.Fields, NewFieldDefn("BAND_"+strconv.Itoa(bn), ft))
	}
	gt := src.GT
	var valids [][]bool
	var datas [][]float64
	for _, bn := range bands {
		b := src.Bands[bn-1]
		valids = append(valids, b.validMask())
		datas = append(datas, b.Data())
	}
	for y := 0; y < src.YSize; y++ {
		for x := 0; x < src.XSize; x++ {
			k := y*src.XSize + x
			if a.Bool("skip-nodata") {
				all := true
				for _, v := range valids {
					if v[k] {
						all = false
					}
				}
				if all {
					continue
				}
			}
			f := l.NewFeature()
			fi := 0
			cx, cy := applyGT(gt, float64(x)+0.5, float64(y)+0.5)
			if a.Bool("include-xy") {
				f.Fields[0] = FieldValue{State: 2, F: cx}
				f.Fields[1] = FieldValue{State: 2, F: cy}
				fi = 2
			}
			if a.Bool("include-row-col") {
				f.Fields[fi] = FieldValue{State: 2, I: int64(y)}
				f.Fields[fi+1] = FieldValue{State: 2, I: int64(x)}
				fi += 2
			}
			for i := range bands {
				if valids[i][k] {
					f.Fields[fi+i] = FieldValue{State: 2, F: datas[i][k]}
				} else {
					f.Fields[fi+i] = FieldValue{State: 1}
				}
			}
			switch gtype {
			case "point":
				f.Geoms[0] = NewPoint(cx, cy)
			case "polygon":
				pt := func(px, py float64) Pt { xx, yy := applyGT(gt, px, py); return Pt{X: xx, Y: yy} }
				fx, fy := float64(x), float64(y)
				f.Geoms[0] = &Geom{T: wkbPolygon, Parts: []*Geom{{T: wkbLinearRing, Pts: []Pt{pt(fx, fy), pt(fx, fy+1), pt(fx+1, fy+1), pt(fx+1, fy), pt(fx, fy)}}}}
			}
			l.AddFeature(f)
		}
	}
	l.loaded = true
	ds := NewDataset(src.Name, 0, 0)
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, ds, []*Layer{l})
	if saved != nil {
		a.Vals["output-layer"] = saved
	}
	return ok
}
EOF
