cd /workspace/gdalgo && cat > proximity.go <<'EOF'
package main

import (
	"math"
	"strings"
)

func init() {
	registerCommand("raster proximity", runProximity)
	registerCommand("raster sieve", runSieve)
}

func runProximity(a *Alg) bool {
	src := srcRaster(a)
	bi := 1
	if a.IsSet("band") {
		bi = a.Int("band")
	}
	sb := src.Bands[bi-1]
	W, H := src.XSize, src.YSize
	data := sb.Data()
	targets := a.RealList("target-values")
	isTarget := func(v float64) bool {
		if len(targets) == 0 {
			return v != 0
		}
		for _, t := range targets {
			if v == t {
				return true
			}
		}
		return false
	}
	var tp []ipt
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			if isTarget(data[y*W+x]) {
				tp = append(tp, ipt{x, y})
			}
		}
	}
	geo := strings.EqualFold(a.Str("distance-units"), "geo")
	sx, sy := 1.0, 1.0
	if geo {
		sx, sy = math.Abs(src.GT[1]), math.Abs(src.GT[5])
	}
	maxD := a.Real("max-distance")
	dt := GDT_Float32
	if a.IsSet("output-data-type") {
		dt = dataTypeFromName(a.Str("output-data-type"))
	}
	nd := 0.0
	hasND := false
	if a.IsSet("nodata") {
		nd, hasND = parseNodataArg(a.Str("nodata"))
	}
	out := make([]float64, W*H)
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			best := math.Inf(1)
			for _, t := range tp {
				dx := float64(t.x-x) * sx
				dy := float64(t.y-y) * sy
				d := dx*dx + dy*dy
				if d < best {
					best = d
				}
			}
			d := math.Sqrt(best)
			if math.IsInf(d, 1) || (maxD > 0 && d > maxD) {
				if hasND {
					out[y*W+x] = nd
				} else {
					out[y*W+x] = 65535
					if dt.IsFloat() {
						out[y*W+x] = -1
					}
				}
				continue
			}
			if a.IsSet("fixed-value") && d > 0 {
				d = a.Real("fixed-value")
			}
			out[y*W+x] = d
		}
	}
	ds := cloneRasterStructure(src, W, H)
	ds.MD = NewMetadata()
	b := ds.AddBand(dt)
	b.data = convertDataToType(out, dt)
	b.loaded = true
	b.HasNoData, b.NoData = hasND, nd
	b.ColorInterp = GCI_GrayIndex
	return writeRasterResult(a, ds)
}

func runSieve(a *Alg) bool {
	src := srcRaster(a)
	bi := 1
	if a.IsSet("band") {
		bi = a.Int("band")
	}
	sb := src.Bands[bi-1]
	W, H := src.XSize, src.YSize
	data := append([]float64{}, sb.Data()...)
	valid := sb.validMask()
	thr := 2
	if a.IsSet("size-threshold") {
		thr = a.Int("size-threshold")
	}
	diag := a.Bool("connect-diagonal-pixels")
	nbs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	if diag {
		nbs = append(nbs, [2]int{1, 1}, [2]int{1, -1}, [2]int{-1, 1}, [2]int{-1, -1})
	}
	for iter := 0; iter < 2; iter++ {
		labels := make([]int, W*H)
		for i := range labels {
			labels[i] = -1
		}
		var comps [][]int
		for k := 0; k < W*H; k++ {
			if labels[k] >= 0 || !valid[k] {
				continue
			}
			id := len(comps)
			var pix []int
			stack := []int{k}
			labels[k] = id
			for len(stack) > 0 {
				p := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				pix = append(pix, p)
				px, py := p%W, p/W
				for _, d := range nbs {
					nx, ny := px+d[0], py+d[1]
					if nx < 0 || ny < 0 || nx >= W || ny >= H {
						continue
					}
					nk := ny*W + nx
					if labels[nk] < 0 && valid[nk] && data[nk] == data[k] {
						labels[nk] = id
						stack = append(stack, nk)
					}
				}
			}
			comps = append(comps, pix)
		}
		changed := false
		for id, pix := range comps {
			if len(pix) >= thr {
				continue
			}
			// find largest neighbouring component
			best, bestSize := -1, 0
			for _, p := range pix {
				px, py := p%W, p/W
				for _, d := range [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} {
					nx, ny := px+d[0], py+d[1]
					if nx < 0 || ny < 0 || nx >= W || ny >= H {
						continue
					}
					nl := labels[ny*W+nx]
					if nl >= 0 && nl != id && len(comps[nl]) > bestSize {
						best, bestSize = nl, len(comps[nl])
					}
				}
			}
			if best >= 0 {
				v := data[comps[best][0]]
				for _, p := range pix {
					data[p] = v
				}
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	ds := cloneRasterStructure(src, W, H)
	b := newBandFrom(ds, sb, sb.DataType, data)
	removeStatsMD(b)
	return writeRasterResult(a, ds)
}
