// nodataArgValue reads a nodata-like argument regardless of its declared type.
func nodataArgValue(a *Alg, name string) (float64, bool) {
	v := a.V(name)
	switch v.Def.Type {
	case "real":
		return v.Real, true
	case "integer":
		return float64(v.Int), true
