{"command":"cd /workspace/gdalgo && cat > colormap.go <<'EOF'
package main

import (
	"math"
	"sort"
	"strings"
)

func init() {
	registerCommand("raster color-map", runColorMap)
}

type cmEntry struct {
	v          float64
	r, g, b, a float64
	nv         bool
}

func runColorMap(a *Alg) bool {
	src := srcRaster(a)
	bi := 1
	if a.IsSet("band") {
		bi = a.Int("band")
	}
	sb := src.Bands[bi-1]
	var entries []cmEntry
	var nvEntry *cmEntry
	cmName := a.Str("color-map")
	if cmName == "" && sb.ColorTable != nil {
		for i, e := range sb.ColorTable.Entries {
			entries = append(entries, cmEntry{v: float64(i), r: float64(e.C1), g: float64(e.C2), b: float64(e.C3), a: float64(e.C4)})
		}
	} else {
		data, err := vfsReadFile(cmName)
		if err != nil {
			CPLError(CE_Failure, CPLE_OpenFailed, "Cannot find %s", cmName)
			return false
		}
		mn, mx, _ := sb.ComputeMinMax(false)
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(line, ",", " "), "\t", " "))
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			f := strings.Fields(line)
			if len(f) < 2 {
				continue
			}
			e := cmEntry{a: 255}
			key := strings.ToLower(f[0])
			if key == "nv" {
				e.nv = true
			} else if strings.HasSuffix(key, "%") {
				p := cplAtof(key[:len(key)-1]) / 100
				e.v = mn + p*(mx-mn)
			} else {
				e.v = cplAtof(key)
			}
			vals := []float64{}
			for _, x := range f[1:] {
				vals = append(vals, cplAtof(x))
			}
			if len(vals) == 1 {
				e.r, e.g, e.b = vals[0], vals[0], vals[0]
			} else if len(vals) >= 3 {
				e.r, e.g, e.b = vals[0], vals[1], vals[2]
				if len(vals) >= 4 {
					e.a = vals[3]
				}
			}
			if e.nv {
				ee := e
				nvEntry = &ee
				continue
			}
			entries = append(entries, e)
		}
		if nvEntry != nil && !sb.HasNoData {
			CPLError(CE_Warning, CPLE_AppDefined, "Input dataset has no nodata value. Ignoring 'nv' entry in color palette")
			nvEntry = nil
		}
	}
	sort.SliceStable(entries, func(i, j int) bool { return entries[i].v < entries[j].v })
	sel := strings.ToLower(a.Str("color-selection"))
	addAlpha := a.Bool("add-alpha")
	W, H := src.XSize, src.YSize
	nb := 3
	if addAlpha {
		nb = 4
	}
	outs := make([][]float64, nb)
	for i := range outs {
		outs[i] = make([]float64, W*H)
	}
	data := sb.Data()
	valid := sb.validMask()
	for k, v := range data {
		var c cmEntry
		if !valid[k] || math.IsNaN(v) {
			if nvEntry != nil {
				c = *nvEntry
			} else {
				c = cmEntry{}
			}
		} else if len(entries) == 0 {
			c = cmEntry{}
		} else {
			switch sel {
			case "exact":
				found := false
				for _, e := range entries {
					if e.v == v {
						c = e
						found = true
						break
					}
				}
				if !found {
					c = cmEntry{}
				}
			case "nearest":
				best := entries[0]
				for _, e := range entries {
					if math.Abs(e.v-v) < math.Abs(best.v-v) {
						best = e
					}
				}
				c = best
			default:
				if v <= entries[0].v {
					c = entries[0]
				} else if v >= entries[len(entries)-1].v {
					c = entries[len(entries)-1]
				} else {
					for i := 1; i < len(entries); i++ {
						if v <= entries[i].v {
							e0, e1 := entries[i-1], entries[i]
							t := 0.0
							if e1.v != e0.v {
								t = (v - e0.v) / (e1.v - e0.v)
							}
							c = cmEntry{r: e0.r + t*(e1.r-e0.r), g: e0.g + t*(e1.g-e0.g), b: e0.b + t*(e1.b-e0.b), a: e0.a + t*(e1.a-e0.a)}
							break
						}
					}
				}
			}
		}
		outs[0][k] = clampRound(GDT_Byte, c.r)
		outs[1][k] = clampRound(GDT_Byte, c.g)
		outs[2][k] = clampRound(GDT_Byte, c.b)
		if addAlpha {
			outs[3][k] = clampRound(GDT_Byte, c.a)
		}
	}
	ds := cloneRasterStructure(src, W, H)
	ds.MD = NewMetadata()
	for i := 0; i < nb; i++ {
		b := ds.AddBand(GDT_Byte)
		b.data = outs[i]
		b.loaded = true
		b.ColorInterp = GCI_RedBand + i
		if i == 3 {
			b.ColorInterp = GCI_AlphaBand
		}
	}
	setDefaultMaskFlags(ds)
	return writeRasterResult(a, ds)
}
EOF
go build -o /tmp/gdalgo_bin . 2>&1 | head; cp /tmp/rt/fix/cm.txt /tmp/rt/fix/cm.txt; cat > /tmp/rt/t_cm.txt <<'EOF'
GDAL raster color-map --color-map cm.txt dem.tif o.tif && GDAL raster info --checksum o.tif
