GDAL raster color-map --color-map cm.txt --color-selection nearest dem.tif o.tif && GDAL raster info --checksum o.tif
GDAL raster color-map --color-map cm.txt --color-selection exact dem.tif o.tif && GDAL raster info --checksum o.tif
EOF
