		a.ReportError(CPLE_NotSupported, "This algorithm is only supported for builds against GEOS")
		return false
	})
	registerCommand("vector partition", func(a *Alg) bool {
		if len(a.StrList("field")) == 0 && !a.IsSet("feature-limit") && !a.IsSet("max-file-size") {
			a.ReportError(CPLE_IllegalArg, "When 'fields' argument is not specified, 'feature-limit' and/or 'max-file-size' must be specified")
			printErrStr(a.Def.shortUsage())
			return false
		}
		a.ReportError(CPLE_NotSupported, "partition not supported in this build")
		return false
	})
	registerCommand("vector index", runVectorIndex)
}

func runVectorIndex(a *Alg) bool {
	lname := a.Str("output-layer")
	if lname == "" {
		lname = "tileindex"
	}
	locField := a.Str("location-name")
	if locField == "" {
		locField = "location"
	}
	l := NewLayer(lname)
	lf := NewFieldDefn(locField, OFTString)
	lf.Width = 254
	l.Fields = []*FieldDefn{lf}
	var refFields int = -1
	var layerSRS *SRS
	if a.IsSet("dst-crs") {
		layerSRS, _ = a.parseCRSArg("dst-crs")
	}
	for _, n := range expandInputList(a.StrList("input")) {
		ds := OpenDataset(n, OF_VECTOR, a.StrList("input-format"), a.StrList("open-option"), true)
		if ds == nil {
			continue
		}
		for li, sl := range ds.Layers {
			if refFields < 0 {
				refFields = len(sl.Fields)
				if layerSRS == nil {
					layerSRS = sl.SRS()
				}
				l.GeomFields = []*GeomFieldDefn{{Name: "", Type: wkbPolygon, SRS: layerSRS, Nullable: true}}
			} else if len(sl.Fields) != refFields {
				a.ReportWarning(CPLE_AppDefined, "Number of attributes of layer %s of %s does not match. Skipping it.", sl.Name, n)
				continue
			}
			env, ok := extentOf(sl.Feats(), 0)
			if !ok {
				continue
			}
			ring := &Geom{T: wkbLinearRing, Pts: []Pt{{X: env.MinX, Y: env.MinY}, {X: env.MinX, Y: env.MaxY}, {X: env.MaxX, Y: env.MaxY}, {X: env.MaxX, Y: env.MinY}, {X: env.MinX, Y: env.MinY}}}
			g := &Geom{T: wkbPolygon, Parts: []*Geom{ring}}
			if sl.SRS() != nil && layerSRS != nil && !sl.SRS().IsSame(layerSRS) {
				if ct := NewCoordTransform(sl.SRS(), layerSRS); ct != nil {
					transformGeom(g, ct)
				}
			}
			f := l.NewFeature()
			loc := n
			if a.Bool("absolute-path") {
				loc = absPath(n)
			}
			f.Fields[0] = FieldValue{State: 2, S: loc + "," + itoa(li)}
			f.Geoms[0] = g
			l.AddFeature(f)
		}
	}
	if len(l.GeomFields) == 0 {
		l.GeomFields = []*GeomFieldDefn{{Name: "", Type: wkbPolygon, Nullable: true}}
	}
	l.loaded = true
	src := NewDataset(a.DSName("output"), 0, 0)
	saved := a.Vals["output-layer"]
	delete(a.Vals, "output-layer")
	ok := writeVectorResult(a, src, []*Layer{l})
	if saved != nil {
		a.Vals["output-layer"] = saved
	}
	return ok
}
